-- Audit the actual recursive runtime role/member set, not semantic
-- pg_has_role membership selection (which includes unrelated superusers).
DO $$ DECLARE runtime_ids OID[]; BEGIN
 WITH RECURSIVE members(oid) AS (SELECT oid FROM pg_roles WHERE rolname IN ('enta_runtime','enta_gameplay_runtime') UNION SELECT membership.member FROM pg_auth_members membership JOIN members prior ON membership.roleid=prior.oid), reachable(oid) AS (SELECT oid FROM members UNION SELECT membership.roleid FROM pg_auth_members membership JOIN reachable prior ON membership.member=prior.oid) SELECT array_agg(oid) INTO runtime_ids FROM reachable;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='enta_gameplay_runtime' AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreaterole) OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='enta_finance_executor' AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreaterole) THEN RAISE EXCEPTION 'audited separate NOLOGIN executor/runtime required'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles role WHERE role.oid=ANY(runtime_ids) AND (role.rolsuper OR role.rolcreaterole OR role.rolcreatedb OR role.rolreplication OR role.rolbypassrls))
 OR EXISTS(SELECT 1 FROM pg_roles role CROSS JOIN pg_roles writer WHERE role.oid=ANY(runtime_ids) AND writer.rolname IN ('enta_finance_executor','enta_outbox_worker','catalog_assembler','catalog_reviewer','catalog_publisher','catalog_validator','catalog_activator','enta_huroof_reserver','enta_huroof_provisioner','enta_huroof_reconciler') AND pg_has_role(role.oid,writer.oid,'member'))
 OR EXISTS(SELECT 1 FROM pg_roles role CROSS JOIN pg_namespace namespace WHERE role.oid=ANY(runtime_ids) AND namespace.nspname IN ('public','int4_crypto') AND (pg_has_role(role.oid,namespace.nspowner,'member') OR has_schema_privilege(role.oid,namespace.oid,'CREATE')))
 OR EXISTS(SELECT 1 FROM pg_roles role CROSS JOIN pg_class relation JOIN pg_namespace namespace ON namespace.oid=relation.relnamespace WHERE role.oid=ANY(runtime_ids) AND namespace.nspname='public' AND relation.relname IN ('EntaCompetitiveRelease','EntaCompetitivePrompt','EntaCompetitiveHint','EntaCompetitiveGrapheme','GameCompetitivePin','CompetitiveRosterPlayer','CompetitiveRoundPin','CompetitiveAllowance','CompetitiveEffect','CompetitiveConsumption','CompetitiveAttempt','CompetitiveClassification','CompetitiveScorePosting','CompetitiveScoreRead','CompetitiveDependency','CompetitiveEffectAttempt','CompetitiveRulingHead','CompetitiveReversal','CompetitiveItemConsumption','CompetitiveAssignmentPlayer','CompetitiveTargetDisclosure','CompetitiveItemReview','CompetitiveItemResolution','CompetitiveRuntimeHead','CompetitiveAuditReport','EngineTournamentBindingSnapshot','EngineTournamentBindingParticipant','EngineMatchResult','EngineMatchResultHead','EngineMatchResultSignal') AND (has_table_privilege(role.oid,relation.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE') OR has_any_column_privilege(role.oid,relation.oid,'SELECT,INSERT,UPDATE')))
 OR EXISTS(SELECT 1 FROM pg_roles role CROSS JOIN pg_class relation JOIN pg_namespace namespace ON namespace.oid=relation.relnamespace WHERE role.oid=ANY(runtime_ids) AND namespace.nspname='public' AND relation.relname IN ('Wallet','WalletEntry','Admission','Reservation','AdmissionEvent','AdmissionOutbox','Game','Team','Player','GameQuestion','GameCategoryPin','CatalogRelease','ActiveCatalogPointer','CatalogValidationReceipt') AND (has_table_privilege(role.oid,relation.oid,'INSERT,UPDATE,DELETE,TRUNCATE') OR has_any_column_privilege(role.oid,relation.oid,'INSERT,UPDATE'))) THEN RAISE EXCEPTION 'runtime has inherited private reader/writer/elevated/schema authority; audit outside migration, no automatic remedy'; END IF;
END $$;
-- Pure restricted successor helpers; every public entry authorizes and locks.
ALTER TABLE public."CompetitiveReversal" ADD CONSTRAINT "CompetitiveReversal_gameId_reversalEffectId_key" UNIQUE("gameId","reversalEffectId");
-- Fresh5 only. Engine-local restrictive references; immutable claims/one disposition.
CREATE TABLE public."CompetitiveCapacityClaim" (
 "id" TEXT PRIMARY KEY, "gameId" TEXT NOT NULL, "roundId" TEXT, "sourceKind" TEXT NOT NULL, "sourceId" TEXT NOT NULL, "lane" TEXT NOT NULL, "cost" JSONB NOT NULL,
 "attemptId" TEXT, "itemId" TEXT, "reviewId" TEXT, "boardReversalEffectId" TEXT, "pauseEventId" TEXT, "grantId" TEXT,
 UNIQUE("gameId","id"), UNIQUE("gameId","roundId","sourceKind","sourceId"),
 FOREIGN KEY("gameId") REFERENCES public."Game"("id") ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY("gameId","roundId") REFERENCES public."GameRound"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("gameId","roundId","attemptId") REFERENCES public."CompetitiveAttempt"("gameId","roundId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("roundId","itemId") REFERENCES public."RoundItemPin"("roundId","itemId") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("gameId","reviewId") REFERENCES public."CompetitiveItemReview"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("gameId","boardReversalEffectId") REFERENCES public."CompetitiveReversal"("gameId","reversalEffectId") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("gameId","pauseEventId") REFERENCES public."RoundAuthorityEvent"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("gameId","grantId") REFERENCES public."RoundGrant"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 CHECK(("sourceKind"='ATTEMPT' AND "attemptId" IS NOT NULL AND "attemptId"="sourceId" AND "roundId" IS NOT NULL AND num_nonnulls("attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId")=1)
 OR ("sourceKind"='ITEM' AND "itemId" IS NOT NULL AND "itemId"="sourceId" AND "roundId" IS NOT NULL AND num_nonnulls("attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId")=1)
 OR ("sourceKind"='REVIEW' AND "reviewId" IS NOT NULL AND "reviewId"="sourceId" AND "roundId" IS NOT NULL AND num_nonnulls("attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId")=1)
 OR ("sourceKind"='BOARD_REVIEW' AND "boardReversalEffectId" IS NOT NULL AND "boardReversalEffectId"="sourceId" AND "roundId" IS NOT NULL AND num_nonnulls("attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId")=1)
 OR ("sourceKind"='PAUSE' AND "pauseEventId" IS NOT NULL AND "pauseEventId"="sourceId" AND "roundId" IS NOT NULL AND num_nonnulls("attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId")=1)
 OR ("sourceKind"='GRANT' AND "grantId" IS NOT NULL AND "grantId"="sourceId" AND "roundId" IS NOT NULL AND num_nonnulls("attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId")=1)
 OR ("sourceKind"='ROUND' AND "sourceId"="roundId" AND "roundId" IS NOT NULL AND num_nonnulls("attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId")=0)
 OR ("sourceKind"='FINISH' AND "sourceId"="gameId" AND "roundId" IS NULL AND num_nonnulls("attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId")=0))
);
CREATE INDEX "CompetitiveCapacityClaim_gameId_roundId_lane_idx" ON public."CompetitiveCapacityClaim"("gameId","roundId","lane");
CREATE TABLE public."CompetitiveCapacityDisposition" (
 "claimId" TEXT PRIMARY KEY, "gameId" TEXT NOT NULL, "eventId" TEXT NOT NULL, "kind" TEXT NOT NULL CHECK("kind" IN ('CONSUME','RELEASE')), UNIQUE("gameId","claimId"),
 FOREIGN KEY("gameId","claimId") REFERENCES public."CompetitiveCapacityClaim"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("gameId","eventId") REFERENCES public."RoundAuthorityEvent"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE public."CompetitiveCapacityCharge" (
 "eventId" TEXT PRIMARY KEY, "gameId" TEXT NOT NULL, "roundId" TEXT, "lane" TEXT NOT NULL, "cost" JSONB NOT NULL, UNIQUE("gameId","eventId"),
 FOREIGN KEY("gameId") REFERENCES public."Game"("id") ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY("gameId","roundId") REFERENCES public."GameRound"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("gameId","eventId") REFERENCES public."RoundAuthorityEvent"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX "CompetitiveCapacityCharge_gameId_roundId_lane_idx" ON public."CompetitiveCapacityCharge"("gameId","roundId","lane");
CREATE TABLE public."CompetitiveCapacityHead" (
 "roundId" TEXT PRIMARY KEY, "gameId" TEXT NOT NULL, "version" INTEGER NOT NULL CHECK("version" BETWEEN 1 AND 64946), "used" JSONB NOT NULL, "reserved" JSONB NOT NULL, "resourceEventId" TEXT,
 UNIQUE("gameId","roundId"), FOREIGN KEY("gameId") REFERENCES public."Game"("id") ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY("gameId","roundId") REFERENCES public."GameRound"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY("gameId","resourceEventId") REFERENCES public."RoundAuthorityEvent"("gameId","id") ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED
);
REVOKE ALL ON public."CompetitiveCapacityClaim",public."CompetitiveCapacityDisposition",public."CompetitiveCapacityCharge",public."CompetitiveCapacityHead" FROM PUBLIC,enta_runtime,enta_gameplay_runtime;
GRANT SELECT,INSERT ON public."CompetitiveCapacityClaim",public."CompetitiveCapacityDisposition",public."CompetitiveCapacityCharge",public."CompetitiveCapacityHead" TO enta_finance_executor;
GRANT UPDATE("version","used","reserved","resourceEventId") ON public."CompetitiveCapacityHead" TO enta_finance_executor;
CREATE TRIGGER "CompetitiveCapacityClaim_immutable" BEFORE UPDATE OR DELETE ON public."CompetitiveCapacityClaim" FOR EACH ROW EXECUTE FUNCTION public.int5a_reject_immutable_rows();
CREATE TRIGGER "CompetitiveCapacityDisposition_immutable" BEFORE UPDATE OR DELETE ON public."CompetitiveCapacityDisposition" FOR EACH ROW EXECUTE FUNCTION public.int5a_reject_immutable_rows();
CREATE TRIGGER "CompetitiveCapacityCharge_immutable" BEFORE UPDATE OR DELETE ON public."CompetitiveCapacityCharge" FOR EACH ROW EXECUTE FUNCTION public.int5a_reject_immutable_rows();

CREATE INDEX "CompetitiveEffect_gameId_eventId_idx" ON public."CompetitiveEffect"("gameId","eventId");
CREATE INDEX "CompetitiveClassification_gameId_eventId_idx" ON public."CompetitiveClassification"("gameId","eventId");
CREATE INDEX "CompetitiveItemConsumption_gameId_effectId_idx" ON public."CompetitiveItemConsumption"("gameId","effectId");
CREATE INDEX "CompetitiveRulingHead_gameId_roundId_scopeId_idx" ON public."CompetitiveRulingHead"("gameId","roundId","scopeId");

CREATE FUNCTION public.int9_now() RETURNS DOUBLE PRECISION LANGUAGE SQL VOLATILE SET search_path=pg_catalog AS $$ SELECT floor(extract(epoch FROM clock_timestamp())*1000)::DOUBLE PRECISION $$;
CREATE FUNCTION public.int9_error(code TEXT) RETURNS VOID LANGUAGE SQL SET search_path=pg_catalog AS $$ SELECT public.int6_enta_error(code) $$;
CREATE FUNCTION public.int9_put(s JSONB,key TEXT,value JSONB) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT jsonb_set(s,ARRAY[key],value) $$;
CREATE FUNCTION public.int9_round(s JSONB,rid TEXT) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT x FROM jsonb_array_elements(s->'rounds') x WHERE x->>'id'=rid $$;
CREATE FUNCTION public.int9_pending(s JSONB,rid TEXT,item_id TEXT,all_items BOOLEAN) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT COALESCE(jsonb_agg(a ORDER BY ord),'[]'::JSONB) FROM jsonb_array_elements(s->'attempts') WITH ORDINALITY attempts(a,ord) WHERE a->>'roundId'=rid AND (all_items OR a->>'itemId' IS NOT DISTINCT FROM item_id) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'classifications') c WHERE c->>'attemptId'=a->>'id') $$;
CREATE FUNCTION public.int9_review(s JSONB) RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT s->'openItemReview' IS DISTINCT FROM 'null'::JSONB OR s->'correctionReview' IS DISTINCT FROM 'null'::JSONB $$;
CREATE FUNCTION public.int9_items(r JSONB) RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT r->'pin'->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') $$;
CREATE FUNCTION public.int9_standalone(s JSONB) RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT s->'request'->>'executionFormat' IN ('STANDALONE_LIST','STANDALONE_ACTING') $$;
CREATE FUNCTION public.int9_snapshot(r JSONB) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('phase',r->'phase','phaseOrdinal',r->'phaseOrdinal','generation',r->'generation','currentTeamId',r->'currentTeamId','deadline',r->'deadline','overallDeadline',r->'overallDeadline','pause',r->'pause') $$;
CREATE OR REPLACE FUNCTION public.int9_event(s JSONB,cid TEXT,hash TEXT,kind TEXT,rid TEXT,authority JSONB,moment DOUBLE PRECISION,reason TEXT) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE event_id TEXT; BEGIN IF (s->>'version')::INTEGER>=64946 THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF; event_id:=gen_random_uuid()::TEXT; RETURN s||jsonb_build_object('version',(s->>'version')::INTEGER+1,'events',s->'events'||jsonb_build_array(jsonb_build_object('id',event_id,'commandId',cid,'hash',hash,'sequence',(s->>'version')::INTEGER+1,'type',kind,'roundId',rid,'authority',authority,'at',moment,'pauseReason',reason))); END $$;
CREATE FUNCTION public.int9_host_event(s JSONB,c JSONB,rid TEXT,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE SQL SET search_path=pg_catalog AS $$ SELECT public.int9_event(s,c->>'commandId',public.int6_enta_hash(c),c->>'type',rid,jsonb_build_object('kind','HOST','identityId',s->>'identityId'),moment,c->>'reason') $$;
CREATE OR REPLACE FUNCTION public.int9_effect(s JSONB,r JSONB,kind TEXT,options JSONB) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE effect JSONB; next_sequence INTEGER; BEGIN
 next_sequence:=(CASE WHEN s ? 'factContext' THEN (s->'factContext'->>'effectSequence')::INTEGER+1 ELSE jsonb_array_length(s->'effects')+1 END);
 IF next_sequence>64945 THEN PERFORM public.int9_error('EFFECT_BUDGET_EXCEEDED'); END IF;
 effect:=jsonb_build_object('id',gen_random_uuid()::TEXT,'eventId',s->'events'->-1->>'id','sequence',next_sequence,'roundId',r->>'id','kind',kind,'aid',NULL,'amountKind','NONE','reversible',FALSE,'barrier',TRUE,'reads','[]'::JSONB,'dependencies','[]'::JSONB,'postingIds','[]'::JSONB,'beforeClock',NULL,'afterClock',CASE WHEN r IS NULL THEN 'null'::JSONB ELSE public.int9_snapshot(r) END,'originalAttemptIds','[]'::JSONB,'correctAttemptIds','[]'::JSONB,'bonusSnapshot','[]'::JSONB,'predecessorId',NULL,'predecessorHash',NULL,'reason',NULL,'hash','')||options;
 IF s ? 'factContext' THEN s:=jsonb_set(s,'{factContext,effectSequence}',to_jsonb(next_sequence)); END IF;
 RETURN s||jsonb_build_object('effects',s->'effects'||jsonb_build_array(effect),'latestEffectId',effect->'id');
END $$;
CREATE FUNCTION public.int9_effect_hash(effect JSONB) RETURNS TEXT LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE keys TEXT[]:=ARRAY['afterClock','aid','amountKind','barrier','beforeClock','bonusSnapshot','correctAttemptIds','dependencies','eventId','id','kind','originalAttemptIds','postingIds','predecessorHash','predecessorId','reads','reason','reversible','roundId','sequence']; key TEXT; member JSONB; part TEXT; first_key BOOLEAN:=TRUE; first_member BOOLEAN; material TEXT:='{"domain":"maydan.enta.effect.v1","payload":{'; bytes BYTEA; BEGIN
 IF public.int6_enta_exact_keys(effect,ARRAY['afterClock','aid','amountKind','barrier','beforeClock','bonusSnapshot','correctAttemptIds','dependencies','eventId','id','kind','originalAttemptIds','postingIds','predecessorHash','predecessorId','reads','reason','reversible','roundId','sequence','hash']) IS NOT TRUE THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['reads','dependencies','postingIds','originalAttemptIds','correctAttemptIds','bonusSnapshot']) field WHERE jsonb_typeof(effect->field) IS DISTINCT FROM 'array') THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF jsonb_array_length(effect->'reads')>8 OR jsonb_array_length(effect->'dependencies')>8 OR jsonb_array_length(effect->'postingIds')>4 OR jsonb_array_length(effect->'originalAttemptIds')>512 OR jsonb_array_length(effect->'correctAttemptIds')>512 OR jsonb_array_length(effect->'bonusSnapshot')>512 THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 FOREACH key IN ARRAY keys LOOP
  part:=(CASE WHEN first_key THEN '' ELSE ',' END)||to_jsonb(key)::TEXT||':'; material:=material||part; part:=NULL; first_key:=FALSE;
  IF key=ANY(ARRAY['reads','dependencies','postingIds','originalAttemptIds','correctAttemptIds','bonusSnapshot']) THEN
   part:='['; material:=material||part; part:=NULL; first_member:=TRUE;
   FOR member IN SELECT value FROM jsonb_array_elements(effect->key) WITH ORDINALITY members(value,ordinal) ORDER BY ordinal LOOP
    part:=(CASE WHEN first_member THEN '' ELSE ',' END)||public.int6_enta_canonical(member); material:=material||part; part:=NULL; member:=NULL; first_member:=FALSE;
   END LOOP;
   part:=']'; material:=material||part; part:=NULL;
  ELSE part:=public.int6_enta_canonical(effect->key); material:=material||part; part:=NULL; END IF;
 END LOOP;
 part:='}}'; material:=material||part; effect:=NULL; member:=NULL; part:=NULL; key:=NULL; keys:=NULL;
 bytes:=convert_to(material,'UTF8'); material:=NULL; RETURN encode(int4_crypto.digest(bytes,'sha256'),'hex');
END $$;
CREATE FUNCTION public.int9_seal(s JSONB) RETURNS JSONB LANGUAGE SQL SET search_path=pg_catalog AS $$ SELECT jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT,'hash'],to_jsonb(public.int9_effect_hash(s->'effects'->-1))) $$;
CREATE FUNCTION public.int9_read(t JSONB,kind TEXT) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('teamId',t->'id','scoreVersion',t->'scoreVersion','value',t->'score','sourceEffectId',t->'scoreHead','kind',kind) $$;
CREATE FUNCTION public.int9_post(s JSONB,tid TEXT,delta BIGINT,clamped BOOLEAN) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE t JSONB; effect JSONB; posting JSONB; read JSONB; after_score BIGINT; idx INTEGER; BEGIN
 SELECT x,ord::INTEGER-1 INTO t,idx FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'=tid; IF t IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 effect:=s->'effects'->-1; IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'postings') p WHERE p->>'effectId'=effect->>'id' AND p->>'teamId'=tid) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 after_score:=(t->>'score')::BIGINT+delta; IF clamped THEN after_score:=greatest(0,after_score); END IF;
 IF after_score NOT BETWEEN -2147483648 AND 2147483647 OR NOT public.int9_standalone(s) AND after_score<0 THEN PERFORM public.int9_error('SCORE_BOUND_EXCEEDED'); END IF;
 read:=public.int9_read(t,CASE WHEN clamped THEN 'CLAMP' ELSE 'BASE' END);
 effect:=effect||jsonb_build_object('reads',effect->'reads'||jsonb_build_array(read),'dependencies',CASE WHEN read->>'sourceEffectId' IS NOT NULL AND NOT effect->'dependencies' ? (read->>'sourceEffectId') THEN effect->'dependencies'||jsonb_build_array(read->>'sourceEffectId') ELSE effect->'dependencies' END);
 posting:=jsonb_build_object('id',gen_random_uuid()::TEXT,'effectId',effect->'id','teamId',tid,'delta',after_score-(t->>'score')::BIGINT,'before',t->'score','after',after_score,'scoreVersion',(t->>'scoreVersion')::INTEGER+1,'previousHead',t->'scoreHead');
 effect:=effect||jsonb_build_object('postingIds',effect->'postingIds'||jsonb_build_array(posting->'id')); t:=t||jsonb_build_object('score',after_score,'scoreVersion',(t->>'scoreVersion')::INTEGER+1,'scoreHead',effect->'id');
 s:=jsonb_set(s,ARRAY['teams',idx::TEXT],t); s:=jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT],effect); RETURN s||jsonb_build_object('postings',s->'postings'||jsonb_build_array(posting));
END $$;
CREATE OR REPLACE FUNCTION public.int9_invalidate(s JSONB,r JSONB,advance BOOLEAN) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE grants JSONB; scopes JSONB; rounds JSONB; changed_round JSONB; patch JSONB; result JSONB; BEGIN
 SELECT COALESCE(jsonb_agg(CASE WHEN x->>'roundId'=r->>'id' THEN jsonb_set(x,'{revoked}','true'::JSONB) ELSE x END ORDER BY ord),'[]'::JSONB) INTO grants FROM jsonb_array_elements(s->'grants') WITH ORDINALITY rows(x,ord);
 SELECT COALESCE(jsonb_agg(CASE WHEN x->>'roundId'=r->>'id' THEN x||jsonb_build_object('activeGrantId',NULL,'generation',(x->>'generation')::INTEGER+(CASE WHEN advance THEN 1 ELSE 0 END)) ELSE x END ORDER BY ord),'[]'::JSONB) INTO scopes FROM jsonb_array_elements(s->'grantScopes') WITH ORDINALITY rows(x,ord);
 changed_round:=r||jsonb_build_object('assignment',NULL);
 SELECT jsonb_agg(CASE WHEN x->'id'=r->'id' THEN changed_round ELSE x END ORDER BY ord) INTO rounds FROM jsonb_array_elements(s->'rounds') WITH ORDINALITY rows(x,ord);
 changed_round:=NULL;
 -- int8_put_round has no COALESCE: empty/missing rounds returns SQL NULL.
 IF rounds IS NULL THEN grants:=NULL; scopes:=NULL; RETURN NULL; END IF;
 patch:=jsonb_build_object('grants',grants,'grantScopes',scopes,'rounds',rounds);
 grants:=NULL; scopes:=NULL; rounds:=NULL;
 result:=s||patch; patch:=NULL; RETURN result;
END $$;
CREATE FUNCTION public.int9_close(s JSONB,r JSONB,reason TEXT) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF jsonb_array_length(public.int9_pending(s,r->>'id',NULL,TRUE))<>0 THEN PERFORM public.int9_error('PENDING_RULING_REQUIRED'); END IF;
 s:=s||jsonb_build_object('activeRoundId',NULL,'turnIndex',(s->>'turnIndex')::INTEGER+(CASE WHEN (r->>'turnAdvanced')::BOOLEAN THEN 0 ELSE 1 END));
 r:=r||jsonb_build_object('phase','RESOLVED','reason',reason,'pause',NULL,'deadline',NULL,'overallDeadline',NULL,'version',(r->>'version')::INTEGER+1,'turnAdvanced',TRUE); RETURN public.int9_invalidate(s,r,FALSE);
END $$;
CREATE FUNCTION public.int9_team_ids(attempts JSONB) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT COALESCE(jsonb_agg(x->'id' ORDER BY ord),'[]'::JSONB) FROM jsonb_array_elements(attempts) WITH ORDINALITY items(x,ord) $$;
CREATE FUNCTION public.int9_bonus(attempts JSONB) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT COALESCE(jsonb_agg(jsonb_build_object('attemptId',x->'id','teamId',x->'teamId','multiplier',x->'bonusMultiplier','sourceEventId',x->'bonusEventId') ORDER BY ord),'[]'::JSONB) FROM jsonb_array_elements(attempts) WITH ORDINALITY items(x,ord) $$;
CREATE FUNCTION public.int9_head(s JSONB,r JSONB,item_id TEXT) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE effect JSONB:=s->'effects'->-1; scope TEXT:=public.int6_enta_canonical(jsonb_build_array(r->>'id',item_id)); BEGIN
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'rulings') h WHERE h->>'scopeId'=scope) THEN PERFORM public.int9_error('RULING_ALREADY_FINAL'); END IF;
 RETURN s||jsonb_build_object('rulings',s->'rulings'||jsonb_build_array(jsonb_build_object('roundId',r->'id','itemId',item_id,'scopeId',scope,'originalEffectId',effect->'id','effectId',effect->'id','version',1,'hash',effect->'hash','reversed',FALSE)));
END $$;
CREATE FUNCTION public.int9_recording_closed(s JSONB,r JSONB,moment DOUBLE PRECISION,anchor DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE before_clock JSONB:=public.int9_snapshot(r); pending JSONB; originals JSONB; BEGIN
 r:=r||jsonb_build_object('deadline',NULL,'overallDeadline',NULL,'version',(r->>'version')::INTEGER+1); s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id'); pending:=public.int9_pending(s,r->>'id',NULL,TRUE);
 s:=public.int9_event(s,'clock-'||(r->>'id')||'-'||(r->>'generation')||'-'||(s->>'version'),public.int6_enta_hash(jsonb_build_object('type','RECORDING_CLOSED','roundId',r->'id','generation',r->'generation','anchor',anchor,'moment',moment)),'RECORDING_CLOSED',r->>'id',jsonb_build_object('kind','SYSTEM','operation','CLOCK_SETTLEMENT'),moment,NULL);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'itemReviews') review WHERE review->>'id'=s->>'openItemReview' AND review->>'roundId'=r->>'id') THEN
  s:=s||jsonb_build_object('activeRoundId',NULL,'turnIndex',(s->>'turnIndex')::INTEGER+(CASE WHEN (r->>'turnAdvanced')::BOOLEAN THEN 0 ELSE 1 END)); r:=r||jsonb_build_object('phase',CASE WHEN jsonb_array_length(pending)>0 THEN 'AWAITING_RULING' ELSE 'RESOLVED' END,'reason','TIME_EXPIRED','turnAdvanced',TRUE); s:=public.int8_put_round(s,r); RETURN public.int9_seal(public.int9_effect(s,r,'TIMING',jsonb_build_object('beforeClock',before_clock)));
 END IF;
 IF jsonb_array_length(pending)>0 THEN r:=r||jsonb_build_object('phase','AWAITING_RULING'); s:=public.int8_put_round(s,r); RETURN public.int9_seal(public.int9_effect(s,r,'TIMING',jsonb_build_object('beforeClock',before_clock))); END IF;
 SELECT COALESCE(jsonb_agg(x ORDER BY ord),'[]'::JSONB) INTO originals FROM jsonb_array_elements(s->'attempts') WITH ORDINALITY attempts(x,ord) WHERE x->>'roundId'=r->>'id';
 s:=public.int9_effect(s,r,'NO_SCORE',jsonb_build_object('reversible',NOT public.int9_items(r),'beforeClock',before_clock,'originalAttemptIds',public.int9_team_ids(originals),'bonusSnapshot',public.int9_bonus(originals))); s:=public.int9_close(s,r,'TIME_EXPIRED'); r:=public.int9_round(s,r->>'id'); s:=jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT,'afterClock'],public.int9_snapshot(r)); RETURN public.int9_head(public.int9_seal(s),r,NULL);
END $$;
CREATE OR REPLACE FUNCTION public.int9_clock(s JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r JSONB; before_clock JSONB; anchor DOUBLE PRECISION; elapsed BIGINT; interval_ms INTEGER; team_index INTEGER; kind TEXT; prospective_deadline DOUBLE PRECISION; required INTEGER; system_used BIGINT; phone BOOLEAN; stop_reason TEXT; BEGIN
 r:=public.int9_round(s,s->>'activeRoundId'); IF r IS NULL OR (s->>'finished')::BOOLEAN THEN RETURN s; END IF;
 IF r->'resourceStop' IS DISTINCT FROM 'null'::JSONB THEN RETURN s; END IF;
 phone:=r->'pause'->>'cause'='PHONE' AND r->'pause'->>'resumeAt' IS NOT NULL AND moment>=(r->'pause'->>'resumeAt')::DOUBLE PRECISION;
 prospective_deadline:=(CASE WHEN phone THEN CASE WHEN r->'pause'->'phaseRemaining'='null'::JSONB THEN NULL ELSE (r->'pause'->>'resumeAt')::DOUBLE PRECISION+(r->'pause'->>'phaseRemaining')::DOUBLE PRECISION END ELSE (r->>'deadline')::DOUBLE PRECISION END);
 required:=(CASE WHEN phone THEN 1 ELSE 0 END)+(CASE WHEN prospective_deadline IS NOT NULL AND moment>=prospective_deadline THEN CASE WHEN r->>'phase' IN ('MAIN','TRAP') AND moment>=prospective_deadline+10000 THEN 2 ELSE 1 END ELSE 0 END);
 elapsed:=(CASE WHEN r->>'phase'='TURN' AND prospective_deadline IS NOT NULL AND moment>=prospective_deadline THEN floor((moment-prospective_deadline)/((s->'request'->'setup'->'rules'->>'turnSeconds')::INTEGER*1000))+1 ELSE 0 END);
 SELECT count(*) INTO system_used FROM public."RoundAuthorityEvent" e WHERE e."gameId"=s->>'id' AND e."roundId"=r->>'id' AND e."authorityKind"='SYSTEM' AND e."type"<>'RESOURCE_LIMIT_REACHED';
 IF system_used+required>256 OR (r->>'generation')::BIGINT>=2000000000 OR (r->>'phaseOrdinal')::BIGINT>=2000000000 OR moment<0 OR moment>9007199254740991 OR moment<>floor(moment) OR elapsed>9007199254740991 OR (r->>'generation')::BIGINT+elapsed>2000000000 OR (r->>'phaseOrdinal')::BIGINT+elapsed>2000000000 THEN
  stop_reason:=(CASE WHEN system_used+required>256 THEN 'SYSTEM_CAPACITY' ELSE 'GENERATION_BOUND' END);
  s:=public.int9_event(s,'resource-'||(r->>'id'),public.int6_enta_hash(jsonb_build_object('roundId',r->'id','reason',stop_reason,'generation',r->'generation')),'RESOURCE_LIMIT_REACHED',r->>'id',jsonb_build_object('kind','SYSTEM','operation','CLOCK_SETTLEMENT'),moment,NULL);
  r:=r||jsonb_build_object('resourceStop',jsonb_build_object('eventId',s->'events'->-1->'id','at',moment,'reason',stop_reason),'version',(r->>'version')::INTEGER+1); s:=public.int8_put_round(public.int8_invalidate(s,r->>'id'),r); RETURN public.int9_seal(public.int9_effect(s,r,'TIMING','{}'::JSONB));
 END IF;
 IF r->'pause' IS DISTINCT FROM 'null'::JSONB THEN
  IF r->'pause'->>'cause'<>'PHONE' OR moment<(r->'pause'->>'resumeAt')::DOUBLE PRECISION THEN RETURN s; END IF;
  before_clock:=public.int9_snapshot(r); anchor:=(r->'pause'->>'resumeAt')::DOUBLE PRECISION; r:=r||jsonb_build_object('deadline',CASE WHEN r->'pause'->'phaseRemaining'='null'::JSONB THEN NULL ELSE anchor+(r->'pause'->>'phaseRemaining')::DOUBLE PRECISION END,'overallDeadline',CASE WHEN r->'pause'->'overallRemaining'='null'::JSONB THEN NULL ELSE anchor+(r->'pause'->>'overallRemaining')::DOUBLE PRECISION END,'pause',NULL,'version',(r->>'version')::INTEGER+1);
  s:=public.int8_put_round(s,r); s:=public.int9_event(s,'clock-'||(r->>'id')||'-'||(r->>'generation')||'-'||(s->>'version'),public.int6_enta_hash(jsonb_build_object('type','PHONE_ENDED','roundId',r->'id','generation',r->'generation','anchor',anchor,'moment',moment)),'PHONE_ENDED',r->>'id',jsonb_build_object('kind','SYSTEM','operation','CLOCK_SETTLEMENT'),moment,NULL); s:=public.int9_seal(public.int9_effect(s,r,'TIMING',jsonb_build_object('beforeClock',before_clock)));
 END IF;
 IF r->'deadline'='null'::JSONB OR r->>'phase' IN ('AWAITING_RULING','RESOLVED') THEN RETURN s; END IF;
 IF r->'overallDeadline'<>'null'::JSONB AND moment>=(r->>'overallDeadline')::DOUBLE PRECISION THEN RETURN public.int9_recording_closed(s,r,moment,(r->>'overallDeadline')::DOUBLE PRECISION); END IF;
 IF moment<(r->>'deadline')::DOUBLE PRECISION THEN RETURN s; END IF; anchor:=(r->>'deadline')::DOUBLE PRECISION; before_clock:=public.int9_snapshot(r);
 IF r->>'phase' IN ('MAIN','TRAP') THEN
  r:=r||jsonb_build_object('phase','STEAL','phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+1,'generation',(r->>'generation')::INTEGER+1,'deadline',anchor+10000,'currentTeamId',NULL,'pickedPlayerId',NULL,'pickedEventId',NULL,'doubleAttemptTeamId',NULL,'version',(r->>'version')::INTEGER+1); s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id'); kind:='STEAL_OPENED';
 ELSIF r->>'phase' IN ('STEAL','SHARED') THEN RETURN public.int9_recording_closed(s,r,moment,anchor);
 ELSIF r->>'phase'='TURN' AND public.int9_standalone(s) THEN
  interval_ms:=(s->'request'->'setup'->'rules'->>'turnSeconds')::INTEGER*1000; elapsed:=floor((moment-anchor)/interval_ms)::BIGINT+1; SELECT ord::INTEGER-1 INTO team_index FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'=r->>'currentTeamId';
  r:=r||jsonb_build_object('currentTeamId',s->'teams'->(((team_index+elapsed)%jsonb_array_length(s->'teams'))::INTEGER)->'id','deadline',anchor+elapsed::DOUBLE PRECISION*interval_ms,'phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+elapsed,'generation',(r->>'generation')::INTEGER+elapsed,'doubleAttemptTeamId',NULL,'version',(r->>'version')::INTEGER+1); s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id'); kind:='TURN_TRANSFERRED';
 ELSE PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 s:=public.int9_event(s,'clock-'||(r->>'id')||'-'||(r->>'generation')||'-'||(s->>'version'),public.int6_enta_hash(jsonb_build_object('type',kind,'roundId',r->'id','generation',r->'generation','anchor',anchor,'moment',moment)),kind,r->>'id',jsonb_build_object('kind','SYSTEM','operation','CLOCK_SETTLEMENT'),moment,NULL); s:=public.int9_seal(public.int9_effect(s,r,'TIMING',jsonb_build_object('beforeClock',before_clock)));
 IF kind='STEAL_OPENED' AND moment>=(r->>'deadline')::DOUBLE PRECISION THEN s:=public.int9_recording_closed(s,r,moment,(r->>'deadline')::DOUBLE PRECISION); END IF; RETURN s;
END $$;
CREATE FUNCTION public.int9_players(s JSONB,r JSONB,tid TEXT) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT COALESCE(jsonb_agg(player ORDER BY ord),'[]'::JSONB) FROM jsonb_array_elements(s->'teams') team CROSS JOIN LATERAL jsonb_array_elements(team->'players') WITH ORDINALITY players(player,ord) WHERE team->>'id'=tid AND (r->'pin'->>'format'<>'DRAWING_TARGET' OR (player->>'id' IS DISTINCT FROM r->'assignment'->>'playerId' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'disclosures') d WHERE d->>'roundId'=r->>'id' AND d->>'playerId'=player->>'id'))) $$;
CREATE FUNCTION public.int9_transfer(s JSONB,r JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE idx INTEGER; BEGIN
 SELECT ord::INTEGER-1 INTO idx FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'=r->>'currentTeamId';
 r:=r||jsonb_build_object('currentTeamId',s->'teams'->((idx+1)%jsonb_array_length(s->'teams'))->'id','phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+1,'generation',(r->>'generation')::INTEGER+1,'doubleAttemptTeamId',NULL,'deadline',moment+(s->'request'->'setup'->'rules'->>'turnSeconds')::INTEGER*1000,'version',(r->>'version')::INTEGER+1); RETURN public.int9_invalidate(s,r,FALSE);
END $$;

CREATE FUNCTION public.int9_aids(fmt TEXT,family TEXT) RETURNS TEXT[] LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE
 WHEN fmt IN ('STANDALONE_LIST','STANDALONE_ACTING') AND family=(CASE fmt WHEN 'STANDALONE_LIST' THEN 'LIST_ITEMS' ELSE 'ACTING_ITEMS' END) THEN ARRAY['HINT','PASS','FREEZE','DOUBLE','PHONE']
 WHEN fmt='TIER_BOARD' AND family='ORDINARY_TIER' OR fmt='MIXED_BOARD' AND family IN ('ORDINARY_TIER','DRAWING_TARGET') THEN ARRAY['PHONE_A_FRIEND','DOUBLE_ANSWER','MORE_HINT','TRAP','PICK_ANSWERER','STEAL_POINTS','DOUBLE_POINTS']
 WHEN fmt='MIXED_BOARD' AND family IN ('LIST_ITEMS','ACTING_ITEMS') THEN ARRAY['PHONE_A_FRIEND','MORE_HINT','PICK_ANSWERER','STEAL_POINTS'] ELSE ARRAY[]::TEXT[] END $$;
CREATE FUNCTION public.int9_palette() RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT '{"CORAL":{"label":"مرجاني","color":"#ff7a4d"},"SKY":{"label":"سماوي","color":"#3fc6ff"},"VIOLET":{"label":"بنفسجي","color":"#7c5cff"},"MINT":{"label":"نعناعي","color":"#34d399"},"GOLD":{"label":"ذهبي","color":"#ffc94d"},"ROSE":{"label":"وردي","color":"#ff5c72"}}'::JSONB $$;
CREATE FUNCTION public.int9_palette_root() RETURNS TEXT LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT public.int6_enta_hash(jsonb_build_object('version','enta-team-palette-1','entries','[{"key":"CORAL","color":"#ff7a4d"},{"key":"SKY","color":"#3fc6ff"},{"key":"VIOLET","color":"#7c5cff"},{"key":"MINT","color":"#34d399"},{"key":"GOLD","color":"#ffc94d"},{"key":"ROSE","color":"#ff5c72"}]'::JSONB)) $$;
CREATE FUNCTION public.int9_valid_request(request JSONB) RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE s JSONB:=request->'setup'; rules JSONB:=s->'rules'; t JSONB; cat JSONB; fmt TEXT:=request->>'executionFormat'; standalone BOOLEAN:=fmt IN ('STANDALONE_LIST','STANDALONE_ACTING'); all_aids TEXT[]; BEGIN
 IF public.int6_enta_exact_keys(request,ARRAY['version','requestKey','logicalMatchId','operation','executionFormat','predecessor','setup']) IS NOT TRUE OR request->'version' IS DISTINCT FROM '5'::JSONB OR request->'predecessor' IS DISTINCT FROM 'null'::JSONB OR fmt IS NULL OR fmt NOT IN ('TIER_BOARD','MIXED_BOARD','STANDALONE_LIST','STANDALONE_ACTING') OR jsonb_typeof(request->'requestKey') IS DISTINCT FROM 'string' OR COALESCE(request->>'requestKey'~'^[A-Za-z0-9._:-]{8,128}$',FALSE) IS NOT TRUE OR public.int8_json_id(request->'logicalMatchId') IS NOT TRUE OR request->>'operation' IS DISTINCT FROM (CASE fmt WHEN 'STANDALONE_LIST' THEN 'PAID_ENTA_LIST' WHEN 'STANDALONE_ACTING' THEN 'PAID_ENTA_ACTING' ELSE 'PAID_ENTA_CLASSIC' END) THEN RETURN FALSE; END IF;
 IF public.int6_enta_exact_keys(s,ARRAY['version','categories','teams','rules']) IS NOT TRUE OR s->'version' IS DISTINCT FROM '5'::JSONB OR public.int6_enta_exact_keys(rules,ARRAY['version','paletteVersion','questionSeconds','turnSeconds','overallSeconds','stealSeconds','phoneSeconds','embeddedStealCap']) IS NOT TRUE OR rules->>'version' IS DISTINCT FROM 'enta-competitive-1' OR rules->>'paletteVersion' IS DISTINCT FROM 'enta-team-palette-1' OR public.int5b_json_integer(rules->'questionSeconds',5,120) IS NOT TRUE OR rules->'turnSeconds' NOT IN ('15'::JSONB,'30'::JSONB,'45'::JSONB) OR rules->'overallSeconds' NOT IN ('null'::JSONB,'300'::JSONB,'600'::JSONB) OR rules->'stealSeconds' IS DISTINCT FROM '10'::JSONB OR rules->'phoneSeconds' IS DISTINCT FROM '60'::JSONB OR rules->'embeddedStealCap' IS DISTINCT FROM '200'::JSONB THEN RETURN FALSE; END IF;
 IF jsonb_typeof(s->'categories') IS DISTINCT FROM 'array' OR jsonb_array_length(s->'categories')<>(CASE WHEN standalone THEN 1 ELSE 6 END) OR jsonb_typeof(s->'teams') IS DISTINCT FROM 'array' OR jsonb_array_length(s->'teams') NOT BETWEEN 2 AND (CASE WHEN standalone THEN 2 ELSE 4 END) THEN RETURN FALSE; END IF;
 FOR cat IN SELECT x FROM jsonb_array_elements(s->'categories') x LOOP IF public.int6_enta_exact_keys(cat,ARRAY['key','promptRefs']) IS NOT TRUE OR public.int8_json_id(cat->'key') IS NOT TRUE OR jsonb_typeof(cat->'promptRefs') IS DISTINCT FROM 'array' OR jsonb_array_length(cat->'promptRefs')>6 OR (standalone OR fmt='TIER_BOARD') AND cat->'promptRefs'<>'[]'::JSONB OR EXISTS(SELECT 1 FROM jsonb_array_elements(cat->'promptRefs') ref WHERE public.int8_json_id(ref) IS NOT TRUE) OR (SELECT count(DISTINCT ref) FROM jsonb_array_elements(cat->'promptRefs') ref)<>jsonb_array_length(cat->'promptRefs') THEN RETURN FALSE; END IF; END LOOP;
 IF (SELECT count(DISTINCT x->>'key') FROM jsonb_array_elements(s->'categories') x)<>jsonb_array_length(s->'categories') THEN RETURN FALSE; END IF;
 all_aids:=(CASE WHEN standalone THEN ARRAY['HINT','PASS','FREEZE','DOUBLE','PHONE'] ELSE ARRAY['PHONE_A_FRIEND','DOUBLE_ANSWER','MORE_HINT','TRAP','PICK_ANSWERER','STEAL_POINTS','DOUBLE_POINTS'] END);
 FOR t IN SELECT x FROM jsonb_array_elements(s->'teams') x LOOP IF public.int6_enta_exact_keys(t,ARRAY['name','colorKey','players','aids']) IS NOT TRUE OR public.int6_enta_valid_text(t->'name',2,22) IS NOT TRUE OR jsonb_typeof(t->'colorKey') IS DISTINCT FROM 'string' OR NOT public.int9_palette() ? (t->>'colorKey') OR jsonb_typeof(t->'players') IS DISTINCT FROM 'array' OR jsonb_array_length(t->'players') NOT BETWEEN 1 AND 8 OR EXISTS(SELECT 1 FROM jsonb_array_elements(t->'players') p WHERE public.int6_enta_valid_text(p,1,30) IS NOT TRUE) OR (SELECT count(DISTINCT p) FROM jsonb_array_elements(t->'players') p)<>jsonb_array_length(t->'players') OR jsonb_typeof(t->'aids') IS DISTINCT FROM 'array' OR jsonb_array_length(t->'aids')<>3 OR (SELECT count(DISTINCT aid) FROM jsonb_array_elements(t->'aids') aid)<>3 OR EXISTS(SELECT 1 FROM jsonb_array_elements(t->'aids') aid WHERE jsonb_typeof(aid) IS DISTINCT FROM 'string' OR NOT (aid#>>'{}')=ANY(all_aids)) THEN RETURN FALSE; END IF; END LOOP;
 IF (SELECT count(DISTINCT translate(x->>'name','ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz')) FROM jsonb_array_elements(s->'teams') x)<>jsonb_array_length(s->'teams') THEN RETURN FALSE; END IF; RETURN TRUE;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN FALSE;
END $$;
CREATE FUNCTION public.int9_valid_command(c JSONB,capability BOOLEAN) RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE kind TEXT:=c->>'type'; fields TEXT[]; value JSONB; key TEXT; BEGIN
 IF capability THEN RETURN public.int8_valid_command(c,TRUE); END IF;
 fields:=(CASE kind WHEN 'OPEN_ROUND' THEN ARRAY['roundId'] WHEN 'NEXT_ROUND' THEN ARRAY[]::TEXT[] WHEN 'USE_AID' THEN ARRAY['roundId','teamId','aid'] WHEN 'RECORD_ATTEMPT' THEN ARRAY['roundId','teamId','playerId','itemId'] WHEN 'INTERIM_WRONG' THEN ARRAY['roundId','attemptId'] WHEN 'PUBLIC_REVEAL' THEN ARRAY['roundId','itemId'] WHEN 'FINAL_RULING' THEN ARRAY['roundId','itemId','classifications'] WHEN 'REVEAL_HINT' THEN ARRAY['roundId'] WHEN 'END_ASSISTANCE' THEN ARRAY['roundId'] WHEN 'RESUME_ROUND' THEN ARRAY['roundId'] WHEN 'CLOSE_ROUND' THEN ARRAY['roundId'] WHEN 'PAUSE_ROUND' THEN ARRAY['roundId','reason'] WHEN 'SELECT_SCORING_TEAM' THEN ARRAY['roundId','teamId'] WHEN 'ASSIGN_ACTOR' THEN ARRAY['roundId','teamId','playerId','itemId'] WHEN 'CREATE_GRANT' THEN ARRAY['roundId','role','durationSeconds'] WHEN 'ROTATE_GRANT' THEN ARRAY['roundId','scopeId','expectedGeneration','durationSeconds'] WHEN 'REVOKE_GRANT' THEN ARRAY['roundId','scopeId'] WHEN 'UNDO_EFFECT' THEN ARRAY['effectId','effectHash'] WHEN 'CORRECT_RULING' THEN ARRAY['effectId','rulingVersion','correctAttemptIds','reason'] WHEN 'RESOLVE_ITEM_REVIEW' THEN ARRAY['reviewId','reviewHash','rulingVersion','mode','correctAttemptIds','reason'] WHEN 'REPORT_VAR' THEN ARRAY['roundId','effectId','blockingIds','reason'] WHEN 'FINISH' THEN ARRAY['confirmEarly'] WHEN 'RESOLVE_TIE' THEN ARRAY['resultHash'] ELSE NULL END);
 IF fields IS NULL OR public.int6_enta_exact_keys(c,ARRAY['type','commandId','expectedVersion']||fields) IS NOT TRUE OR jsonb_typeof(c->'type') IS DISTINCT FROM 'string' OR jsonb_typeof(c->'commandId') IS DISTINCT FROM 'string' OR COALESCE(c->>'commandId'~'^[A-Za-z0-9._:-]{8,128}$',FALSE) IS NOT TRUE OR public.int5b_json_integer(c->'expectedVersion',1,2000000000) IS NOT TRUE THEN RETURN FALSE; END IF;
 FOREACH key IN ARRAY ARRAY['roundId','teamId','playerId','attemptId','scopeId','reviewId'] LOOP IF c ? key AND public.int8_json_id(c->key) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
 FOREACH key IN ARRAY ARRAY['itemId','effectId'] LOOP IF c ? key AND c->key IS DISTINCT FROM 'null'::JSONB AND public.int8_json_id(c->key) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
 IF kind='USE_AID' AND (jsonb_typeof(c->'aid') IS DISTINCT FROM 'string' OR c->>'aid' NOT IN ('PHONE_A_FRIEND','DOUBLE_ANSWER','MORE_HINT','TRAP','PICK_ANSWERER','STEAL_POINTS','DOUBLE_POINTS','HINT','PASS','FREEZE','DOUBLE','PHONE')) OR kind='CREATE_GRANT' AND (jsonb_typeof(c->'role') IS DISTINCT FROM 'string' OR c->>'role' NOT IN ('JUDGE','ACTOR')) THEN RETURN FALSE; END IF;
 IF kind IN ('CREATE_GRANT','ROTATE_GRANT') AND public.int5b_json_integer(c->'durationSeconds',1,600) IS NOT TRUE OR kind='ROTATE_GRANT' AND public.int5b_json_integer(c->'expectedGeneration',1,2000000000) IS NOT TRUE OR kind='FINISH' AND jsonb_typeof(c->'confirmEarly') IS DISTINCT FROM 'boolean' OR c ? 'reason' AND public.int6_enta_valid_text(c->'reason',3,240) IS NOT TRUE THEN RETURN FALSE; END IF;
 FOREACH key IN ARRAY ARRAY['effectHash','resultHash','reviewHash'] LOOP IF c ? key AND (jsonb_typeof(c->key) IS DISTINCT FROM 'string' OR COALESCE(c->>key~'^[a-f0-9]{64}$',FALSE) IS NOT TRUE) THEN RETURN FALSE; END IF; END LOOP;
 IF kind IN ('UNDO_EFFECT','CORRECT_RULING') AND public.int8_json_id(c->'effectId') IS NOT TRUE OR c ? 'rulingVersion' AND public.int5b_json_integer(c->'rulingVersion',1,2000000000) IS NOT TRUE THEN RETURN FALSE; END IF;
 FOREACH key IN ARRAY ARRAY['correctAttemptIds','blockingIds'] LOOP IF c ? key THEN IF jsonb_typeof(c->key) IS DISTINCT FROM 'array' OR jsonb_array_length(c->key)>(CASE key WHEN 'blockingIds' THEN 32 ELSE 512 END) OR EXISTS(SELECT 1 FROM jsonb_array_elements(c->key) id WHERE CASE WHEN key='blockingIds' THEN public.int8_json_id(id) ELSE jsonb_typeof(id)='string' AND (id#>>'{}')~'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' END IS NOT TRUE) OR (SELECT count(DISTINCT id) FROM jsonb_array_elements(c->key) id)<>jsonb_array_length(c->key) THEN RETURN FALSE; END IF; END IF; END LOOP;
 IF kind='RESOLVE_ITEM_REVIEW' AND (jsonb_typeof(c->'mode') IS DISTINCT FROM 'string' OR c->>'mode' NOT IN ('RESTORE_ORIGINAL','REPLACE') OR c->>'mode'='RESTORE_ORIGINAL' AND c->'correctAttemptIds'<>'[]'::JSONB) THEN RETURN FALSE; END IF;
 IF kind='FINAL_RULING' THEN IF jsonb_typeof(c->'classifications') IS DISTINCT FROM 'array' OR jsonb_array_length(c->'classifications')>512 THEN RETURN FALSE; END IF; FOR value IN SELECT x FROM jsonb_array_elements(c->'classifications') x LOOP IF jsonb_typeof(value) IS DISTINCT FROM 'array' OR jsonb_array_length(value)<>2 OR jsonb_typeof(value->0) IS DISTINCT FROM 'string' OR COALESCE(value->>0~'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$',FALSE) IS NOT TRUE OR jsonb_typeof(value->1) IS DISTINCT FROM 'boolean' THEN RETURN FALSE; END IF; END LOOP; IF (SELECT count(DISTINCT x->>0) FROM jsonb_array_elements(c->'classifications') x)<>jsonb_array_length(c->'classifications') THEN RETURN FALSE; END IF; END IF;
 RETURN TRUE; EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN FALSE;
END $$;
CREATE FUNCTION public.int9_scope(s JSONB,c JSONB) RETURNS VOID LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r JSONB; original JSONB; review JSONB; BEGIN
 IF c ? 'roundId' THEN r:=public.int9_round(s,c->>'roundId'); IF r IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; END IF;
 IF c ? 'teamId' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'teams') t WHERE t->>'id'=c->>'teamId') OR c ? 'playerId' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'teams') t CROSS JOIN LATERAL jsonb_array_elements(t->'players') p WHERE t->>'id'=c->>'teamId' AND p->>'id'=c->>'playerId') THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 IF c ? 'itemId' AND c->'itemId'<>'null'::JSONB AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'pin'->'items') i WHERE i->>'id'=c->>'itemId') OR c ? 'attemptId' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'attempts') a WHERE a->>'id'=c->>'attemptId' AND a->>'roundId'=r->>'id') OR c ? 'scopeId' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'grantScopes') sc WHERE sc->>'id'=c->>'scopeId' AND sc->>'roundId'=r->>'id') THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 IF c ? 'effectId' AND c->'effectId'<>'null'::JSONB THEN SELECT x INTO original FROM jsonb_array_elements(s->'effects') x WHERE x->>'id'=c->>'effectId' AND (r IS NULL OR x->>'roundId'=r->>'id'); IF original IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; END IF;
 IF c->>'type'='FINAL_RULING' AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'classifications') x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'attempts') a WHERE a->>'id'=x->>0 AND a->>'roundId'=r->>'id' AND (c->'itemId'='null'::JSONB OR a->>'itemId'=c->>'itemId'))) THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 IF c->>'type'='RESOLVE_ITEM_REVIEW' THEN SELECT x INTO review FROM jsonb_array_elements(s->'itemReviews') x WHERE x->>'id'=c->>'reviewId'; IF review IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; SELECT x INTO original FROM jsonb_array_elements(s->'effects') x WHERE x->>'id'=review->>'originalEffectId'; END IF;
 IF c ? 'correctAttemptIds' AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'correctAttemptIds') id WHERE original IS NULL OR NOT original->'originalAttemptIds' @> jsonb_build_array(id)) THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
END $$;

CREATE FUNCTION public.int9_number(x JSONB,minimum NUMERIC,maximum NUMERIC,nullable BOOLEAN) RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE WHEN x='null'::JSONB THEN nullable WHEN jsonb_typeof(x)='number' THEN (x#>>'{}')::NUMERIC=trunc((x#>>'{}')::NUMERIC) AND (x#>>'{}')::NUMERIC BETWEEN minimum AND maximum ELSE FALSE END $$;
CREATE FUNCTION public.int9_id_or_null(x JSONB) RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT x='null'::JSONB OR public.int8_json_id(x) $$;
CREATE FUNCTION public.int9_state_shape(s JSONB) RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE x JSONB; y JSONB; key TEXT; BEGIN
 IF public.int6_enta_exact_keys(s,ARRAY['id','identityId','projectId','hostUid','admissionId','request','requestHash','intent','intentHash','version','finished','activeRoundId','turnIndex','resultReason','teams','categories','rounds','allowances','consumptions','attempts','classifications','disclosures','effects','postings','rulings','events','grants','grantScopes','canvases','reports','latestEffectId','correctionReview','openItemReview','itemReviews','itemResolutions','tournamentBinding','results','resultSignals']) IS NOT TRUE OR public.int9_valid_request(s->'request') IS NOT TRUE OR public.int5b_json_integer(s->'version',1,2000000000) IS NOT TRUE OR public.int5b_json_integer(s->'turnIndex',0,36) IS NOT TRUE OR jsonb_typeof(s->'finished') IS DISTINCT FROM 'boolean' OR s->'resultReason' NOT IN ('null'::JSONB,'"ALL_ROUNDS"'::JSONB,'"HOST_ENDED"'::JSONB) THEN RETURN FALSE; END IF;
 FOREACH key IN ARRAY ARRAY['activeRoundId','latestEffectId','correctionReview','openItemReview'] LOOP IF public.int9_id_or_null(s->key) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
 FOREACH key IN ARRAY ARRAY['teams','categories','rounds','allowances','consumptions','attempts','classifications','disclosures','effects','postings','rulings','events','grants','grantScopes','canvases','reports','itemReviews','itemResolutions','results','resultSignals'] LOOP IF jsonb_typeof(s->key) IS DISTINCT FROM 'array' THEN RETURN FALSE; END IF; END LOOP;
 IF jsonb_array_length(s->'teams') NOT BETWEEN 2 AND 4 OR jsonb_array_length(s->'rounds') NOT BETWEEN 1 AND 36 OR jsonb_array_length(s->'effects')>4096 OR jsonb_array_length(s->'attempts')>4096 OR jsonb_array_length(s->'events')>4096 OR jsonb_array_length(s->'grants')>4096 OR jsonb_array_length(s->'disclosures')>4096 THEN RETURN FALSE; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'teams') LOOP
  IF public.int6_enta_exact_keys(x,ARRAY['id','name','colorKey','players','aids','score','scoreVersion','scoreHead']) IS NOT TRUE OR public.int8_json_id(x->'id') IS NOT TRUE OR public.int6_enta_valid_text(x->'name',2,22) IS NOT TRUE OR jsonb_typeof(x->'colorKey') IS DISTINCT FROM 'string' OR NOT public.int9_palette() ? (x->>'colorKey') OR public.int9_number(x->'score',-2147483648,2147483647,FALSE) IS NOT TRUE OR public.int5b_json_integer(x->'scoreVersion',0,4096) IS NOT TRUE OR public.int9_id_or_null(x->'scoreHead') IS NOT TRUE OR jsonb_typeof(x->'players') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'players') NOT BETWEEN 1 AND 8 OR jsonb_typeof(x->'aids') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'aids')<>3 THEN RETURN FALSE; END IF;
  FOR y IN SELECT value FROM jsonb_array_elements(x->'players') LOOP IF public.int6_enta_exact_keys(y,ARRAY['id','name']) IS NOT TRUE OR public.int8_json_id(y->'id') IS NOT TRUE OR public.int6_enta_valid_text(y->'name',1,30) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'rounds') LOOP
  IF public.int6_enta_exact_keys(x,ARRAY['id','questionId','ordinal','pin','phase','phaseOrdinal','generation','version','originalTeamId','currentTeamId','originalDeadline','deadline','overallDeadline','pause','publicRevealed','itemReveals','assignment','pickedPlayerId','pickedEventId','usedAidIds','doubleAttemptTeamId','bonus','revealedHintIds','graphemeHints','consumed','reason','turnAdvanced']) IS NOT TRUE OR public.int8_json_id(x->'id') IS NOT TRUE OR public.int8_json_id(x->'questionId') IS NOT TRUE OR public.int5b_json_integer(x->'ordinal',0,35) IS NOT TRUE OR public.int5b_json_integer(x->'phaseOrdinal',0,2000000000) IS NOT TRUE OR public.int5b_json_integer(x->'generation',0,2000000000) IS NOT TRUE OR public.int5b_json_integer(x->'version',0,2000000000) IS NOT TRUE OR jsonb_typeof(x->'phase') IS DISTINCT FROM 'string' OR x->>'phase' NOT IN ('READY','MAIN','TRAP','STEAL','SHARED','TURN','AWAITING_RULING','RESOLVED') OR jsonb_typeof(x->'publicRevealed') IS DISTINCT FROM 'boolean' OR jsonb_typeof(x->'turnAdvanced') IS DISTINCT FROM 'boolean' OR x->'reason' NOT IN ('null'::JSONB,'"TIME_EXPIRED"'::JSONB,'"ADJUDICATED"'::JSONB,'"HOST_CLOSED"'::JSONB,'"ALL_ITEMS"'::JSONB) THEN RETURN FALSE; END IF;
  FOREACH key IN ARRAY ARRAY['originalTeamId','currentTeamId','pickedPlayerId','pickedEventId','doubleAttemptTeamId'] LOOP IF public.int9_id_or_null(x->key) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
  FOREACH key IN ARRAY ARRAY['originalDeadline','deadline','overallDeadline'] LOOP IF public.int9_number(x->key,0,9007199254740991,TRUE) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
  FOREACH key IN ARRAY ARRAY['itemReveals','usedAidIds','revealedHintIds','graphemeHints','consumed'] LOOP IF jsonb_typeof(x->key) IS DISTINCT FROM 'array' THEN RETURN FALSE; END IF; END LOOP;
  IF x->'pause'<>'null'::JSONB THEN y:=x->'pause'; IF public.int6_enta_exact_keys(y,ARRAY['cause','eventId','resumeAt','phaseRemaining','overallRemaining']) IS NOT TRUE OR y->>'cause' NOT IN ('ADMIN','PHONE','FREEZE') OR public.int8_json_id(y->'eventId') IS NOT TRUE OR public.int9_number(y->'resumeAt',0,9007199254740991,TRUE) IS NOT TRUE OR public.int9_number(y->'phaseRemaining',0,600000,TRUE) IS NOT TRUE OR public.int9_number(y->'overallRemaining',0,600000,TRUE) IS NOT TRUE OR (y->>'cause'='PHONE')<>(y->'resumeAt'<>'null'::JSONB) OR x->'deadline'<>'null'::JSONB OR x->'overallDeadline'<>'null'::JSONB THEN RETURN FALSE; END IF; END IF;
  IF x->'assignment'<>'null'::JSONB THEN y:=x->'assignment'; IF public.int6_enta_exact_keys(y,ARRAY['id','teamId','playerId','itemId','generation']) IS NOT TRUE OR public.int8_json_id(y->'id') IS NOT TRUE OR public.int8_json_id(y->'teamId') IS NOT TRUE OR public.int8_json_id(y->'playerId') IS NOT TRUE OR public.int9_id_or_null(y->'itemId') IS NOT TRUE OR public.int5b_json_integer(y->'generation',1,2000000000) IS NOT TRUE THEN RETURN FALSE; END IF; END IF;
  IF x->'bonus'<>'null'::JSONB THEN y:=x->'bonus'; IF public.int6_enta_exact_keys(y,ARRAY['teamId','multiplier','eventId']) IS NOT TRUE OR public.int8_json_id(y->'teamId') IS NOT TRUE OR public.int8_json_id(y->'eventId') IS NOT TRUE OR y->'multiplier' IS DISTINCT FROM '2'::JSONB THEN RETURN FALSE; END IF; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'attempts') LOOP
  IF public.int6_enta_exact_keys(x,ARRAY['id','roundId','itemId','phase','phaseOrdinal','generation','teamId','playerId','ordinal','acceptedAt','deadline','eventId','pickedEventId','allowanceId','bonusEventId','bonusMultiplier','disclosureHead','eligiblePlayerIds','eligibilityHash']) IS NOT TRUE OR jsonb_typeof(x->'phase') IS DISTINCT FROM 'string' OR x->>'phase' NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN') OR public.int5b_json_integer(x->'phaseOrdinal',1,2000000000) IS NOT TRUE OR public.int5b_json_integer(x->'generation',1,2000000000) IS NOT TRUE OR public.int5b_json_integer(x->'ordinal',1,2) IS NOT TRUE OR public.int9_number(x->'acceptedAt',0,9007199254740991,FALSE) IS NOT TRUE OR public.int9_number(x->'deadline',0,9007199254740991,FALSE) IS NOT TRUE OR (x->>'acceptedAt')::NUMERIC>=(x->>'deadline')::NUMERIC OR x->'bonusMultiplier' NOT IN ('1'::JSONB,'2'::JSONB) OR jsonb_typeof(x->'eligiblePlayerIds') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'eligiblePlayerIds') NOT BETWEEN 1 AND 8 THEN RETURN FALSE; END IF;
  FOREACH key IN ARRAY ARRAY['id','roundId','teamId','playerId','eventId'] LOOP IF public.int8_json_id(x->key) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
  FOREACH key IN ARRAY ARRAY['itemId','pickedEventId','allowanceId','bonusEventId','disclosureHead'] LOOP IF public.int9_id_or_null(x->key) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'effects') LOOP
  IF public.int6_enta_exact_keys(x,ARRAY['id','eventId','sequence','roundId','kind','aid','amountKind','reversible','barrier','reads','dependencies','postingIds','beforeClock','afterClock','originalAttemptIds','correctAttemptIds','bonusSnapshot','predecessorId','predecessorHash','reason','hash']) IS NOT TRUE OR public.int8_json_id(x->'id') IS NOT TRUE OR public.int8_json_id(x->'eventId') IS NOT TRUE OR public.int5b_json_integer(x->'sequence',1,4096) IS NOT TRUE OR public.int9_id_or_null(x->'roundId') IS NOT TRUE OR x->>'kind' NOT IN ('AID','RULING','NO_SCORE','INTERIM','TIMING','DISCLOSURE','REVERSAL','CORRECTION','FINISH') OR x->>'amountKind' NOT IN ('FIXED','DERIVED','NONE') OR jsonb_typeof(x->'reversible') IS DISTINCT FROM 'boolean' OR jsonb_typeof(x->'barrier') IS DISTINCT FROM 'boolean' OR jsonb_typeof(x->'hash') IS DISTINCT FROM 'string' OR x->>'hash'!~'^[a-f0-9]{64}$' THEN RETURN FALSE; END IF;
  FOREACH key IN ARRAY ARRAY['reads','dependencies','postingIds','originalAttemptIds','correctAttemptIds','bonusSnapshot'] LOOP IF jsonb_typeof(x->key) IS DISTINCT FROM 'array' THEN RETURN FALSE; END IF; END LOOP;
  FOR y IN SELECT value FROM jsonb_array_elements(x->'reads') LOOP IF public.int6_enta_exact_keys(y,ARRAY['teamId','scoreVersion','value','sourceEffectId','kind']) IS NOT TRUE OR public.int8_json_id(y->'teamId') IS NOT TRUE OR public.int5b_json_integer(y->'scoreVersion',0,4096) IS NOT TRUE OR public.int9_number(y->'value',-2147483648,2147483647,FALSE) IS NOT TRUE OR public.int9_id_or_null(y->'sourceEffectId') IS NOT TRUE OR y->>'kind' NOT IN ('BASE','RANK','CLAMP','CAP') THEN RETURN FALSE; END IF; END LOOP;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'canvases') LOOP
  IF public.int6_enta_exact_keys(x,ARRAY['roundId','revision','strokes','visibleIds','redoIds','cumulativePoints','mutations','receipts']) IS NOT TRUE OR public.int8_json_id(x->'roundId') IS NOT TRUE OR public.int5b_json_integer(x->'revision',0,512) IS NOT TRUE OR public.int5b_json_integer(x->'mutations',0,512) IS NOT TRUE OR public.int5b_json_integer(x->'cumulativePoints',0,8192) IS NOT TRUE OR jsonb_typeof(x->'strokes') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'strokes')>128 OR jsonb_typeof(x->'visibleIds') IS DISTINCT FROM 'array' OR jsonb_typeof(x->'redoIds') IS DISTINCT FROM 'array' OR jsonb_typeof(x->'receipts') IS DISTINCT FROM 'array' THEN RETURN FALSE; END IF;
  FOR y IN SELECT value FROM jsonb_array_elements(x->'strokes') LOOP IF public.int8_valid_command(jsonb_build_object('type','APPEND','commandId','shape-check-0001','expectedRevision',0,'stroke',y),TRUE) IS NOT TRUE THEN RETURN FALSE; END IF; END LOOP;
  IF (SELECT COALESCE(sum(jsonb_array_length(stroke_row->'points')),0) FROM jsonb_array_elements(x->'strokes') stroke_row)<>(x->>'cumulativePoints')::INTEGER OR (x->>'revision')::INTEGER<>(x->>'mutations')::INTEGER OR jsonb_array_length(x->'receipts')<>(x->>'mutations')::INTEGER OR EXISTS(SELECT 1 FROM jsonb_array_elements(x->'visibleIds') id WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(x->'strokes') stroke WHERE stroke->'id'=id)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(x->'redoIds') id WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(x->'strokes') stroke WHERE stroke->'id'=id)) THEN RETURN FALSE; END IF;
 END LOOP;
 RETURN TRUE; EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN FALSE;
END $$;

CREATE FUNCTION public.int9_aid(s JSONB,c JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE r JSONB:=public.int9_round(s,c->>'roundId'); standalone BOOLEAN:=public.int9_standalone(s); aid TEXT:=c->>'aid'; tid TEXT:=c->>'teamId'; allowance JSONB; before_clock JSONB; hint JSONB; item JSONB; proof JSONB; player JSONB; opponent JSONB; effect JSONB; consumption JSONB; amount BIGINT; idx INTEGER; BEGIN
 IF public.int9_review(s) OR r->'pause'<>'null'::JSONB OR (r->>'publicRevealed')::BOOLEAN OR r->>'phase' NOT IN ('MAIN','SHARED','TURN') OR r->'deadline'='null'::JSONB OR moment>=(r->>'deadline')::DOUBLE PRECISION OR tid IS DISTINCT FROM (CASE WHEN standalone THEN r->>'currentTeamId' ELSE r->>'originalTeamId' END) OR NOT aid=ANY(public.int9_aids(s->'request'->>'executionFormat',r->'pin'->>'format')) THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
 SELECT x INTO allowance FROM jsonb_array_elements(s->'allowances') x WHERE x->>'teamId'=tid AND x->>'aid'=aid AND x->>'scopeId'=(CASE WHEN standalone THEN r->>'id' ELSE s->>'id' END);
 IF allowance IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'consumptions') x WHERE x->>'allowanceId'=allowance->>'id') OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'consumptions') x WHERE r->'usedAidIds' @> jsonb_build_array(x->'id') AND x->>'aid'='TRAP') THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
 before_clock:=public.int9_snapshot(r); s:=public.int9_host_event(s,c,r->>'id',moment); s:=public.int9_effect(s,r,'AID',jsonb_build_object('aid',aid,'beforeClock',before_clock));
 IF aid IN ('PHONE_A_FRIEND','PHONE','FREEZE') THEN r:=r||jsonb_build_object('pause',jsonb_build_object('cause',CASE WHEN aid='FREEZE' THEN 'FREEZE' ELSE 'PHONE' END,'eventId',s->'events'->-1->'id','resumeAt',CASE WHEN aid='FREEZE' THEN NULL ELSE moment+60000 END,'phaseRemaining',(r->>'deadline')::DOUBLE PRECISION-moment,'overallRemaining',CASE WHEN r->'overallDeadline'='null'::JSONB THEN NULL ELSE greatest(0,(r->>'overallDeadline')::DOUBLE PRECISION-moment) END),'deadline',NULL,'overallDeadline',NULL);
 ELSIF aid IN ('DOUBLE_ANSWER','DOUBLE') THEN IF r->'doubleAttemptTeamId'<>'null'::JSONB THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF; r:=r||jsonb_build_object('doubleAttemptTeamId',tid);
 ELSIF aid='DOUBLE_POINTS' THEN IF r->'bonus'<>'null'::JSONB OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'attempts') a WHERE a->>'roundId'=r->>'id' AND a->>'teamId'=tid) THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF; r:=r||jsonb_build_object('bonus',jsonb_build_object('teamId',tid,'multiplier',2,'eventId',s->'events'->-1->'id'));
 ELSIF aid='MORE_HINT' THEN
  IF jsonb_array_length(r->'pin'->'hints')=0 OR NOT public.int9_items(r) AND NOT r->'revealedHintIds' @> jsonb_build_array(r->'pin'->'hints'->0->'id') THEN PERFORM public.int9_error('HINT_UNAVAILABLE'); END IF;
  SELECT x INTO hint FROM jsonb_array_elements(r->'pin'->'hints') WITH ORDINALITY hints(x,ord) WHERE NOT r->'revealedHintIds' @> jsonb_build_array(x->'id') ORDER BY ord LIMIT 1; IF hint IS NULL OR r->'pin'->>'format'='DRAWING_TARGET' AND hint->'safeDrawing' IS DISTINCT FROM 'true'::JSONB THEN PERFORM public.int9_error('HINT_UNAVAILABLE'); END IF; r:=r||jsonb_build_object('revealedHintIds',r->'revealedHintIds'||jsonb_build_array(hint->'id'));
 ELSIF aid='HINT' THEN
  SELECT x INTO item FROM jsonb_array_elements(r->'pin'->'items') x WHERE x->'trap'='false'::JSONB AND NOT r->'itemReveals' @> jsonb_build_array(x->'id') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=x->'id') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'graphemeHints') used WHERE used->'itemId'=x->'id') ORDER BY (x->>'value')::INTEGER DESC,(x->>'ordinal')::INTEGER LIMIT 1;
  SELECT x INTO proof FROM jsonb_array_elements(r->'pin'->'graphemes') x WHERE x->'answerRevisionId'=item->'revisionId' AND x->'answerHash'=item->'hash'; IF item IS NULL OR proof IS NULL THEN PERFORM public.int9_error('HINT_UNAVAILABLE'); END IF; r:=r||jsonb_build_object('graphemeHints',r->'graphemeHints'||jsonb_build_array(jsonb_build_object('proofId',proof->'id','itemId',item->'id','eventId',s->'events'->-1->'id')));
 ELSIF aid='PICK_ANSWERER' THEN SELECT x INTO player FROM jsonb_array_elements(public.int9_players(s,r,tid)) x ORDER BY public.int6_enta_hash(jsonb_build_array(s->'intent'->>'seed',r->>'id',r->'generation',x->>'id')) COLLATE "C",(x->>'id') COLLATE "C" LIMIT 1; IF player IS NULL THEN PERFORM public.int9_error('NO_ELIGIBLE_PLAYER'); END IF; r:=r||jsonb_build_object('pickedPlayerId',player->'id','pickedEventId',s->'events'->-1->'id');
 ELSIF aid='TRAP' THEN
  IF r->'usedAidIds'<>'[]'::JSONB OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'attempts') a WHERE a->'roundId'=r->'id') THEN PERFORM public.int9_error('AID_PAIRING_DENIED'); END IF; SELECT ord::INTEGER-1 INTO idx FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'=r->>'originalTeamId'; r:=r||jsonb_build_object('phase','TRAP','phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+1,'generation',(r->>'generation')::INTEGER+1,'currentTeamId',s->'teams'->((idx+1)%jsonb_array_length(s->'teams'))->'id','deadline',least((r->>'deadline')::DOUBLE PRECISION,moment+10000),'doubleAttemptTeamId',NULL); s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id');
 ELSIF aid='PASS' THEN IF r->>'doubleAttemptTeamId'=tid AND (SELECT count(*) FROM jsonb_array_elements(s->'attempts') a WHERE a->'roundId'=r->'id' AND a->>'teamId'=tid AND a->'generation'=r->'generation')<2 THEN PERFORM public.int9_error('AID_PAIRING_DENIED'); END IF; s:=public.int9_transfer(s,r,moment); r:=public.int9_round(s,r->>'id');
 ELSIF aid='STEAL_POINTS' THEN
  SELECT x INTO opponent FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'<>tid ORDER BY (x->>'score')::INTEGER DESC,ord LIMIT 1; amount:=least((r->'pin'->>'effectValue')::BIGINT,greatest(0,(opponent->>'score')::BIGINT)); IF opponent IS NULL OR amount=0 THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
  effect:=s->'effects'->-1; effect:=effect||jsonb_build_object('amountKind','DERIVED','reversible',TRUE,'reads',(SELECT jsonb_agg(public.int9_read(x,'RANK') ORDER BY ord) FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'<>tid),'dependencies',(SELECT COALESCE(jsonb_agg(value ORDER BY first_ord),'[]'::JSONB) FROM (SELECT x->'scoreHead' value,min(ord) first_ord FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'<>tid AND x->'scoreHead'<>'null'::JSONB GROUP BY x->'scoreHead') distinct_heads)); s:=jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT],effect); s:=public.int9_post(s,opponent->>'id',-amount,FALSE); s:=public.int9_post(s,tid,amount,FALSE);
 ELSE PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
 IF r->'pause'<>'null'::JSONB THEN s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id'); END IF;
 consumption:=jsonb_build_object('id',gen_random_uuid()::TEXT,'allowanceId',allowance->'id','roundId',r->'id','eventId',s->'events'->-1->'id','effectId',s->'effects'->-1->'id','aid',aid,'teamId',tid); s:=s||jsonb_build_object('consumptions',s->'consumptions'||jsonb_build_array(consumption)); r:=r||jsonb_build_object('usedAidIds',r->'usedAidIds'||jsonb_build_array(consumption->'id'),'version',(r->>'version')::INTEGER+1); s:=public.int8_put_round(s,r); s:=jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT,'afterClock'],public.int9_snapshot(r)); RETURN public.int9_seal(s);
END $$;
CREATE FUNCTION public.int9_attempt(s JSONB,c JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r JSONB:=public.int9_round(s,c->>'roundId'); tid TEXT:=c->>'teamId'; player_id TEXT:=c->>'playerId'; previous JSONB; players JSONB; snapshot JSONB; attempt JSONB; allowance JSONB; picked BOOLEAN; budget INTEGER; BEGIN
 IF s->'activeRoundId' IS DISTINCT FROM r->'id' OR public.int9_review(s) OR r->'pause'<>'null'::JSONB OR (r->>'publicRevealed')::BOOLEAN OR r->'deadline'='null'::JSONB OR moment>=(r->>'deadline')::DOUBLE PRECISION OR r->>'phase' NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN') THEN PERFORM public.int9_error('ATTEMPT_UNAVAILABLE'); END IF;
 IF (CASE r->>'phase' WHEN 'STEAL' THEN tid=r->>'originalTeamId' WHEN 'SHARED' THEN FALSE ELSE tid IS DISTINCT FROM r->>'currentTeamId' END) OR (CASE WHEN public.int9_items(r) THEN c->'itemId'='null'::JSONB OR r->'itemReveals' @> jsonb_build_array(c->'itemId') OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=c->'itemId') ELSE c->'itemId'<>'null'::JSONB END) THEN PERFORM public.int9_error('ATTEMPT_UNAVAILABLE'); END IF;
 players:=public.int9_players(s,r,tid); picked:=EXISTS(SELECT 1 FROM jsonb_array_elements(s->'teams') t CROSS JOIN LATERAL jsonb_array_elements(t->'players') p WHERE t->>'id'=tid AND p->'id'=r->'pickedPlayerId'); IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(players) p WHERE p->>'id'=player_id) OR picked AND player_id IS DISTINCT FROM r->>'pickedPlayerId' THEN PERFORM public.int9_error('NO_ELIGIBLE_PLAYER'); END IF;
 SELECT COALESCE(jsonb_agg(x ORDER BY ord),'[]'::JSONB) INTO previous FROM jsonb_array_elements(s->'attempts') WITH ORDINALITY attempts(x,ord) WHERE x->'roundId'=r->'id' AND x->>'teamId'=tid AND x->'phaseOrdinal'=r->'phaseOrdinal' AND x->'generation'=r->'generation' AND (r->>'phase'<>'SHARED' OR x->'itemId'=c->'itemId'); budget:=(CASE WHEN r->>'phase' IN ('MAIN','TURN') AND r->>'doubleAttemptTeamId'=tid THEN 2 ELSE 1 END);
 IF jsonb_array_length(previous)>=budget OR EXISTS(SELECT 1 FROM jsonb_array_elements(previous) a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'classifications') cl WHERE cl->'attemptId'=a->'id') OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'classifications') cl WHERE cl->'attemptId'=a->'id' AND cl->'correct'='true'::JSONB)) THEN PERFORM public.int9_error('ATTEMPT_BUDGET_EXCEEDED'); END IF;
 s:=public.int9_host_event(s,c,r->>'id',moment); SELECT x INTO allowance FROM jsonb_array_elements(s->'allowances') x WHERE r->>'doubleAttemptTeamId'=tid AND x->>'teamId'=tid AND x->>'aid' IN ('DOUBLE','DOUBLE_ANSWER') AND x->>'scopeId'=(CASE WHEN public.int9_standalone(s) THEN r->>'id' ELSE s->>'id' END);
 snapshot:=jsonb_build_object('roundId',r->'id','phase',r->'phase','phaseOrdinal',r->'phaseOrdinal','generation',r->'generation','teamId',tid,'playerId',player_id,'eligiblePlayerIds',(SELECT jsonb_agg(p->'id' ORDER BY ord) FROM jsonb_array_elements(players) WITH ORDINALITY p(p,ord)),'pickedEventId',CASE WHEN picked THEN r->'pickedEventId' ELSE 'null'::JSONB END,'disclosureHead',(SELECT x->'id' FROM jsonb_array_elements(s->'disclosures') WITH ORDINALITY disclosures(x,ord) WHERE x->'roundId'=r->'id' ORDER BY ord DESC LIMIT 1),'deadline',r->'deadline');
 attempt:=snapshot-'disclosureHead'||jsonb_build_object('id',gen_random_uuid()::TEXT,'itemId',c->'itemId','ordinal',jsonb_array_length(previous)+1,'acceptedAt',moment,'eventId',s->'events'->-1->'id','allowanceId',allowance->'id','bonusEventId',CASE WHEN r->'bonus'->>'teamId'=tid AND r->>'phase'='MAIN' THEN r->'bonus'->'eventId' ELSE 'null'::JSONB END,'bonusMultiplier',CASE WHEN r->'bonus'->>'teamId'=tid AND r->>'phase'='MAIN' THEN 2 ELSE 1 END,'disclosureHead',snapshot->'disclosureHead','eligibilityHash',public.int6_enta_hash(snapshot));
 s:=s||jsonb_build_object('attempts',s->'attempts'||jsonb_build_array(attempt)); s:=public.int9_seal(public.int9_effect(s,r,'TIMING','{}'::JSONB)); RETURN public.int8_put_round(s,r||jsonb_build_object('version',(r->>'version')::INTEGER+1));
END $$;
CREATE FUNCTION public.int9_interim(s JSONB,c JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r JSONB:=public.int9_round(s,c->>'roundId'); a JSONB; before_clock JSONB; budget INTEGER; used INTEGER; BEGIN
 IF public.int9_review(s) OR r->'pause'<>'null'::JSONB OR (r->>'publicRevealed')::BOOLEAN THEN PERFORM public.int9_error('INVALID_PHASE'); END IF; SELECT x INTO a FROM jsonb_array_elements(s->'attempts') x WHERE x->>'id'=c->>'attemptId'; IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'classifications') cl WHERE cl->'attemptId'=a->'id') THEN PERFORM public.int9_error('ATTEMPT_ALREADY_CLASSIFIED'); END IF;
 before_clock:=public.int9_snapshot(r); s:=public.int9_host_event(s,c,r->>'id',moment); s:=s||jsonb_build_object('classifications',s->'classifications'||jsonb_build_array(jsonb_build_object('id',gen_random_uuid()::TEXT,'attemptId',a->'id','eventId',s->'events'->-1->'id','correct',FALSE,'interim',TRUE)));
 IF public.int9_standalone(s) AND a->'generation'=r->'generation' AND a->'teamId'=r->'currentTeamId' AND r->>'phase'='TURN' AND r->'deadline'<>'null'::JSONB AND moment<(r->>'deadline')::DOUBLE PRECISION THEN budget:=(CASE WHEN r->'doubleAttemptTeamId'=a->'teamId' THEN 2 ELSE 1 END); SELECT count(*) INTO used FROM jsonb_array_elements(s->'attempts') x WHERE x->'roundId'=r->'id' AND x->'teamId'=a->'teamId' AND x->'generation'=a->'generation'; IF used>=budget THEN s:=public.int9_transfer(s,r,moment); r:=public.int9_round(s,r->>'id'); END IF; END IF;
 s:=public.int9_seal(public.int9_effect(s,r,'INTERIM',jsonb_build_object('beforeClock',before_clock,'originalAttemptIds',jsonb_build_array(a->'id')))); RETURN public.int8_put_round(s,r||jsonb_build_object('version',(r->>'version')::INTEGER+1));
END $$;
CREATE FUNCTION public.int9_reveal(s JSONB,c JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r JSONB:=public.int9_round(s,c->>'roundId'); before_clock JSONB; BEGIN
 IF public.int9_review(s) OR r->'pause'<>'null'::JSONB OR r->>'phase' IN ('READY','RESOLVED') OR NOT public.int9_items(r) AND c->'itemId'<>'null'::JSONB THEN PERFORM public.int9_error('INVALID_PHASE'); END IF;
 before_clock:=public.int9_snapshot(r); s:=public.int9_host_event(s,c,r->>'id',moment);
 IF c->'itemId'='null'::JSONB THEN IF (r->>'publicRevealed')::BOOLEAN THEN PERFORM public.int9_error('INVALID_PHASE'); END IF; r:=r||jsonb_build_object('publicRevealed',TRUE,'phase','AWAITING_RULING','deadline',NULL,'overallDeadline',NULL); s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id');
 ELSE IF r->'itemReveals' @> jsonb_build_array(c->'itemId') THEN PERFORM public.int9_error('ITEM_RESOLVED'); END IF; r:=r||jsonb_build_object('itemReveals',r->'itemReveals'||jsonb_build_array(c->'itemId')); IF r->'assignment'->'itemId'=c->'itemId' THEN s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id'); END IF; END IF;
 s:=public.int9_seal(public.int9_effect(s,r,'DISCLOSURE',jsonb_build_object('beforeClock',before_clock))); RETURN public.int8_put_round(s,r||jsonb_build_object('version',(r->>'version')::INTEGER+1));
END $$;

CREATE OR REPLACE FUNCTION public.int9_ruling(s JSONB,c JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE r JSONB:=public.int9_round(s,c->>'roundId'); pending JSONB; chosen JSONB; correct JSONB; originals JSONB; item JSONB; keys JSONB; key JSONB; v_attempt JSONB; team JSONB; winner JSONB; multiplier INTEGER; start_effect INTEGER:=jsonb_array_length(s->'effects'); effect JSONB; before_clock JSONB:=public.int9_snapshot(r); item_heads JSONB:='[]'::JSONB; whole_items BOOLEAN:=public.int9_items(r) AND c->'itemId'='null'::JSONB; idx INTEGER; BEGIN
 IF r->>'phase' IN ('READY','RESOLVED') THEN PERFORM public.int9_error('INVALID_PHASE'); END IF;
 IF public.int9_review(s) OR r->'pause'<>'null'::JSONB OR (CASE WHEN c->'itemId'='null'::JSONB THEN r->'publicRevealed' IS DISTINCT FROM 'true'::JSONB ELSE NOT r->'itemReveals' @> jsonb_build_array(c->'itemId') END) THEN PERFORM public.int9_error('PUBLIC_REVEAL_REQUIRED'); END IF;
 IF NOT public.int9_items(r) AND c->'itemId'<>'null'::JSONB OR c->'itemId'<>'null'::JSONB AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=c->'itemId') THEN PERFORM public.int9_error('ITEM_RESOLVED'); END IF;
 pending:=public.int9_pending(s,r->>'id',c->>'itemId',whole_items);
 IF jsonb_array_length(pending)<>jsonb_array_length(c->'classifications') OR EXISTS(SELECT 1 FROM jsonb_array_elements(c->'classifications') requested WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pending) a WHERE a->'id'=requested->0)) THEN PERFORM public.int9_error('COMPLETE_RULING_REQUIRED'); END IF;
 IF whole_items AND EXISTS(SELECT 1 FROM jsonb_array_elements(pending) a WHERE a->'itemId'='null'::JSONB) THEN PERFORM public.int9_error('ATTEMPT_PROOF_UNAVAILABLE'); END IF;
 s:=public.int9_host_event(s,c,r->>'id',moment);
 FOR v_attempt IN SELECT x FROM jsonb_array_elements(pending) x LOOP SELECT x INTO chosen FROM jsonb_array_elements(c->'classifications') x WHERE x->0=v_attempt->'id'; s:=s||jsonb_build_object('classifications',s->'classifications'||jsonb_build_array(jsonb_build_object('id',gen_random_uuid()::TEXT,'attemptId',v_attempt->'id','eventId',s->'events'->-1->'id','correct',chosen->1,'interim',FALSE))); END LOOP;
 IF whole_items THEN SELECT COALESCE(jsonb_agg(item_id ORDER BY first_ord),'[]'::JSONB) INTO keys FROM (SELECT x->'itemId' item_id,min(ord) first_ord FROM jsonb_array_elements(pending) WITH ORDINALITY attempts(x,ord) GROUP BY x->'itemId') unique_items; IF keys='[]'::JSONB THEN keys:='[null]'::JSONB; END IF; ELSE keys:=jsonb_build_array(c->'itemId'); END IF;
 FOR key IN SELECT x FROM jsonb_array_elements(keys) x LOOP
  item:=NULL; IF key<>'null'::JSONB THEN SELECT x INTO item FROM jsonb_array_elements(r->'pin'->'items') x WHERE x->'id'=key; IF item IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=key) THEN PERFORM public.int9_error('ITEM_RESOLVED'); END IF; END IF;
  SELECT COALESCE(jsonb_agg(a ORDER BY ord),'[]'::JSONB) INTO correct FROM jsonb_array_elements(pending) WITH ORDINALITY attempts(a,ord) WHERE (key='null'::JSONB OR a->'itemId'=key) AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'classifications') cl WHERE cl->0=a->'id' AND cl->1='true'::JSONB);
  SELECT COALESCE(jsonb_agg(a ORDER BY ord),'[]'::JSONB) INTO originals FROM jsonb_array_elements(s->'attempts') WITH ORDINALITY attempts(a,ord) WHERE a->'roundId'=r->'id' AND (key='null'::JSONB OR a->'itemId'=key);
  IF item IS NOT NULL AND (SELECT count(DISTINCT a->'teamId') FROM jsonb_array_elements(correct) a)>1 THEN PERFORM public.int9_error('ITEM_RULING_REQUIRED'); END IF;
  s:=public.int9_effect(s,r,CASE WHEN jsonb_array_length(correct)>0 THEN 'RULING' ELSE 'NO_SCORE' END,jsonb_build_object('reversible',NOT(whole_items AND key='null'::JSONB),'amountKind',CASE WHEN item->'trap'='true'::JSONB AND NOT public.int9_standalone(s) THEN 'DERIVED' WHEN whole_items AND key='null'::JSONB THEN 'NONE' ELSE 'FIXED' END,'beforeClock',CASE WHEN whole_items THEN 'null'::JSONB ELSE before_clock END,'originalAttemptIds',public.int9_team_ids(originals),'correctAttemptIds',public.int9_team_ids(correct),'bonusSnapshot',public.int9_bonus(originals)));
  IF item IS NOT NULL THEN winner:=correct->0; IF winner IS NOT NULL THEN s:=public.int9_post(s,winner->>'teamId',CASE WHEN item->'trap'='true'::JSONB THEN -(item->>'value')::BIGINT ELSE (item->>'value')::BIGINT END,NOT public.int9_standalone(s)); END IF;
   r:=r||jsonb_build_object('consumed',r->'consumed'||jsonb_build_array(jsonb_build_object('itemId',key,'effectId',s->'effects'->-1->'id','teamId',winner->'teamId'))); s:=public.int8_put_round(s,r);
   IF NOT whole_items THEN
    IF r->'assignment'->'itemId'=key THEN s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id'); END IF;
    IF r->'resourceStop'='null'::JSONB AND public.int9_standalone(s) AND winner IS NOT NULL AND winner->'generation'=r->'generation' AND winner->'teamId'=r->'currentTeamId' AND r->>'phase'='TURN' AND r->'deadline'<>'null'::JSONB AND moment<(r->>'deadline')::DOUBLE PRECISION THEN
     IF item->'trap'='true'::JSONB THEN s:=public.int9_transfer(s,r,moment); r:=public.int9_round(s,r->>'id'); ELSE r:=r||jsonb_build_object('deadline',moment+(s->'request'->'setup'->'rules'->>'turnSeconds')::INTEGER*1000,'phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+1,'generation',(r->>'generation')::INTEGER+1,'doubleAttemptTeamId',NULL,'version',(r->>'version')::INTEGER+1); s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id'); END IF;
    END IF;
    IF jsonb_array_length(r->'consumed')=jsonb_array_length(r->'pin'->'items') AND public.int9_pending(s,r->>'id',NULL,TRUE)='[]'::JSONB THEN s:=public.int9_close(s,r,'ALL_ITEMS'); r:=public.int9_round(s,r->>'id'); ELSIF r->'deadline'='null'::JSONB AND public.int9_pending(s,r->>'id',NULL,TRUE)='[]'::JSONB THEN s:=public.int9_close(s,r,'TIME_EXPIRED'); r:=public.int9_round(s,r->>'id'); END IF;
   END IF;
  ELSIF NOT public.int9_items(r) THEN
   FOR team IN SELECT x FROM jsonb_array_elements(s->'teams') x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(correct) a WHERE a->'teamId'=x->'id') LOOP SELECT max((a->>'bonusMultiplier')::INTEGER) INTO multiplier FROM jsonb_array_elements(correct) a WHERE a->'teamId'=team->'id'; s:=public.int9_post(s,team->>'id',(r->'pin'->>'points')::BIGINT*multiplier,FALSE); END LOOP;
  END IF;
  item_heads:=item_heads||jsonb_build_array(jsonb_build_object('effectId',s->'effects'->-1->'id','itemId',key));
 END LOOP;
 IF c->'itemId'='null'::JSONB THEN s:=public.int9_close(s,r,'ADJUDICATED'); r:=public.int9_round(s,r->>'id'); END IF;
 FOR effect IN SELECT x FROM jsonb_array_elements(s->'effects') WITH ORDINALITY effects(x,ord) WHERE ord>start_effect LOOP
  SELECT ord::INTEGER-1 INTO idx FROM jsonb_array_elements(s->'effects') WITH ORDINALITY effects(x,ord) WHERE x->'id'=effect->'id'; IF idx IS NULL THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF; effect:=effect||jsonb_build_object('afterClock',public.int9_snapshot(r)); effect:=jsonb_set(effect,'{hash}',to_jsonb(public.int9_effect_hash(effect))); s:=jsonb_set(s,ARRAY['effects',idx::TEXT],effect);
  SELECT x->'itemId' INTO key FROM jsonb_array_elements(item_heads) x WHERE x->'effectId'=effect->'id';
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'rulings') h WHERE h->>'scopeId'=public.int6_enta_canonical(jsonb_build_array(r->>'id',key))) THEN PERFORM public.int9_error('RULING_ALREADY_FINAL'); END IF;
  s:=s||jsonb_build_object('rulings',s->'rulings'||jsonb_build_array(jsonb_build_object('roundId',r->'id','itemId',key,'scopeId',public.int6_enta_canonical(jsonb_build_array(r->>'id',key)),'originalEffectId',effect->'id','effectId',effect->'id','version',1,'hash',effect->'hash','reversed',FALSE)));
 END LOOP;
 IF NOT whole_items THEN s:=public.int8_put_round(s,r||jsonb_build_object('version',(r->>'version')::INTEGER+1)); END IF; RETURN s;
END $$;

CREATE OR REPLACE FUNCTION public.int9_actual(s JSONB,effect JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE proof JSONB; result JSONB; BEGIN
 proof:=public.int9_effect_proof(s->>'id',effect->>'id'); IF proof->'effect' IS DISTINCT FROM effect THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 SELECT COALESCE(jsonb_object_agg(p->>'teamId',p->'delta'),'{}'::JSONB) INTO result FROM jsonb_array_elements(proof->'postings') p; RETURN result;
END $$;
CREATE OR REPLACE FUNCTION public.int9_blockers(s JSONB,original JSONB,excluded JSONB,changed_teams JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE blocked JSONB:='[]'::JSONB; total INTEGER:=0; locked_version INTEGER; terminal INTEGER; expected INTEGER:=(original->>'sequence')::INTEGER+1; seen INTEGER:=0; row_record RECORD; proof JSONB; effect JSONB; page_bytes INTEGER:=2; page_rows INTEGER:=0; row_bytes INTEGER; BEGIN
 SELECT "version" INTO locked_version FROM public."GameRuntime" WHERE "gameId"=s->>'id'; SELECT COALESCE(max("sequence"),0) INTO terminal FROM public."CompetitiveEffect" WHERE "gameId"=s->>'id';
 IF locked_version IS DISTINCT FROM (s->>'version')::INTEGER OR terminal<(original->>'sequence')::INTEGER OR jsonb_array_length(excluded)>256 OR jsonb_array_length(changed_teams)>4 OR public.int9_effect_proof(s->>'id',original->>'id')->'effect' IS DISTINCT FROM original THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 -- Game is held through this complete ordered cursor. Each logical page is at
 -- most 256 rows and 512KiB, but no prefix or early blocker ends the scan.
 FOR row_record IN SELECT "id","sequence" FROM public."CompetitiveEffect" WHERE "gameId"=s->>'id' AND "sequence">(original->>'sequence')::INTEGER AND "sequence"<=terminal ORDER BY "sequence" LOOP
  IF row_record."sequence"<>expected THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
  proof:=public.int9_effect_proof(s->>'id',row_record."id"); effect:=proof->'effect'; row_bytes:=octet_length(convert_to(public.int6_enta_canonical(proof),'UTF8'));
  IF page_rows=256 OR page_bytes+row_bytes+(CASE WHEN page_rows>0 THEN 1 ELSE 0 END)>524288 THEN page_rows:=0; page_bytes:=2; END IF;
  page_bytes:=page_bytes+row_bytes+(CASE WHEN page_rows>0 THEN 1 ELSE 0 END); page_rows:=page_rows+1; expected:=expected+1; seen:=seen+1;
  IF excluded @> jsonb_build_array(effect->'id') THEN proof:=NULL; effect:=NULL; CONTINUE; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(effect->'reads') read WHERE changed_teams @> jsonb_build_array(read->'teamId')) AND (effect->>'amountKind'='DERIVED' OR EXISTS(SELECT 1 FROM jsonb_array_elements(effect->'reads') read WHERE changed_teams @> jsonb_build_array(read->'teamId') AND read->>'kind'<>'BASE') OR jsonb_array_length(effect->'postingIds')>0 AND effect->>'amountKind'<>'FIXED') THEN
   total:=total+1; IF jsonb_array_length(blocked)<32 THEN blocked:=blocked||jsonb_build_array(effect->'id'); END IF;
   SELECT COALESCE(jsonb_agg(DISTINCT team),'[]'::JSONB) INTO changed_teams FROM (SELECT team FROM jsonb_array_elements(changed_teams) team UNION SELECT p->'teamId' FROM jsonb_array_elements(proof->'postings') p) participants;
  END IF;
  proof:=NULL; effect:=NULL;
 END LOOP;
 IF seen<>terminal-(original->>'sequence')::INTEGER OR expected<>terminal+1 OR (SELECT "version" FROM public."GameRuntime" WHERE "gameId"=s->>'id') IS DISTINCT FROM locked_version OR (SELECT COALESCE(max("sequence"),0) FROM public."CompetitiveEffect" WHERE "gameId"=s->>'id')<>terminal THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('ids',blocked,'total',total);
END $$;
CREATE OR REPLACE FUNCTION public.int9_review_error(blocked JSONB) RETURNS VOID LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION USING MESSAGE='CORRECTION_DEPENDENCY_REVIEW_REQUIRED',DETAIL='INT9_BLOCKERS:'||public.int6_enta_canonical(CASE WHEN jsonb_typeof(blocked)='array' THEN jsonb_build_object('ids',blocked,'total',jsonb_array_length(blocked)) ELSE blocked END); END $$;
CREATE OR REPLACE FUNCTION public.int9_require_independent(s JSONB,original JSONB,excluded JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE blocked JSONB; changed_teams JSONB; BEGIN s:=jsonb_build_object('id',s->'id','version',s->'version'); SELECT COALESCE(jsonb_agg(p->'teamId'),'[]'::JSONB) INTO changed_teams FROM jsonb_array_elements(public.int9_effect_proof(s->>'id',original->>'id')->'postings') p; blocked:=public.int9_blockers(s,original,excluded,changed_teams); IF (blocked->>'total')::INTEGER>0 THEN PERFORM public.int9_review_error(blocked); END IF; END $$;
CREATE OR REPLACE FUNCTION public.int9_apply_delta_map(s JSONB,deltas JSONB) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE team JSONB; tid TEXT; posting_delta BIGINT; t JSONB; effect JSONB; posting JSONB; read JSONB; after_score BIGINT; idx INTEGER; BEGIN
 FOR team IN SELECT x FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) ORDER BY ord LOOP IF deltas ? (team->>'id') THEN
  tid:=team->>'id'; posting_delta:=(deltas->>(team->>'id'))::BIGINT;

 SELECT x,ord::INTEGER-1 INTO t,idx FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'=tid; IF t IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 effect:=s->'effects'->-1; IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'postings') p WHERE p->>'effectId'=effect->>'id' AND p->>'teamId'=tid) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 after_score:=(t->>'score')::BIGINT+posting_delta; IF FALSE THEN after_score:=greatest(0,after_score); END IF;
 IF after_score NOT BETWEEN -2147483648 AND 2147483647 OR NOT (s->'request'->>'executionFormat' IN ('STANDALONE_LIST','STANDALONE_ACTING')) AND after_score<0 THEN PERFORM public.int9_error('SCORE_BOUND_EXCEEDED'); END IF;
 read:=public.int9_read(t,CASE WHEN FALSE THEN 'CLAMP' ELSE 'BASE' END);
 effect:=effect||jsonb_build_object('reads',effect->'reads'||jsonb_build_array(read),'dependencies',CASE WHEN read->>'sourceEffectId' IS NOT NULL AND NOT effect->'dependencies' ? (read->>'sourceEffectId') THEN effect->'dependencies'||jsonb_build_array(read->>'sourceEffectId') ELSE effect->'dependencies' END);
 posting:=jsonb_build_object('id',gen_random_uuid()::TEXT,'effectId',effect->'id','teamId',tid,'delta',after_score-(t->>'score')::BIGINT,'before',t->'score','after',after_score,'scoreVersion',(t->>'scoreVersion')::INTEGER+1,'previousHead',t->'scoreHead');
 effect:=effect||jsonb_build_object('postingIds',effect->'postingIds'||jsonb_build_array(posting->'id')); t:=t||jsonb_build_object('score',after_score,'scoreVersion',(t->>'scoreVersion')::INTEGER+1,'scoreHead',effect->'id');
 s:=jsonb_set(s,ARRAY['teams',idx::TEXT],t); s:=jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT],effect); s:=s||jsonb_build_object('postings',s->'postings'||jsonb_build_array(posting));

 END IF; END LOOP; RETURN s;
END $$;
CREATE FUNCTION public.int9_replacement(s JSONB,original JSONB,correct_ids JSONB) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r JSONB:=public.int9_round(s,original->>'roundId'); h JSONB; chosen JSONB; v_attempt JSONB; item JSONB; posting JSONB; team JSONB; multiplier INTEGER; result JSONB:='{}'::JSONB; BEGIN
 SELECT x INTO h FROM jsonb_array_elements(s->'rulings') x WHERE x->'originalEffectId'=original->'id'; IF h IS NULL THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF;
 SELECT COALESCE(jsonb_agg(a ORDER BY ord),'[]'::JSONB) INTO chosen FROM jsonb_array_elements(s->'attempts') WITH ORDINALITY attempts(a,ord) WHERE correct_ids @> jsonb_build_array(a->'id');
 IF jsonb_array_length(chosen)<>jsonb_array_length(correct_ids) OR EXISTS(SELECT 1 FROM jsonb_array_elements(chosen) a WHERE NOT original->'originalAttemptIds' @> jsonb_build_array(a->'id') OR a->'roundId'<>r->'id' OR NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" physical WHERE physical."gameId"=s->>'id' AND physical."roundId"=r->>'id' AND physical."id"=a->>'id' AND physical."teamId"=a->>'teamId' AND physical."playerId"=a->>'playerId' AND physical."acceptedAt"<physical."deadline" AND physical."payload"->'eligiblePlayerIds' @> jsonb_build_array(a->'playerId')) OR h->'itemId'<>'null'::JSONB AND a->'itemId'<>h->'itemId') THEN PERFORM public.int9_error('ORIGINAL_ATTEMPT_REQUIRED'); END IF;
 IF h->'itemId'<>'null'::JSONB THEN
  SELECT x INTO item FROM jsonb_array_elements(r->'pin'->'items') x WHERE x->'id'=h->'itemId'; IF item IS NULL THEN PERFORM public.int9_error('ITEM_PROOF_UNAVAILABLE'); END IF;
  IF (SELECT count(DISTINCT a->'teamId') FROM jsonb_array_elements(chosen) a)>1 THEN PERFORM public.int9_error('ITEM_RULING_REQUIRED'); END IF; IF chosen='[]'::JSONB THEN RETURN result; END IF; v_attempt:=chosen->0;
  IF item->'trap'='true'::JSONB AND NOT public.int9_standalone(s) THEN SELECT p INTO posting FROM jsonb_array_elements(s->'postings') p WHERE p->'effectId'=original->'id' AND p->'teamId'=v_attempt->'teamId'; IF posting IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(chosen) attempt WHERE original->'correctAttemptIds' @> jsonb_build_array(attempt->'id')) THEN PERFORM public.int9_review_error(jsonb_build_array(original->'id')); END IF; result:=jsonb_build_object(v_attempt->>'teamId',posting->'delta');
  ELSE result:=jsonb_build_object(v_attempt->>'teamId',CASE WHEN item->'trap'='true'::JSONB THEN -(item->>'value')::BIGINT ELSE (item->>'value')::BIGINT END); END IF;
 ELSE
  IF public.int9_items(r) THEN PERFORM public.int9_review_error(jsonb_build_array(original->'id')); END IF;
  FOR team IN SELECT x FROM jsonb_array_elements(s->'teams') x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(chosen) a WHERE a->'teamId'=x->'id') LOOP
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(chosen) a WHERE a->'teamId'=team->'id' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(original->'bonusSnapshot') b WHERE b->'attemptId'=a->'id' AND b->'teamId'=a->'teamId')) THEN PERFORM public.int9_error('BONUS_PROOF_UNAVAILABLE'); END IF;
   SELECT max((b->>'multiplier')::INTEGER) INTO multiplier FROM jsonb_array_elements(original->'bonusSnapshot') b WHERE b->'teamId'=team->'id' AND correct_ids @> jsonb_build_array(b->'attemptId'); result:=result||jsonb_build_object(team->>'id',(r->'pin'->>'points')::BIGINT*multiplier);
  END LOOP;
 END IF; RETURN result;
END $$;
CREATE FUNCTION public.int9_undo(s JSONB,c JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE original JSONB; r JSONB; h JSONB; consumption JSONB; review JSONB; reversal JSONB; deltas JSONB; BEGIN
 SELECT x INTO original FROM jsonb_array_elements(s->'effects') x WHERE x->>'id'=c->>'effectId'; r:=public.int9_round(s,original->>'roundId');
 IF (s->>'finished')::BOOLEAN OR public.int9_review(s) OR r->'pause'<>'null'::JSONB OR s->'latestEffectId' IS DISTINCT FROM original->'id' OR original->>'hash' IS DISTINCT FROM c->>'effectHash' OR original->'reversible' IS DISTINCT FROM 'true'::JSONB OR NOT (original->>'kind' IN ('RULING','NO_SCORE') OR original->>'kind'='AID' AND original->>'aid'='STEAL_POINTS') OR original->'predecessorId'<>'null'::JSONB OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'effects') e WHERE e->>'kind'='REVERSAL' AND e->'predecessorId'=original->'id') THEN PERFORM public.int9_error('UNDO_UNAVAILABLE'); END IF;
 PERFORM public.int9_require_independent(s,original,'[]'::JSONB);
 IF original->>'kind'<>'AID' THEN SELECT x INTO h FROM jsonb_array_elements(s->'rulings') x WHERE x->'originalEffectId'=original->'id'; IF h IS NOT NULL AND h->'itemId'='null'::JSONB AND public.int9_items(r) THEN PERFORM public.int9_error('UNDO_UNAVAILABLE'); END IF; IF h IS NULL OR h->'effectId'<>original->'id' OR h->'hash'<>original->'hash' OR h->'reversed'='true'::JSONB THEN PERFORM public.int9_error('STALE_RULING_HEAD'); END IF; IF h->'itemId'<>'null'::JSONB THEN SELECT x INTO consumption FROM jsonb_array_elements(r->'consumed') x WHERE x->'itemId'=h->'itemId' AND x->'effectId'=original->'id'; IF consumption IS NULL THEN PERFORM public.int9_error('ITEM_PROOF_UNAVAILABLE'); END IF; END IF; END IF;
 s:=public.int9_host_event(s,c,r->>'id',moment); s:=public.int9_effect(s,r,'REVERSAL',jsonb_build_object('amountKind','FIXED','predecessorId',original->'id','predecessorHash',original->'hash','beforeClock',public.int9_snapshot(r),'originalAttemptIds',original->'originalAttemptIds','correctAttemptIds',original->'correctAttemptIds','bonusSnapshot',original->'bonusSnapshot')); SELECT COALESCE(jsonb_object_agg(key,-(value#>>'{}')::BIGINT),'{}'::JSONB) INTO deltas FROM jsonb_each(public.int9_actual(s,original)); s:=public.int9_apply_delta_map(s,deltas); s:=public.int9_invalidate(s,r,TRUE); s:=public.int9_seal(s); reversal:=s->'effects'->-1;
 IF h IS NOT NULL THEN
  IF consumption IS NOT NULL THEN review:=jsonb_build_object('id',gen_random_uuid()::TEXT,'roundId',r->'id','itemId',consumption->'itemId','originalEffectId',original->'id','originalEffectHash',original->'hash','reversalEffectId',reversal->'id','predecessorRulingVersion',h->'version','predecessorRulingHash',h->'hash','originalAttemptIds',original->'originalAttemptIds','consumptionEffectId',consumption->'effectId','eventId',s->'events'->-1->'id'); review:=review||jsonb_build_object('hash',public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.item-review.v1','payload',review))); s:=s||jsonb_build_object('itemReviews',s->'itemReviews'||jsonb_build_array(review),'openItemReview',review->'id'); ELSE s:=s||jsonb_build_object('correctionReview',r->'id'); END IF;
  h:=h||jsonb_build_object('effectId',reversal->'id','hash',reversal->'hash','version',(h->>'version')::INTEGER+1,'reversed',TRUE); s:=jsonb_set(s,'{rulings}',(SELECT jsonb_agg(CASE WHEN x->'scopeId'=h->'scopeId' THEN h ELSE x END ORDER BY ord) FROM jsonb_array_elements(s->'rulings') WITH ORDINALITY heads(x,ord)));
 END IF; RETURN s;
END $$;
CREATE FUNCTION public.int9_resolve_review(s JSONB,c JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE review JSONB; original JSONB; h JSONB; r JSONB; deltas JSONB; successor JSONB; resolution JSONB; BEGIN
 SELECT x INTO review FROM jsonb_array_elements(s->'itemReviews') x WHERE x->>'id'=c->>'reviewId'; SELECT x INTO original FROM jsonb_array_elements(s->'effects') x WHERE x->'id'=review->'originalEffectId'; SELECT x INTO h FROM jsonb_array_elements(s->'rulings') x WHERE x->'originalEffectId'=original->'id'; r:=public.int9_round(s,review->>'roundId');
 IF (s->>'finished')::BOOLEAN OR s->'openItemReview' IS DISTINCT FROM review->'id' OR review->>'hash' IS DISTINCT FROM c->>'reviewHash' OR h->'version' IS DISTINCT FROM c->'rulingVersion' OR h->'reversed' IS DISTINCT FROM 'true'::JSONB OR h->'effectId' IS DISTINCT FROM review->'reversalEffectId' OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'itemResolutions') x WHERE x->'reviewId'=review->'id') THEN PERFORM public.int9_error('STALE_REVIEW_HEAD'); END IF;
 PERFORM public.int9_require_independent(s,original,jsonb_build_array(review->'reversalEffectId'));
 deltas:=(CASE c->>'mode' WHEN 'RESTORE_ORIGINAL' THEN public.int9_actual(s,original) ELSE public.int9_replacement(s,original,c->'correctAttemptIds') END); s:=public.int9_host_event(s,c,r->>'id',moment); s:=public.int9_effect(s,r,'CORRECTION',jsonb_build_object('amountKind','FIXED','predecessorId',h->'effectId','predecessorHash',h->'hash','originalAttemptIds',original->'originalAttemptIds','correctAttemptIds',CASE c->>'mode' WHEN 'RESTORE_ORIGINAL' THEN original->'correctAttemptIds' ELSE c->'correctAttemptIds' END,'bonusSnapshot',original->'bonusSnapshot','reason',c->'reason')); s:=public.int9_seal(public.int9_apply_delta_map(s,deltas)); successor:=s->'effects'->-1;
 h:=h||jsonb_build_object('effectId',successor->'id','hash',successor->'hash','version',(h->>'version')::INTEGER+1,'reversed',FALSE); s:=jsonb_set(s,'{rulings}',(SELECT jsonb_agg(CASE WHEN x->'scopeId'=h->'scopeId' THEN h ELSE x END ORDER BY ord) FROM jsonb_array_elements(s->'rulings') WITH ORDINALITY heads(x,ord)));
 resolution:=jsonb_build_object('id',gen_random_uuid()::TEXT,'reviewId',review->'id','reviewHash',review->'hash','effectId',successor->'id','eventId',s->'events'->-1->'id','rulingVersion',h->'version','rulingHash',h->'hash','mode',c->'mode','reason',c->'reason'); RETURN s||jsonb_build_object('itemResolutions',s->'itemResolutions'||jsonb_build_array(resolution),'openItemReview',NULL);
END $$;
CREATE OR REPLACE FUNCTION public.int9_correct(s JSONB,c JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE original JSONB; r JSONB; h JSONB; cursor JSONB; chain JSONB:='[]'::JSONB; desired JSONB; current JSONB:='{}'::JSONB; deltas JSONB; changed_teams JSONB; blocked JSONB; team JSONB; row RECORD; successor JSONB; BEGIN
 SELECT x INTO original FROM jsonb_array_elements(s->'effects') x WHERE x->>'id'=c->>'effectId'; r:=public.int9_round(s,original->>'roundId'); SELECT x INTO h FROM jsonb_array_elements(s->'rulings') x WHERE x->'originalEffectId'=original->'id';
 IF (s->>'finished')::BOOLEAN OR s->'activeRoundId'<>'null'::JSONB OR s->'openItemReview'<>'null'::JSONB OR r->>'phase'<>'RESOLVED' OR h->'version' IS DISTINCT FROM c->'rulingVersion' OR h->'itemId'<>'null'::JSONB OR original->>'kind' NOT IN ('RULING','NO_SCORE') OR s->'correctionReview'<>'null'::JSONB AND s->'correctionReview'<>r->'id' THEN PERFORM public.int9_error('CORRECTION_UNAVAILABLE'); END IF;
 cursor:=public.int9_effect_proof(s->>'id',h->>'effectId')->'effect';
 LOOP IF cursor IS NULL OR chain @> jsonb_build_array(cursor->'id') OR jsonb_array_length(chain)>=256 THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF; chain:=chain||jsonb_build_array(cursor->'id'); FOR row IN SELECT key,value FROM jsonb_each(public.int9_actual(s,cursor)) LOOP current:=current||jsonb_build_object(row.key,COALESCE((current->>row.key)::BIGINT,0)+(row.value#>>'{}')::BIGINT); END LOOP; EXIT WHEN cursor->'id'=original->'id'; successor:=public.int9_effect_proof(s->>'id',cursor->>'predecessorId')->'effect'; IF successor->'hash' IS DISTINCT FROM cursor->'predecessorHash' OR (successor->>'sequence')::INTEGER>=(cursor->>'sequence')::INTEGER THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF; cursor:=successor; END LOOP;
 desired:=public.int9_replacement(s,original,c->'correctAttemptIds'); SELECT jsonb_object_agg(t->>'id',COALESCE((desired->>(t->>'id'))::BIGINT,0)-COALESCE((current->>(t->>'id'))::BIGINT,0)),COALESCE(jsonb_agg(t->'id') FILTER(WHERE COALESCE((desired->>(t->>'id'))::BIGINT,0)<>COALESCE((current->>(t->>'id'))::BIGINT,0)),'[]'::JSONB) INTO deltas,changed_teams FROM jsonb_array_elements(s->'teams') t;
 blocked:=public.int9_blockers(jsonb_build_object('id',s->'id','version',s->'version'),original,chain,changed_teams); IF (blocked->>'total')::INTEGER>0 THEN PERFORM public.int9_review_error(blocked); END IF;
 s:=public.int9_host_event(s,c,r->>'id',moment); s:=public.int9_effect(s,r,'CORRECTION',jsonb_build_object('amountKind','FIXED','predecessorId',h->'effectId','predecessorHash',h->'hash','originalAttemptIds',original->'originalAttemptIds','correctAttemptIds',c->'correctAttemptIds','bonusSnapshot',original->'bonusSnapshot','reason',c->'reason')); s:=public.int9_seal(public.int9_apply_delta_map(s,deltas)); successor:=s->'effects'->-1; h:=h||jsonb_build_object('effectId',successor->'id','hash',successor->'hash','version',(h->>'version')::INTEGER+1,'reversed',FALSE); s:=jsonb_set(s,'{rulings}',(SELECT jsonb_agg(CASE WHEN x->'scopeId'=h->'scopeId' THEN h ELSE x END ORDER BY ord) FROM jsonb_array_elements(s->'rulings') WITH ORDINALITY heads(x,ord))); RETURN s||jsonb_build_object('correctionReview',NULL);
END $$;

CREATE FUNCTION public.int9_grant(s JSONB,c JSONB,proposal JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r JSONB:=public.int9_round(s,c->>'roundId'); scope JSONB; "grant" JSONB; entropy JSONB; scope_index INTEGER; BEGIN
 IF c->>'type'='CREATE_GRANT' THEN SELECT x,ord::INTEGER-1 INTO scope,scope_index FROM jsonb_array_elements(s->'grantScopes') WITH ORDINALITY scopes(x,ord) WHERE x->'roundId'=r->'id' AND x->>'role'=c->>'role' AND x->'assignmentId' IS NOT DISTINCT FROM CASE WHEN c->>'role'='ACTOR' THEN r->'assignment'->'id' ELSE 'null'::JSONB END;
 ELSE SELECT x,ord::INTEGER-1 INTO scope,scope_index FROM jsonb_array_elements(s->'grantScopes') WITH ORDINALITY scopes(x,ord) WHERE x->>'id'=c->>'scopeId'; END IF;
 IF (s->>'finished')::BOOLEAN OR c->>'type'<>'REVOKE_GRANT' AND (public.int9_review(s) OR s->'activeRoundId' IS DISTINCT FROM r->'id' OR r->'pause'<>'null'::JSONB OR (r->>'publicRevealed')::BOOLEAN OR r->'deadline'='null'::JSONB OR moment>=(r->>'deadline')::DOUBLE PRECISION OR r->>'phase' NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN')) THEN PERFORM public.int9_error('INVALID_PHASE'); END IF;
 IF c->>'type'='CREATE_GRANT' THEN
  IF (CASE c->>'role' WHEN 'JUDGE' THEN NOT public.int9_items(r) ELSE r->'assignment'='null'::JSONB OR r->'pin'->>'format' NOT IN ('ACTING_ITEMS','DRAWING_TARGET') END) THEN PERFORM public.int9_error('ASSIGNMENT_UNAVAILABLE'); END IF;
  IF scope IS NOT NULL AND scope->'activeGrantId'<>'null'::JSONB THEN PERFORM public.int9_error('GRANT_ALREADY_ACTIVE'); END IF;
  IF scope IS NULL THEN scope_index:=jsonb_array_length(s->'grantScopes'); scope:=jsonb_build_object('id',gen_random_uuid()::TEXT,'roundId',r->'id','role',c->'role','assignmentId',CASE WHEN c->>'role'='ACTOR' THEN r->'assignment'->'id' ELSE 'null'::JSONB END,'generation',0,'activeGrantId',NULL); s:=s||jsonb_build_object('grantScopes',s->'grantScopes'||jsonb_build_array(scope)); END IF;
 END IF;
 IF scope IS NULL OR c->>'type'='ROTATE_GRANT' AND scope->'generation' IS DISTINCT FROM c->'expectedGeneration' THEN PERFORM public.int9_error('STALE_GRANT_GENERATION'); END IF;
 IF c->>'type'<>'REVOKE_GRANT' AND scope->>'role'='ACTOR' AND scope->'assignmentId' IS DISTINCT FROM r->'assignment'->'id' THEN PERFORM public.int9_error('ASSIGNMENT_UNAVAILABLE'); END IF;
 -- Only opaque server-generated entropy is accepted from the TS proposal.
 -- No role/scope/generation/time/score/disclosure field is trusted. API strict
 -- command shapes never expose this hash input. Token is not stored or logged.
 SELECT x INTO entropy FROM jsonb_array_elements(proposal->'grants') x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'grants') old WHERE old->'id'=x->'id'); IF entropy IS NULL OR jsonb_typeof(entropy->'tokenHash') IS DISTINCT FROM 'string' OR entropy->>'tokenHash'!~'^[a-f0-9]{64}$' OR EXISTS(SELECT 1 FROM public."RoundGrant" old WHERE old."tokenHash"=entropy->>'tokenHash') OR (SELECT count(*) FROM jsonb_array_elements(proposal->'grants') x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'grants') old WHERE old->'id'=x->'id'))<>1 THEN PERFORM public.int9_error('GRANT_DATA_UNAVAILABLE'); END IF;
 s:=jsonb_set(s,'{grants}',(SELECT COALESCE(jsonb_agg(CASE WHEN x->'id'=scope->'activeGrantId' THEN x||jsonb_build_object('revoked',TRUE) ELSE x END ORDER BY ord),'[]'::JSONB) FROM jsonb_array_elements(s->'grants') WITH ORDINALITY grants(x,ord))); s:=public.int9_host_event(s,c,r->>'id',moment);
 "grant":=jsonb_build_object('id',s->'events'->-1->'id','scopeId',scope->'id','roundId',r->'id','role',scope->'role','assignmentId',scope->'assignmentId','generation',(scope->>'generation')::INTEGER+1,'tokenHash',entropy->'tokenHash','expiresAt',CASE WHEN c->>'type'='REVOKE_GRANT' THEN moment ELSE moment+(c->>'durationSeconds')::INTEGER*1000 END,'revoked',c->>'type'='REVOKE_GRANT'); scope:=scope||jsonb_build_object('generation',"grant"->'generation','activeGrantId',CASE WHEN c->>'type'='REVOKE_GRANT' THEN 'null'::JSONB ELSE "grant"->'id' END); s:=jsonb_set(s,ARRAY['grantScopes',scope_index::TEXT],scope); s:=s||jsonb_build_object('grants',s->'grants'||jsonb_build_array("grant")); IF c->>'type'<>'REVOKE_GRANT' THEN s:=public.int9_seal(public.int9_effect(s,r,'DISCLOSURE','{}'::JSONB)); END IF; RETURN s;
END $$;
CREATE OR REPLACE FUNCTION public.int9_result(s JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result JSONB; BEGIN
 IF s->'finished' IS DISTINCT FROM 'true'::JSONB OR s->'results' IS DISTINCT FROM '[]'::JSONB OR s->'tournamentBinding' IS DISTINCT FROM 'null'::JSONB OR public.int9_review(s) OR s->'activeRoundId'<>'null'::JSONB THEN PERFORM public.int9_error('RESULT_NOT_TERMINAL'); END IF;
 result:=public.int9_result_material(s->>'id',s->'events'->-1,s->>'resultReason'); RETURN s||jsonb_build_object('results',jsonb_build_array(result));
END $$;
CREATE OR REPLACE FUNCTION public.int9_reduce(s JSONB,c JSONB,proposal JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE kind TEXT:=c->>'type'; r JSONB; before_clock JSONB; hint JSONB; target_id TEXT; tid TEXT; player JSONB; remaining INTEGER; pause JSONB; BEGIN
 IF (s->>'finished')::BOOLEAN THEN PERFORM public.int9_error('MATCH_FINISHED'); END IF;
 IF s->'openItemReview'<>'null'::JSONB AND kind NOT IN ('RESOLVE_ITEM_REVIEW','REVOKE_GRANT') OR s->'correctionReview'<>'null'::JSONB AND kind NOT IN ('CORRECT_RULING','REVOKE_GRANT') THEN PERFORM public.int9_error('RULING_REVIEW_OPEN'); END IF;
 r:=public.int9_round(s,c->>'roundId');
 IF r->'resourceStop' IS DISTINCT FROM 'null'::JSONB AND r IS NOT NULL AND kind NOT IN ('PUBLIC_REVEAL','FINAL_RULING','CLOSE_ROUND','END_ASSISTANCE','RESUME_ROUND','REVOKE_GRANT','RESOLVE_ITEM_REVIEW','CORRECT_RULING','FINISH','REPORT_VAR') THEN PERFORM public.int9_error('RESOURCE_LIMIT_REACHED'); END IF;
 CASE kind
 WHEN 'USE_AID' THEN RETURN public.int9_aid(s,c,moment);
 WHEN 'RECORD_ATTEMPT' THEN RETURN public.int9_attempt(s,c,moment);
 WHEN 'INTERIM_WRONG' THEN RETURN public.int9_interim(s,c,moment);
 WHEN 'PUBLIC_REVEAL' THEN RETURN public.int9_reveal(s,c,moment);
 WHEN 'FINAL_RULING' THEN RETURN public.int9_ruling(s,c,moment);
 WHEN 'UNDO_EFFECT' THEN RETURN public.int9_undo(s,c,moment);
 WHEN 'CORRECT_RULING' THEN RETURN public.int9_correct(s,c,moment);
 WHEN 'RESOLVE_ITEM_REVIEW' THEN RETURN public.int9_resolve_review(s,c,moment);
 WHEN 'CREATE_GRANT','ROTATE_GRANT','REVOKE_GRANT' THEN RETURN public.int9_grant(s,c,proposal,moment);
 WHEN 'OPEN_ROUND','NEXT_ROUND' THEN
  IF s->'activeRoundId'<>'null'::JSONB OR public.int9_review(s) OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'attempts') a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'classifications') cl WHERE cl->'attemptId'=a->'id')) THEN PERFORM public.int9_error('PENDING_RULING_REQUIRED'); END IF;
  IF kind='NEXT_ROUND' THEN SELECT x INTO r FROM jsonb_array_elements(s->'rounds') WITH ORDINALITY rounds(x,ord) WHERE x->>'phase'='READY' ORDER BY ord LIMIT 1; END IF;
  IF r IS NULL OR r->>'phase'<>'READY' OR public.int9_standalone(s) AND r->'id' IS DISTINCT FROM (SELECT x->'id' FROM jsonb_array_elements(s->'rounds') WITH ORDINALITY rounds(x,ord) WHERE x->>'phase'='READY' ORDER BY ord LIMIT 1) THEN PERFORM public.int9_error('INVALID_PHASE'); END IF;
  s:=public.int9_host_event(s,c,r->>'id',moment); tid:=s->'teams'->((s->>'turnIndex')::INTEGER%jsonb_array_length(s->'teams'))->>'id';
  r:=r||jsonb_build_object('originalTeamId',tid,'currentTeamId',tid,'phase',CASE WHEN public.int9_standalone(s) THEN 'TURN' WHEN public.int9_items(r) THEN 'SHARED' ELSE 'MAIN' END,'phaseOrdinal',1,'generation',1,'deadline',moment+(CASE WHEN public.int9_standalone(s) THEN (s->'request'->'setup'->'rules'->>'turnSeconds')::INTEGER*1000 WHEN public.int9_items(r) THEN 40000 ELSE (s->'request'->'setup'->'rules'->>'questionSeconds')::INTEGER*1000 END),'overallDeadline',CASE WHEN public.int9_standalone(s) AND s->'request'->'setup'->'rules'->'overallSeconds'<>'null'::JSONB THEN moment+(s->'request'->'setup'->'rules'->>'overallSeconds')::INTEGER*1000 ELSE NULL END,'version',(r->>'version')::INTEGER+1); r:=r||jsonb_build_object('originalDeadline',r->'deadline'); s:=public.int8_put_round(s||jsonb_build_object('activeRoundId',r->'id'),r);
  IF r->'pin'->>'format'='DRAWING_TARGET' THEN s:=s||jsonb_build_object('canvases',s->'canvases'||jsonb_build_array(jsonb_build_object('roundId',r->'id','revision',0,'strokes','[]'::JSONB,'visibleIds','[]'::JSONB,'redoIds','[]'::JSONB,'cumulativePoints',0,'mutations',0,'receipts','[]'::JSONB))); END IF; RETURN public.int9_seal(public.int9_effect(s,r,'TIMING','{}'::JSONB));
 WHEN 'REVEAL_HINT','SELECT_SCORING_TEAM','ASSIGN_ACTOR','PAUSE_ROUND','CLOSE_ROUND' THEN
  IF s->'activeRoundId' IS DISTINCT FROM r->'id' OR r->>'phase' IN ('READY','RESOLVED') OR r->'pause'<>'null'::JSONB THEN PERFORM public.int9_error('INVALID_PHASE'); END IF; before_clock:=public.int9_snapshot(r);
  IF kind='REVEAL_HINT' THEN IF (r->>'publicRevealed')::BOOLEAN OR r->'revealedHintIds'<>'[]'::JSONB OR r->'pin'->>'format' NOT IN ('ORDINARY_TIER','DRAWING_TARGET') THEN PERFORM public.int9_error('HINT_UNAVAILABLE'); END IF; hint:=r->'pin'->'hints'->0; IF hint IS NULL OR r->'pin'->>'format'='DRAWING_TARGET' AND hint->'safeDrawing' IS DISTINCT FROM 'true'::JSONB THEN PERFORM public.int9_error('HINT_UNAVAILABLE'); END IF; r:=r||jsonb_build_object('revealedHintIds',jsonb_build_array(hint->'id'));
  ELSIF kind='SELECT_SCORING_TEAM' THEN IF r->>'phase'<>'SHARED' OR NOT public.int9_items(r) OR (r->>'publicRevealed')::BOOLEAN THEN PERFORM public.int9_error('INVALID_PHASE'); END IF; r:=r||jsonb_build_object('currentTeamId',c->'teamId');
  ELSIF kind='ASSIGN_ACTOR' THEN IF (r->>'publicRevealed')::BOOLEAN OR r->'pin'->>'format' NOT IN ('ACTING_ITEMS','DRAWING_TARGET') OR r->'pin'->>'format'='DRAWING_TARGET' AND c->'itemId'<>'null'::JSONB OR r->'pin'->>'format'='ACTING_ITEMS' AND (c->'itemId'='null'::JSONB OR r->'itemReveals' @> jsonb_build_array(c->'itemId') OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=c->'itemId')) THEN PERFORM public.int9_error('ASSIGNMENT_UNAVAILABLE'); END IF;
  ELSIF kind='PAUSE_ROUND' THEN IF r->'deadline'='null'::JSONB OR (r->>'publicRevealed')::BOOLEAN THEN PERFORM public.int9_error('INVALID_PHASE'); END IF;
  ELSE IF r->'publicRevealed' IS DISTINCT FROM 'true'::JSONB OR public.int9_pending(s,r->>'id',NULL,TRUE)<>'[]'::JSONB THEN PERFORM public.int9_error('PENDING_RULING_REQUIRED'); END IF; END IF;
  s:=public.int9_host_event(s,c,r->>'id',moment);
  IF kind='ASSIGN_ACTOR' THEN s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id'); r:=r||jsonb_build_object('version',(r->>'version')::INTEGER+1,'assignment',jsonb_build_object('id',s->'events'->-1->'id','teamId',c->'teamId','playerId',c->'playerId','itemId',c->'itemId','generation',(r->>'version')::INTEGER+1));
  ELSIF kind='PAUSE_ROUND' THEN r:=r||jsonb_build_object('pause',jsonb_build_object('cause','ADMIN','eventId',s->'events'->-1->'id','resumeAt',NULL,'phaseRemaining',(r->>'deadline')::DOUBLE PRECISION-moment,'overallRemaining',CASE WHEN r->'overallDeadline'='null'::JSONB THEN NULL ELSE (r->>'overallDeadline')::DOUBLE PRECISION-moment END),'deadline',NULL,'overallDeadline',NULL); s:=public.int9_invalidate(s,r,FALSE); r:=public.int9_round(s,r->>'id');
  ELSIF kind='CLOSE_ROUND' THEN s:=public.int9_close(s,r,'HOST_CLOSED'); r:=public.int9_round(s,r->>'id'); END IF;
  s:=public.int8_put_round(s,r); RETURN public.int9_seal(public.int9_effect(s,r,CASE WHEN kind IN ('ASSIGN_ACTOR','REVEAL_HINT') THEN 'DISCLOSURE' ELSE 'TIMING' END,CASE WHEN kind='PAUSE_ROUND' THEN jsonb_build_object('beforeClock',before_clock) ELSE '{}'::JSONB END));
 WHEN 'END_ASSISTANCE','RESUME_ROUND' THEN
  IF s->'activeRoundId' IS DISTINCT FROM r->'id' OR r->>'phase' IN ('READY','RESOLVED') OR r->'pause'='null'::JSONB OR (CASE kind WHEN 'END_ASSISTANCE' THEN r->'pause'->>'cause'<>'PHONE' ELSE r->'pause'->>'cause'='PHONE' END) THEN PERFORM public.int9_error('INVALID_PHASE'); END IF;
  before_clock:=public.int9_snapshot(r); s:=public.int9_host_event(s,c,r->>'id',moment); pause:=r->'pause'; r:=r||jsonb_build_object('deadline',CASE WHEN pause->'phaseRemaining'='null'::JSONB THEN NULL ELSE moment+(pause->>'phaseRemaining')::DOUBLE PRECISION END,'overallDeadline',CASE WHEN pause->'overallRemaining'='null'::JSONB THEN NULL ELSE moment+(pause->>'overallRemaining')::DOUBLE PRECISION END,'pause',NULL,'version',(r->>'version')::INTEGER+1); s:=public.int8_put_round(s,r); RETURN public.int9_seal(public.int9_effect(s,r,'TIMING',jsonb_build_object('beforeClock',before_clock)));
 WHEN 'FINISH' THEN
  IF s->'activeRoundId'<>'null'::JSONB OR public.int9_review(s) OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'attempts') a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'classifications') cl WHERE cl->'attemptId'=a->'id')) THEN PERFORM public.int9_error('PENDING_RULING_REQUIRED'); END IF; SELECT count(*) INTO remaining FROM jsonb_array_elements(s->'rounds') x WHERE x->>'phase'<>'RESOLVED'; IF remaining>0 AND c->'confirmEarly' IS DISTINCT FROM 'true'::JSONB THEN PERFORM public.int9_error('EARLY_FINISH_CONFIRMATION_REQUIRED'); END IF;
  s:=public.int9_host_event(s,c,NULL,moment); s:=s||jsonb_build_object('finished',TRUE,'resultReason',CASE WHEN remaining>0 THEN 'HOST_ENDED' ELSE 'ALL_ROUNDS' END); s:=public.int9_seal(public.int9_effect(s,NULL,'FINISH','{}'::JSONB)); RETURN public.int9_result(s);
 WHEN 'RESOLVE_TIE' THEN PERFORM public.int9_error('TIE_AUTHORITY_UNAVAILABLE');
 ELSE PERFORM public.int9_error('INVALID_COMMAND'); END CASE; RETURN s;
END $$;

CREATE FUNCTION public.int9_assert_competitive(release_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 -- Separate independently reviewed competitive receipt/hint/grapheme/palette
 -- issuer and activation do not exist. Neither a sealed row nor client Boolean
 -- bypasses this production denial. No authoring route, seed or GUC authority.
 PERFORM public.int9_error('COMPETITIVE_RECEIPT_POLICY_UNAVAILABLE');
END $$;
CREATE FUNCTION public.int9_prompt_pin(prompt_id TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE p public."EntaCompetitivePrompt"%ROWTYPE; base JSONB; hints JSONB; graphemes JSONB; BEGIN
 SELECT * INTO p FROM public."EntaCompetitivePrompt" WHERE "id"=prompt_id; IF NOT FOUND THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF; base:=public.int8_prompt_pin(p."formatId");
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',"id",'revisionId',"questionRevisionId",'revisionHash',"questionHash",'ordinal',"ordinal",'text',"text",'contentHash',"contentHash",'safeDrawing',"safeDrawing") ORDER BY "ordinal"),'[]'::JSONB) INTO hints FROM public."EntaCompetitiveHint" WHERE "promptId"=p."id";
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',g."id",'answerRevisionId',g."answerRevisionId",'answerHash',g."answerHash",'segmentationVersion',g."segmentationVersion",'grapheme',g."grapheme",'proofHash',g."proofHash") ORDER BY item."ordinal"),'[]'::JSONB) INTO graphemes FROM public."EntaCompetitiveGrapheme" g JOIN public."EntaFormatItem" item ON item."formatId"=p."formatId" AND item."answerRevisionId"=g."answerRevisionId" AND item."answerHash"=g."answerHash" WHERE g."promptId"=p."id";
 RETURN base||jsonb_build_object('hints',hints,'graphemes',graphemes,'hintRoot',p."hintRoot",'effectValue',p."effectValue",'effectValueSource',p."effectValueSource",'proofHash',p."proofHash");
END $$;
CREATE FUNCTION public.int9_catalog(ns TEXT,project TEXT,uid TEXT,execution_format TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN PERFORM public.int6_enta_identity(ns,project,uid); PERFORM public.int9_error('COMPETITIVE_RECEIPT_POLICY_UNAVAILABLE'); RETURN NULL; END $$;
CREATE FUNCTION public.int9_proof_child_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE release_id TEXT; stamp TIMESTAMPTZ; BEGIN
 IF TG_OP='UPDATE' AND (TG_TABLE_NAME='EntaCompetitivePrompt' AND to_jsonb(OLD)->'releaseId' IS DISTINCT FROM to_jsonb(NEW)->'releaseId' OR TG_TABLE_NAME<>'EntaCompetitivePrompt' AND to_jsonb(OLD)->'promptId' IS DISTINCT FROM to_jsonb(NEW)->'promptId') THEN PERFORM public.int9_error('IMMUTABLE_COMPETITIVE_ANCESTRY'); END IF;
 IF TG_TABLE_NAME='EntaCompetitivePrompt' THEN release_id:=(CASE WHEN TG_OP='DELETE' THEN OLD."releaseId" ELSE NEW."releaseId" END); ELSE SELECT "releaseId" INTO release_id FROM public."EntaCompetitivePrompt" WHERE "id"=(CASE WHEN TG_OP='DELETE' THEN OLD."promptId" ELSE NEW."promptId" END); END IF;
 SELECT "sealedAt" INTO stamp FROM public."EntaCompetitiveRelease" WHERE "id"=release_id FOR UPDATE; IF NOT FOUND OR stamp IS NOT NULL THEN PERFORM public.int9_error('IMMUTABLE_COMPETITIVE_PROOF'); END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;
CREATE FUNCTION public.int9_proof_seal_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE p public."EntaCompetitivePrompt"%ROWTYPE; pin JSONB; base JSONB; hint JSONB; grapheme JSONB; proofs JSONB; expected_root TEXT; BEGIN
 IF TG_OP='INSERT' THEN IF NEW."sealedAt" IS NOT NULL THEN PERFORM public.int9_error('IMMUTABLE_COMPETITIVE_PROOF'); END IF; RETURN NEW; END IF;
 IF OLD."sealedAt" IS NOT NULL OR (to_jsonb(NEW)-'sealedAt') IS DISTINCT FROM (to_jsonb(OLD)-'sealedAt') OR NEW."sealedAt" IS NULL OR NEW."rulesVersion"<>'enta-competitive-1' OR NEW."paletteRoot"<>public.int9_palette_root() OR NEW."issuerEvidenceHash"!~'^[a-f0-9]{64}$' OR NOT EXISTS(SELECT 1 FROM public."EntaFormatRelease" f WHERE f."id"=NEW."formatReleaseId" AND f."formatRoot"=NEW."formatRoot" AND f."mediaRoot"=NEW."mediaRoot" AND f."sealedAt" IS NOT NULL) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 IF (SELECT count(*) FROM public."EntaCompetitivePrompt" WHERE "releaseId"=NEW."id") NOT BETWEEN 1 AND 6000 THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 FOR p IN SELECT * FROM public."EntaCompetitivePrompt" WHERE "releaseId"=NEW."id" ORDER BY "formatId" COLLATE "C" LOOP
  IF NOT EXISTS(SELECT 1 FROM public."EntaFormatRevision" f WHERE f."id"=p."formatId" AND f."releaseId"=NEW."formatReleaseId" AND f."questionRevisionId"=p."questionRevisionId" AND f."questionHash"=p."questionHash") THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
  pin:=public.int9_prompt_pin(p."id"); base:=pin-ARRAY['hints','graphemes','hintRoot','effectValue','effectValueSource','proofHash'];
  IF p."hintRoot"<>public.int6_enta_hash(jsonb_build_object('hints',pin->'hints','graphemes',pin->'graphemes')) OR p."proofHash"<>public.int6_enta_hash(jsonb_build_object('version','enta-competitive-1','baseHash',public.int6_enta_hash(base),'hints',pin->'hints','graphemes',pin->'graphemes','hintRoot',p."hintRoot",'effectValue',p."effectValue",'effectValueSource',p."effectValueSource")) OR p."effectValue" IS DISTINCT FROM (CASE WHEN base->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') THEN 200 ELSE (base->>'points')::INTEGER END) OR p."effectValueSource" IS DISTINCT FROM (CASE WHEN base->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') THEN 'OWNER_EMBEDDED_200' ELSE 'PINNED_TIER' END) OR jsonb_array_length(pin->'hints')>4 OR jsonb_array_length(pin->'graphemes')>128 THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
  FOR hint IN SELECT x FROM jsonb_array_elements(pin->'hints') x LOOP IF public.int6_enta_valid_text(hint->'text',1,512) IS NOT TRUE OR hint->'revisionId'<>base->'revisionId' OR hint->'revisionHash'<>base->'hash' OR hint->>'contentHash'<>public.int6_enta_hash(jsonb_build_object('ordinal',hint->'ordinal','text',hint->'text')) THEN PERFORM public.int9_error('HINT_PROOF_UNAVAILABLE'); END IF; END LOOP;
  IF EXISTS(SELECT 1 FROM generate_series(0,jsonb_array_length(pin->'hints')-1) n WHERE NOT EXISTS(SELECT 1 FROM public."EntaCompetitiveHint" h WHERE h."promptId"=p."id" AND h."ordinal"=n)) THEN PERFORM public.int9_error('HINT_PROOF_UNAVAILABLE'); END IF;
  FOR grapheme IN SELECT x FROM jsonb_array_elements(pin->'graphemes') x LOOP
   IF grapheme->>'segmentationVersion'<>'unicode-17.0-icu-78.3' OR grapheme->>'proofHash'<>public.int6_enta_hash(grapheme-ARRAY['id','proofHash']) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(base->'items') item WHERE item->'revisionId'=grapheme->'answerRevisionId' AND item->'hash'=grapheme->'answerHash' AND item->'trap'='false'::JSONB) OR public.int6_enta_valid_text(grapheme->'grapheme',1,64) IS NOT TRUE THEN PERFORM public.int9_error('GRAPHEME_PROOF_UNAVAILABLE'); END IF;
   -- SQL pins a named independently issued Unicode segmentation proof; it
   -- never substitutes code-unit/code-point slicing for a grapheme algorithm.
  END LOOP;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('formatId',"formatId",'proofHash',"proofHash") ORDER BY "formatId" COLLATE "C") INTO proofs FROM public."EntaCompetitivePrompt" WHERE "releaseId"=NEW."id";
 expected_root:=public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.competitive-release.v1','version','enta-competitive-1','competitiveReleaseId',NEW."id",'formatReleaseId',NEW."formatReleaseId",'formatRoot',NEW."formatRoot",'mediaRoot',NEW."mediaRoot",'paletteRoot',NEW."paletteRoot",'promptProofs',proofs)); IF NEW."proofRoot"<>expected_root THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 -- Root+issuer association is immutable evidence, not editorial permission.
 -- Production admission assertion above remains unconditional denial.
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.int9_store_facts(s JSONB,old JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE x JSONB; e JSONB; r JSONB; t JSONB; idx INTEGER; BEGIN
 PERFORM public.int9_capacity_preflight(s,old);
 FOR e IN SELECT value FROM jsonb_array_elements(s->'events') LOOP
  INSERT INTO public."RoundAuthorityEvent"("id","gameId","ownerIdentityId","roundId","commandId","sequence","type","intentHash","authorityKind","authorityGrantId","authorityGeneration","assignmentId","systemOperation","pauseReason","at") SELECT e->>'id',s->>'id',s->>'identityId',e->>'roundId',e->>'commandId',(e->>'sequence')::INTEGER,e->>'type',e->>'hash',e->'authority'->>'kind',e->'authority'->>'grantId',(e->'authority'->>'generation')::INTEGER,e->'authority'->>'assignmentId',e->'authority'->>'operation',e->>'pauseReason',to_timestamp((e->>'at')::DOUBLE PRECISION/1000) WHERE NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" prior WHERE prior."id"=e->>'id');
 END LOOP;
 -- Assignment events pin stable roster identity even after runtime clears it.
 FOR r IN SELECT value FROM jsonb_array_elements(s->'rounds') WHERE value->'assignment'<>'null'::JSONB LOOP
  x:=r->'assignment'; SELECT ord::INTEGER-1 INTO idx FROM jsonb_array_elements(s->'teams') team CROSS JOIN LATERAL jsonb_array_elements(team->'players') WITH ORDINALITY players(player,ord) WHERE team->'id'=x->'teamId' AND player->'id'=x->'playerId';
  INSERT INTO public."RoundActorAssignment"("id","gameId","roundId","teamId","playerIndex","itemId","generation") SELECT x->>'id',s->>'id',r->>'id',x->>'teamId',idx,x->>'itemId',(x->>'generation')::INTEGER WHERE NOT EXISTS(SELECT 1 FROM public."RoundActorAssignment" prior WHERE prior."id"=x->>'id');
  INSERT INTO public."CompetitiveAssignmentPlayer"("assignmentId","gameId","roundId","teamId","playerId","generation","targetHash") SELECT x->>'id',s->>'id',r->>'id',x->>'teamId',x->>'playerId',(x->>'generation')::INTEGER,public.int6_enta_hash(jsonb_build_object('revisionId',r->'pin'->'revisionId','revisionHash',r->'pin'->'hash','target',r->'pin'->'target')) WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveAssignmentPlayer" prior WHERE prior."assignmentId"=x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'grantScopes') LOOP
  INSERT INTO public."RoundGrantScope"("id","gameId","roundId","role","assignmentId","generation","activeGrantId") VALUES(x->>'id',s->>'id',x->>'roundId',x->>'role',x->>'assignmentId',(x->>'generation')::INTEGER,x->>'activeGrantId') ON CONFLICT("id") DO UPDATE SET "generation"=EXCLUDED."generation","activeGrantId"=EXCLUDED."activeGrantId" WHERE "RoundGrantScope"."gameId"=s->>'id' AND "RoundGrantScope"."roundId"=EXCLUDED."roundId";
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'grants') LOOP
  INSERT INTO public."RoundGrant"("id","gameId","scopeId","roundId","role","assignmentId","generation","tokenHash","expiresAt","revoked") VALUES(x->>'id',s->>'id',x->>'scopeId',x->>'roundId',x->>'role',x->>'assignmentId',(x->>'generation')::INTEGER,x->>'tokenHash',to_timestamp((x->>'expiresAt')::DOUBLE PRECISION/1000),(x->>'revoked')::BOOLEAN) ON CONFLICT("id") DO UPDATE SET "revoked"=EXCLUDED."revoked" WHERE "RoundGrant"."gameId"=s->>'id';
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'disclosures') LOOP
  INSERT INTO public."CompetitiveTargetDisclosure"("id","gameId","roundId","targetRevisionId","targetHash","teamId","playerId","assignmentId","assignmentGeneration","grantId","grantGeneration","createdAt") SELECT x->>'id',s->>'id',x->>'roundId',x->>'targetRevisionId',x->>'targetHash',(SELECT "teamId" FROM public."CompetitiveRosterPlayer" WHERE "gameId"=s->>'id' AND "playerId"=x->>'playerId'),x->>'playerId',x->>'assignmentId',(x->>'assignmentGeneration')::INTEGER,x->>'grantId',(x->>'grantGeneration')::INTEGER,to_timestamp((x->>'at')::DOUBLE PRECISION/1000) WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveTargetDisclosure" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'attempts') LOOP
  INSERT INTO public."CompetitiveAttempt"("id","gameId","roundId","itemId","teamId","playerId","phase","phaseOrdinal","generation","ordinal","acceptedAt","deadline","eventId","pickedEventId","allowanceId","bonusEventId","disclosureHeadId","payload","eligibilityHash") SELECT x->>'id',s->>'id',x->>'roundId',x->>'itemId',x->>'teamId',x->>'playerId',x->>'phase',(x->>'phaseOrdinal')::INTEGER,(x->>'generation')::INTEGER,(x->>'ordinal')::INTEGER,to_timestamp((x->>'acceptedAt')::DOUBLE PRECISION/1000),to_timestamp((x->>'deadline')::DOUBLE PRECISION/1000),x->>'eventId',x->>'pickedEventId',x->>'allowanceId',x->>'bonusEventId',x->>'disclosureHead',x,x->>'eligibilityHash' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'classifications') LOOP
  INSERT INTO public."CompetitiveClassification"("id","gameId","attemptId","eventId","correct","interim") SELECT x->>'id',s->>'id',x->>'attemptId',x->>'eventId',(x->>'correct')::BOOLEAN,(x->>'interim')::BOOLEAN WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'effects') LOOP
  INSERT INTO public."CompetitiveEffect"("id","gameId","roundId","eventId","sequence","kind","amountKind","reversible","barrier","predecessorId","predecessorHash","hash","payload") SELECT x->>'id',s->>'id',x->>'roundId',x->>'eventId',(x->>'sequence')::INTEGER,x->>'kind',x->>'amountKind',(x->>'reversible')::BOOLEAN,(x->>'barrier')::BOOLEAN,x->>'predecessorId',x->>'predecessorHash',x->>'hash',x WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'consumptions') LOOP
  INSERT INTO public."CompetitiveConsumption"("id","gameId","roundId","teamId","allowanceId","eventId","effectId","aid") SELECT x->>'id',s->>'id',x->>'roundId',x->>'teamId',x->>'allowanceId',x->>'eventId',x->>'effectId',x->>'aid' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveConsumption" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'postings') LOOP
  INSERT INTO public."CompetitiveScorePosting"("id","gameId","effectId","teamId","delta","before","after","scoreVersion","previousHeadId") SELECT x->>'id',s->>'id',x->>'effectId',x->>'teamId',(x->>'delta')::INTEGER,(x->>'before')::INTEGER,(x->>'after')::INTEGER,(x->>'scoreVersion')::INTEGER,x->>'previousHead' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveScorePosting" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(s->'effects') LOOP
 FOR x IN SELECT value FROM jsonb_array_elements(e->'reads') LOOP
  idx:=COALESCE((SELECT ord::INTEGER-1 FROM jsonb_array_elements(e->'reads') WITH ORDINALITY reads(value,ord) WHERE value=x ORDER BY ord LIMIT 1),0);
  INSERT INTO public."CompetitiveScoreRead"("gameId","effectId","ordinal","teamId","scoreVersion","value","sourceEffectId","kind") SELECT s->>'id',e->>'id',idx,x->>'teamId',(x->>'scoreVersion')::INTEGER,(x->>'value')::INTEGER,x->>'sourceEffectId',x->>'kind' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveScoreRead" prior WHERE prior."effectId" IS NOT DISTINCT FROM e->>'id' AND prior."ordinal" IS NOT DISTINCT FROM idx);
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(e->'dependencies') LOOP
  INSERT INTO public."CompetitiveDependency"("gameId","effectId","sourceEffectId") SELECT s->>'id',e->>'id',x#>>'{}' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveDependency" prior WHERE prior."effectId" IS NOT DISTINCT FROM e->>'id' AND prior."sourceEffectId" IS NOT DISTINCT FROM x#>>'{}');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(e->'originalAttemptIds') LOOP
  INSERT INTO public."CompetitiveEffectAttempt"("gameId","effectId","roundId","attemptId","correct","bonusMultiplier","bonusEventId") SELECT s->>'id',e->>'id',e->>'roundId',x#>>'{}',e->'correctAttemptIds' @> jsonb_build_array(x),COALESCE((SELECT (b->>'multiplier')::INTEGER FROM jsonb_array_elements(e->'bonusSnapshot') b WHERE b->'attemptId'=x),1),(SELECT b->>'sourceEventId' FROM jsonb_array_elements(e->'bonusSnapshot') b WHERE b->'attemptId'=x) WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveEffectAttempt" prior WHERE prior."effectId" IS NOT DISTINCT FROM e->>'id' AND prior."attemptId" IS NOT DISTINCT FROM x#>>'{}');
 END LOOP;
  IF e->>'kind'='REVERSAL' THEN INSERT INTO public."CompetitiveReversal"("originalEffectId","gameId","originalHash","reversalEffectId") SELECT e->>'predecessorId',s->>'id',e->>'predecessorHash',e->>'id' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveReversal" prior WHERE prior."originalEffectId"=e->>'predecessorId'); END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(s->'rounds') WHERE value->'contextSummary' IS DISTINCT FROM 'true'::JSONB LOOP
 FOR x IN SELECT value FROM jsonb_array_elements(r->'consumed') LOOP
  INSERT INTO public."CompetitiveItemConsumption"("gameId","roundId","itemId","effectId","teamId") SELECT s->>'id',r->>'id',x->>'itemId',x->>'effectId',x->>'teamId' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" prior WHERE prior."roundId" IS NOT DISTINCT FROM r->>'id' AND prior."itemId" IS NOT DISTINCT FROM x->>'itemId');
 END LOOP;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'itemReviews') LOOP
  INSERT INTO public."CompetitiveItemReview"("id","gameId","roundId","itemId","originalEffectId","originalHash","reversalEffectId","consumptionEffectId","eventId","predecessorVersion","predecessorHash","hash","payload") SELECT x->>'id',s->>'id',x->>'roundId',x->>'itemId',x->>'originalEffectId',x->>'originalEffectHash',x->>'reversalEffectId',x->>'consumptionEffectId',x->>'eventId',(x->>'predecessorRulingVersion')::INTEGER,x->>'predecessorRulingHash',x->>'hash',x WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveItemReview" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'itemResolutions') LOOP
  INSERT INTO public."CompetitiveItemResolution"("id","gameId","reviewId","reviewHash","effectId","eventId","rulingVersion","rulingHash","mode","reason") SELECT x->>'id',s->>'id',x->>'reviewId',x->>'reviewHash',x->>'effectId',x->>'eventId',(x->>'rulingVersion')::INTEGER,x->>'rulingHash',x->>'mode',x->>'reason' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveItemResolution" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'rulings') LOOP
  INSERT INTO public."CompetitiveRulingHead"("gameId","scopeId","roundId","itemId","originalEffectId","effectId","hash","version","reversed") VALUES(s->>'id',x->>'scopeId',x->>'roundId',x->>'itemId',x->>'originalEffectId',x->>'effectId',x->>'hash',(x->>'version')::INTEGER,(x->>'reversed')::BOOLEAN) ON CONFLICT("gameId","scopeId") DO UPDATE SET "effectId"=EXCLUDED."effectId","hash"=EXCLUDED."hash","version"=EXCLUDED."version","reversed"=EXCLUDED."reversed" WHERE "CompetitiveRulingHead"."roundId"=EXCLUDED."roundId" AND "CompetitiveRulingHead"."originalEffectId"=EXCLUDED."originalEffectId";
 END LOOP;
 INSERT INTO public."CompetitiveRuntimeHead"("gameId","latestEffectId","boardReviewRoundId","openItemReviewId","openItemReviewHash") VALUES(s->>'id',s->>'latestEffectId',s->>'correctionReview',s->>'openItemReview',(SELECT review_row->>'hash' FROM jsonb_array_elements(s->'itemReviews') review_row WHERE review_row->'id'=s->'openItemReview')) ON CONFLICT("gameId") DO UPDATE SET "latestEffectId"=EXCLUDED."latestEffectId","boardReviewRoundId"=EXCLUDED."boardReviewRoundId","openItemReviewId"=EXCLUDED."openItemReviewId","openItemReviewHash"=EXCLUDED."openItemReviewHash";
 FOR r IN SELECT value FROM jsonb_array_elements(s->'rounds') WHERE value->'contextSummary' IS DISTINCT FROM 'true'::JSONB LOOP
  UPDATE public."GameRound" SET "state"=r-'pin' WHERE "gameId"=s->>'id' AND "id"=r->>'id' AND "state" IS DISTINCT FROM r-'pin';
  UPDATE public."GameQuestion" SET "isOpened"=(r->>'phase'<>'READY'),"isCorrect"=(CASE WHEN r->>'phase'='RESOLVED' THEN EXISTS(SELECT 1 FROM public."CompetitiveRulingHead" h JOIN public."CompetitiveEffect" effect ON effect."gameId"=h."gameId" AND effect."id"=h."effectId" WHERE h."gameId"=s->>'id' AND h."roundId"=r->>'id' AND NOT h."reversed" AND effect."payload"->'correctAttemptIds'<>'[]'::JSONB) ELSE NULL END) WHERE "gameId"=s->>'id' AND "id"=r->>'questionId';
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'canvases') LOOP
  IF NOT EXISTS(SELECT 1 FROM public."GameRound" round_row WHERE round_row."gameId"=s->>'id' AND round_row."id"=x->>'roundId' AND round_row."pin"->>'format'='DRAWING_TARGET') THEN PERFORM public.int9_error('CANVAS_DENIED'); END IF;
  INSERT INTO public."DrawingCanvasState"("roundId","revision","state") VALUES(x->>'roundId',(x->>'revision')::INTEGER,x) ON CONFLICT("roundId") DO UPDATE SET "revision"=EXCLUDED."revision","state"=EXCLUDED."state" WHERE EXISTS(SELECT 1 FROM public."GameRound" round_row WHERE round_row."gameId"=s->>'id' AND round_row."id"="DrawingCanvasState"."roundId");
 END LOOP;
 FOR t IN SELECT value FROM jsonb_array_elements(s->'teams') LOOP UPDATE public."Team" SET "score"=(t->>'score')::INTEGER WHERE "gameId"=s->>'id' AND "id"=t->>'id' AND "score" IS DISTINCT FROM (t->>'score')::INTEGER; END LOOP;
 UPDATE public."EntaExecutionPin" SET "state"=jsonb_build_object('contextVersion',1,'gameId',s->'id','version',s->'version') WHERE "gameId"=s->>'id';
 -- One statement per event revision preserves existing GameEvent sequence
 -- guard. SYSTEM/GRANT attribution exists only in RoundAuthorityEvent; never
 -- masquerades as a Firebase host to satisfy a legacy event column.
 FOR e IN SELECT value FROM jsonb_array_elements(s->'events') WITH ORDINALITY events(value,ord) WHERE (value->>'sequence')::INTEGER>(old->>'version')::INTEGER ORDER BY (value->>'sequence')::INTEGER LOOP
  UPDATE public."GameRuntime" SET "version"=(e->>'sequence')::INTEGER,"activeRoundId"=s->>'activeRoundId',"turnIndex"=(s->>'turnIndex')::INTEGER,"state"=(CASE WHEN s->'finished'='true'::JSONB THEN 'FINISHED' ELSE 'BOARD' END),"resultReason"=(CASE WHEN s->'finished'='true'::JSONB THEN CASE WHEN s->>'resultReason'='HOST_ENDED' THEN 'HOST_ENDED' ELSE 'ALL_QUESTIONS_PLAYED' END ELSE NULL END),"unplayedCount"=(CASE WHEN s->'finished'='true'::JSONB THEN (SELECT count(*) FROM jsonb_array_elements(s->'rounds') round_value WHERE round_value->>'phase'<>'RESOLVED') ELSE 0 END),"updatedAt"=to_timestamp((e->>'at')::DOUBLE PRECISION/1000) WHERE "gameId"=s->>'id';
  IF e->'authority'->>'kind'='HOST' THEN INSERT INTO public."GameEvent"("gameId","commandId","sequence","actorFirebaseIdentityId","type","intentHash") VALUES(s->>'id',e->>'commandId',(e->>'sequence')::INTEGER,s->>'identityId',e->>'type',e->>'hash'); END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'results') LOOP
  INSERT INTO public."EngineMatchResult"("gameId","resultVersion","resultHash","ownerIdentityId","admissionId","terminalRevision","terminalEventId","authorityEventId","predecessorVersion","predecessorHash","bindingId","bindingHash","payload") SELECT s->>'id',(x->'payload'->>'resultVersion')::INTEGER,x->>'hash',s->>'identityId',s->>'admissionId',(x->'payload'->'terminal'->>'revision')::INTEGER,x->'payload'->'terminal'->>'eventId',x->'payload'->'authority'->>'eventId',(x->'payload'->'predecessor'->>'version')::INTEGER,x->'payload'->'predecessor'->>'hash',x->'payload'->'tournamentBinding'->>'id',x->'payload'->'tournamentBinding'->>'hash',x->'payload' WHERE NOT EXISTS(SELECT 1 FROM public."EngineMatchResult" prior WHERE prior."gameId" IS NOT DISTINCT FROM s->>'id' AND prior."resultVersion" IS NOT DISTINCT FROM (x->'payload'->>'resultVersion')::INTEGER);
 END LOOP;
 IF jsonb_array_length(s->'results')>0 THEN x:=s->'results'->-1; INSERT INTO public."EngineMatchResultHead"("gameId","resultVersion","resultHash") VALUES(s->>'id',(x->'payload'->>'resultVersion')::INTEGER,x->>'hash') ON CONFLICT("gameId") DO NOTHING; END IF;
 IF s->'finished'='true'::JSONB AND old->'finished'='false'::JSONB THEN UPDATE public."Game" SET "status"='FINISHED',"finishedAt"=to_timestamp((s->'events'->-1->>'at')::DOUBLE PRECISION/1000) AT TIME ZONE 'UTC',"winnerTeamId"=(CASE WHEN s->'results'->-1->'payload'->>'outcome'='DECISIVE' THEN s->'results'->-1->'payload'->'winnerParticipantIds'->>0 ELSE NULL END),"isTie"=s->'results'->-1->'payload'->>'outcome'='UNRESOLVED_TIE' WHERE "id"=s->>'id'; END IF;
END $$;

CREATE OR REPLACE FUNCTION public.int9_assert_stored(game_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE pin public."EntaExecutionPin"%ROWTYPE; profile public."GameCompetitivePin"%ROWTYPE; runtime public."GameRuntime"%ROWTYPE; admission_row public."Admission"%ROWTYPE; head public."CompetitiveRuntimeHead"%ROWTYPE; round_count INTEGER; event_count INTEGER; effect_count INTEGER; team_row RECORD; BEGIN
 SELECT "clientBinding","clientHash","executionFormat","fullIntent","gameId","intentHash","state" INTO pin."clientBinding",pin."clientHash",pin."executionFormat",pin."fullIntent",pin."gameId",pin."intentHash",pin."state" FROM public."EntaExecutionPin" WHERE "gameId"=game_id; SELECT "admissionId","firebaseIdentityId","gameId","paletteRoot","proofRoot","releaseId","requestVersion","rulesVersion" INTO profile."admissionId",profile."firebaseIdentityId",profile."gameId",profile."paletteRoot",profile."proofRoot",profile."releaseId",profile."requestVersion",profile."rulesVersion" FROM public."GameCompetitivePin" WHERE "gameId"=game_id; SELECT "activeQuestionId","activeRoundId","gameId","setup","setupHash","state","teamOrder","turnIndex","version" INTO runtime."activeQuestionId",runtime."activeRoundId",runtime."gameId",runtime."setup",runtime."setupHash",runtime."state",runtime."teamOrder",runtime."turnIndex",runtime."version" FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT "boardReviewRoundId","gameId","latestEffectId","openItemReviewHash","openItemReviewId" INTO head."boardReviewRoundId",head."gameId",head."latestEffectId",head."openItemReviewHash",head."openItemReviewId" FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id;
 IF pin."fullIntent"->>'domain' IS DISTINCT FROM 'maydan.enta.competitive.start-intent.v1' OR pin."fullIntent"->>'pinMaterial' IS DISTINCT FROM 'maydan.enta.competitive.pin-references.v1' THEN PERFORM public.int9_error('DRAFT5_COMPATIBILITY_REVIEW_REQUIRED'); END IF;
 SELECT a."engine",a."id",a."intentHash",a."predecessorAdmissionId",a."requestHash",a."requestVersion",a."state" INTO admission_row."engine",admission_row."id",admission_row."intentHash",admission_row."predecessorAdmissionId",admission_row."requestHash",admission_row."requestVersion",admission_row."state" FROM public."Game" g JOIN public."Admission" a ON a."id"=g."admissionId" AND a."firebaseIdentityId"=g."firebaseIdentityId" WHERE g."id"=game_id AND g."gameFormat"='FIREBASE_PINNED' AND g."firebaseIdentityId"=profile."firebaseIdentityId" AND g."executionFormat"=pin."executionFormat" AND g."catalogReleaseId"=a."catalogReleaseId" AND g."catalogReleaseRootHash"=a."releaseRootHash" AND g."validationReceiptId"=a."validationReceiptId";
 IF pin."gameId" IS NULL OR profile."gameId" IS NULL OR runtime."gameId" IS NULL OR head."gameId" IS NULL OR admission_row."id" IS NULL OR profile."admissionId" IS DISTINCT FROM admission_row."id" OR admission_row."state"<>'COMMITTED' OR admission_row."engine"<>'ENTA' OR admission_row."requestVersion"<>5 OR admission_row."predecessorAdmissionId" IS NOT NULL OR profile."requestVersion"<>5 OR profile."rulesVersion"<>'enta-competitive-1' OR public.int9_valid_request(pin."clientBinding") IS NOT TRUE OR pin."clientHash" IS DISTINCT FROM public.int6_enta_hash(pin."clientBinding") OR pin."intentHash" IS DISTINCT FROM public.int9_intent_hash(pin."fullIntent") OR pin."clientHash" IS DISTINCT FROM admission_row."requestHash" OR pin."intentHash" IS DISTINCT FROM admission_row."intentHash" OR pin."fullIntent"->'request' IS DISTINCT FROM pin."clientBinding" OR pin."fullIntent"->>'competitiveReleaseId' IS DISTINCT FROM profile."releaseId" OR pin."fullIntent"->>'proofRoot' IS DISTINCT FROM profile."proofRoot" OR pin."fullIntent"->>'paletteRoot' IS DISTINCT FROM profile."paletteRoot" OR pin."fullIntent"->'tournamentBinding' IS DISTINCT FROM 'null'::JSONB OR runtime."activeQuestionId" IS NOT NULL OR runtime."setup" IS DISTINCT FROM pin."clientBinding"->'setup' OR runtime."setupHash" IS DISTINCT FROM public.int6_enta_hash(runtime."setup") OR pin."state" IS DISTINCT FROM jsonb_build_object('contextVersion',1,'gameId',game_id,'version',runtime."version") THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 SELECT count(*) INTO round_count FROM public."GameRound" WHERE "gameId"=game_id;
 SELECT count(*) INTO event_count FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id;
 SELECT count(*) INTO effect_count FROM public."CompetitiveEffect" WHERE "gameId"=game_id;
 IF round_count NOT BETWEEN 1 AND 36 OR round_count IS DISTINCT FROM (pin."fullIntent"->>'roundCount')::INTEGER OR round_count<>jsonb_array_length(pin."fullIntent"->'selection') OR pin."fullIntent"->>'pinsHash' IS DISTINCT FROM public.int9_references_hash(pin."fullIntent"->'selection') OR runtime."version" IS DISTINCT FROM event_count+1 OR runtime."version" NOT BETWEEN 1 AND 64946 OR event_count>64945 OR effect_count>64945 OR effect_count<>COALESCE((SELECT max("sequence") FROM public."CompetitiveEffect" WHERE "gameId"=game_id),0) OR event_count>0 AND ((SELECT min("sequence") FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id)<>2 OR (SELECT max("sequence") FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id)<>runtime."version") OR runtime."turnIndex" NOT BETWEEN 0 AND round_count OR (SELECT count(*) FROM public."Team" WHERE "gameId"=game_id)<>cardinality(runtime."teamOrder") OR cardinality(runtime."teamOrder") NOT BETWEEN 2 AND 4 OR (SELECT count(*) FROM public."CompetitiveRoundPin" WHERE "gameId"=game_id)<>round_count OR (SELECT count(*) FROM public."CompetitiveAttempt" WHERE "gameId"=game_id)>18432 OR (SELECT count(*) FROM public."CompetitiveClassification" WHERE "gameId"=game_id)>18432 OR (SELECT count(*) FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id)>4644 OR (SELECT count(*) FROM public."CompetitiveItemConsumption" WHERE "gameId"=game_id)>4608 OR (SELECT count(*) FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id)>56592 OR (SELECT count(*) FROM public."CompetitiveAuditReport" WHERE "gameId"=game_id)>128 OR head."latestEffectId" IS DISTINCT FROM (SELECT "id" FROM public."CompetitiveEffect" WHERE "gameId"=game_id ORDER BY "sequence" DESC LIMIT 1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 FOR team_row IN SELECT "id","score" FROM public."Team" WHERE "gameId"=game_id LOOP
  IF team_row."score"::BIGINT IS DISTINCT FROM (SELECT COALESCE(sum("delta"::BIGINT),0) FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "teamId"=team_row."id") OR (SELECT count(*) FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "teamId"=team_row."id")<>COALESCE((SELECT max("scoreVersion") FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "teamId"=team_row."id"),0) OR NOT team_row."id"=ANY(runtime."teamOrder") THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 END LOOP;
 IF (SELECT count(*) FROM public."CompetitiveItemReview" review WHERE review."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveItemResolution" resolution WHERE resolution."gameId"=game_id AND resolution."reviewId"=review."id"))<>(CASE WHEN head."openItemReviewId" IS NULL THEN 0 ELSE 1 END) OR head."openItemReviewId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."CompetitiveItemReview" review WHERE review."gameId"=game_id AND review."id"=head."openItemReviewId" AND review."hash"=head."openItemReviewHash" AND NOT EXISTS(SELECT 1 FROM public."CompetitiveItemResolution" resolution WHERE resolution."gameId"=game_id AND resolution."reviewId"=review."id")) OR head."openItemReviewId" IS NOT NULL AND head."boardReviewRoundId" IS NOT NULL OR (SELECT count(*) FROM public."CompetitiveReversal" WHERE "gameId"=game_id)<>(SELECT count(*) FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "kind"='REVERSAL') THEN PERFORM public.int9_error('STALE_REVIEW_HEAD'); END IF;
 IF EXISTS(SELECT 1 FROM public."EngineTournamentBindingSnapshot" WHERE "gameId"=game_id) OR EXISTS(SELECT 1 FROM public."EngineMatchResultSignal" WHERE "gameId"=game_id) OR EXISTS(SELECT 1 FROM public."CompetitiveAuditReport" report JOIN public."RoundAuthorityEvent" event ON event."gameId"=report."gameId" AND event."commandId"=report."commandId" WHERE report."gameId"=game_id) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM public."RoundGrantScope" scope WHERE scope."gameId"=game_id AND scope."activeGrantId" IS NOT NULL AND scope."roundId" IS DISTINCT FROM runtime."activeRoundId") THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 IF runtime."activeRoundId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."GameRound" WHERE "gameId"=game_id AND "id"=runtime."activeRoundId" AND "state"->>'phase' NOT IN ('READY','RESOLVED')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF (SELECT count(*) FROM public."CompetitiveAllowance" WHERE "gameId"=game_id)<>cardinality(runtime."teamOrder")*3*(CASE WHEN pin."executionFormat" IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN round_count ELSE 1 END) OR (SELECT count(*) FROM public."DrawingCanvasState" canvas JOIN public."GameRound" round_row ON round_row."id"=canvas."roundId" WHERE round_row."gameId"=game_id)<>(SELECT count(*) FROM public."GameRound" WHERE "gameId"=game_id AND "pin"->>'format'='DRAWING_TARGET' AND "state"->>'phase'<>'READY') THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 PERFORM public.int9_assert_capacity(game_id);
 IF runtime."state"='FINISHED' THEN PERFORM public.int9_assert_terminal(game_id); ELSE IF EXISTS(SELECT 1 FROM public."EngineMatchResult" WHERE "gameId"=game_id) OR EXISTS(SELECT 1 FROM public."EngineMatchResultHead" WHERE "gameId"=game_id) THEN PERFORM public.int9_error('RESULT_INTEGRITY_FAILURE'); END IF; END IF;
END $$;

CREATE OR REPLACE FUNCTION public.int9_complete_game(game_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE g public."Game"%ROWTYPE; a public."Admission"%ROWTYPE; p public."EntaExecutionPin"%ROWTYPE; profile public."GameCompetitivePin"%ROWTYPE; r public."GameRuntime"%ROWTYPE; count_rounds INTEGER; category JSONB; family TEXT; actual JSONB; round_row RECORD; descriptor JSONB; reference JSONB; BEGIN
 SELECT "admissionId","catalogReleaseId","catalogReleaseRootHash","executionFormat","firebaseIdentityId","gameFormat","id","mode","userId","validationReceiptId" INTO g."admissionId",g."catalogReleaseId",g."catalogReleaseRootHash",g."executionFormat",g."firebaseIdentityId",g."gameFormat",g."id",g."mode",g."userId",g."validationReceiptId" FROM public."Game" WHERE "id"=game_id; SELECT "catalogReleaseId","engine","id","intentHash","logicalMatchId","mode","operation","predecessorAdmissionId","releaseRootHash","requestHash","requestKey","requestVersion","selectorVersion","state","validationReceiptId","walletId" INTO a."catalogReleaseId",a."engine",a."id",a."intentHash",a."logicalMatchId",a."mode",a."operation",a."predecessorAdmissionId",a."releaseRootHash",a."requestHash",a."requestKey",a."requestVersion",a."selectorVersion",a."state",a."validationReceiptId",a."walletId" FROM public."Admission" WHERE "id"=g."admissionId" AND "firebaseIdentityId"=g."firebaseIdentityId"; SELECT "clientBinding","clientHash","executionFormat","formatReleaseId","formatRoot","fullIntent","gameId","intentHash","mediaRoot" INTO p."clientBinding",p."clientHash",p."executionFormat",p."formatReleaseId",p."formatRoot",p."fullIntent",p."gameId",p."intentHash",p."mediaRoot" FROM public."EntaExecutionPin" WHERE "gameId"=game_id; SELECT "admissionId","firebaseIdentityId","gameId","paletteRoot","proofRoot","releaseId","requestVersion","rulesVersion" INTO profile."admissionId",profile."firebaseIdentityId",profile."gameId",profile."paletteRoot",profile."proofRoot",profile."releaseId",profile."requestVersion",profile."rulesVersion" FROM public."GameCompetitivePin" WHERE "gameId"=game_id; SELECT "gameId","setup","setupHash","teamOrder" INTO r."gameId",r."setup",r."setupHash",r."teamOrder" FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT count(*) INTO count_rounds FROM public."GameRound" WHERE "gameId"=game_id;
 IF g."id" IS NULL OR g."gameFormat"<>'FIREBASE_PINNED' OR g."userId" IS NOT NULL OR a."id" IS NULL OR a."state"<>'COMMITTED' OR a."engine"<>'ENTA' OR a."requestVersion"<>5 OR a."selectorVersion"<>'enta-competitive-1' OR a."predecessorAdmissionId" IS NOT NULL OR a."logicalMatchId"<>g."id" OR a."mode" IS DISTINCT FROM g."mode" OR a."operation" IS DISTINCT FROM (CASE g."executionFormat" WHEN 'STANDALONE_LIST' THEN 'PAID_ENTA_LIST' WHEN 'STANDALONE_ACTING' THEN 'PAID_ENTA_ACTING' ELSE 'PAID_ENTA_CLASSIC' END) OR a."catalogReleaseId" IS DISTINCT FROM g."catalogReleaseId" OR a."releaseRootHash" IS DISTINCT FROM g."catalogReleaseRootHash" OR a."validationReceiptId" IS DISTINCT FROM g."validationReceiptId" OR profile."gameId" IS NULL OR profile."admissionId"<>a."id" OR profile."firebaseIdentityId"<>g."firebaseIdentityId" OR profile."requestVersion"<>5 OR profile."rulesVersion"<>'enta-competitive-1' OR p."gameId" IS NULL OR r."gameId" IS NULL OR NOT public.int9_valid_request(p."clientBinding") OR p."clientHash"<>a."requestHash" OR p."intentHash"<>a."intentHash" OR p."clientHash"<>public.int6_enta_hash(p."clientBinding") OR p."intentHash"<>public.int9_intent_hash(p."fullIntent") OR p."fullIntent"->'request'<>p."clientBinding" OR p."fullIntent"->'version'<>'5'::JSONB OR r."setup"<>p."clientBinding"->'setup' OR r."setupHash"<>public.int6_enta_hash(r."setup") OR g."executionFormat"<>p."executionFormat" OR p."clientBinding"->>'executionFormat'<>g."executionFormat" OR g."mode" IS DISTINCT FROM (CASE g."executionFormat" WHEN 'STANDALONE_LIST' THEN 'LIST' WHEN 'STANDALONE_ACTING' THEN 'ACTING' ELSE 'CLASSIC' END) THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public."EntaCompetitiveRelease" proof JOIN public."EntaFormatRelease" format_proof ON format_proof."id"=proof."formatReleaseId" AND format_proof."formatRoot"=proof."formatRoot" AND format_proof."mediaRoot"=proof."mediaRoot" WHERE proof."id"=profile."releaseId" AND proof."proofRoot"=profile."proofRoot" AND proof."paletteRoot"=profile."paletteRoot" AND proof."paletteRoot"=public.int9_palette_root() AND proof."rulesVersion"=profile."rulesVersion" AND proof."sealedAt" IS NOT NULL AND format_proof."sealedAt" IS NOT NULL AND format_proof."baseReleaseId"=g."catalogReleaseId" AND format_proof."baseRoot"=g."catalogReleaseRootHash" AND format_proof."receiptId"=g."validationReceiptId" AND p."formatReleaseId"=format_proof."id" AND p."formatRoot"=format_proof."formatRoot" AND p."mediaRoot"=format_proof."mediaRoot") THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 IF count_rounds NOT BETWEEN 1 AND 36 OR count_rounds<>(p."fullIntent"->>'roundCount')::INTEGER OR count_rounds<>(SELECT count(*) FROM public."GameQuestion" WHERE "gameId"=game_id) OR (SELECT count(*) FROM public."GameCategoryPin" WHERE "gameId"=game_id)<>(CASE WHEN g."executionFormat" IN ('TIER_BOARD','MIXED_BOARD') THEN 6 ELSE 1 END) OR g."executionFormat" IN ('STANDALONE_LIST','STANDALONE_ACTING') AND (count_rounds NOT BETWEEN 1 AND 4 OR cardinality(r."teamOrder")<>2) OR (SELECT count(DISTINCT ("sourceNamespace","sourceId")) FROM public."GameRound" WHERE "gameId"=game_id)<>count_rounds OR EXISTS(SELECT 1 FROM generate_series(0,count_rounds-1) ordinal WHERE NOT EXISTS(SELECT 1 FROM public."GameRound" round_row WHERE round_row."gameId"=game_id AND round_row."ordinal"=ordinal)) OR p."fullIntent"->>'pinsHash' IS DISTINCT FROM public.int9_references_hash(p."fullIntent"->'selection') THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 IF (SELECT jsonb_agg("categoryKey" ORDER BY "ordinal") FROM public."GameCategoryPin" WHERE "gameId"=game_id) IS DISTINCT FROM (SELECT jsonb_agg(value->'key' ORDER BY ord) FROM jsonb_array_elements(r."setup"->'categories') WITH ORDINALITY categories(value,ord)) OR EXISTS(SELECT 1 FROM public."GameCategory" WHERE "gameId"=game_id) OR EXISTS(SELECT 1 FROM public."EntaRematchLink" WHERE "childGameId"=game_id) OR EXISTS(SELECT 1 FROM public."EngineTournamentBindingSnapshot" WHERE "gameId"=game_id) THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 IF p."fullIntent"->>'poolHash' IS DISTINCT FROM public.int9_pool_root(profile."releaseId",p."clientBinding") THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
 IF p."fullIntent"->'selection' IS DISTINCT FROM public.int9_select_references_at(profile."releaseId",p."clientBinding",p."fullIntent"->>'seed',g."firebaseIdentityId",game_id) THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
 FOR round_row IN SELECT physical."categoryKey",physical."formatId",physical."gameId",physical."id",physical."ordinal",physical."pin",physical."questionHash",physical."questionRevisionId",physical."sourceId",physical."sourceNamespace",competitive."promptId",competitive."proofHash",competitive."targetHash",competitive."pin" AS competitive_pin FROM public."GameRound" physical JOIN public."CompetitiveRoundPin" competitive ON competitive."gameId"=physical."gameId" AND competitive."roundId"=physical."id" WHERE physical."gameId"=game_id ORDER BY physical."ordinal" LOOP
  descriptor:=NULL; descriptor:=public.int9_descriptor(round_row."promptId"); reference:=p."fullIntent"->'selection'->round_row."ordinal";
  IF descriptor IS DISTINCT FROM round_row.competitive_pin OR round_row."pin" IS DISTINCT FROM descriptor-ARRAY['hints','graphemes','hintRoot','effectValue','effectValueSource','proofHash'] OR round_row."proofHash" IS DISTINCT FROM descriptor->>'proofHash' OR round_row."targetHash" IS DISTINCT FROM public.int6_enta_hash(jsonb_build_object('revisionId',descriptor->'revisionId','revisionHash',descriptor->'hash','target',descriptor->'target')) OR reference IS DISTINCT FROM public.int9_reference(round_row."formatId",round_row."promptId",round_row."ordinal",(reference->>'cycle')::INTEGER) OR NOT EXISTS(SELECT 1 FROM public."CatalogReleaseQuestion" member WHERE member."catalogReleaseId"=g."catalogReleaseId" AND member."questionRevisionId"=round_row."questionRevisionId" AND member."questionContentHash"=round_row."questionHash" AND member."categoryKey"=round_row."categoryKey") OR (SELECT count(*) FROM public."RoundItemPin" WHERE "roundId"=round_row."id")<>jsonb_array_length(descriptor->'items') OR EXISTS(SELECT 1 FROM public."RoundItemPin" item WHERE item."roundId"=round_row."id" AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(descriptor->'items') pinned WHERE pinned->>'id'=item."itemId" AND pinned->>'revisionId'=item."answerRevisionId" AND pinned->>'hash'=item."answerHash" AND (pinned->>'ordinal')::INTEGER=item."ordinal")) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 END LOOP;
 FOR category IN SELECT value FROM jsonb_array_elements(r."setup"->'categories') LOOP
  SELECT min(physical."pin"->>'format') INTO family FROM public."GameRound" physical WHERE physical."gameId"=game_id AND physical."categoryKey"=category->>'key';
  IF family IS NULL OR (SELECT count(DISTINCT physical."pin"->>'format') FROM public."GameRound" physical WHERE physical."gameId"=game_id AND physical."categoryKey"=category->>'key')<>1 OR g."executionFormat"='TIER_BOARD' AND family<>'ORDINARY_TIER' OR g."executionFormat"='STANDALONE_LIST' AND family<>'LIST_ITEMS' OR g."executionFormat"='STANDALONE_ACTING' AND family<>'ACTING_ITEMS' THEN PERFORM public.int9_error('FORMAT_UNAVAILABLE'); END IF;
  IF g."executionFormat" IN ('TIER_BOARD','MIXED_BOARD') THEN
   IF family IN ('ORDINARY_TIER','DRAWING_TARGET') THEN IF category->'promptRefs'<>'[]'::JSONB OR (SELECT count(*) FROM public."GameRound" physical WHERE physical."gameId"=game_id AND physical."categoryKey"=category->>'key')<>6 OR EXISTS(SELECT 1 FROM (VALUES(200),(400),(600)) tier(value) WHERE (SELECT count(*) FROM public."GameRound" physical WHERE physical."gameId"=game_id AND physical."categoryKey"=category->>'key' AND (physical."pin"->>'points')::INTEGER=tier.value)<>2) THEN PERFORM public.int9_error('TIER_SUPPLY_UNAVAILABLE'); END IF;
   ELSE SELECT jsonb_agg(physical."pin"->'ref' ORDER BY physical."ordinal") INTO actual FROM public."GameRound" physical WHERE physical."gameId"=game_id AND physical."categoryKey"=category->>'key'; IF family NOT IN ('LIST_ITEMS','ACTING_ITEMS') OR jsonb_array_length(category->'promptRefs') NOT BETWEEN 1 AND 6 OR actual IS DISTINCT FROM category->'promptRefs' THEN PERFORM public.int9_error('PROMPT_UNAVAILABLE'); END IF; END IF;
  END IF;
 END LOOP;
 IF g."executionFormat" IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN
  IF (SELECT count(*) FROM public."EntaSourceExposure" WHERE "gameId"=game_id)<>count_rounds OR EXISTS(SELECT 1 FROM public."GameRound" round_row WHERE round_row."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."EntaSourceExposure" exposure WHERE exposure."gameId"=game_id AND exposure."ordinal"=round_row."ordinal" AND exposure."firebaseIdentityId"=g."firebaseIdentityId" AND exposure."executionFormat"=g."executionFormat" AND exposure."categoryKey"=round_row."categoryKey" AND exposure."sourceNamespace"=round_row."sourceNamespace" AND exposure."sourceId"=round_row."sourceId" AND exposure."revisionId"=round_row."questionRevisionId" AND exposure."cycle"=(p."fullIntent"->'selection'->round_row."ordinal"->>'cycle')::INTEGER AND exposure."cycle">0)) THEN PERFORM public.int9_error('EXPOSURE_UNAVAILABLE'); END IF;
 ELSE IF EXISTS(SELECT 1 FROM public."EntaSourceExposure" WHERE "gameId"=game_id) OR EXISTS(SELECT 1 FROM jsonb_array_elements(p."fullIntent"->'selection') selected WHERE selected->'cycle' IS DISTINCT FROM '0'::JSONB) THEN PERFORM public.int9_error('EXPOSURE_UNAVAILABLE'); END IF; END IF;
 IF NOT EXISTS(SELECT 1 FROM public."GameEvent" e WHERE e."gameId"=game_id AND e."sequence"=1 AND e."type"='START' AND e."actorFirebaseIdentityId"=g."firebaseIdentityId" AND e."commandId"=a."requestKey" AND e."intentHash"=a."intentHash") OR NOT EXISTS(SELECT 1 FROM public."Reservation" reservation WHERE reservation."admissionId"=a."id" AND reservation."state"='COMMITTED' AND reservation."quantity"=1 AND EXISTS(SELECT 1 FROM public."WalletEntry" ledger WHERE ledger."walletId"=a."walletId" AND ledger."reservationId"=reservation."id" AND ledger."originType"='ADMISSION' AND ledger."originId"=a."id" AND ledger."effect"='RESERVE' AND ledger."deltaAvailable"=-1 AND ledger."deltaHeld"=1 AND ledger."deltaDebt"=0 AND ledger."actorFirebaseIdentityId"=g."firebaseIdentityId" AND ledger."evidenceHash"=a."requestHash") AND EXISTS(SELECT 1 FROM public."WalletEntry" ledger WHERE ledger."walletId"=a."walletId" AND ledger."reservationId"=reservation."id" AND ledger."originType"='ADMISSION' AND ledger."originId"=a."id" AND ledger."effect"='COMMIT' AND ledger."deltaAvailable"=0 AND ledger."deltaHeld"=-1 AND ledger."deltaDebt"=0 AND ledger."actorFirebaseIdentityId"=g."firebaseIdentityId" AND ledger."evidenceHash"=a."intentHash")) THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 PERFORM public.int9_assert_stored(game_id);
END $$;
CREATE FUNCTION public.int9_complete_start() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE game_id TEXT; BEGIN game_id:=(CASE WHEN TG_TABLE_NAME='Game' THEN NEW."id" ELSE NEW."gameId" END); IF EXISTS(SELECT 1 FROM public."Game" g JOIN public."Admission" a ON a."id"=g."admissionId" AND a."firebaseIdentityId"=g."firebaseIdentityId" WHERE g."id"=game_id AND g."gameFormat"='FIREBASE_PINNED' AND a."requestVersion"=5) THEN PERFORM public.int9_complete_game(game_id); END IF; RETURN NULL; END $$;
CREATE OR REPLACE FUNCTION public.int9_fact_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE x JSONB:=to_jsonb(NEW); gid TEXT:=x->>'gameId'; e JSONB; a public."CompetitiveAttempt"%ROWTYPE; r public."GameRound"%ROWTYPE; parent JSONB; physical RECORD; ordinal INTEGER; BEGIN
 CASE TG_TABLE_NAME
 WHEN 'CompetitiveEffect' THEN PERFORM public.int9_assert_effect(gid,x->>'id');
 WHEN 'CompetitiveAttempt' THEN PERFORM public.int9_assert_attempt(gid,x->>'id');
 WHEN 'CompetitiveClassification' THEN
  SELECT "bonusEventId","id","payload","roundId" INTO a."bonusEventId",a."id",a."payload",a."roundId" FROM public."CompetitiveAttempt" WHERE "gameId"=gid AND "id"=x->>'attemptId';
  IF NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" event WHERE event."gameId"=gid AND event."id"=x->>'eventId' AND event."roundId"=a."roundId" AND event."authorityKind"='HOST' AND event."type"=(CASE WHEN (x->>'interim')::BOOLEAN THEN 'INTERIM_WRONG' ELSE 'FINAL_RULING' END)) OR (x->>'interim')::BOOLEAN AND (x->>'correct')::BOOLEAN THEN PERFORM public.int9_error('ATTEMPT_PROOF_UNAVAILABLE'); END IF;
 WHEN 'CompetitiveScorePosting','CompetitiveScoreRead','CompetitiveDependency' THEN
  e:=public.int9_effect_proof(gid,x->>'effectId');
 WHEN 'CompetitiveEffectAttempt' THEN
  SELECT "payload" INTO e FROM public."CompetitiveEffect" WHERE "gameId"=gid AND "id"=x->>'effectId'; SELECT "bonusEventId","id","payload","roundId" INTO a."bonusEventId",a."id",a."payload",a."roundId" FROM public."CompetitiveAttempt" WHERE "gameId"=gid AND "id"=x->>'attemptId';
  IF NOT e->'originalAttemptIds' @> jsonb_build_array(a."id") OR a."roundId" IS DISTINCT FROM x->>'roundId' OR x->'correct' IS DISTINCT FROM to_jsonb(e->'correctAttemptIds' @> jsonb_build_array(a."id")) OR (CASE WHEN e->>'kind'='INTERIM' THEN (x->>'bonusMultiplier')::INTEGER<>1 OR x->>'bonusEventId' IS NOT NULL ELSE x->'bonusMultiplier' IS DISTINCT FROM a."payload"->'bonusMultiplier' OR x->>'bonusEventId' IS DISTINCT FROM a."bonusEventId" END) THEN PERFORM public.int9_error('BONUS_PROOF_UNAVAILABLE'); END IF;
 WHEN 'CompetitiveRulingHead' THEN
  -- Earlier queued head revisions cannot revalidate a successor as an old head.
  IF (SELECT "version" FROM public."CompetitiveRulingHead" WHERE "gameId"=gid AND "scopeId"=x->>'scopeId')=(x->>'version')::INTEGER THEN PERFORM public.int9_assert_ruling(gid,x->>'scopeId'); END IF;
 WHEN 'CompetitiveReversal' THEN PERFORM public.int9_assert_reversal(gid,x->>'reversalEffectId');
 WHEN 'CompetitiveItemReview' THEN PERFORM public.int9_assert_review(gid,x->>'id');
 WHEN 'CompetitiveItemResolution' THEN PERFORM public.int9_assert_review(gid,x->>'reviewId');
 WHEN 'CompetitiveItemConsumption' THEN
  IF NOT EXISTS(SELECT 1 FROM public."CompetitiveRulingHead" h JOIN public."CompetitiveEffect" effect ON effect."gameId"=h."gameId" AND effect."id"=h."originalEffectId" WHERE h."gameId"=gid AND h."roundId"=x->>'roundId' AND h."itemId"=x->>'itemId' AND h."originalEffectId"=x->>'effectId' AND effect."kind" IN ('RULING','NO_SCORE')) THEN PERFORM public.int9_error('ITEM_PROOF_UNAVAILABLE'); END IF;
 WHEN 'CompetitiveConsumption' THEN
  IF NOT EXISTS(SELECT 1 FROM public."CompetitiveAllowance" allowance JOIN public."CompetitiveEffect" effect ON effect."gameId"=allowance."gameId" AND effect."id"=x->>'effectId' WHERE allowance."gameId"=gid AND allowance."id"=x->>'allowanceId' AND allowance."teamId"=x->>'teamId' AND allowance."aid"=x->>'aid' AND effect."eventId"=x->>'eventId' AND effect."roundId"=x->>'roundId' AND effect."kind"='AID' AND effect."payload"->>'aid'=allowance."aid") THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
 WHEN 'CompetitiveAllowance' THEN
  SELECT runtime."setup"->'teams'->(ordered.ordinal::INTEGER-1) INTO parent FROM public."GameRuntime" runtime CROSS JOIN LATERAL unnest(runtime."teamOrder") WITH ORDINALITY ordered(id,ordinal) WHERE runtime."gameId"=gid AND ordered.id=x->>'teamId';
  IF parent->'aids'->((x->>'ordinal')::INTEGER) IS DISTINCT FROM x->'aid' OR (CASE WHEN x->>'scope'='MATCH' THEN x->>'scopeId'<>gid OR x->>'roundId' IS NOT NULL OR (SELECT "executionFormat" FROM public."Game" WHERE "id"=gid) IN ('STANDALONE_LIST','STANDALONE_ACTING') ELSE x->>'scope' IS DISTINCT FROM 'PINNED_QUESTION' OR x->>'scopeId' IS DISTINCT FROM x->>'roundId' OR NOT EXISTS(SELECT 1 FROM public."GameRound" WHERE "gameId"=gid AND "id"=x->>'roundId') OR (SELECT "executionFormat" FROM public."Game" WHERE "id"=gid) NOT IN ('STANDALONE_LIST','STANDALONE_ACTING') END) THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
 WHEN 'CompetitiveRosterPlayer' THEN
  SELECT runtime."setup"->'teams'->(ordered.ordinal::INTEGER-1) INTO parent FROM public."GameRuntime" runtime CROSS JOIN LATERAL unnest(runtime."teamOrder") WITH ORDINALITY ordered(id,ordinal) WHERE runtime."gameId"=gid AND ordered.id=x->>'teamId';
  IF NOT EXISTS(SELECT 1 FROM public."Player" player WHERE player."id"=x->>'playerId' AND player."teamId"=x->>'teamId' AND to_jsonb(player."name")=parent->'players'->((x->>'ordinal')::INTEGER)) OR (x->>'ordinal')::INTEGER NOT BETWEEN 0 AND 7 THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 WHEN 'CompetitiveRoundPin' THEN
  e:=public.int9_descriptor(x->>'promptId'); IF e IS DISTINCT FROM x->'pin' OR x->>'proofHash' IS DISTINCT FROM e->>'proofHash' OR x->>'targetHash' IS DISTINCT FROM public.int6_enta_hash(jsonb_build_object('revisionId',e->'revisionId','revisionHash',e->'hash','target',e->'target')) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 WHEN 'CompetitiveAssignmentPlayer' THEN
  IF NOT EXISTS(SELECT 1 FROM public."RoundActorAssignment" assignment JOIN public."CompetitiveRosterPlayer" player ON player."gameId"=assignment."gameId" AND player."teamId"=assignment."teamId" AND player."ordinal"=assignment."playerIndex" JOIN public."CompetitiveRoundPin" pinned ON pinned."gameId"=assignment."gameId" AND pinned."roundId"=assignment."roundId" WHERE assignment."gameId"=gid AND assignment."id"=x->>'assignmentId' AND assignment."roundId"=x->>'roundId' AND assignment."teamId"=x->>'teamId' AND assignment."generation"=(x->>'generation')::INTEGER AND player."playerId"=x->>'playerId' AND pinned."targetHash"=x->>'targetHash') THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 WHEN 'CompetitiveTargetDisclosure' THEN
  IF NOT EXISTS(SELECT 1 FROM public."CompetitiveAssignmentPlayer" assignment JOIN public."RoundGrant" grant_row ON grant_row."gameId"=assignment."gameId" AND grant_row."assignmentId"=assignment."assignmentId" AND grant_row."roundId"=assignment."roundId" JOIN public."RoundAuthorityEvent" event ON event."gameId"=grant_row."gameId" AND event."id"=x->>'id' WHERE assignment."gameId"=gid AND assignment."assignmentId"=x->>'assignmentId' AND assignment."playerId"=x->>'playerId' AND assignment."teamId"=x->>'teamId' AND assignment."targetHash"=x->>'targetHash' AND assignment."generation"=(x->>'assignmentGeneration')::INTEGER AND grant_row."id"=x->>'grantId' AND grant_row."role"='ACTOR' AND grant_row."generation"=(x->>'grantGeneration')::INTEGER AND grant_row."expiresAt">NEW."createdAt" AND event."type"='TARGET_DELIVERY' AND event."authorityGrantId"=grant_row."id" AND event."assignmentId"=assignment."assignmentId" AND event."at"=NEW."createdAt") THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 WHEN 'CompetitiveRuntimeHead' THEN
  IF to_jsonb(NEW)=(SELECT to_jsonb(current_head) FROM public."CompetitiveRuntimeHead" current_head WHERE current_head."gameId"=gid) THEN PERFORM public.int9_assert_stored(gid); END IF;
 WHEN 'GameCompetitivePin' THEN PERFORM public.int9_complete_game(gid);
 WHEN 'EngineMatchResult','EngineMatchResultHead' THEN PERFORM public.int9_assert_terminal(gid);
 WHEN 'CompetitiveCapacityClaim' THEN PERFORM public.int9_assert_claim(gid,x->>'id');
 WHEN 'CompetitiveCapacityDisposition' THEN PERFORM public.int9_assert_claim(gid,x->>'claimId');
 WHEN 'CompetitiveCapacityCharge' THEN PERFORM public.int9_assert_charge(gid,x->>'eventId');
 WHEN 'CompetitiveCapacityHead' THEN
  IF to_jsonb(NEW)=(SELECT to_jsonb(current_head) FROM public."CompetitiveCapacityHead" current_head WHERE current_head."gameId"=gid AND current_head."roundId"=x->>'roundId') THEN PERFORM public.int9_assert_capacity_round(gid,x->>'roundId'); END IF;
 ELSE PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END CASE; RETURN NULL;
END $$;
CREATE FUNCTION public.int9_bound_denied() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN PERFORM public.int9_error('TOURNAMENT_ALLOCATOR_UNAVAILABLE'); RETURN NULL; END $$;

CREATE OR REPLACE FUNCTION public.int9_locked_state(ns TEXT,project TEXT,game_id TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN RETURN public.int9_lock_context(ns,project,game_id,NULL,NULL,NULL); END $$;
CREATE OR REPLACE FUNCTION public.int9_owner_load(ns TEXT,project TEXT,uid TEXT,game_id TEXT,locked BOOLEAN) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE identity_id TEXT; BEGIN
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; IF NOT EXISTS(SELECT 1 FROM public."Game" g JOIN public."GameCompetitivePin" profile ON profile."gameId"=g."id" AND profile."firebaseIdentityId"=g."firebaseIdentityId" WHERE g."id"=game_id AND g."firebaseIdentityId"=identity_id AND g."gameFormat"='FIREBASE_PINNED' AND profile."requestVersion"=5) THEN RETURN NULL; END IF;
 PERFORM public.int9_lock_only(ns,project,game_id,NULL,NULL,NULL);
 PERFORM public.int9_mutation_owner(game_id,NULL,NULL,NULL,NULL,'{"grants":[]}'::JSONB,NULL,NULL,public.int9_now());
 RETURN public.int9_scope_dto(game_id,uid,NULL);
END $$;
CREATE FUNCTION public.int9_locate_grant(ns TEXT,project TEXT,token_hash TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE game_id TEXT; BEGIN
 PERFORM public.int8_namespace(ns,project); IF token_hash IS NULL OR token_hash!~'^[a-f0-9]{64}$' THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 SELECT grant_row."gameId" INTO game_id FROM public."RoundGrant" grant_row JOIN public."GameCompetitivePin" profile ON profile."gameId"=grant_row."gameId" JOIN public."FirebaseIdentity" identity_row ON identity_row."id"=profile."firebaseIdentityId" WHERE grant_row."tokenHash"=token_hash AND identity_row."firebaseProjectId"=project AND profile."requestVersion"=5; IF NOT FOUND THEN RETURN NULL; END IF; RETURN jsonb_build_object('gameId',game_id);
END $$;
CREATE OR REPLACE FUNCTION public.int9_authorize_grant(state JSONB,token_hash TEXT,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE grant_row JSONB; scope JSONB; r JSONB; BEGIN
 SELECT x INTO grant_row FROM jsonb_array_elements(state->'grants') x WHERE x->>'tokenHash'=token_hash; SELECT x INTO scope FROM jsonb_array_elements(state->'grantScopes') x WHERE x->'id'=grant_row->'scopeId'; r:=public.int9_round(state,grant_row->>'roundId');
 IF state IS NULL OR grant_row IS NULL OR scope IS NULL OR r IS NULL OR state->'finished'='true'::JSONB OR public.int9_review(state) OR grant_row->'revoked'='true'::JSONB OR moment>=(grant_row->>'expiresAt')::DOUBLE PRECISION OR scope->'activeGrantId' IS DISTINCT FROM grant_row->'id' OR scope->'generation' IS DISTINCT FROM grant_row->'generation' OR scope->'assignmentId' IS DISTINCT FROM grant_row->'assignmentId' OR state->'activeRoundId' IS DISTINCT FROM r->'id' OR r->'resourceStop' IS DISTINCT FROM 'null'::JSONB OR r->'pause'<>'null'::JSONB OR r->'publicRevealed'='true'::JSONB OR r->>'phase' NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN') OR r->'deadline'='null'::JSONB OR moment>=(r->>'deadline')::DOUBLE PRECISION OR r->'overallDeadline'<>'null'::JSONB AND moment>=(r->>'overallDeadline')::DOUBLE PRECISION THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 IF grant_row->>'role'='JUDGE' THEN IF NOT public.int9_items(r) OR grant_row->'assignmentId'<>'null'::JSONB THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 ELSIF grant_row->>'role'='ACTOR' THEN IF r->'assignment'='null'::JSONB OR r->'assignment'->'id' IS DISTINCT FROM grant_row->'assignmentId' OR r->'pin'->>'format' NOT IN ('ACTING_ITEMS','DRAWING_TARGET') OR r->'assignment'->'itemId'<>'null'::JSONB AND (r->'itemReveals' @> jsonb_build_array(r->'assignment'->'itemId') OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=r->'assignment'->'itemId')) THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 ELSE PERFORM public.int9_error('GRANT_DENIED'); END IF; RETURN grant_row;
END $$;
CREATE OR REPLACE FUNCTION public.int9_grant_load(ns TEXT,project TEXT,game_id TEXT,token_hash TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE grant_row JSONB; scope_id TEXT; BEGIN SELECT "scopeId" INTO scope_id FROM public."RoundGrant" WHERE "gameId"=game_id AND "tokenHash"=token_hash; PERFORM public.int9_lock_only(ns,project,game_id,NULL,NULL,scope_id); grant_row:=public.int9_grant_physical(game_id,token_hash,public.int9_now()); RETURN public.int9_scope_dto(game_id,NULL,grant_row); END $$;
CREATE OR REPLACE FUNCTION public.int9_find_start(ns TEXT,project TEXT,uid TEXT,request_key TEXT,logical_id TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE identity_id TEXT; admission_row public."Admission"%ROWTYPE; state JSONB; saved_game_id TEXT; BEGIN
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; SELECT "engine","id","intentHash","requestHash","requestVersion","state" INTO admission_row."engine",admission_row."id",admission_row."intentHash",admission_row."requestHash",admission_row."requestVersion",admission_row."state" FROM public."Admission" WHERE "firebaseIdentityId"=identity_id AND ("requestKey"=request_key OR "engine"='ENTA' AND "logicalMatchId"=logical_id) ORDER BY CASE WHEN "requestKey"=request_key THEN 0 ELSE 1 END LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF admission_row."engine"<>'ENTA' OR admission_row."requestVersion"<>5 OR admission_row."state"<>'COMMITTED' THEN PERFORM public.int9_error('IDEMPOTENCY_KEY_CONFLICT'); END IF;
 SELECT "id" INTO saved_game_id FROM public."Game" WHERE "admissionId"=admission_row."id" AND "firebaseIdentityId"=identity_id FOR UPDATE; IF saved_game_id IS NULL THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 PERFORM public.int9_complete_game(saved_game_id);
 SELECT jsonb_build_object('id',saved_game_id,'identityId',identity_id,'request',"clientBinding",'requestHash',"clientHash",'intentHash',"intentHash") INTO state FROM public."EntaExecutionPin" WHERE "gameId"=saved_game_id; IF state IS NULL OR state->>'requestHash' IS DISTINCT FROM admission_row."requestHash" OR state->>'intentHash' IS DISTINCT FROM admission_row."intentHash" THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 -- Complete original compact commitment and one descriptor per round, before
 -- any current publication, remaining credit or policy novelty on retry.
 RETURN state;
END $$;
CREATE FUNCTION public.int9_canvas(s JSONB,c JSONB,grant_row JSONB,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r JSONB:=public.int9_round(s,grant_row->>'roundId'); canvas JSONB; stroke JSONB; BEGIN
 IF grant_row->>'role'<>'ACTOR' OR r->'pin'->>'format'<>'DRAWING_TARGET' OR public.int9_review(s) OR r->'pause'<>'null'::JSONB THEN PERFORM public.int9_error('CANVAS_DENIED'); END IF;
 SELECT value INTO canvas FROM jsonb_array_elements(s->'canvases') WHERE value->'roundId'=r->'id'; IF canvas IS NULL THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF;
 IF c->'expectedRevision' IS DISTINCT FROM canvas->'revision' THEN PERFORM public.int9_error('STALE_CANVAS_REVISION'); END IF; IF (canvas->>'mutations')::INTEGER>=512 THEN PERFORM public.int9_error('CANVAS_BUDGET_EXCEEDED'); END IF;
 IF c->>'type'='APPEND' THEN stroke:=c->'stroke'; IF jsonb_array_length(canvas->'strokes')>=128 OR (canvas->>'cumulativePoints')::INTEGER+jsonb_array_length(stroke->'points')>8192 OR EXISTS(SELECT 1 FROM jsonb_array_elements(canvas->'strokes') prior WHERE prior->'id'=stroke->'id') THEN PERFORM public.int9_error('CANVAS_BUDGET_EXCEEDED'); END IF; canvas:=canvas||jsonb_build_object('strokes',canvas->'strokes'||jsonb_build_array(stroke),'visibleIds',canvas->'visibleIds'||jsonb_build_array(stroke->'id'),'redoIds','[]'::JSONB,'cumulativePoints',(canvas->>'cumulativePoints')::INTEGER+jsonb_array_length(stroke->'points'));
 ELSIF c->>'type'='UNDO' THEN IF canvas->'visibleIds'='[]'::JSONB THEN PERFORM public.int9_error('CANVAS_EMPTY'); END IF; canvas:=canvas||jsonb_build_object('redoIds',canvas->'redoIds'||jsonb_build_array(canvas->'visibleIds'->-1),'visibleIds',(canvas->'visibleIds')-(jsonb_array_length(canvas->'visibleIds')-1));
 ELSIF c->>'type'='REDO' THEN IF canvas->'redoIds'='[]'::JSONB THEN PERFORM public.int9_error('NO_REDO'); END IF; canvas:=canvas||jsonb_build_object('visibleIds',canvas->'visibleIds'||jsonb_build_array(canvas->'redoIds'->-1),'redoIds',(canvas->'redoIds')-(jsonb_array_length(canvas->'redoIds')-1));
 ELSE canvas:=canvas||jsonb_build_object('visibleIds','[]'::JSONB,'redoIds','[]'::JSONB); END IF;
 canvas:=canvas||jsonb_build_object('revision',(canvas->>'revision')::INTEGER+1,'mutations',(canvas->>'mutations')::INTEGER+1,'receipts',canvas->'receipts'||jsonb_build_array(jsonb_build_object('commandId',c->>'commandId','hash',public.int6_enta_hash(c),'revision',(canvas->>'revision')::INTEGER+1)));
 s:=jsonb_set(s,'{canvases}',(SELECT jsonb_agg(CASE WHEN x->'roundId'=r->'id' THEN canvas ELSE x END ORDER BY ord) FROM jsonb_array_elements(s->'canvases') WITH ORDINALITY canvases(x,ord))); s:=public.int9_event(s,c->>'commandId',public.int6_enta_hash(c),'CANVAS_'||(c->>'type'),r->>'id',jsonb_build_object('kind','GRANT','grantId',grant_row->'id','generation',grant_row->'generation','assignmentId',grant_row->'assignmentId'),moment,NULL); RETURN public.int9_seal(public.int9_effect(s,r,'TIMING','{}'::JSONB));
END $$;
CREATE OR REPLACE FUNCTION public.int9_apply(ns TEXT,project TEXT,uid TEXT,token_hash TEXT,game_id TEXT,expected_version INTEGER,c JSONB,proposal JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE identity_id TEXT; selected_round TEXT; selected_effect TEXT; selected_scope TEXT; prior RECORD; grant_row JSONB; command_hash TEXT; pre_revision INTEGER; current_revision INTEGER; moment DOUBLE PRECISION; clock_changed BOOLEAN; rejection TEXT; detail TEXT; blocked JSONB; audit JSONB; saved_canvas_revision INTEGER; BEGIN
 PERFORM public.int8_namespace(ns,project); IF (uid IS NULL)=(token_hash IS NULL) THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 IF NOT public.int6_enta_exact_keys(proposal,ARRAY['grants']) OR jsonb_typeof(proposal->'grants') IS DISTINCT FROM 'array' OR jsonb_array_length(proposal->'grants')>1 OR EXISTS(SELECT 1 FROM jsonb_array_elements(proposal->'grants') entropy WHERE public.int6_enta_exact_keys(entropy,ARRAY['tokenHash']) IS NOT TRUE OR entropy->>'tokenHash'!~'^[a-f0-9]{64}$') THEN PERFORM public.int9_error('GRANT_DATA_UNAVAILABLE'); END IF;
 IF c IS NOT NULL AND c<>'null'::JSONB THEN IF public.int9_valid_command(c,token_hash IS NOT NULL) IS NOT TRUE THEN PERFORM public.int9_error('INVALID_COMMAND'); END IF; command_hash:=public.int6_enta_hash(c); END IF;
 IF uid IS NOT NULL THEN identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; IF NOT EXISTS(SELECT 1 FROM public."Game" WHERE "id"=game_id AND "firebaseIdentityId"=identity_id) THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 ELSE SELECT "scopeId","roundId" INTO selected_scope,selected_round FROM public."RoundGrant" WHERE "gameId"=game_id AND "tokenHash"=token_hash; END IF;
 selected_round:=COALESCE(c->>'roundId',selected_round,CASE WHEN c->>'type'='NEXT_ROUND' THEN (SELECT "id" FROM public."GameRound" WHERE "gameId"=game_id AND "state"->>'phase'='READY' ORDER BY "ordinal" LIMIT 1) END,(SELECT "roundId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=c->>'reviewId'));
 selected_effect:=COALESCE(c->>'effectId',(SELECT "originalEffectId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=c->>'reviewId')); selected_scope:=COALESCE(c->>'scopeId',selected_scope);
 -- All Game/authority/selected child locks survive the mutation subtransaction.
 PERFORM public.int9_lock_only(ns,project,game_id,selected_round,selected_effect,selected_scope);
 IF c IS NOT NULL AND c<>'null'::JSONB AND token_hash IS NULL THEN PERFORM public.int9_scope_facts(game_id,c); END IF;
 SELECT "version" INTO pre_revision FROM public."GameRuntime" WHERE "gameId"=game_id;
 moment:=public.int9_now(); IF token_hash IS NOT NULL THEN grant_row:=public.int9_grant_physical(game_id,token_hash,moment); END IF;
 IF c IS NOT NULL AND c<>'null'::JSONB THEN
  IF c->>'type'='REPORT_VAR' THEN
   IF grant_row IS NOT NULL THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
   audit:=public.int9_report(ns,project,uid,game_id,c);
   RETURN jsonb_build_object('match',public.int9_main_dto(game_id,moment),'idempotent',audit->'idempotent','auditId',audit->'id','rejection',NULL,'blockingIds','[]'::JSONB,'blockingTotal',0,'commandReceipt',jsonb_build_object('state','ACCEPTED','gameId',game_id,'commandId',c->'commandId','expectedVersion',c->'expectedVersion','hash',command_hash,'eventId',audit->'id','revision',pre_revision),'issuance',NULL);
  END IF;
  IF EXISTS(SELECT 1 FROM public."CompetitiveAuditReport" WHERE "gameId"=game_id AND "commandId"=c->>'commandId') THEN PERFORM public.int9_error('COMMAND_KEY_CONFLICT'); END IF;
  SELECT "id","intentHash","authorityKind","roundId","authorityGrantId","authorityGeneration" INTO prior FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "commandId"=c->>'commandId';
  IF prior."id" IS NOT NULL THEN
   IF prior."intentHash" IS DISTINCT FROM command_hash OR grant_row IS NULL AND prior."authorityKind"<>'HOST' OR grant_row IS NOT NULL AND (prior."authorityKind"<>'GRANT' OR prior."roundId" IS DISTINCT FROM grant_row->>'roundId' OR prior."authorityGrantId" IS DISTINCT FROM grant_row->>'id' OR prior."authorityGeneration" IS DISTINCT FROM (grant_row->>'generation')::INTEGER) THEN PERFORM public.int9_error('COMMAND_KEY_CONFLICT'); END IF;
   IF grant_row IS NOT NULL THEN SELECT (receipt->>'revision')::INTEGER INTO saved_canvas_revision FROM public."DrawingCanvasState" canvas CROSS JOIN LATERAL jsonb_array_elements(canvas."state"->'receipts') receipt WHERE canvas."roundId"=grant_row->>'roundId' AND receipt->>'commandId'=c->>'commandId' AND receipt->>'hash'=command_hash; IF saved_canvas_revision IS NULL THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF; RETURN jsonb_build_object('idempotent',TRUE,'canvasReceipt',jsonb_build_object('gameId',game_id,'roundId',grant_row->'roundId','commandId',c->'commandId','hash',command_hash,'expectedRevision',c->'expectedRevision','revision',saved_canvas_revision,'eventId',prior."id")); END IF;
   prior:=NULL; PERFORM public.int9_mutation_owner(game_id,selected_round,NULL,NULL,NULL,'{"grants":[]}'::JSONB,NULL,NULL,moment); RETURN public.int9_receipt_result(game_id,c,TRUE,NULL,NULL);
  END IF; prior:=NULL;
 END IF;
 IF c IS NOT NULL AND c<>'null'::JSONB AND grant_row IS NULL AND (expected_version IS NULL OR expected_version IS DISTINCT FROM (c->>'expectedVersion')::INTEGER) THEN PERFORM public.int9_error('STALE_VERSION'); END IF;
 -- Clock settlement is a distinct committed transition in the enclosing SQL
 -- transaction. No changed-clock request proceeds to a FINAL classification.
 clock_changed:=public.int9_mutation_owner(game_id,selected_round,NULL,selected_scope,NULL,'{"grants":[]}'::JSONB,NULL,NULL,moment);
 IF clock_changed THEN rejection:=(CASE WHEN c IS NULL OR c='null'::JSONB THEN NULL WHEN EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "sequence">pre_revision AND "type"='RESOURCE_LIMIT_REACHED') THEN 'RESOURCE_LIMIT_REACHED' ELSE 'ROUND_TIME_EXPIRED' END); RETURN public.int9_receipt_result(game_id,c,FALSE,rejection,NULL); END IF;
 IF c IS NULL OR c='null'::JSONB THEN RETURN public.int9_receipt_result(game_id,NULL,FALSE,NULL,NULL); END IF;
 -- Canvas has its own Game snapshot scalar and expectedRevision; no host key is synthesized.
 IF grant_row IS NOT NULL AND expected_version IS DISTINCT FROM pre_revision THEN PERFORM public.int9_error('STALE_VERSION'); END IF;
 IF grant_row IS NULL AND pre_revision IS DISTINCT FROM expected_version THEN IF pre_revision>expected_version THEN RETURN public.int9_receipt_result(game_id,c,FALSE,'STALE_VERSION',NULL); ELSE PERFORM public.int9_error('STALE_VERSION'); END IF; END IF;
 IF grant_row IS NOT NULL AND (grant_row->>'role'<>'ACTOR' OR NOT EXISTS(SELECT 1 FROM public."GameRound" WHERE "gameId"=game_id AND "id"=grant_row->>'roundId' AND "pin"->>'format'='DRAWING_TARGET')) THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 BEGIN
  PERFORM public.int9_mutation_owner(game_id,selected_round,selected_effect,selected_scope,c,proposal,command_hash,grant_row,moment);
 EXCEPTION WHEN raise_exception THEN GET STACKED DIAGNOSTICS rejection=MESSAGE_TEXT,detail=PG_EXCEPTION_DETAIL;
  IF rejection='ENTA_ERROR' AND detail IN ('OPTIONAL_CAPACITY_EXHAUSTED','ATTEMPT_BUDGET_EXCEEDED') THEN rejection:=detail; END IF;
  -- Helper locals may retain mutated values after rollback. Only immutable
  -- captured scalars and locked physical rows prove the same-CAS negative.
  PERFORM public.int9_lock_only(ns,project,game_id,selected_round,selected_effect,selected_scope);
  SELECT "version" INTO current_revision FROM public."GameRuntime" WHERE "gameId"=game_id;
  IF rejection IN ('OPTIONAL_CAPACITY_EXHAUSTED','ATTEMPT_BUDGET_EXCEEDED') AND grant_row IS NULL AND NOT clock_changed AND expected_version=pre_revision AND current_revision=pre_revision AND NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "commandId"=c->>'commandId') AND NOT EXISTS(SELECT 1 FROM public."CompetitiveAuditReport" WHERE "gameId"=game_id AND "commandId"=c->>'commandId') THEN
   RETURN public.int9_receipt_result(game_id,c,FALSE,rejection,NULL)||jsonb_build_object('commandRejection',jsonb_build_object('version',1,'state','REJECTED','projectId',project,'principalUid',uid,'gameId',game_id,'commandId',c->'commandId','hash',command_hash,'expectedVersion',expected_version,'currentRevision',current_revision,'reason',rejection));
  END IF;
  IF rejection<>'CORRECTION_DEPENDENCY_REVIEW_REQUIRED' OR detail NOT LIKE 'INT9_BLOCKERS:%' THEN RAISE; END IF; blocked:=substring(detail FROM 15)::JSONB;
  IF NOT public.int6_enta_exact_keys(blocked,ARRAY['ids','total']) OR jsonb_typeof(blocked->'ids') IS DISTINCT FROM 'array' OR jsonb_array_length(blocked->'ids')>32 OR public.int5b_json_integer(blocked->'total',jsonb_array_length(blocked->'ids'),64945) IS NOT TRUE OR EXISTS(SELECT 1 FROM jsonb_array_elements(blocked->'ids') id WHERE public.int8_json_id(id) IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=id#>>'{}')) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
  RETURN public.int9_receipt_result(game_id,c,FALSE,rejection,blocked);
 END;
 IF grant_row IS NOT NULL THEN SELECT (receipt->>'revision')::INTEGER INTO saved_canvas_revision FROM public."DrawingCanvasState" canvas CROSS JOIN LATERAL jsonb_array_elements(canvas."state"->'receipts') receipt WHERE canvas."roundId"=grant_row->>'roundId' AND receipt->>'commandId'=c->>'commandId' AND receipt->>'hash'=command_hash; RETURN jsonb_build_object('idempotent',FALSE,'canvasReceipt',jsonb_build_object('gameId',game_id,'roundId',grant_row->'roundId','commandId',c->'commandId','hash',command_hash,'expectedRevision',c->'expectedRevision','revision',saved_canvas_revision,'eventId',(SELECT "id" FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "commandId"=c->>'commandId'))); END IF;
 grant_row:=NULL; RETURN public.int9_receipt_result(game_id,c,FALSE,NULL,NULL);
END $$;
CREATE OR REPLACE FUNCTION public.int9_disclose(ns TEXT,project TEXT,game_id TEXT,token_hash TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE gr JSONB; r RECORD; h JSONB; b JSONB; event_row JSONB; effect JSONB; disclosure JSONB; scope JSONB; data JSONB; target TEXT; moment DOUBLE PRECISION; identity_id TEXT; admission_id TEXT; scope_id TEXT; effect_sequence INTEGER; media_total INTEGER; deadline DOUBLE PRECISION; BEGIN
 SELECT "scopeId" INTO scope_id FROM public."RoundGrant" WHERE "gameId"=game_id AND "tokenHash"=token_hash;
 PERFORM public.int9_lock_only(ns,project,game_id,NULL,NULL,scope_id); moment:=public.int9_now(); gr:=public.int9_grant_physical(game_id,token_hash,moment);
 SELECT physical."id",physical."formatId",physical."state",physical."questionRevisionId",cp."targetHash",physical."pin"->>'format' AS format,physical."pin"->>'target' AS target INTO r FROM public."GameRound" physical JOIN public."CompetitiveRoundPin" cp ON cp."gameId"=physical."gameId" AND cp."roundId"=physical."id" WHERE physical."gameId"=game_id AND physical."id"=gr->>'roundId';
 IF gr->>'role'='ACTOR' AND r.format='DRAWING_TARGET' THEN
  IF NOT EXISTS(SELECT 1 FROM public."CompetitiveAssignmentPlayer" p WHERE p."assignmentId"=r."state"->'assignment'->>'id' AND p."gameId"=game_id AND p."roundId"=r."id" AND p."playerId"=r."state"->'assignment'->>'playerId' AND p."generation"=(r."state"->'assignment'->>'generation')::INTEGER AND p."targetHash"=r."targetHash") THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public."CompetitiveTargetDisclosure" d WHERE d."gameId"=game_id AND d."roundId"=r."id" AND d."assignmentId"=r."state"->'assignment'->>'id' AND d."playerId"=r."state"->'assignment'->>'playerId' AND d."grantId"=gr->>'id' AND d."grantGeneration"=(gr->>'generation')::INTEGER AND d."targetHash"=r."targetHash") THEN
   h:=public.int9_before_header(game_id); SELECT "firebaseIdentityId","admissionId" INTO identity_id,admission_id FROM public."Game" WHERE "id"=game_id; SELECT COALESCE(max("sequence"),0)+1 INTO effect_sequence FROM public."CompetitiveEffect" WHERE "gameId"=game_id;
   event_row:=jsonb_build_object('id',gen_random_uuid()::TEXT,'commandId',gen_random_uuid()::TEXT,'hash',public.int6_enta_hash(jsonb_build_object('hash',token_hash,'targetHash',r."targetHash",'assignmentId',r."state"->'assignment'->'id')),'type','TARGET_DELIVERY','roundId',r."id",'sequence',(h->>'version')::INTEGER+1,'at',moment,'authority',jsonb_build_object('kind','GRANT','grantId',gr->'id','generation',gr->'generation','assignmentId',r."state"->'assignment'->'id'),'pauseReason',NULL);
   effect:=public.int9_seal_patch(public.int9_effect_patch(event_row,effect_sequence,r."id",public.int9_snapshot(r."state"),'DISCLOSURE','{}'::JSONB));
   disclosure:=jsonb_build_object('id',event_row->'id','roundId',r."id",'targetRevisionId',r."questionRevisionId",'targetHash',r."targetHash",'playerId',r."state"->'assignment'->'playerId','assignmentId',r."state"->'assignment'->'id','assignmentGeneration',r."state"->'assignment'->'generation','at',moment,'grantId',gr->'id','grantGeneration',gr->'generation');
   b:=jsonb_build_object('id',game_id,'identityId',identity_id,'admissionId',admission_id,'beforeVersion',h->'version','finalRevision',event_row->'sequence','events',jsonb_build_array(event_row),'effects',jsonb_build_array(effect),'disclosures',jsonb_build_array(disclosure),'headChanges',jsonb_build_object('latestEffectId',effect->'id')); event_row:=NULL; effect:=NULL; disclosure:=NULL;
   PERFORM public.int9_store_batch(b,h); b:=NULL; h:=NULL; PERFORM public.int9_assert_stored(game_id);
  END IF;
 END IF;
 scope:=public.int9_scope_dto(game_id,NULL,gr);
 deadline:=(CASE WHEN r."state"->'deadline'='null'::JSONB THEN (r."state"->>'overallDeadline')::DOUBLE PRECISION WHEN r."state"->'overallDeadline'='null'::JSONB THEN (r."state"->>'deadline')::DOUBLE PRECISION ELSE least((r."state"->>'deadline')::DOUBLE PRECISION,(r."state"->>'overallDeadline')::DOUBLE PRECISION) END);
 SELECT count(*) INTO media_total FROM public."EntaFormatMedia" m WHERE m."formatId"=r."formatId" AND (CASE WHEN gr->>'role'='ACTOR' THEN m."role"='ACTOR' AND r.format='DRAWING_TARGET' OR m."role"='ITEM' AND m."itemId"=r."state"->'assignment'->>'itemId' ELSE m."role" IN ('PROMPT','MASKED','ITEM') END);
 data:=jsonb_build_object('gameId',game_id,'gameVersion',scope->'snapshot','serverNow',moment,'roundId',r."id",'roundVersion',r."state"->'version','assignmentGeneration',r."state"->'assignment'->'generation','role',gr->'role','format',r.format,'grant',scope->'grant','deadline',deadline,'media','[]'::JSONB,'mediaTotal',media_total);
 IF gr->>'role'='JUDGE' THEN data:=data||jsonb_build_object('grading',jsonb_build_object('roundId',r."id",'version',r."state"->'version','format',r.format,'total',scope->'itemTotal','items','[]'::JSONB));
 ELSE target:=(CASE WHEN r.format='DRAWING_TARGET' THEN r.target ELSE (SELECT answer."text" FROM public."EntaFormatItem" item JOIN public."QuestionAnswerRevision" answer ON answer."id"=item."answerRevisionId" AND answer."contentHash"=item."answerHash" WHERE item."formatId"=r."formatId" AND item."id"=r."state"->'assignment'->>'itemId') END); IF target IS NULL THEN PERFORM public.int9_error('GRANT_DENIED'); END IF; data:=data||jsonb_build_object('target',target,'canvas',CASE WHEN r.format='DRAWING_TARGET' THEN jsonb_build_object('revision',scope->'canvasRevision') ELSE 'null'::JSONB END); END IF;
 r:=NULL; gr:=NULL; target:=NULL; IF octet_length(convert_to(public.int6_enta_canonical(data),'UTF8'))>65536 THEN PERFORM public.int9_error('PROJECTION_BOUND_EXCEEDED'); END IF; RETURN jsonb_build_object('scope',scope,'data',data);
END $$;
CREATE OR REPLACE FUNCTION public.int9_has_report(ns TEXT,project TEXT,uid TEXT,game_id TEXT,command_id TEXT) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE identity_id TEXT; BEGIN
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; IF NOT EXISTS(SELECT 1 FROM public."Game" WHERE "id"=game_id AND "firebaseIdentityId"=identity_id) THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; PERFORM public.int9_lock_only(ns,project,game_id,NULL,NULL,NULL);
 RETURN EXISTS(SELECT 1 FROM public."CompetitiveAuditReport" report WHERE report."gameId"=game_id AND report."commandId"=command_id);
END $$;
CREATE OR REPLACE FUNCTION public.int9_report(ns TEXT,project TEXT,uid TEXT,game_id TEXT,c JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE identity_id TEXT; current_revision INTEGER; existing public."CompetitiveAuditReport"%ROWTYPE; report_id TEXT; BEGIN
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; IF NOT EXISTS(SELECT 1 FROM public."Game" WHERE "id"=game_id AND "firebaseIdentityId"=identity_id) THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; PERFORM public.int9_lock_only(ns,project,game_id,c->>'roundId',c->>'effectId',NULL); SELECT "version" INTO current_revision FROM public."GameRuntime" WHERE "gameId"=game_id;
 IF public.int9_valid_command(c,FALSE) IS NOT TRUE OR c->>'type'<>'REPORT_VAR' THEN PERFORM public.int9_error('INVALID_COMMAND'); END IF; PERFORM public.int9_scope_facts(game_id,c);
 SELECT "commandHash","id" INTO existing."commandHash",existing."id" FROM public."CompetitiveAuditReport" WHERE "gameId"=game_id AND "commandId"=c->>'commandId'; IF FOUND THEN IF existing."commandHash" IS DISTINCT FROM public.int6_enta_hash(c) THEN PERFORM public.int9_error('COMMAND_KEY_CONFLICT'); END IF; RETURN jsonb_build_object('id',existing."id",'idempotent',TRUE); END IF;
 IF EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "commandId"=c->>'commandId') THEN PERFORM public.int9_error('COMMAND_KEY_CONFLICT'); END IF; IF current_revision<>(c->>'expectedVersion')::INTEGER THEN PERFORM public.int9_error('STALE_VERSION'); END IF;
 IF (SELECT count(*) FROM public."CompetitiveAuditReport" WHERE "gameId"=game_id)>=128 THEN PERFORM public.int9_error('AUDIT_BUDGET_EXCEEDED'); END IF; report_id:=gen_random_uuid()::TEXT;
 INSERT INTO public."CompetitiveAuditReport"("id","gameId","ownerIdentityId","roundId","effectId","commandId","commandHash","reason","blockingIds","createdAt") VALUES(report_id,game_id,identity_id,c->>'roundId',c->>'effectId',c->>'commandId',public.int6_enta_hash(c),c->>'reason',c->'blockingIds',clock_timestamp()); RETURN jsonb_build_object('id',report_id,'idempotent',FALSE);
 -- No main runtime/version/effect/result mutation, including after FINISH.
END $$;

CREATE OR REPLACE FUNCTION public.int9_start(ns TEXT,project TEXT,uid TEXT,request JSONB,intent JSONB,pins JSONB,receipt_id TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE c4_captured JSONB; identity_id TEXT; w public."Wallet"%ROWTYPE; a_id TEXT:=gen_random_uuid()::TEXT; res_id TEXT:=gen_random_uuid()::TEXT; game_id TEXT:=request->>'logicalMatchId'; existing JSONB; catalog JSONB; competitive JSONB; competitive_prompt_id TEXT; base_pin JSONB; roster JSONB; player_state JSONB; allowances JSONB:='[]'::JSONB; aid JSONB; fmt TEXT:=request->>'executionFormat'; mode TEXT; s JSONB:=request->'setup'; categories JSONB:='[]'::JSONB; teams JSONB:='[]'::JSONB; rounds JSONB:='[]'::JSONB; state JSONB; team JSONB; player JSONB; category JSONB; pin JSONB; item JSONB; choice JSONB; team_id TEXT; round_id TEXT; question_id TEXT; team_ids TEXT[]:=ARRAY[]::TEXT[]; moment TIMESTAMPTZ; i INTEGER:=0; j INTEGER; remaining_count INTEGER:=0; selected_cycle INTEGER; pool_count INTEGER; taken INTEGER; expected_selection JSONB:='[]'::JSONB; pool_hash TEXT; saved_intent_hash TEXT;
BEGIN
 IF public.int9_valid_request(request) IS NOT TRUE THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; SELECT "available","debt","held","id","version" INTO w."available",w."debt",w."held",w."id",w."version" FROM public."Wallet" WHERE "firebaseIdentityId"=identity_id FOR UPDATE; IF NOT FOUND THEN PERFORM public.int6_enta_error('ACCOUNT_NOT_READY'); END IF;
 existing:=public.int9_find_start(ns,project,uid,request->>'requestKey',game_id); IF existing IS NOT NULL THEN IF existing->'request' IS DISTINCT FROM request THEN PERFORM public.int6_enta_error('IDEMPOTENCY_KEY_CONFLICT'); END IF; RETURN existing; END IF;
 IF w."debt">0 THEN PERFORM public.int6_enta_error('WALLET_DEBT_BLOCKS_START'); END IF; IF w."available"<1 THEN PERFORM public.int6_enta_error('INSUFFICIENT_CREDIT'); END IF;
 IF NOT public.int9_valid_request(request) OR NOT public.int6_enta_exact_keys(intent,ARRAY['version','domain','pinMaterial','request','baseReleaseId','baseRoot','receiptId','formatReleaseId','formatRoot','mediaRoot','policyVersion','poolHash','seed','selection','roundCount','pinsHash','competitiveReleaseId','proofRoot','paletteRoot','tournamentBinding']) OR intent->'version'<>'5'::JSONB OR intent->>'domain' IS DISTINCT FROM 'maydan.enta.competitive.start-intent.v1' OR intent->>'pinMaterial' IS DISTINCT FROM 'maydan.enta.competitive.pin-references.v1' OR intent->'tournamentBinding' IS DISTINCT FROM 'null'::JSONB OR intent->'request' IS DISTINCT FROM request OR intent->>'seed'!~'^[a-f0-9]{64}$' OR jsonb_typeof(pins) IS DISTINCT FROM 'array' OR jsonb_array_length(pins) NOT BETWEEN 1 AND 36 OR intent->>'pinsHash' IS DISTINCT FROM public.int9_references_hash(pins) OR intent->'selection' IS DISTINCT FROM pins OR intent->'roundCount' IS DISTINCT FROM to_jsonb(jsonb_array_length(pins)) THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 IF receipt_id IS DISTINCT FROM intent->>'receiptId' THEN PERFORM public.int6_enta_error('FORMAT_CATALOG_UNAVAILABLE'); END IF;
 c4_captured:=public.int9_c4_f11_capture(ns,project,uid,request,intent); competitive:=public.int9_c4_catalog_at(ns,project,uid,request,c4_captured); c4_captured:=NULL; catalog:=competitive->'base'; PERFORM public.int9_assert_competitive(competitive->>'competitiveReleaseId');
 IF (intent->>'baseReleaseId',intent->>'baseRoot',intent->>'receiptId',intent->>'formatReleaseId',intent->>'formatRoot',intent->>'mediaRoot') IS DISTINCT FROM (catalog->>'baseReleaseId',catalog->>'baseRoot',catalog->>'receiptId',catalog->>'formatReleaseId',catalog->>'formatRoot',catalog->>'mediaRoot') OR intent->>'policyVersion' IS DISTINCT FROM 'enta-competitive-1' OR (intent->>'competitiveReleaseId',intent->>'proofRoot',intent->>'paletteRoot') IS DISTINCT FROM (competitive->>'competitiveReleaseId',competitive->>'proofRoot',competitive->>'paletteRoot') OR receipt_id IS DISTINCT FROM catalog->>'receiptId' THEN PERFORM public.int6_enta_error('FORMAT_CATALOG_UNAVAILABLE'); END IF;
 expected_selection:=public.int9_select_references(competitive->>'competitiveReleaseId',request,intent->>'seed',identity_id);
 IF expected_selection IS DISTINCT FROM pins OR public.int9_pool_root(competitive->>'competitiveReleaseId',request) IS DISTINCT FROM intent->>'poolHash' THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
 FOR choice IN SELECT x FROM jsonb_array_elements(pins) x LOOP
  SELECT p."id" INTO competitive_prompt_id FROM public."EntaCompetitivePrompt" p WHERE p."releaseId"=competitive->>'competitiveReleaseId' AND p."formatId"=choice->>'formatId';
  IF public.int9_reference(choice->>'formatId',competitive_prompt_id,(choice->>'ordinal')::INTEGER,(choice->>'cycle')::INTEGER) IS DISTINCT FROM choice OR NOT EXISTS(SELECT 1 FROM public."EntaFormatRevision" f JOIN public."CatalogReleaseQuestion" q ON q."questionRevisionId"=f."questionRevisionId" AND q."questionContentHash"=f."questionHash" AND q."catalogReleaseId"=catalog->>'baseReleaseId' WHERE f."id"=choice->>'formatId' AND f."releaseId"=catalog->>'formatReleaseId') THEN PERFORM public.int9_error('PROMPT_UNAVAILABLE'); END IF;
 END LOOP;
 expected_selection:=NULL; saved_intent_hash:=public.int9_intent_hash(intent);
 mode:=(CASE fmt WHEN 'STANDALONE_LIST' THEN 'LIST' WHEN 'STANDALONE_ACTING' THEN 'ACTING' ELSE 'CLASSIC' END); moment:=clock_timestamp();
 INSERT INTO public."Admission"("id","firebaseIdentityId","walletId","engine","operation","mode","logicalMatchId","requestKey","requestHash","intentHash","requestVersion","catalogReleaseId","releaseRootHash","validationReceiptId","selectorVersion","state","version","updatedAt") VALUES(a_id,identity_id,w."id",'ENTA',request->>'operation',mode,game_id,request->>'requestKey',public.int6_enta_hash(request),saved_intent_hash,5,catalog->>'baseReleaseId',catalog->>'baseRoot',receipt_id,'enta-competitive-1','HELD',0,moment);
 INSERT INTO public."Reservation"("id","admissionId","quantity","state","updatedAt") VALUES(res_id,a_id,1,'HELD',moment);
 INSERT INTO public."WalletEntry"("id","walletId","sequence","originType","originId","effect","reservationId","deltaAvailable","deltaHeld","deltaDebt","resultingAvailable","resultingHeld","resultingDebt","actorFirebaseIdentityId","evidenceHash") VALUES(gen_random_uuid()::TEXT,w."id",w."version"+1,'ADMISSION',a_id,'RESERVE',res_id,-1,1,0,w."available"-1,w."held"+1,w."debt",identity_id,public.int6_enta_hash(request));
 UPDATE public."Wallet" SET "available"="available"-1,"held"="held"+1,"version"="version"+1,"updatedAt"=moment WHERE "id"=w."id";
 INSERT INTO public."AdmissionEvent"("id","admissionId","sequence","eventType","evidenceHash") VALUES(gen_random_uuid()::TEXT,a_id,1,'HELD',public.int6_enta_hash(request));
 INSERT INTO public."Game"("id","userId","gameFormat","executionFormat","firebaseIdentityId","admissionId","catalogReleaseId","catalogReleaseRootHash","validationReceiptId","mode","status","createdAt") VALUES(game_id,NULL,'FIREBASE_PINNED',fmt,identity_id,a_id,catalog->>'baseReleaseId',catalog->>'baseRoot',receipt_id,mode,'ACTIVE',moment AT TIME ZONE 'UTC');
 FOR team IN SELECT x FROM jsonb_array_elements(s->'teams') x LOOP team_id:=gen_random_uuid()::TEXT; team_ids:=array_append(team_ids,team_id); INSERT INTO public."Team"("id","gameId","name","color","score") VALUES(team_id,game_id,team->>'name',public.int9_palette()->(team->>'colorKey')->>'color',0); j:=0; player_state:='[]'::JSONB; FOR player IN SELECT x FROM jsonb_array_elements(team->'players') x LOOP j:=j+1; INSERT INTO public."Player"("id","teamId","name") VALUES(team_id||'-p'||lpad(j::TEXT,2,'0'),team_id,player#>>'{}'); player_state:=player_state||jsonb_build_array(jsonb_build_object('id',team_id||'-p'||lpad(j::TEXT,2,'0'),'name',player)); END LOOP; teams:=teams||jsonb_build_array(jsonb_build_object('id',team_id,'name',team->>'name','players',player_state,'colorKey',team->'colorKey','aids',team->'aids','score',0,'scoreVersion',0,'scoreHead',NULL)); i:=i+1; END LOOP;
 i:=0; FOR category IN SELECT x FROM jsonb_array_elements(s->'categories') x LOOP INSERT INTO public."GameCategoryPin"("id","gameId","catalogReleaseId","categoryKey","categoryRevisionId","ordinal") SELECT gen_random_uuid()::TEXT,game_id,catalog->>'baseReleaseId',category->>'key',"categoryRevisionId",i FROM public."CatalogReleaseCategory" WHERE "catalogReleaseId"=catalog->>'baseReleaseId' AND "categoryKey"=category->>'key'; SELECT categories||jsonb_build_array(c-'prompts'-'roundCount') INTO categories FROM jsonb_array_elements(catalog->'categories') c WHERE c->>'key'=category->>'key'; i:=i+1; END LOOP;
 state:=jsonb_build_object('contextVersion',1,'gameId',game_id,'version',1);
 INSERT INTO public."EntaExecutionPin"("gameId","firebaseIdentityId","executionFormat","formatReleaseId","formatRoot","mediaRoot","clientBinding","clientHash","fullIntent","intentHash","state") VALUES(game_id,identity_id,fmt,catalog->>'formatReleaseId',catalog->>'formatRoot',catalog->>'mediaRoot',request,public.int6_enta_hash(request),intent,saved_intent_hash,state);
 INSERT INTO public."GameCompetitivePin"("gameId","firebaseIdentityId","admissionId","releaseId","proofRoot","paletteRoot","rulesVersion","requestVersion") VALUES(game_id,identity_id,a_id,competitive->>'competitiveReleaseId',competitive->>'proofRoot',competitive->>'paletteRoot','enta-competitive-1',5);
 intent:=NULL; state:=NULL;
 i:=0; FOR choice IN SELECT x FROM jsonb_array_elements(pins) x LOOP
 SELECT p."id" INTO competitive_prompt_id FROM public."EntaCompetitivePrompt" p WHERE p."releaseId"=competitive->>'competitiveReleaseId' AND p."formatId"=choice->>'formatId'; pin:=NULL; base_pin:=NULL; item:=NULL; pin:=public.int9_descriptor(competitive_prompt_id); round_id:=gen_random_uuid()::TEXT; question_id:=gen_random_uuid()::TEXT; INSERT INTO public."GameQuestion"("id","gameId","catalogReleaseId","questionRevisionId","questionId","isOpened","usedVar","alsoCorrectTeamIds") VALUES(question_id,game_id,catalog->>'baseReleaseId',pin->>'revisionId',NULL,FALSE,FALSE,ARRAY[]::TEXT[]);
 base_pin:=pin-ARRAY['hints','graphemes','hintRoot','effectValue','effectValueSource','proofHash']; choice:=jsonb_build_object('id',round_id,'questionId',question_id,'ordinal',i,'phase','READY','phaseOrdinal',0,'generation',0,'version',0,'originalTeamId',NULL,'currentTeamId',NULL,'originalDeadline',NULL,'deadline',NULL,'overallDeadline',NULL,'pause',NULL,'publicRevealed',FALSE,'itemReveals','[]'::JSONB,'assignment',NULL,'pickedPlayerId',NULL,'pickedEventId',NULL,'usedAidIds','[]'::JSONB,'doubleAttemptTeamId',NULL,'bonus',NULL,'revealedHintIds','[]'::JSONB,'graphemeHints','[]'::JSONB,'consumed','[]'::JSONB,'reason',NULL,'turnAdvanced',FALSE,'resourceStop',NULL);
 INSERT INTO public."GameRound"("id","gameId","gameQuestionId","formatId","questionRevisionId","questionHash","categoryKey","sourceNamespace","sourceId","formatHash","ordinal","pin","state") VALUES(round_id,game_id,question_id,pin->>'formatId',pin->>'revisionId',pin->>'hash',pin->>'categoryKey',pin->>'sourceNamespace',pin->>'sourceId',pin->>'formatHash',i,base_pin,choice-'pin');
 FOR item IN SELECT x FROM jsonb_array_elements(pin->'items') x LOOP INSERT INTO public."RoundItemPin"("roundId","formatId","itemId","answerRevisionId","answerHash","ordinal") VALUES(round_id,pin->>'formatId',item->>'id',item->>'revisionId',item->>'hash',(item->>'ordinal')::INTEGER); END LOOP;
 INSERT INTO public."CompetitiveRoundPin"("gameId","roundId","promptId","proofHash","targetHash","pin") VALUES(game_id,round_id,competitive_prompt_id,pin->>'proofHash',public.int6_enta_hash(jsonb_build_object('revisionId',pin->'revisionId','revisionHash',pin->'hash','target',pin->'target')),pin);
 rounds:=rounds||jsonb_build_array(choice-'pin'); i:=i+1; END LOOP;

 FOR team IN SELECT x FROM jsonb_array_elements(teams) x LOOP FOR aid IN SELECT x FROM jsonb_array_elements(team->'aids') x LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pins) p WHERE (aid#>>'{}')=ANY(public.int9_aids(fmt,p->>'format'))) THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
  IF fmt IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN FOR choice IN SELECT x FROM jsonb_array_elements(rounds) x LOOP allowances:=allowances||jsonb_build_array(jsonb_build_object('id',gen_random_uuid()::TEXT,'teamId',team->'id','aid',aid,'scope','PINNED_QUESTION','scopeId',choice->'id','roundId',choice->'id')); END LOOP;
  ELSE allowances:=allowances||jsonb_build_array(jsonb_build_object('id',gen_random_uuid()::TEXT,'teamId',team->'id','aid',aid,'scope','MATCH','scopeId',game_id,'roundId',NULL)); END IF;
 END LOOP; END LOOP;
 FOR team IN SELECT x FROM jsonb_array_elements(teams) x LOOP j:=0; FOR player IN SELECT x FROM jsonb_array_elements(team->'players') x LOOP INSERT INTO public."CompetitiveRosterPlayer"("gameId","teamId","playerId","ordinal") VALUES(game_id,team->>'id',player->>'id',j); j:=j+1; END LOOP; END LOOP;
 FOR aid IN SELECT x FROM jsonb_array_elements(allowances) x LOOP INSERT INTO public."CompetitiveAllowance"("id","gameId","teamId","roundId","scope","scopeId","aid","ordinal") VALUES(aid->>'id',game_id,aid->>'teamId',aid->>'roundId',aid->>'scope',aid->>'scopeId',aid->>'aid',(SELECT ord::INTEGER-1 FROM jsonb_array_elements(s->'teams') setup_team CROSS JOIN LATERAL jsonb_array_elements(setup_team->'aids') WITH ORDINALITY keys(key,ord) WHERE setup_team->>'name'=(SELECT "name" FROM public."Team" WHERE "id"=aid->>'teamId' AND "gameId"=game_id) AND key=aid->'aid')); END LOOP;
 INSERT INTO public."CompetitiveRuntimeHead"("gameId") VALUES(game_id);
 IF fmt IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN FOR choice IN SELECT x FROM jsonb_array_elements(pins) x LOOP INSERT INTO public."EntaSourceExposure"("gameId","ordinal","firebaseIdentityId","executionFormat","categoryKey","sourceNamespace","sourceId","cycle","revisionId") VALUES(game_id,(choice->>'ordinal')::INTEGER,identity_id,fmt,s->'categories'->0->>'key',choice->>'sourceNamespace',choice->>'sourceId',(choice->>'cycle')::INTEGER,choice->>'revisionId'); END LOOP; END IF;
 INSERT INTO public."GameRuntime"("gameId","version","state","setup","setupHash","teamOrder","turnIndex","updatedAt") VALUES(game_id,1,'BOARD',s,public.int6_enta_hash(s),team_ids,0,moment);
 INSERT INTO public."GameEvent"("gameId","commandId","sequence","actorFirebaseIdentityId","type","intentHash") VALUES(game_id,request->>'requestKey',1,identity_id,'START',saved_intent_hash);
 SELECT "available","debt","held","id","version" INTO w."available",w."debt",w."held",w."id",w."version" FROM public."Wallet" WHERE "id"=w."id";
 INSERT INTO public."WalletEntry"("id","walletId","sequence","originType","originId","effect","reservationId","deltaAvailable","deltaHeld","deltaDebt","resultingAvailable","resultingHeld","resultingDebt","actorFirebaseIdentityId","evidenceHash") VALUES(gen_random_uuid()::TEXT,w."id",w."version"+1,'ADMISSION',a_id,'COMMIT',res_id,0,-1,0,w."available",w."held"-1,w."debt",identity_id,saved_intent_hash);
 UPDATE public."Wallet" SET "held"="held"-1,"version"="version"+1,"updatedAt"=moment WHERE "id"=w."id"; UPDATE public."Reservation" SET "state"='COMMITTED',"updatedAt"=moment WHERE "id"=res_id; UPDATE public."Admission" SET "state"='COMMITTED',"version"=1,"updatedAt"=moment WHERE "id"=a_id; INSERT INTO public."AdmissionEvent"("id","admissionId","sequence","eventType","evidenceHash") VALUES(gen_random_uuid()::TEXT,a_id,2,'COMMITTED',saved_intent_hash); pins:=NULL; pin:=NULL; base_pin:=NULL; choice:=NULL; item:=NULL; state:=NULL; catalog:=NULL; competitive:=NULL; categories:=NULL; teams:=NULL; rounds:=NULL; allowances:=NULL; PERFORM public.int9_capacity_initialize(game_id); RETURN jsonb_build_object('id',game_id);
END $$;

CREATE OR REPLACE FUNCTION public.int6_enta_game_insert_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE a public."Admission"%ROWTYPE;
BEGIN
 -- INT-062 exact request5 branch; every predecessor branch below is retained.
 IF EXISTS(SELECT 1 FROM public."Admission" candidate WHERE candidate."id"=NEW."admissionId" AND candidate."firebaseIdentityId"=NEW."firebaseIdentityId" AND candidate."engine"='ENTA' AND candidate."requestVersion"=5) THEN
  SELECT "catalogReleaseId","engine","logicalMatchId","mode","operation","predecessorAdmissionId","releaseRootHash","requestVersion","selectorVersion","state","validationReceiptId" INTO a."catalogReleaseId",a."engine",a."logicalMatchId",a."mode",a."operation",a."predecessorAdmissionId",a."releaseRootHash",a."requestVersion",a."selectorVersion",a."state",a."validationReceiptId" FROM public."Admission" WHERE "id"=NEW."admissionId" AND "firebaseIdentityId"=NEW."firebaseIdentityId";
  IF NEW."gameFormat"<>'FIREBASE_PINNED' OR NEW."userId" IS NOT NULL OR NEW."executionFormat" NOT IN ('TIER_BOARD','MIXED_BOARD','STANDALONE_LIST','STANDALONE_ACTING') OR a."state"<>'HELD' OR a."selectorVersion"<>'enta-competitive-1' OR a."logicalMatchId"<>NEW."id" OR a."predecessorAdmissionId" IS NOT NULL OR a."mode" IS DISTINCT FROM NEW."mode" OR NEW."mode" IS DISTINCT FROM (CASE NEW."executionFormat" WHEN 'STANDALONE_LIST' THEN 'LIST' WHEN 'STANDALONE_ACTING' THEN 'ACTING' ELSE 'CLASSIC' END) OR a."operation" IS DISTINCT FROM (CASE NEW."executionFormat" WHEN 'STANDALONE_LIST' THEN 'PAID_ENTA_LIST' WHEN 'STANDALONE_ACTING' THEN 'PAID_ENTA_ACTING' ELSE 'PAID_ENTA_CLASSIC' END) OR a."catalogReleaseId" IS DISTINCT FROM NEW."catalogReleaseId" OR a."releaseRootHash" IS DISTINCT FROM NEW."catalogReleaseRootHash" OR a."validationReceiptId" IS DISTINCT FROM NEW."validationReceiptId" OR NOT EXISTS(SELECT 1 FROM public."FirebaseIdentity" identity_row JOIN public."DeploymentNamespace" deployment ON deployment."firebaseProjectId"=identity_row."firebaseProjectId" WHERE identity_row."id"=NEW."firebaseIdentityId" AND deployment."id"='singleton') THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
  IF (SELECT count(*) FROM public."EntaFormatRelease" WHERE "receiptId"=a."validationReceiptId" AND "baseReleaseId"=a."catalogReleaseId" AND "baseRoot"=a."releaseRootHash" AND "sealedAt" IS NOT NULL AND "policyVersion"='enta-format-1')<>1 THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
  PERFORM public.int9_assert_competitive((SELECT proof."id" FROM public."EntaCompetitiveRelease" proof JOIN public."EntaFormatRelease" format_proof ON format_proof."id"=proof."formatReleaseId" AND format_proof."formatRoot"=proof."formatRoot" AND format_proof."mediaRoot"=proof."mediaRoot" WHERE format_proof."receiptId"=a."validationReceiptId" AND proof."rulesVersion"='enta-competitive-1' AND proof."paletteRoot"=public.int9_palette_root() AND proof."sealedAt" IS NOT NULL)); RETURN NEW;
 END IF;

 IF NEW."executionFormat"<>'TIER_BOARD' THEN
 SELECT * INTO a FROM public."Admission" WHERE "id"=NEW."admissionId" AND "firebaseIdentityId"=NEW."firebaseIdentityId";
 IF NOT FOUND OR NEW."gameFormat"<>'FIREBASE_PINNED' OR NEW."userId" IS NOT NULL OR a."state"<>'HELD' OR a."engine"<>'ENTA' OR a."requestVersion"<>4 OR a."mode" IS DISTINCT FROM NEW."mode" OR a."operation" IS DISTINCT FROM (CASE NEW."executionFormat" WHEN 'MIXED_BOARD' THEN 'PAID_ENTA_CLASSIC' WHEN 'STANDALONE_LIST' THEN 'PAID_ENTA_LIST' WHEN 'STANDALONE_ACTING' THEN 'PAID_ENTA_ACTING' END) OR a."catalogReleaseId" IS DISTINCT FROM NEW."catalogReleaseId" OR a."releaseRootHash" IS DISTINCT FROM NEW."catalogReleaseRootHash" OR a."validationReceiptId" IS DISTINCT FROM NEW."validationReceiptId" THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF; PERFORM public.int8_assert_format((SELECT "id" FROM public."EntaFormatRelease" WHERE "receiptId"=a."validationReceiptId" AND "baseReleaseId"=a."catalogReleaseId" AND "baseRoot"=a."releaseRootHash" AND "sealedAt" IS NOT NULL)); RETURN NEW; END IF;

 IF NEW."gameFormat"<>'FIREBASE_PINNED' OR NEW."userId" IS NOT NULL OR NEW."mode" NOT IN ('CLASSIC','KIDS') THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 SELECT * INTO a FROM public."Admission" WHERE "id"=NEW."admissionId" AND "firebaseIdentityId"=NEW."firebaseIdentityId";
 IF NOT FOUND OR a."state"<>'HELD' OR a."engine"<>'ENTA' OR a."mode" IS DISTINCT FROM NEW."mode" OR a."operation" IS DISTINCT FROM (CASE WHEN NEW."mode"='KIDS' THEN 'PAID_ENTA_KIDS' ELSE 'PAID_ENTA_CLASSIC' END) OR a."requestVersion" NOT IN (2,3) OR (a."requestVersion"=2 AND NEW."mode"<>'CLASSIC')
 OR a."catalogReleaseId" IS DISTINCT FROM NEW."catalogReleaseId" OR a."releaseRootHash" IS DISTINCT FROM NEW."catalogReleaseRootHash" OR a."validationReceiptId" IS DISTINCT FROM NEW."validationReceiptId" THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 IF a."requestVersion"=2 THEN PERFORM public.int6_enta_assert_receipt(a."validationReceiptId",a."catalogReleaseId",a."releaseRootHash"); ELSE PERFORM public.int7_enta_assert_receipt(a."validationReceiptId",a."catalogReleaseId",a."releaseRootHash",a."mode"); END IF; RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.int6_enta_runtime_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE g public."Game"%ROWTYPE; a public."Admission"%ROWTYPE; i INTEGER; names TEXT[];
BEGIN
 -- INT-062 exact request5 branch; every predecessor branch below is retained.
 SELECT * INTO g FROM public."Game" WHERE "id"=(CASE WHEN TG_OP='DELETE' THEN OLD."gameId" ELSE NEW."gameId" END);
 IF EXISTS(SELECT 1 FROM public."Admission" candidate WHERE candidate."id"=g."admissionId" AND candidate."firebaseIdentityId"=g."firebaseIdentityId" AND candidate."engine"='ENTA' AND candidate."requestVersion"=5) THEN
  IF TG_OP='DELETE' THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
  IF NEW."activeQuestionId" IS NOT NULL OR NEW."activeRoundId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."GameRound" round_row WHERE round_row."id"=NEW."activeRoundId" AND round_row."gameId"=NEW."gameId") THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
  IF TG_OP='UPDATE' THEN IF (NEW."gameId",NEW."setup",NEW."setupHash",NEW."teamOrder",NEW."createdAt") IS DISTINCT FROM (OLD."gameId",OLD."setup",OLD."setupHash",OLD."teamOrder",OLD."createdAt") OR OLD."state"='FINISHED' OR NEW."version"<>OLD."version"+1 OR NEW."turnIndex"<OLD."turnIndex" OR NEW."turnIndex">OLD."turnIndex"+1 THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF; RETURN NEW; END IF;
  SELECT * INTO a FROM public."Admission" WHERE "id"=g."admissionId" AND "firebaseIdentityId"=g."firebaseIdentityId";
  IF g."gameFormat"<>'FIREBASE_PINNED' OR a."state"<>'HELD' OR NEW."version"<>1 OR NEW."state"<>'BOARD' OR NEW."turnIndex"<>0 OR NEW."activeRoundId" IS NOT NULL OR NEW."setupHash"<>public.int6_enta_hash(NEW."setup") OR NOT EXISTS(SELECT 1 FROM public."EntaExecutionPin" execution WHERE execution."gameId"=g."id" AND execution."clientBinding"->'setup'=NEW."setup" AND public.int9_valid_request(execution."clientBinding")) OR NOT EXISTS(SELECT 1 FROM public."GameCompetitivePin" proof WHERE proof."gameId"=g."id" AND proof."firebaseIdentityId"=g."firebaseIdentityId" AND proof."admissionId"=a."id" AND proof."requestVersion"=5) OR cardinality(NEW."teamOrder")<>(SELECT count(*) FROM public."Team" WHERE "gameId"=g."id") OR (SELECT count(DISTINCT id) FROM unnest(NEW."teamOrder") id)<>cardinality(NEW."teamOrder") THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF; RETURN NEW;
 END IF;

 SELECT * INTO g FROM public."Game" WHERE "id"=(CASE WHEN TG_OP='DELETE' THEN OLD."gameId" ELSE NEW."gameId" END);
 IF g."executionFormat"<>'TIER_BOARD' THEN
 IF TG_OP='DELETE' THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 IF TG_OP='UPDATE' THEN IF (NEW."gameId",NEW."setup",NEW."setupHash",NEW."teamOrder",NEW."createdAt") IS DISTINCT FROM (OLD."gameId",OLD."setup",OLD."setupHash",OLD."teamOrder",OLD."createdAt") OR OLD."state"='FINISHED' OR NEW."version"<>OLD."version"+1 OR NEW."turnIndex"<OLD."turnIndex" OR NEW."turnIndex">OLD."turnIndex"+1 THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF; RETURN NEW; END IF;
 SELECT * INTO a FROM public."Admission" WHERE "id"=g."admissionId" AND "firebaseIdentityId"=g."firebaseIdentityId";
 IF a."state" IS DISTINCT FROM 'HELD' OR a."requestVersion"<>4 OR NEW."version"<>1 OR NEW."state"<>'BOARD' OR NEW."turnIndex"<>0 OR NEW."setupHash"<>public.int6_enta_hash(NEW."setup") OR NOT EXISTS(SELECT 1 FROM public."EntaExecutionPin" p WHERE p."gameId"=g."id" AND p."clientBinding"->'setup'=NEW."setup" AND public.int8_valid_request(p."clientBinding")) OR cardinality(NEW."teamOrder")<>(SELECT count(*) FROM public."Team" WHERE "gameId"=g."id") OR (SELECT count(DISTINCT id) FROM unnest(NEW."teamOrder") id)<>cardinality(NEW."teamOrder") THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 FOR i IN 1..cardinality(NEW."teamOrder") LOOP IF (SELECT "name" FROM public."Team" WHERE "gameId"=g."id" AND "id"=NEW."teamOrder"[i]) IS DISTINCT FROM NEW."setup"->'teams'->(i-1)->>'name' OR (SELECT jsonb_agg("name" ORDER BY "id") FROM public."Player" WHERE "teamId"=NEW."teamOrder"[i]) IS DISTINCT FROM NEW."setup"->'teams'->(i-1)->'players' THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF; END LOOP; RETURN NEW; END IF;

 IF TG_OP='DELETE' THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW."gameId",NEW."setup",NEW."setupHash",NEW."teamOrder",NEW."createdAt") IS DISTINCT FROM (OLD."gameId",OLD."setup",OLD."setupHash",OLD."teamOrder",OLD."createdAt") OR OLD."state"='FINISHED' OR NEW."version"<>OLD."version"+1 OR NEW."turnIndex"<OLD."turnIndex" OR NEW."turnIndex">OLD."turnIndex"+1 THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO g FROM public."Game" WHERE "id"=NEW."gameId";
 SELECT * INTO a FROM public."Admission" WHERE "id"=g."admissionId" AND "firebaseIdentityId"=g."firebaseIdentityId";
 IF g."gameFormat"<>'FIREBASE_PINNED' OR g."mode" NOT IN ('CLASSIC','KIDS') OR a."mode" IS DISTINCT FROM g."mode" OR a."state"<>'HELD' OR a."requestVersion" NOT IN (2,3) OR NEW."version"<>1 OR NEW."state"<>'BOARD' OR NEW."turnIndex"<>0 OR NOT (CASE WHEN a."requestVersion"=2 THEN g."mode"='CLASSIC' AND public.int6_enta_valid_setup(NEW."setup") ELSE public.int7_enta_valid_setup(NEW."setup",g."mode") END) OR NEW."setupHash"<>public.int6_enta_hash(NEW."setup") THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 IF cardinality(NEW."teamOrder")<>(SELECT count(*) FROM public."Team" WHERE "gameId"=g."id") OR (SELECT count(DISTINCT id) FROM unnest(NEW."teamOrder") id)<>cardinality(NEW."teamOrder") OR EXISTS(SELECT 1 FROM unnest(NEW."teamOrder") id WHERE NOT EXISTS(SELECT 1 FROM public."Team" t WHERE t."gameId"=g."id" AND t."id"=id)) THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 FOR i IN 1..cardinality(NEW."teamOrder") LOOP
  IF (SELECT "name" FROM public."Team" WHERE "gameId"=g."id" AND "id"=NEW."teamOrder"[i]) IS DISTINCT FROM NEW."setup"->'teams'->(i-1)->>'name' THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
  SELECT array_agg("name" ORDER BY "id") INTO names FROM public."Player" WHERE "teamId"=NEW."teamOrder"[i];
  IF to_jsonb(names) IS DISTINCT FROM NEW."setup"->'teams'->(i-1)->'players' THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 END LOOP; RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.int8_pin_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE game_id TEXT; g public."Game"%ROWTYPE; BEGIN
 -- INT-062 exact request5 branch; every predecessor branch below is retained.
 IF TG_TABLE_NAME='EntaExecutionPin' OR TG_TABLE_NAME='GameRound' THEN game_id:=(CASE WHEN TG_OP='DELETE' THEN OLD."gameId" ELSE NEW."gameId" END); ELSE SELECT "gameId" INTO game_id FROM public."GameRound" WHERE "id"=(CASE WHEN TG_OP='DELETE' THEN OLD."roundId" ELSE NEW."roundId" END); END IF;
 IF EXISTS(SELECT 1 FROM public."Game" parent JOIN public."Admission" admission_row ON admission_row."id"=parent."admissionId" AND admission_row."firebaseIdentityId"=parent."firebaseIdentityId" WHERE parent."id"=game_id AND parent."gameFormat"='FIREBASE_PINNED' AND admission_row."engine"='ENTA' AND admission_row."requestVersion"=5) THEN
  PERFORM 1 FROM public."Game" WHERE "id"=game_id FOR UPDATE;
  IF TG_OP='DELETE' THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
  IF TG_OP='UPDATE' THEN
   IF TG_TABLE_NAME='GameRound' THEN
    IF (NEW."id" COLLATE "C") IS DISTINCT FROM (OLD."id" COLLATE "C")
    OR (NEW."gameId" COLLATE "C") IS DISTINCT FROM (OLD."gameId" COLLATE "C")
    OR (NEW."gameQuestionId" COLLATE "C") IS DISTINCT FROM (OLD."gameQuestionId" COLLATE "C")
    OR (NEW."formatId" COLLATE "C") IS DISTINCT FROM (OLD."formatId" COLLATE "C")
    OR (NEW."questionRevisionId" COLLATE "C") IS DISTINCT FROM (OLD."questionRevisionId" COLLATE "C")
    OR (NEW."questionHash" COLLATE "C") IS DISTINCT FROM (OLD."questionHash" COLLATE "C")
    OR (NEW."categoryKey" COLLATE "C") IS DISTINCT FROM (OLD."categoryKey" COLLATE "C")
    OR (NEW."sourceNamespace" COLLATE "C") IS DISTINCT FROM (OLD."sourceNamespace" COLLATE "C")
    OR (NEW."sourceId" COLLATE "C") IS DISTINCT FROM (OLD."sourceId" COLLATE "C")
    OR (NEW."formatHash" COLLATE "C") IS DISTINCT FROM (OLD."formatHash" COLLATE "C")
    OR NEW."ordinal" IS DISTINCT FROM OLD."ordinal"
    OR (CASE
    WHEN NEW."pin" IS NULL THEN OLD."pin" IS NOT NULL AND OLD."pin" IS DISTINCT FROM 'null'::JSONB
    WHEN OLD."pin" IS NULL THEN NEW."pin" IS DISTINCT FROM 'null'::JSONB
    ELSE NEW."pin" IS DISTINCT FROM OLD."pin"
   END)
    OR OLD."state"->>'phase'='RESOLVED' THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
   ELSE
    IF TG_TABLE_NAME NOT IN ('EntaExecutionPin','GameRound') OR (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') OR TG_TABLE_NAME='GameRound' AND OLD."state"->>'phase'='RESOLVED' THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
   END IF;
   RETURN NEW;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public."Admission" admission_row JOIN public."Game" parent ON parent."admissionId"=admission_row."id" AND parent."firebaseIdentityId"=admission_row."firebaseIdentityId" WHERE parent."id"=game_id AND admission_row."state"='HELD') THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF; RETURN NEW;
 END IF;

 IF TG_TABLE_NAME='EntaExecutionPin' THEN game_id:=NEW."gameId"; IF TG_OP='UPDATE' THEN IF (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF; RETURN NEW; END IF;
 ELSIF TG_TABLE_NAME='GameRound' THEN game_id:=NEW."gameId"; IF TG_OP='UPDATE' THEN IF (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') OR OLD."state"->>'state'='RESOLVED' THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF; RETURN NEW; END IF;
 ELSE SELECT "gameId" INTO game_id FROM public."GameRound" WHERE "id"=NEW."roundId"; END IF;
 IF TG_OP<>'INSERT' THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF; SELECT * INTO g FROM public."Game" WHERE "id"=game_id FOR UPDATE;
 IF g."executionFormat"='TIER_BOARD' OR NOT EXISTS(SELECT 1 FROM public."Admission" WHERE "id"=g."admissionId" AND "firebaseIdentityId"=g."firebaseIdentityId" AND "state"='HELD' AND "requestVersion"=4) THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF; RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.int8_complete_start() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE g public."Game"%ROWTYPE; a public."Admission"%ROWTYPE; p public."EntaExecutionPin"%ROWTYPE; r public."GameRuntime"%ROWTYPE; count_rounds INTEGER; BEGIN
 -- INT-062 exact request5 branch; every predecessor branch below is retained.
 IF EXISTS(SELECT 1 FROM public."Game" parent JOIN public."Admission" admission_row ON admission_row."id"=parent."admissionId" AND admission_row."firebaseIdentityId"=parent."firebaseIdentityId" WHERE parent."id"=NEW."id" AND parent."gameFormat"='FIREBASE_PINNED' AND admission_row."engine"='ENTA' AND admission_row."requestVersion"=5) THEN PERFORM public.int9_complete_game(NEW."id"); RETURN NULL; END IF;

 SELECT * INTO g FROM public."Game" WHERE "id"=NEW."id"; IF g."gameFormat"<>'FIREBASE_PINNED' OR g."executionFormat"='TIER_BOARD' THEN RETURN NULL; END IF;
 SELECT * INTO a FROM public."Admission" WHERE "id"=g."admissionId" AND "firebaseIdentityId"=g."firebaseIdentityId"; SELECT * INTO p FROM public."EntaExecutionPin" WHERE "gameId"=g."id"; SELECT * INTO r FROM public."GameRuntime" WHERE "gameId"=g."id";
 SELECT count(*) INTO count_rounds FROM public."GameRound" WHERE "gameId"=g."id";
 IF a."state" IS DISTINCT FROM 'COMMITTED' OR a."requestVersion"<>4 OR a."engine"<>'ENTA' OR a."mode"<>g."mode" OR a."catalogReleaseId"<>g."catalogReleaseId" OR a."releaseRootHash"<>g."catalogReleaseRootHash" OR a."validationReceiptId"<>g."validationReceiptId" OR a."predecessorAdmissionId" IS NOT NULL OR p."gameId" IS NULL OR r."gameId" IS NULL OR p."executionFormat"<>g."executionFormat" OR NOT public.int8_valid_request(p."clientBinding") OR p."clientHash"<>public.int6_enta_hash(p."clientBinding") OR p."intentHash"<>public.int6_enta_hash(p."fullIntent") OR p."clientHash"<>a."requestHash" OR p."intentHash"<>a."intentHash" OR p."fullIntent"->'request'<>p."clientBinding" OR r."setup"<>p."clientBinding"->'setup' OR r."setupHash"<>public.int6_enta_hash(r."setup") OR count_rounds NOT BETWEEN 1 AND 36 OR count_rounds<>(p."fullIntent"->>'roundCount')::INTEGER OR count_rounds<>(SELECT count(*) FROM public."GameQuestion" WHERE "gameId"=g."id") OR (g."executionFormat"<>'MIXED_BOARD' AND (count_rounds NOT BETWEEN 1 AND 4 OR cardinality(r."teamOrder")<>2)) OR (SELECT count(*) FROM public."GameCategoryPin" WHERE "gameId"=g."id")<>(CASE WHEN g."executionFormat"='MIXED_BOARD' THEN 6 ELSE 1 END) THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 IF p."fullIntent"->>'pinsHash'<>public.int6_enta_hash((SELECT jsonb_agg("pin" ORDER BY "ordinal") FROM public."GameRound" WHERE "gameId"=g."id")) OR EXISTS(SELECT 1 FROM public."GameRound" rr WHERE rr."gameId"=g."id" AND rr."pin" IS DISTINCT FROM public.int8_prompt_pin(rr."formatId")) OR EXISTS(SELECT 1 FROM generate_series(0,count_rounds-1) n WHERE NOT EXISTS(SELECT 1 FROM public."GameRound" rr WHERE rr."gameId"=g."id" AND rr."ordinal"=n)) OR EXISTS(SELECT 1 FROM public."GameRound" rr WHERE rr."gameId"=g."id" AND (SELECT count(*) FROM public."RoundItemPin" i WHERE i."roundId"=rr."id")<>jsonb_array_length(rr."pin"->'items')) OR (SELECT count(DISTINCT ("sourceNamespace","sourceId")) FROM public."GameRound" WHERE "gameId"=g."id")<>count_rounds THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public."GameEvent" e WHERE e."gameId"=g."id" AND e."sequence"=1 AND e."type"='START' AND e."actorFirebaseIdentityId"=g."firebaseIdentityId" AND e."commandId"=a."requestKey" AND e."intentHash"=a."intentHash") OR NOT EXISTS(SELECT 1 FROM public."Reservation" rr WHERE rr."admissionId"=a."id" AND rr."state"='COMMITTED' AND EXISTS(SELECT 1 FROM public."WalletEntry" e WHERE e."reservationId"=rr."id" AND e."walletId"=a."walletId" AND e."effect"='RESERVE') AND EXISTS(SELECT 1 FROM public."WalletEntry" e WHERE e."reservationId"=rr."id" AND e."walletId"=a."walletId" AND e."effect"='COMMIT')) OR EXISTS(SELECT 1 FROM public."GameCategory" WHERE "gameId"=g."id") OR EXISTS(SELECT 1 FROM public."EntaRematchLink" WHERE "childGameId"=g."id") THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 IF g."executionFormat"<>'MIXED_BOARD' AND (SELECT count(*) FROM public."EntaSourceExposure" WHERE "gameId"=g."id")<>count_rounds THEN PERFORM public.int6_enta_error('INVALID_REQUEST'); END IF;
 PERFORM public.int8_assert_stored(g."id"); RETURN NULL;
END $$;
CREATE OR REPLACE FUNCTION public.int8_scope_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE scope public."RoundGrantScope"%ROWTYPE; gr public."RoundGrant"%ROWTYPE; r public."GameRound"%ROWTYPE; e public."RoundAuthorityEvent"%ROWTYPE; assignment public."RoundActorAssignment"%ROWTYPE; scope_key TEXT; BEGIN
 -- INT-062 exact request5 branch; every predecessor branch below is retained.
 IF EXISTS(SELECT 1 FROM public."GameCompetitivePin" proof WHERE proof."gameId"=NEW."gameId" AND proof."requestVersion"=5) THEN PERFORM public.int9_scope_fact_complete(TG_TABLE_NAME,to_jsonb(NEW)); RETURN NULL; END IF;

 IF TG_TABLE_NAME='RoundAuthorityEvent' THEN
  SELECT * INTO e FROM public."RoundAuthorityEvent" WHERE "id"=NEW."id";
  IF e."authorityKind"='GRANT' THEN SELECT * INTO gr FROM public."RoundGrant" WHERE "id"=e."authorityGrantId" AND "gameId"=e."gameId" AND "roundId"=e."roundId" AND "generation"=e."authorityGeneration" AND "assignmentId"=e."assignmentId"; SELECT * INTO scope FROM public."RoundGrantScope" WHERE "id"=gr."scopeId"; SELECT * INTO r FROM public."GameRound" WHERE "id"=e."roundId" AND "gameId"=e."gameId";
   IF gr."id" IS NULL OR gr."revoked" OR gr."expiresAt"<=e."at" OR gr."role"<>'ACTOR' OR scope."activeGrantId" IS DISTINCT FROM gr."id" OR scope."generation"<>gr."generation" OR r."state"->'assignment'->>'id' IS DISTINCT FROM gr."assignmentId" OR e."type" NOT IN ('CANVAS_APPEND','CANVAS_UNDO','CANVAS_REDO','CANVAS_CLEAR') THEN PERFORM public.int6_enta_error('GRANT_DENIED'); END IF;
  END IF; RETURN NULL;
 END IF;
 IF TG_TABLE_NAME='RoundGrantScope' THEN scope_key:=NEW."id"; ELSE scope_key:=NEW."scopeId"; END IF;
 FOR scope IN SELECT * FROM public."RoundGrantScope" WHERE "id"=scope_key LOOP
  IF scope."activeGrantId" IS NULL THEN CONTINUE; END IF;
  SELECT * INTO gr FROM public."RoundGrant" WHERE "id"=scope."activeGrantId" AND "scopeId"=scope."id" AND "gameId"=scope."gameId" AND "roundId"=scope."roundId"; SELECT * INTO r FROM public."GameRound" WHERE "id"=scope."roundId" AND "gameId"=scope."gameId";
  IF gr."id" IS NULL OR gr."revoked" OR (SELECT "status" FROM public."Game" WHERE "id"=scope."gameId")='FINISHED' OR gr."role"<>scope."role" OR gr."generation"<>scope."generation" OR gr."assignmentId" IS DISTINCT FROM scope."assignmentId" OR r."state"->>'state' NOT IN ('RUNNING','PAUSED') OR r."state"->'revealed'='true'::JSONB OR (SELECT "activeRoundId" FROM public."GameRuntime" WHERE "gameId"=scope."gameId") IS DISTINCT FROM r."id" THEN PERFORM public.int6_enta_error('GRANT_DENIED'); END IF;
  IF scope."role"='JUDGE' THEN IF scope."assignmentId" IS NOT NULL OR r."pin"->>'format' NOT IN ('LIST_ITEMS','ACTING_ITEMS') THEN PERFORM public.int6_enta_error('GRANT_DENIED'); END IF;
  ELSE SELECT * INTO assignment FROM public."RoundActorAssignment" WHERE "id"=scope."assignmentId" AND "gameId"=scope."gameId" AND "roundId"=scope."roundId";
   IF assignment."id" IS NULL OR r."state"->'assignment'->>'id' IS DISTINCT FROM assignment."id" OR (assignment."itemId" IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(r."state"->'consumed') x WHERE x->>'itemId'=assignment."itemId")) THEN PERFORM public.int6_enta_error('GRANT_DENIED'); END IF;
  END IF;
 END LOOP; RETURN NULL;
END $$;
CREATE OR REPLACE FUNCTION public.int5a_game_start_completeness() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $$
DECLARE g public."Game"%ROWTYPE; a public."Admission"%ROWTYPE; reservation_state TEXT; pin_count INTEGER; q_count INTEGER;
BEGIN
 -- INT-062 exact request5 branch; every predecessor branch below is retained.
 IF EXISTS(SELECT 1 FROM public."Game" parent JOIN public."Admission" admission_row ON admission_row."id"=parent."admissionId" AND admission_row."firebaseIdentityId"=parent."firebaseIdentityId" WHERE parent."id"=NEW."id" AND parent."gameFormat"='FIREBASE_PINNED' AND admission_row."engine"='ENTA' AND admission_row."requestVersion"=5) THEN PERFORM public.int9_complete_game(NEW."id"); RETURN NULL; END IF;

 SELECT * INTO g FROM public."Game" WHERE "id"=NEW."id";
 IF g."gameFormat"<>'FIREBASE_PINNED' THEN RETURN NULL; END IF;
 SELECT * INTO a FROM public."Admission" WHERE "id"=g."admissionId" AND "firebaseIdentityId"=g."firebaseIdentityId";
 IF NOT FOUND OR a."state"<>'COMMITTED' OR a."operation"<>'PAID_ENTA_CLASSIC' OR a."catalogReleaseId"<>g."catalogReleaseId" OR a."releaseRootHash"<>g."catalogReleaseRootHash" OR a."validationReceiptId"<>g."validationReceiptId" THEN
  RAISE EXCEPTION 'new game requires same-owner committed admission and exact pins';
 END IF;
 SELECT r."state" INTO reservation_state FROM public."Reservation" r WHERE r."admissionId"=a."id";
 IF reservation_state IS DISTINCT FROM 'COMMITTED' OR NOT EXISTS(SELECT 1 FROM public."WalletEntry" e JOIN public."Reservation" r ON r."id"=e."reservationId" WHERE r."admissionId"=a."id" AND e."effect"='RESERVE') OR NOT EXISTS(SELECT 1 FROM public."WalletEntry" e JOIN public."Reservation" r ON r."id"=e."reservationId" WHERE r."admissionId"=a."id" AND e."effect"='COMMIT') THEN
  RAISE EXCEPTION 'committed start requires matching reservation and ledger effects';
 END IF;
 IF EXISTS(SELECT 1 FROM public."GameCategory" WHERE "gameId"=g."id") THEN RAISE EXCEPTION 'pinned game cannot contain legacy category rows'; END IF;
 SELECT count(*) INTO pin_count FROM public."GameCategoryPin" WHERE "gameId"=g."id";
 IF pin_count=0 OR EXISTS(SELECT 1 FROM generate_series(0,pin_count-1) n WHERE NOT EXISTS(SELECT 1 FROM public."GameCategoryPin" p WHERE p."gameId"=g."id" AND p."ordinal"=n)) THEN RAISE EXCEPTION 'ordered category pins must be complete'; END IF;
 IF (SELECT count(*) FROM public."Team" WHERE "gameId"=g."id")<2 THEN RAISE EXCEPTION 'pinned game needs at least two teams'; END IF;
 SELECT count(*) INTO q_count FROM public."GameQuestion" WHERE "gameId"=g."id" AND "catalogReleaseId"=g."catalogReleaseId";
 IF q_count<>pin_count*6 THEN RAISE EXCEPTION 'CLASSIC game requires six pinned questions per category'; END IF;
 IF EXISTS (SELECT 1 FROM public."GameCategoryPin" p CROSS JOIN (VALUES ('200'),('400'),('600')) t(tier)
   WHERE p."gameId"=g."id" AND NOT EXISTS (SELECT 1 FROM public."CatalogReleaseAvailability" availability_row WHERE availability_row."catalogReleaseId"=g."catalogReleaseId" AND availability_row."categoryKey"=p."categoryKey" AND availability_row."engine"='ENTA' AND availability_row."mode"='CLASSIC' AND availability_row."modality"='classic' AND availability_row."tier"=t.tier)) THEN
  RAISE EXCEPTION 'release must seal all three supported CLASSIC availability tiers per category';
 END IF;
 IF EXISTS (
   SELECT 1 FROM public."GameCategoryPin" p CROSS JOIN (VALUES ('200',200),('400',400),('600',600)) t(tier,points)
   LEFT JOIN LATERAL (SELECT count(*) n, count(DISTINCT q."sourceQuestionId") sources,
     count(*) FILTER (WHERE EXISTS(SELECT 1 FROM public."QuestionRevisionMedia" m WHERE m."questionRevisionId"=q."id")) media_count
     FROM public."GameQuestion" gq JOIN public."CatalogReleaseQuestion" m ON m."catalogReleaseId"=gq."catalogReleaseId" AND m."questionRevisionId"=gq."questionRevisionId" AND m."categoryKey"=p."categoryKey"
     JOIN public."QuestionRevision" q ON q."id"=m."questionRevisionId"
     WHERE gq."gameId"=g."id" AND q."engine"='ENTA' AND q."mode"='CLASSIC' AND q."modality"='classic' AND q."tier"=t.tier AND q."points"=t.points) selected ON TRUE
   WHERE p."gameId"=g."id" GROUP BY p."categoryKey",t.tier HAVING max(selected.n)<>2 OR max(selected.sources)<>2 OR max(selected.media_count)<>0
 ) THEN RAISE EXCEPTION 'CLASSIC pins require exact two-per-tier unique-source text-only supply'; END IF;
 IF EXISTS (SELECT 1 FROM public."GameCategoryPin" p LEFT JOIN public."GameQuestion" gq ON gq."gameId"=g."id" AND gq."catalogReleaseId"=g."catalogReleaseId"
   LEFT JOIN public."CatalogReleaseQuestion" m ON m."catalogReleaseId"=gq."catalogReleaseId" AND m."questionRevisionId"=gq."questionRevisionId" AND m."categoryKey"=p."categoryKey"
   LEFT JOIN public."QuestionRevision" q ON q."id"=m."questionRevisionId"
   WHERE p."gameId"=g."id" GROUP BY p."categoryKey" HAVING count(DISTINCT q."sourceQuestionId")<>6) THEN
  RAISE EXCEPTION 'CLASSIC board cannot reuse source question identity across tiers';
 END IF;
 RETURN NULL;
END $$;

CREATE FUNCTION public.int9_head_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF TG_TABLE_NAME='CompetitiveRulingHead' THEN IF (to_jsonb(NEW)-ARRAY['effectId','hash','version','reversed']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['effectId','hash','version','reversed']) OR NEW."version" NOT IN (OLD."version",OLD."version"+1) THEN PERFORM public.int9_error('STALE_RULING_HEAD'); END IF;
 ELSIF TG_TABLE_NAME='CompetitiveRuntimeHead' THEN IF NEW."gameId"<>OLD."gameId" THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 ELSE PERFORM public.int9_error('RESULT_SUCCESSOR_AUTHORITY_UNAVAILABLE'); END IF; RETURN NEW;
END $$;
