-- NULL item scope still has one ordinal: no nullable UNIQUE escape hatch.
CREATE UNIQUE INDEX "CompetitiveAttempt_null_item_ordinal" ON public."CompetitiveAttempt"("roundId","phaseOrdinal","generation","teamId","ordinal") WHERE "itemId" IS NULL;
ALTER TABLE public."CompetitiveAttempt" ADD CONSTRAINT "CompetitiveAttempt_timely" CHECK("acceptedAt"<"deadline" AND "ordinal" BETWEEN 1 AND 2 AND "phaseOrdinal">0 AND "generation">0 AND "phase" IN ('MAIN','TRAP','STEAL','SHARED','TURN'));
ALTER TABLE public."CompetitiveRuntimeHead" ADD CONSTRAINT "CompetitiveRuntimeHead_complete_review" CHECK(("openItemReviewId" IS NULL)=("openItemReviewHash" IS NULL) AND NOT("boardReviewRoundId" IS NOT NULL AND "openItemReviewId" IS NOT NULL));
ALTER TABLE public."CompetitiveAllowance" ADD CONSTRAINT "CompetitiveAllowance_scope" CHECK(("scope"='MATCH' AND "roundId" IS NULL AND "scopeId"="gameId") OR ("scope"='PINNED_QUESTION' AND "roundId" IS NOT NULL AND "scopeId"="roundId"));
ALTER TABLE public."CompetitiveScorePosting" ADD CONSTRAINT "CompetitivePosting_actual_delta" CHECK("after"::BIGINT-"before"::BIGINT="delta"::BIGINT AND "scoreVersion">0);
ALTER TABLE public."CompetitiveAssignmentPlayer" ADD CONSTRAINT "CompetitiveAssignment_generation" CHECK("generation">0);
ALTER TABLE public."GameCompetitivePin" ADD CONSTRAINT "CompetitivePin_exact_profile" CHECK("requestVersion"=5 AND "rulesVersion"='enta-competitive-1');
ALTER TABLE public."EngineMatchResult" ADD CONSTRAINT "EngineMatchResult_default_original" CHECK("resultVersion"=1 AND "predecessorVersion" IS NULL AND "predecessorHash" IS NULL AND "bindingId" IS NULL AND "bindingHash" IS NULL);
-- Append-only local evidence tables and narrowly mutable heads only. No new
-- runtime SELECT/DML and no role membership or financial privilege change.
GRANT SELECT ON public."EntaCompetitiveRelease",public."EntaCompetitivePrompt",public."EntaCompetitiveHint",public."EntaCompetitiveGrapheme",public."GameCompetitivePin",public."CompetitiveRosterPlayer",public."CompetitiveRoundPin",public."CompetitiveAllowance",public."CompetitiveEffect",public."CompetitiveConsumption",public."CompetitiveAttempt",public."CompetitiveClassification",public."CompetitiveScorePosting",public."CompetitiveScoreRead",public."CompetitiveDependency",public."CompetitiveEffectAttempt",public."CompetitiveRulingHead",public."CompetitiveReversal",public."CompetitiveItemConsumption",public."CompetitiveAssignmentPlayer",public."CompetitiveTargetDisclosure",public."CompetitiveItemReview",public."CompetitiveItemResolution",public."CompetitiveRuntimeHead",public."CompetitiveAuditReport",public."EngineTournamentBindingSnapshot",public."EngineTournamentBindingParticipant",public."EngineMatchResult",public."EngineMatchResultHead",public."EngineMatchResultSignal" TO enta_finance_executor;
