CREATE FUNCTION public.int9_receipt_result(game_id TEXT,c JSONB,idempotent BOOLEAN,rejection TEXT,blocking JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE event_row public."RoundAuthorityEvent"%ROWTYPE; grant_row public."RoundGrant"%ROWTYPE; current_revision INTEGER; receipt JSONB; issuance JSONB; BEGIN
 SELECT "id","intentHash","sequence" INTO event_row."id",event_row."intentHash",event_row."sequence" FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "commandId"=c->>'commandId' AND "authorityKind"='HOST';
 IF event_row."id" IS NOT NULL THEN IF event_row."intentHash" IS DISTINCT FROM public.int6_enta_hash(c) THEN PERFORM public.int9_error('COMMAND_KEY_CONFLICT'); END IF; receipt:=jsonb_build_object('state','ACCEPTED','gameId',game_id,'commandId',c->'commandId','expectedVersion',c->'expectedVersion','hash',event_row."intentHash",'eventId',event_row."id",'revision',event_row."sequence"); END IF;
 SELECT "version" INTO current_revision FROM public."GameRuntime" WHERE "gameId"=game_id;
 IF receipt IS NULL AND c IS NOT NULL AND current_revision>(c->>'expectedVersion')::INTEGER THEN receipt:=jsonb_build_object('state','ABSENT','gameId',game_id,'commandId',c->'commandId','expectedVersion',c->'expectedVersion','hash',public.int6_enta_hash(c),'eventId',NULL,'revision',current_revision); END IF;
 IF c->>'type' IN ('CREATE_GRANT','ROTATE_GRANT','REVOKE_GRANT') AND event_row."id" IS NOT NULL THEN SELECT "expiresAt","generation","id","revoked","role","roundId","scopeId" INTO grant_row."expiresAt",grant_row."generation",grant_row."id",grant_row."revoked",grant_row."role",grant_row."roundId",grant_row."scopeId" FROM public."RoundGrant" WHERE "gameId"=game_id AND "id"=event_row."id"; IF grant_row."id" IS NULL THEN PERFORM public.int9_error('GRANT_DATA_UNAVAILABLE'); END IF; issuance:=jsonb_build_object('id',grant_row."id",'scopeId',grant_row."scopeId",'roundId',grant_row."roundId",'role',grant_row."role",'generation',grant_row."generation",'expiresAt',floor(extract(epoch FROM grant_row."expiresAt")*1000),'revoked',grant_row."revoked"); END IF;
 event_row:=NULL; grant_row:=NULL;
 RETURN jsonb_build_object('match',public.int9_main_dto(game_id,public.int9_now()),'idempotent',idempotent,'rejection',rejection,'blockingIds',COALESCE(blocking->'ids','[]'::JSONB),'blockingTotal',COALESCE((blocking->>'total')::INTEGER,0),'commandReceipt',receipt,'issuance',issuance);
END $$;
CREATE FUNCTION public.int9_validate_batch(b JSONB,h JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE key TEXT; x JSONB; n INTEGER; expected INTEGER; BEGIN
 IF jsonb_typeof(b) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(b) k WHERE NOT k=ANY(ARRAY['id','identityId','admissionId','beforeVersion','finalRevision','events','attempts','classifications','effects','postings','consumptions','assignmentFacts','disclosures','itemConsumptions','itemReviews','itemResolutions','results','roundChanges','teamChanges','grantScopes','grants','rulings','canvasChanges','runtimeChanges','headChanges','resultHead','gameChanges'])) OR EXISTS(SELECT 1 FROM unnest(ARRAY['id','identityId','admissionId','beforeVersion','finalRevision']) k WHERE NOT b ? k) OR b->'id' IS DISTINCT FROM h->'id' OR b->'beforeVersion' IS DISTINCT FROM h->'version' OR public.int5b_json_integer(b->'finalRevision',1,64946) IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM public."Game" g JOIN public."GameRuntime" rt ON rt."gameId"=g."id" WHERE g."id"=b->>'id' AND g."firebaseIdentityId"=b->>'identityId' AND g."admissionId"=b->>'admissionId' AND rt."version"=(h->>'version')::INTEGER) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'events' AND (jsonb_typeof(b->'events') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'events')>3) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'attempts' AND (jsonb_typeof(b->'attempts') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'attempts')>1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'classifications' AND (jsonb_typeof(b->'classifications') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'classifications')>512) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'effects' AND (jsonb_typeof(b->'effects') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'effects')>128) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'postings' AND (jsonb_typeof(b->'postings') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'postings')>512) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'consumptions' AND (jsonb_typeof(b->'consumptions') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'consumptions')>1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'assignmentFacts' AND (jsonb_typeof(b->'assignmentFacts') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'assignmentFacts')>1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'disclosures' AND (jsonb_typeof(b->'disclosures') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'disclosures')>1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'itemConsumptions' AND (jsonb_typeof(b->'itemConsumptions') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'itemConsumptions')>128) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'itemReviews' AND (jsonb_typeof(b->'itemReviews') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'itemReviews')>1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'itemResolutions' AND (jsonb_typeof(b->'itemResolutions') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'itemResolutions')>1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'results' AND (jsonb_typeof(b->'results') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'results')>1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'roundChanges' AND (jsonb_typeof(b->'roundChanges') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'roundChanges')>36) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'teamChanges' AND (jsonb_typeof(b->'teamChanges') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'teamChanges')>4) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'grantScopes' AND (jsonb_typeof(b->'grantScopes') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'grantScopes')>3) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'grants' AND (jsonb_typeof(b->'grants') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'grants')>3) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'rulings' AND (jsonb_typeof(b->'rulings') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'rulings')>128) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'canvasChanges' AND (jsonb_typeof(b->'canvasChanges') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'canvasChanges')>1) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'runtimeChanges' AND jsonb_typeof(b->'runtimeChanges') IS DISTINCT FROM 'object' THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'headChanges' AND jsonb_typeof(b->'headChanges') IS DISTINCT FROM 'object' THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'resultHead' AND jsonb_typeof(b->'resultHead') IS DISTINCT FROM 'object' THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'gameChanges' AND jsonb_typeof(b->'gameChanges') IS DISTINCT FROM 'object' THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'runtimeChanges' AND EXISTS(SELECT 1 FROM jsonb_object_keys(b->'runtimeChanges') k WHERE NOT k=ANY(ARRAY['activeRoundId','turnIndex','state','resultReason','unplayedCount','updatedAt'])) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'headChanges' AND EXISTS(SELECT 1 FROM jsonb_object_keys(b->'headChanges') k WHERE NOT k=ANY(ARRAY['latestEffectId','boardReviewRoundId','openItemReviewId','openItemReviewHash'])) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'resultHead' AND EXISTS(SELECT 1 FROM jsonb_object_keys(b->'resultHead') k WHERE NOT k=ANY(ARRAY['resultVersion','resultHash'])) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'gameChanges' AND EXISTS(SELECT 1 FROM jsonb_object_keys(b->'gameChanges') k WHERE NOT k=ANY(ARRAY['status','finishedAt','winnerTeamId','isTie'])) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF b ? 'headChanges' AND ((b->'headChanges' ? 'openItemReviewId') IS DISTINCT FROM (b->'headChanges' ? 'openItemReviewHash') OR b->'headChanges' ? 'openItemReviewId' AND (b->'headChanges'->'openItemReviewId'='null'::JSONB) IS DISTINCT FROM (b->'headChanges'->'openItemReviewHash'='null'::JSONB)) THEN PERFORM public.int9_error('STALE_REVIEW_HEAD'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'attempts') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','roundId','itemId','phase','phaseOrdinal','generation','teamId','playerId','ordinal','acceptedAt','deadline','eventId','pickedEventId','allowanceId','bonusEventId','bonusMultiplier','disclosureHead','eligiblePlayerIds','eligibilityHash']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'classifications') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','attemptId','eventId','correct','interim']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'effects') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','eventId','sequence','roundId','kind','aid','amountKind','reversible','barrier','reads','dependencies','postingIds','beforeClock','afterClock','originalAttemptIds','correctAttemptIds','bonusSnapshot','predecessorId','predecessorHash','reason','hash']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'postings') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','effectId','teamId','delta','before','after','scoreVersion','previousHead']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'consumptions') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','allowanceId','roundId','eventId','effectId','aid','teamId']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'assignmentFacts') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','roundId','teamId','playerIndex','itemId','generation','playerId','targetHash']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'disclosures') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','roundId','targetRevisionId','targetHash','playerId','assignmentId','assignmentGeneration','at','grantId','grantGeneration']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'itemConsumptions') x WHERE public.int6_enta_exact_keys(x,ARRAY['roundId','itemId','effectId','teamId']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'itemReviews') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','roundId','itemId','originalEffectId','originalEffectHash','reversalEffectId','predecessorRulingVersion','predecessorRulingHash','originalAttemptIds','consumptionEffectId','eventId','hash']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'itemResolutions') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','reviewId','reviewHash','effectId','eventId','rulingVersion','rulingHash','mode','reason']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'results') x WHERE public.int6_enta_exact_keys(x,ARRAY['payload','hash']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'rulings') x WHERE public.int6_enta_exact_keys(x,ARRAY['roundId','itemId','scopeId','originalEffectId','effectId','version','hash','reversed']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'grantScopes') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','roundId','role','assignmentId','generation','activeGrantId']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'grants') x WHERE public.int6_enta_exact_keys(x,ARRAY['id','scopeId','roundId','role','assignmentId','generation','tokenHash','expiresAt','revoked']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'canvasChanges') x WHERE public.int6_enta_exact_keys(x,ARRAY['roundId','revision','mutations','cumulativePoints','strokes','visibleIds','redoIds','receipts']) IS NOT TRUE) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 expected:=(h->>'version')::INTEGER; FOR x IN SELECT value FROM jsonb_array_elements(b->'events') ORDER BY (value->>'sequence')::INTEGER LOOP expected:=expected+1; IF public.int6_enta_exact_keys(x,ARRAY['id','commandId','hash','type','roundId','sequence','at','authority','pauseReason']) IS NOT TRUE OR x->'sequence' IS DISTINCT FROM to_jsonb(expected) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF; END LOOP; IF b->'finalRevision' IS DISTINCT FROM to_jsonb(expected) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'events') x JOIN public."RoundAuthorityEvent" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'events') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'events')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'attempts') x JOIN public."CompetitiveAttempt" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'attempts') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'attempts')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'classifications') x JOIN public."CompetitiveClassification" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'classifications') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'classifications')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'effects') x JOIN public."CompetitiveEffect" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'effects') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'effects')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'postings') x JOIN public."CompetitiveScorePosting" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'postings') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'postings')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'consumptions') x JOIN public."CompetitiveConsumption" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'consumptions') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'consumptions')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'assignmentFacts') x JOIN public."RoundActorAssignment" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'assignmentFacts') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'assignmentFacts')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'disclosures') x JOIN public."CompetitiveTargetDisclosure" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'disclosures') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'disclosures')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'itemReviews') x JOIN public."CompetitiveItemReview" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'itemReviews') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'itemReviews')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'itemResolutions') x JOIN public."CompetitiveItemResolution" saved ON saved."id"=x->>'id') OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'itemResolutions') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'itemResolutions')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(b->'roundChanges') LOOP IF public.int6_enta_exact_keys(x,ARRAY['id','fields']) IS NOT TRUE OR jsonb_typeof(x->'fields') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(x->'fields') k WHERE NOT k=ANY(ARRAY['phase','phaseOrdinal','generation','version','originalTeamId','currentTeamId','originalDeadline','deadline','overallDeadline','pause','publicRevealed','itemReveals','assignment','pickedPlayerId','pickedEventId','usedAidIds','doubleAttemptTeamId','bonus','revealedHintIds','graphemeHints','consumed','reason','turnAdvanced','resourceStop'])) OR NOT EXISTS(SELECT 1 FROM public."GameRound" r WHERE r."gameId"=b->>'id' AND r."id"=x->>'id') THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; END LOOP;
 IF (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(b->'roundChanges') x) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(b->'roundChanges')) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(b->'teamChanges') LOOP IF public.int6_enta_exact_keys(x,ARRAY['id','score']) IS NOT TRUE OR public.int5b_json_integer(x->'score',-2147483648,2147483647) IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM public."Team" t WHERE t."gameId"=b->>'id' AND t."id"=x->>'id') THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.int9_store_batch(s JSONB,old JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE x JSONB; e JSONB; r JSONB; t JSONB; changes JSONB; idx INTEGER; BEGIN
 PERFORM public.int9_validate_batch(s,old); PERFORM public.int9_capacity_batch(s,old);
 FOR e IN SELECT value FROM jsonb_array_elements(s->'events') LOOP
  INSERT INTO public."RoundAuthorityEvent"("id","gameId","ownerIdentityId","roundId","commandId","sequence","type","intentHash","authorityKind","authorityGrantId","authorityGeneration","assignmentId","systemOperation","pauseReason","at") SELECT e->>'id',s->>'id',s->>'identityId',e->>'roundId',e->>'commandId',(e->>'sequence')::INTEGER,e->>'type',e->>'hash',e->'authority'->>'kind',e->'authority'->>'grantId',(e->'authority'->>'generation')::INTEGER,e->'authority'->>'assignmentId',e->'authority'->>'operation',e->>'pauseReason',to_timestamp((e->>'at')::DOUBLE PRECISION/1000) WHERE NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" prior WHERE prior."id"=e->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'assignmentFacts') LOOP
  INSERT INTO public."RoundActorAssignment"("id","gameId","roundId","teamId","playerIndex","itemId","generation") VALUES(x->>'id',s->>'id',x->>'roundId',x->>'teamId',(x->>'playerIndex')::INTEGER,x->>'itemId',(x->>'generation')::INTEGER);
  INSERT INTO public."CompetitiveAssignmentPlayer"("assignmentId","gameId","roundId","teamId","playerId","generation","targetHash") VALUES(x->>'id',s->>'id',x->>'roundId',x->>'teamId',x->>'playerId',(x->>'generation')::INTEGER,x->>'targetHash');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'grantScopes') LOOP
  INSERT INTO public."RoundGrantScope"("id","gameId","roundId","role","assignmentId","generation","activeGrantId") VALUES(x->>'id',s->>'id',x->>'roundId',x->>'role',x->>'assignmentId',(x->>'generation')::INTEGER,x->>'activeGrantId') ON CONFLICT("id") DO UPDATE SET "generation"=EXCLUDED."generation","activeGrantId"=EXCLUDED."activeGrantId" WHERE "RoundGrantScope"."gameId"=s->>'id' AND "RoundGrantScope"."roundId"=EXCLUDED."roundId";
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'grants') LOOP
  INSERT INTO public."RoundGrant"("id","gameId","scopeId","roundId","role","assignmentId","generation","tokenHash","expiresAt","revoked") VALUES(x->>'id',s->>'id',x->>'scopeId',x->>'roundId',x->>'role',x->>'assignmentId',(x->>'generation')::INTEGER,x->>'tokenHash',to_timestamp((x->>'expiresAt')::DOUBLE PRECISION/1000),(x->>'revoked')::BOOLEAN) ON CONFLICT("id") DO UPDATE SET "revoked"=EXCLUDED."revoked" WHERE "RoundGrant"."gameId"=s->>'id';
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'disclosures') LOOP
  INSERT INTO public."CompetitiveTargetDisclosure"("id","gameId","roundId","targetRevisionId","targetHash","teamId","playerId","assignmentId","assignmentGeneration","grantId","grantGeneration","createdAt") SELECT x->>'id',s->>'id',x->>'roundId',x->>'targetRevisionId',x->>'targetHash',(SELECT "teamId" FROM public."CompetitiveRosterPlayer" WHERE "gameId"=s->>'id' AND "playerId"=x->>'playerId'),x->>'playerId',x->>'assignmentId',(x->>'assignmentGeneration')::INTEGER,x->>'grantId',(x->>'grantGeneration')::INTEGER,to_timestamp((x->>'at')::DOUBLE PRECISION/1000) WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveTargetDisclosure" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'attempts') LOOP
  INSERT INTO public."CompetitiveAttempt"("id","gameId","roundId","itemId","teamId","playerId","phase","phaseOrdinal","generation","ordinal","acceptedAt","deadline","eventId","pickedEventId","allowanceId","bonusEventId","disclosureHeadId","payload","eligibilityHash") SELECT x->>'id',s->>'id',x->>'roundId',x->>'itemId',x->>'teamId',x->>'playerId',x->>'phase',(x->>'phaseOrdinal')::INTEGER,(x->>'generation')::INTEGER,(x->>'ordinal')::INTEGER,to_timestamp((x->>'acceptedAt')::DOUBLE PRECISION/1000),to_timestamp((x->>'deadline')::DOUBLE PRECISION/1000),x->>'eventId',x->>'pickedEventId',x->>'allowanceId',x->>'bonusEventId',x->>'disclosureHead',x,x->>'eligibilityHash' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'classifications') LOOP
  INSERT INTO public."CompetitiveClassification"("id","gameId","attemptId","eventId","correct","interim") SELECT x->>'id',s->>'id',x->>'attemptId',x->>'eventId',(x->>'correct')::BOOLEAN,(x->>'interim')::BOOLEAN WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'effects') LOOP
  INSERT INTO public."CompetitiveEffect"("id","gameId","roundId","eventId","sequence","kind","amountKind","reversible","barrier","predecessorId","predecessorHash","hash","payload") SELECT x->>'id',s->>'id',x->>'roundId',x->>'eventId',(x->>'sequence')::INTEGER,x->>'kind',x->>'amountKind',(x->>'reversible')::BOOLEAN,(x->>'barrier')::BOOLEAN,x->>'predecessorId',x->>'predecessorHash',x->>'hash',x WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'consumptions') LOOP
  INSERT INTO public."CompetitiveConsumption"("id","gameId","roundId","teamId","allowanceId","eventId","effectId","aid") SELECT x->>'id',s->>'id',x->>'roundId',x->>'teamId',x->>'allowanceId',x->>'eventId',x->>'effectId',x->>'aid' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveConsumption" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'postings') LOOP
  INSERT INTO public."CompetitiveScorePosting"("id","gameId","effectId","teamId","delta","before","after","scoreVersion","previousHeadId") SELECT x->>'id',s->>'id',x->>'effectId',x->>'teamId',(x->>'delta')::INTEGER,(x->>'before')::INTEGER,(x->>'after')::INTEGER,(x->>'scoreVersion')::INTEGER,x->>'previousHead' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveScorePosting" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(s->'effects') LOOP
 FOR x IN SELECT value FROM jsonb_array_elements(e->'reads') LOOP
  idx:=COALESCE((SELECT ord::INTEGER-1 FROM jsonb_array_elements(e->'reads') WITH ORDINALITY reads(value,ord) WHERE value=x ORDER BY ord LIMIT 1),0);
  INSERT INTO public."CompetitiveScoreRead"("gameId","effectId","ordinal","teamId","scoreVersion","value","sourceEffectId","kind") SELECT s->>'id',e->>'id',idx,x->>'teamId',(x->>'scoreVersion')::INTEGER,(x->>'value')::INTEGER,x->>'sourceEffectId',x->>'kind' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveScoreRead" prior WHERE prior."effectId" IS NOT DISTINCT FROM e->>'id' AND prior."ordinal" IS NOT DISTINCT FROM idx);
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(e->'dependencies') LOOP
  INSERT INTO public."CompetitiveDependency"("gameId","effectId","sourceEffectId") SELECT s->>'id',e->>'id',x#>>'{}' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveDependency" prior WHERE prior."effectId" IS NOT DISTINCT FROM e->>'id' AND prior."sourceEffectId" IS NOT DISTINCT FROM x#>>'{}');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(e->'originalAttemptIds') LOOP
  INSERT INTO public."CompetitiveEffectAttempt"("gameId","effectId","roundId","attemptId","correct","bonusMultiplier","bonusEventId") SELECT s->>'id',e->>'id',e->>'roundId',x#>>'{}',e->'correctAttemptIds' @> jsonb_build_array(x),COALESCE((SELECT (b->>'multiplier')::INTEGER FROM jsonb_array_elements(e->'bonusSnapshot') b WHERE b->'attemptId'=x),1),(SELECT b->>'sourceEventId' FROM jsonb_array_elements(e->'bonusSnapshot') b WHERE b->'attemptId'=x) WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveEffectAttempt" prior WHERE prior."effectId" IS NOT DISTINCT FROM e->>'id' AND prior."attemptId" IS NOT DISTINCT FROM x#>>'{}');
 END LOOP;
  IF e->>'kind'='REVERSAL' THEN INSERT INTO public."CompetitiveReversal"("originalEffectId","gameId","originalHash","reversalEffectId") SELECT e->>'predecessorId',s->>'id',e->>'predecessorHash',e->>'id' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveReversal" prior WHERE prior."originalEffectId"=e->>'predecessorId'); END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'itemConsumptions') LOOP
  IF EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" prior WHERE prior."roundId"=x->>'roundId' AND prior."itemId"=x->>'itemId') THEN PERFORM public.int9_error('ITEM_RESOLVED'); END IF;
  INSERT INTO public."CompetitiveItemConsumption"("gameId","roundId","itemId","effectId","teamId") VALUES(s->>'id',x->>'roundId',x->>'itemId',x->>'effectId',x->>'teamId');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'itemReviews') LOOP
  INSERT INTO public."CompetitiveItemReview"("id","gameId","roundId","itemId","originalEffectId","originalHash","reversalEffectId","consumptionEffectId","eventId","predecessorVersion","predecessorHash","hash","payload") SELECT x->>'id',s->>'id',x->>'roundId',x->>'itemId',x->>'originalEffectId',x->>'originalEffectHash',x->>'reversalEffectId',x->>'consumptionEffectId',x->>'eventId',(x->>'predecessorRulingVersion')::INTEGER,x->>'predecessorRulingHash',x->>'hash',x WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveItemReview" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'itemResolutions') LOOP
  INSERT INTO public."CompetitiveItemResolution"("id","gameId","reviewId","reviewHash","effectId","eventId","rulingVersion","rulingHash","mode","reason") SELECT x->>'id',s->>'id',x->>'reviewId',x->>'reviewHash',x->>'effectId',x->>'eventId',(x->>'rulingVersion')::INTEGER,x->>'rulingHash',x->>'mode',x->>'reason' WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveItemResolution" prior WHERE prior."id" IS NOT DISTINCT FROM x->>'id');
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'rulings') LOOP
  INSERT INTO public."CompetitiveRulingHead"("gameId","scopeId","roundId","itemId","originalEffectId","effectId","hash","version","reversed") VALUES(s->>'id',x->>'scopeId',x->>'roundId',x->>'itemId',x->>'originalEffectId',x->>'effectId',x->>'hash',(x->>'version')::INTEGER,(x->>'reversed')::BOOLEAN) ON CONFLICT("gameId","scopeId") DO UPDATE SET "effectId"=EXCLUDED."effectId","hash"=EXCLUDED."hash","version"=EXCLUDED."version","reversed"=EXCLUDED."reversed" WHERE "CompetitiveRulingHead"."roundId"=EXCLUDED."roundId" AND "CompetitiveRulingHead"."originalEffectId"=EXCLUDED."originalEffectId";
 END LOOP;
 IF s ? 'headChanges' THEN changes:=s->'headChanges'; UPDATE public."CompetitiveRuntimeHead" SET "latestEffectId"=(CASE WHEN changes ? 'latestEffectId' THEN changes->>'latestEffectId' ELSE "latestEffectId" END),"boardReviewRoundId"=(CASE WHEN changes ? 'boardReviewRoundId' THEN changes->>'boardReviewRoundId' ELSE "boardReviewRoundId" END),"openItemReviewId"=(CASE WHEN changes ? 'openItemReviewId' THEN changes->>'openItemReviewId' ELSE "openItemReviewId" END),"openItemReviewHash"=(CASE WHEN changes ? 'openItemReviewHash' THEN changes->>'openItemReviewHash' ELSE "openItemReviewHash" END) WHERE "gameId"=s->>'id'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(s->'roundChanges') LOOP
  UPDATE public."GameRound" SET "state"="state"||(r->'fields') WHERE "gameId"=s->>'id' AND "id"=r->>'id';
  UPDATE public."GameQuestion" q SET "isOpened"=physical."state"->>'phase'<>'READY',"isCorrect"=(CASE WHEN physical."state"->>'phase'='RESOLVED' THEN EXISTS(SELECT 1 FROM public."CompetitiveRulingHead" head JOIN public."CompetitiveEffect" effect ON effect."gameId"=head."gameId" AND effect."id"=head."effectId" WHERE head."gameId"=s->>'id' AND head."roundId"=r->>'id' AND NOT head."reversed" AND effect."payload"->'correctAttemptIds'<>'[]'::JSONB) ELSE NULL END) FROM public."GameRound" physical WHERE physical."gameId"=s->>'id' AND physical."id"=r->>'id' AND q."gameId"=physical."gameId" AND q."id"=physical."gameQuestionId";
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'canvasChanges') LOOP
  IF NOT EXISTS(SELECT 1 FROM public."GameRound" round_row WHERE round_row."gameId"=s->>'id' AND round_row."id"=x->>'roundId' AND round_row."pin"->>'format'='DRAWING_TARGET') THEN PERFORM public.int9_error('CANVAS_DENIED'); END IF;
  INSERT INTO public."DrawingCanvasState"("roundId","revision","state") VALUES(x->>'roundId',(x->>'revision')::INTEGER,x) ON CONFLICT("roundId") DO UPDATE SET "revision"=EXCLUDED."revision","state"=EXCLUDED."state" WHERE EXISTS(SELECT 1 FROM public."GameRound" round_row WHERE round_row."gameId"=s->>'id' AND round_row."id"="DrawingCanvasState"."roundId");
 END LOOP;
 FOR t IN SELECT value FROM jsonb_array_elements(s->'teamChanges') LOOP UPDATE public."Team" SET "score"=(t->>'score')::INTEGER WHERE "gameId"=s->>'id' AND "id"=t->>'id' AND "score" IS DISTINCT FROM (t->>'score')::INTEGER; END LOOP;
 UPDATE public."EntaExecutionPin" SET "state"=jsonb_build_object('contextVersion',1,'gameId',s->'id','version',s->'finalRevision') WHERE "gameId"=s->>'id';
 -- One statement per event revision preserves existing GameEvent sequence
 -- guard. SYSTEM/GRANT attribution exists only in RoundAuthorityEvent; never
 -- masquerades as a Firebase host to satisfy a legacy event column.
 FOR e IN SELECT value FROM jsonb_array_elements(s->'events') WITH ORDINALITY events(value,ord) WHERE (value->>'sequence')::INTEGER>(old->>'version')::INTEGER ORDER BY (value->>'sequence')::INTEGER LOOP
  changes:=s->'runtimeChanges';
  UPDATE public."GameRuntime" SET "version"=(e->>'sequence')::INTEGER,"activeRoundId"=(CASE WHEN changes ? 'activeRoundId' THEN changes->>'activeRoundId' ELSE "activeRoundId" END),"turnIndex"=(CASE WHEN changes ? 'turnIndex' THEN (changes->>'turnIndex')::INTEGER ELSE "turnIndex" END),"state"=(CASE WHEN changes ? 'state' THEN changes->>'state' ELSE "state" END),"resultReason"=(CASE WHEN changes ? 'resultReason' THEN changes->>'resultReason' ELSE "resultReason" END),"unplayedCount"=(CASE WHEN changes ? 'unplayedCount' THEN (SELECT count(*) FROM public."GameRound" physical WHERE physical."gameId"=s->>'id' AND physical."state"->>'phase'<>'RESOLVED') ELSE "unplayedCount" END),"updatedAt"=to_timestamp((e->>'at')::DOUBLE PRECISION/1000) WHERE "gameId"=s->>'id' AND "version"=(e->>'sequence')::INTEGER-1; IF NOT FOUND THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
  IF e->'authority'->>'kind'='HOST' THEN INSERT INTO public."GameEvent"("gameId","commandId","sequence","actorFirebaseIdentityId","type","intentHash") VALUES(s->>'id',e->>'commandId',(e->>'sequence')::INTEGER,s->>'identityId',e->>'type',e->>'hash'); END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(s->'results') LOOP
  INSERT INTO public."EngineMatchResult"("gameId","resultVersion","resultHash","ownerIdentityId","admissionId","terminalRevision","terminalEventId","authorityEventId","predecessorVersion","predecessorHash","bindingId","bindingHash","payload") SELECT s->>'id',(x->'payload'->>'resultVersion')::INTEGER,x->>'hash',s->>'identityId',s->>'admissionId',(x->'payload'->'terminal'->>'revision')::INTEGER,x->'payload'->'terminal'->>'eventId',x->'payload'->'authority'->>'eventId',(x->'payload'->'predecessor'->>'version')::INTEGER,x->'payload'->'predecessor'->>'hash',x->'payload'->'tournamentBinding'->>'id',x->'payload'->'tournamentBinding'->>'hash',x->'payload' WHERE NOT EXISTS(SELECT 1 FROM public."EngineMatchResult" prior WHERE prior."gameId" IS NOT DISTINCT FROM s->>'id' AND prior."resultVersion" IS NOT DISTINCT FROM (x->'payload'->>'resultVersion')::INTEGER);
 END LOOP;
 IF s ? 'resultHead' THEN x:=s->'resultHead'; INSERT INTO public."EngineMatchResultHead"("gameId","resultVersion","resultHash") VALUES(s->>'id',(x->>'resultVersion')::INTEGER,x->>'resultHash') ON CONFLICT("gameId") DO NOTHING; IF NOT EXISTS(SELECT 1 FROM public."EngineMatchResultHead" current_head WHERE current_head."gameId"=s->>'id' AND current_head."resultVersion"=(x->>'resultVersion')::INTEGER AND current_head."resultHash"=x->>'resultHash') THEN PERFORM public.int9_error('RESULT_INTEGRITY_FAILURE'); END IF; END IF;
 IF s ? 'gameChanges' THEN changes:=s->'gameChanges'; IF old->'finished'<>'false'::JSONB OR changes->>'status'<>'FINISHED' THEN PERFORM public.int9_error('RESULT_INTEGRITY_FAILURE'); END IF; UPDATE public."Game" SET "status"='FINISHED',"finishedAt"=to_timestamp((changes->>'finishedAt')::DOUBLE PRECISION/1000) AT TIME ZONE 'UTC',"winnerTeamId"=changes->>'winnerTeamId',"isTie"=(changes->>'isTie')::BOOLEAN WHERE "id"=s->>'id'; END IF;
END $$;
CREATE FUNCTION public.int9_capacity_batch(s JSONB,old JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE e JSONB; x JSONB; r JSONB; prior JSONB; claim RECORD; lane TEXT; used JSONB; reserved JSONB; usages JSONB; reservations JSONB; event_id TEXT; effects INTEGER; heads INTEGER; classifications INTEGER; consumptions INTEGER; postings INTEGER; gid TEXT:=s->>'id'; BEGIN
 -- All input facts below were independently reduced by SQL in its locked context.
 FOR x IN SELECT a FROM jsonb_array_elements(s->'attempts') a WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" p WHERE p."gameId"=gid AND p."id"=a->>'id') LOOP PERFORM public.int9_capacity_claim(gid,x->>'roundId','ATTEMPT',x->>'id'); END LOOP;
 FOR x IN SELECT a FROM jsonb_array_elements(s->'classifications') a WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" p WHERE p."gameId"=gid AND p."id"=a->>'id') LOOP PERFORM public.int9_capacity_dispose(gid,(SELECT "roundId" FROM public."CompetitiveCapacityClaim" WHERE "gameId"=gid AND "sourceKind"='ATTEMPT' AND "sourceId"=x->>'attemptId'),'ATTEMPT',x->>'attemptId',x->>'eventId','CONSUME'); END LOOP;
 FOR x IN SELECT a FROM jsonb_array_elements(s->'itemReviews') a WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveItemReview" p WHERE p."gameId"=gid AND p."id"=a->>'id') LOOP PERFORM public.int9_capacity_claim(gid,x->>'roundId','REVIEW',x->>'id'); END LOOP;
 IF s->'headChanges' ? 'boardReviewRoundId' AND s->'headChanges'->'boardReviewRoundId'<>'null'::JSONB AND old->'correctionReview'='null'::JSONB THEN SELECT a INTO x FROM jsonb_array_elements(s->'effects') a WHERE a->>'kind'='REVERSAL' AND a->'roundId'=s->'headChanges'->'boardReviewRoundId' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" p WHERE p."gameId"=gid AND p."id"=a->>'id'); IF x IS NULL THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF; PERFORM public.int9_capacity_claim(gid,x->>'roundId','BOARD_REVIEW',x->>'id'); END IF;
 -- Genuine consumption across the complete batch precedes every release.
 FOR claim IN SELECT c.* FROM public."CompetitiveCapacityClaim" c WHERE c."gameId"=gid AND c."sourceKind" IN ('ITEM','ROUND') AND NOT EXISTS(SELECT 1 FROM public."CompetitiveCapacityDisposition" d WHERE d."claimId"=c."id") ORDER BY c."id" COLLATE "C" LOOP
  event_id:=NULL;
  IF claim."sourceKind"='ITEM' THEN SELECT effect->>'eventId' INTO event_id FROM jsonb_array_elements(s->'itemConsumptions') consumed JOIN jsonb_array_elements(s->'effects') effect ON effect->'id'=consumed->'effectId' WHERE consumed->>'roundId'=claim."roundId" AND consumed->>'itemId'=claim."sourceId" AND effect->>'kind' IN ('RULING','NO_SCORE') AND effect->'predecessorId'='null'::JSONB AND NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" saved WHERE saved."gameId"=gid AND saved."id"=effect->>'id');
  ELSE SELECT effect->>'eventId' INTO event_id FROM jsonb_array_elements(s->'rulings') head JOIN jsonb_array_elements(s->'effects') effect ON effect->'id'=head->'originalEffectId' WHERE head->>'roundId'=claim."roundId" AND head->'itemId'='null'::JSONB AND effect->>'kind' IN ('RULING','NO_SCORE') AND effect->'predecessorId'='null'::JSONB AND NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" saved WHERE saved."gameId"=gid AND saved."id"=effect->>'id'); END IF;
  IF event_id IS NOT NULL THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",claim."sourceKind",claim."sourceId",event_id,'CONSUME'); END IF;
 END LOOP;
 FOR e IN SELECT a FROM jsonb_array_elements(s->'events') a WHERE NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" p WHERE p."gameId"=gid AND p."id"=a->>'id') ORDER BY (a->>'sequence')::INTEGER LOOP
  event_id:=e->>'id';
  FOR r IN SELECT jsonb_build_object('id',physical."id",'phase',CASE WHEN change->'fields' ? 'phase' THEN change->'fields'->'phase' ELSE physical."state"->'phase' END,'pause',CASE WHEN change->'fields' ? 'pause' THEN change->'fields'->'pause' ELSE CASE WHEN physical."state"->'pause'='null'::JSONB THEN 'null'::JSONB ELSE jsonb_build_object('eventId',physical."state"->'pause'->'eventId') END END,'resourceStop',CASE WHEN change->'fields' ? 'resourceStop' THEN change->'fields'->'resourceStop' ELSE physical."state"->'resourceStop' END) FROM (SELECT x->>'id' id FROM jsonb_array_elements(s->'roundChanges') x UNION SELECT e->>'roundId' FROM jsonb_array_elements(s->'events') e WHERE e->>'roundId' IS NOT NULL) affected JOIN public."GameRound" physical ON physical."gameId"=gid AND physical."id"=affected.id LEFT JOIN LATERAL (SELECT x change FROM jsonb_array_elements(s->'roundChanges') x WHERE x->>'id'=physical."id") patch ON TRUE LOOP
   prior:=public.int9_round(old,r->>'id'); IF r->'pause'->>'eventId'=event_id AND prior->'pause'->>'eventId' IS DISTINCT FROM event_id THEN PERFORM public.int9_capacity_claim(gid,r->>'id','PAUSE',event_id); END IF;
   FOR claim IN SELECT c.* FROM public."CompetitiveCapacityClaim" c WHERE c."gameId"=gid AND c."roundId"=r->>'id' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveCapacityDisposition" d WHERE d."claimId"=c."id") ORDER BY c."id" COLLATE "C" LOOP
    IF claim."sourceKind" IN ('ITEM','ROUND') AND r->>'phase'='RESOLVED' AND prior->>'phase'<>'RESOLVED' AND e->>'roundId'=r->>'id' AND public.int9_closing_batch_event(CASE WHEN jsonb_typeof(s)='object' THEN
  (CASE WHEN s ? 'events'
    THEN jsonb_build_object('events',s->'events')
    ELSE '{}'::JSONB END)
  ||
  (CASE WHEN s ? 'effects'
    THEN jsonb_build_object('effects',s->'effects')
    ELSE '{}'::JSONB END)
ELSE s END,r->>'id',event_id) THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",claim."sourceKind",claim."sourceId",event_id,'RELEASE');
    ELSIF claim."sourceKind"='PAUSE' AND prior->'pause'->>'eventId'=claim."sourceId" AND r->'pause'='null'::JSONB AND e->>'roundId'=r->>'id' AND e->>'type' IN ('PHONE_ENDED','RESUME_ROUND','END_ASSISTANCE') THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",'PAUSE',claim."sourceId",event_id,'CONSUME');
    ELSIF claim."sourceKind"='BOARD_REVIEW' AND old->'correctionReview'=r->'id' AND s->'headChanges'->'boardReviewRoundId'='null'::JSONB AND e->>'type'='CORRECT_RULING' AND e->'roundId'=r->'id' THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",'BOARD_REVIEW',claim."sourceId",event_id,'CONSUME');
    ELSIF claim."sourceKind"='REVIEW' AND EXISTS(SELECT 1 FROM jsonb_array_elements(s->'itemResolutions') resolution WHERE resolution->>'reviewId'=claim."sourceId" AND resolution->>'eventId'=event_id) THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",'REVIEW',claim."sourceId",event_id,'CONSUME'); END IF;
   END LOOP;
  END LOOP;
  FOR x IN SELECT g FROM jsonb_array_elements(s->'grants') g WHERE g->>'id'=event_id AND g->'revoked'='false'::JSONB LOOP PERFORM public.int9_capacity_claim(gid,x->>'roundId','GRANT',x->>'id'); END LOOP;
  FOR claim IN SELECT c.* FROM public."CompetitiveCapacityClaim" c WHERE c."gameId"=gid AND c."sourceKind"='GRANT' AND c."roundId"=e->>'roundId' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveCapacityDisposition" d WHERE d."claimId"=c."id") LOOP IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'grants') g WHERE g->>'id'=claim."sourceId" AND g->'revoked'='true'::JSONB) THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",'GRANT',claim."sourceId",event_id,CASE WHEN e->>'type'='REVOKE_GRANT' THEN 'CONSUME' ELSE 'RELEASE' END); END IF; END LOOP;
  IF e->>'type'='FINISH' THEN PERFORM public.int9_capacity_dispose(gid,NULL,'FINISH',gid,event_id,'CONSUME'); END IF;
  SELECT count(*),count(*) FILTER(WHERE effect->>'kind' IN ('RULING','NO_SCORE','REVERSAL','CORRECTION')) INTO effects,heads FROM jsonb_array_elements(s->'effects') effect WHERE effect->>'eventId'=event_id;
  SELECT count(*) INTO classifications FROM jsonb_array_elements(s->'classifications') c WHERE c->>'eventId'=event_id;
  SELECT count(*) INTO postings FROM jsonb_array_elements(s->'postings') p WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(s->'effects') effect WHERE effect->'id'=p->'effectId' AND effect->>'eventId'=event_id);
  SELECT count(*) INTO consumptions FROM jsonb_array_elements(s->'itemConsumptions') consumed WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(s->'effects') effect WHERE effect->'id'=consumed->'effectId' AND effect->>'eventId'=event_id);
  INSERT INTO public."CompetitiveCapacityCharge"("eventId","gameId","roundId","lane","cost") VALUES(event_id,gid,e->>'roundId',public.int9_capacity_lane(e->>'type',e->'authority'->>'kind'),public.int9_cost(1,effects,classifications,heads,consumptions,postings));
 END LOOP;
 FOR r IN SELECT jsonb_build_object('id',physical."id",'phase',CASE WHEN change->'fields' ? 'phase' THEN change->'fields'->'phase' ELSE physical."state"->'phase' END,'pause',CASE WHEN change->'fields' ? 'pause' THEN change->'fields'->'pause' ELSE CASE WHEN physical."state"->'pause'='null'::JSONB THEN 'null'::JSONB ELSE jsonb_build_object('eventId',physical."state"->'pause'->'eventId') END END,'resourceStop',CASE WHEN change->'fields' ? 'resourceStop' THEN change->'fields'->'resourceStop' ELSE physical."state"->'resourceStop' END) FROM (SELECT x->>'id' id FROM jsonb_array_elements(s->'roundChanges') x UNION SELECT e->>'roundId' FROM jsonb_array_elements(s->'events') e WHERE e->>'roundId' IS NOT NULL) affected JOIN public."GameRound" physical ON physical."gameId"=gid AND physical."id"=affected.id LEFT JOIN LATERAL (SELECT x change FROM jsonb_array_elements(s->'roundChanges') x WHERE x->>'id'=physical."id") patch ON TRUE LOOP
  usages:='{}'::JSONB; reservations:='{}'::JSONB;
  FOREACH lane IN ARRAY ARRAY['ATTEMPT','INTERIM','CANVAS','PUBLIC','INITIAL','OPEN_CLOSE','SYSTEM','OPTIONAL','PROTECTED'] LOOP
   used:=public.int9_capacity_vector(gid,r->>'id',lane,FALSE); reserved:=public.int9_capacity_vector(gid,r->>'id',lane,TRUE);
   IF (used->>'events')::BIGINT+(reserved->>'events')::BIGINT>public.int9_capacity_limit(r->>'id',lane) OR (used->>'effects')::BIGINT+(reserved->>'effects')::BIGINT>public.int9_capacity_limit(r->>'id',lane) THEN PERFORM public.int9_error(CASE lane WHEN 'ATTEMPT' THEN 'ATTEMPT_BUDGET_EXCEEDED' WHEN 'CANVAS' THEN 'CANVAS_BUDGET_EXCEEDED' ELSE 'OPTIONAL_CAPACITY_EXHAUSTED' END); END IF;
   usages:=usages||jsonb_build_object(lane,used); reservations:=reservations||jsonb_build_object(lane,reserved);
  END LOOP;
  IF (SELECT count(*) FROM public."CompetitiveAttempt" WHERE "gameId"=gid AND "roundId"=r->>'id')+(SELECT count(*) FROM jsonb_array_elements(s->'attempts') a WHERE a->>'roundId'=r->>'id' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" p WHERE p."gameId"=gid AND p."id"=a->>'id'))>public.int9_capacity_limit(r->>'id','ATTEMPT') THEN PERFORM public.int9_error('ATTEMPT_BUDGET_EXCEEDED'); END IF;
  INSERT INTO public."CompetitiveCapacityHead"("roundId","gameId","version","used","reserved","resourceEventId") VALUES(r->>'id',gid,COALESCE(greatest((SELECT max("sequence") FROM public."RoundAuthorityEvent" WHERE "gameId"=gid AND "roundId"=r->>'id'),(SELECT max((a->>'sequence')::INTEGER) FROM jsonb_array_elements(s->'events') a WHERE a->'roundId'=r->'id')),1),usages,reservations,r->'resourceStop'->>'eventId') ON CONFLICT("roundId") DO UPDATE SET "version"=EXCLUDED."version","used"=EXCLUDED."used","reserved"=EXCLUDED."reserved","resourceEventId"=EXCLUDED."resourceEventId" WHERE "CompetitiveCapacityHead"."gameId"=gid;
 END LOOP;
END $$;
CREATE FUNCTION public.int9_assert_canvas(game_id TEXT,round_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c public."DrawingCanvasState"%ROWTYPE; x JSONB; y JSONB; BEGIN
 SELECT "revision","roundId","state" INTO c."revision",c."roundId",c."state" FROM public."DrawingCanvasState" WHERE "roundId"=round_id; x:=c."state";
 IF c."roundId" IS NULL OR NOT EXISTS(SELECT 1 FROM public."GameRound" WHERE "gameId"=game_id AND "id"=round_id AND "pin"->>'format'='DRAWING_TARGET') OR public.int6_enta_exact_keys(x,ARRAY['roundId','revision','strokes','visibleIds','redoIds','cumulativePoints','mutations','receipts']) IS NOT TRUE OR x->>'roundId' IS DISTINCT FROM round_id OR x->'revision' IS DISTINCT FROM to_jsonb(c."revision") OR public.int5b_json_integer(x->'revision',0,512) IS NOT TRUE OR public.int5b_json_integer(x->'cumulativePoints',0,8192) IS NOT TRUE OR x->'revision' IS DISTINCT FROM x->'mutations' OR jsonb_typeof(x->'strokes') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'strokes')>128 OR jsonb_typeof(x->'visibleIds') IS DISTINCT FROM 'array' OR jsonb_typeof(x->'redoIds') IS DISTINCT FROM 'array' OR jsonb_typeof(x->'receipts') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'receipts')<>c."revision" THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF;
 IF (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(x->'strokes'))<>jsonb_array_length(x->'strokes') OR (SELECT COALESCE(sum(jsonb_array_length(value->'points')),0) FROM jsonb_array_elements(x->'strokes'))<>(x->>'cumulativePoints')::INTEGER OR (SELECT count(DISTINCT value->>'commandId') FROM jsonb_array_elements(x->'receipts'))<>c."revision" OR EXISTS(SELECT 1 FROM jsonb_array_elements(x->'receipts') WITH ORDINALITY receipt(value,ordinal) WHERE public.int6_enta_exact_keys(value,ARRAY['commandId','hash','revision']) IS NOT TRUE OR value->'revision' IS DISTINCT FROM to_jsonb(ordinal) OR value->>'hash'!~'^[a-f0-9]{64}$' OR NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" e WHERE e."gameId"=game_id AND e."roundId"=round_id AND e."commandId"=value->>'commandId' AND e."intentHash"=value->>'hash' AND e."authorityKind"='GRANT' AND e."type" IN ('CANVAS_APPEND','CANVAS_UNDO','CANVAS_REDO','CANVAS_CLEAR'))) THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF;
 FOREACH y IN ARRAY ARRAY[x->'visibleIds',x->'redoIds'] LOOP IF jsonb_array_length(y)>128 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(y))<>jsonb_array_length(y) OR EXISTS(SELECT 1 FROM jsonb_array_elements(y) member WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(x->'strokes') stroke WHERE stroke->'id'=member)) THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF; END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(x->'visibleIds') visible JOIN jsonb_array_elements(x->'redoIds') redo ON redo=visible) THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF;
 FOR y IN SELECT value FROM jsonb_array_elements(x->'strokes') LOOP
  IF public.int6_enta_exact_keys(y,ARRAY['id','color','width','erase','points']) IS NOT TRUE OR public.int8_json_id(y->'id') IS NOT TRUE OR y->>'color' NOT IN ('#191615','#ffffff','#ff2e95','#3478bd','#267448') OR y->'width' NOT IN ('2'::JSONB,'5'::JSONB,'10'::JSONB) OR jsonb_typeof(y->'erase') IS DISTINCT FROM 'boolean' OR jsonb_typeof(y->'points') IS DISTINCT FROM 'array' OR jsonb_array_length(y->'points') NOT BETWEEN 1 AND 256 OR EXISTS(SELECT 1 FROM jsonb_array_elements(y->'points') point WHERE jsonb_typeof(point) IS DISTINCT FROM 'array' OR jsonb_array_length(point)<>2 OR public.int5b_json_integer(point->0,0,10000) IS NOT TRUE OR public.int5b_json_integer(point->1,0,10000) IS NOT TRUE) THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF;
 END LOOP;
END $$;
CREATE FUNCTION public.int9_canvas_page(ns TEXT,project TEXT,uid TEXT,token_hash TEXT,game_id TEXT,q JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE scope JSONB; gr JSONB; rt RECORD; r RECORD; canvas_revision INTEGER; stored JSONB; page_rows JSONB; total INTEGER; page_offset INTEGER; moment DOUBLE PRECISION; BEGIN
 IF (uid IS NULL)=(token_hash IS NULL) OR public.int6_enta_exact_keys(q,ARRAY['collection','roundId','effectId','snapshot','canvasRevision','offset']) IS NOT TRUE OR q->>'collection'<>'canvas' OR public.int8_json_id(q->'roundId') IS NOT TRUE OR q->'effectId'<>'null'::JSONB OR q->'snapshot'<>'null'::JSONB AND public.int5b_json_integer(q->'snapshot',1,64946) IS NOT TRUE OR q->'canvasRevision'<>'null'::JSONB AND public.int5b_json_integer(q->'canvasRevision',0,512) IS NOT TRUE OR public.int5b_json_integer(q->'offset',0,128) IS NOT TRUE THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
 IF uid IS NOT NULL THEN scope:=public.int9_owner_load(ns,project,uid,game_id,TRUE); IF scope IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 ELSE scope:=public.int9_grant_load(ns,project,game_id,token_hash); gr:=public.int9_grant_physical(game_id,token_hash,public.int9_now()); IF gr->>'role'<>'ACTOR' OR gr->'roundId' IS DISTINCT FROM q->'roundId' THEN PERFORM public.int9_error('GRANT_DENIED'); END IF; END IF;
 moment:=public.int9_now(); IF public.int9_mutation_owner(game_id,NULL,NULL,gr->>'scopeId',NULL,'{"grants":[]}'::JSONB,NULL,NULL,moment) THEN RETURN jsonb_build_object('restart',TRUE); END IF;
 IF q->'snapshot'<>'null'::JSONB AND q->'snapshot' IS DISTINCT FROM scope->'snapshot' THEN RETURN jsonb_build_object('restart',TRUE); END IF;
 SELECT "state","activeRoundId" INTO rt FROM public."GameRuntime" WHERE "gameId"=game_id;
 SELECT "state","pin"->>'format' AS format INTO r FROM public."GameRound" WHERE "gameId"=game_id AND "id"=q->>'roundId';
 IF r."state" IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 IF rt."state"='FINISHED' OR rt."activeRoundId" IS DISTINCT FROM q->>'roundId' OR r.format<>'DRAWING_TARGET' OR r."state"->'pause'<>'null'::JSONB OR r."state"->'resourceStop'<>'null'::JSONB OR EXISTS(SELECT 1 FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id AND ("openItemReviewId" IS NOT NULL OR "boardReviewRoundId" IS NOT NULL)) THEN RETURN jsonb_build_object('denied',TRUE); END IF;
 SELECT "revision","state" INTO canvas_revision,stored FROM public."DrawingCanvasState" WHERE "roundId"=q->>'roundId'; IF stored IS NULL THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF;
 IF q->'canvasRevision'<>'null'::JSONB AND q->'canvasRevision' IS DISTINCT FROM to_jsonb(canvas_revision) THEN RETURN jsonb_build_object('restart',TRUE); END IF;
 page_offset:=(q->>'offset')::INTEGER; total:=jsonb_array_length(stored->'visibleIds'); IF page_offset>total OR page_offset%16<>0 THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
 SELECT COALESCE(jsonb_agg(stroke ORDER BY visible.ordinal),'[]'::JSONB) INTO page_rows FROM jsonb_array_elements(stored->'visibleIds') WITH ORDINALITY visible(id,ordinal) JOIN jsonb_array_elements(stored->'strokes') stroke ON stroke->'id'=visible.id WHERE visible.ordinal>page_offset AND visible.ordinal<=page_offset+16;
 IF jsonb_array_length(page_rows)<>least(16,total-page_offset) OR octet_length(convert_to(public.int6_enta_canonical(page_rows),'UTF8'))>131072 THEN PERFORM public.int9_error('PAGE_PROOF_UNAVAILABLE'); END IF;
 stored:=NULL; r:=NULL; rt:=NULL; gr:=NULL; RETURN jsonb_build_object('scope',scope,'canvasRevision',canvas_revision,'total',total,'rows',page_rows);
END $$;
CREATE FUNCTION public.int9_closing_batch_event(s JSONB,round_id TEXT,event_id TEXT) RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'events') event JOIN jsonb_array_elements(s->'effects') effect ON effect->>'eventId'=event->>'id' WHERE event->>'id'=event_id AND event->>'roundId'=round_id AND event->>'type' IN ('FINAL_RULING','CLOSE_ROUND','RECORDING_CLOSED') AND effect->>'roundId'=round_id AND effect->'afterClock'->>'phase'='RESOLVED' AND effect->>'kind' IN ('RULING','NO_SCORE','TIMING'))
$$;
CREATE FUNCTION public.int9_closing_event(game_id TEXT,round_id TEXT,event_id TEXT) RETURNS BOOLEAN LANGUAGE SQL STABLE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" event JOIN public."CompetitiveEffect" effect ON effect."gameId"=event."gameId" AND effect."eventId"=event."id" WHERE event."gameId"=game_id AND event."id"=event_id AND event."roundId"=round_id AND event."type" IN ('FINAL_RULING','CLOSE_ROUND','RECORDING_CLOSED') AND effect."roundId"=round_id AND effect."payload"->'afterClock'->>'phase'='RESOLVED' AND effect."kind" IN ('RULING','NO_SCORE','TIMING'))
$$;
CREATE FUNCTION public.int9_cost(events INTEGER,effects INTEGER,classifications INTEGER,heads INTEGER,consumptions INTEGER,postings INTEGER) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('events',events,'effects',effects,'classifications',classifications,'heads',heads,'consumptions',consumptions,'postings',postings) $$;
CREATE FUNCTION public.int9_capacity_lane(kind TEXT,authority TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE WHEN kind IN ('RESOURCE_LIMIT_REACHED','FINISH') THEN 'PROTECTED' WHEN kind='RECORD_ATTEMPT' THEN 'ATTEMPT' WHEN kind='INTERIM_WRONG' THEN 'INTERIM' WHEN kind LIKE 'CANVAS_%' THEN 'CANVAS' WHEN kind='PUBLIC_REVEAL' THEN 'PUBLIC' WHEN kind='FINAL_RULING' THEN 'INITIAL' WHEN kind IN ('OPEN_ROUND','NEXT_ROUND','CLOSE_ROUND') THEN 'OPEN_CLOSE' WHEN authority='SYSTEM' THEN 'SYSTEM' ELSE 'OPTIONAL' END $$;
CREATE FUNCTION public.int9_capacity_limit(round_id TEXT,lane TEXT) RETURNS INTEGER LANGUAGE SQL STABLE SET search_path=pg_catalog AS $$ SELECT CASE lane WHEN 'ATTEMPT' THEN CASE WHEN "pin"->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') THEN 512 ELSE 8 END WHEN 'INTERIM' THEN CASE WHEN "pin"->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') THEN 512 ELSE 8 END WHEN 'CANVAS' THEN CASE WHEN "pin"->>'format'='DRAWING_TARGET' THEN 512 ELSE 0 END WHEN 'PUBLIC' THEN CASE WHEN "pin"->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') THEN 129 ELSE 1 END WHEN 'INITIAL' THEN CASE WHEN "pin"->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') THEN 129 ELSE 1 END WHEN 'OPEN_CLOSE' THEN 2 WHEN 'SYSTEM' THEN 256 WHEN 'OPTIONAL' THEN 256 WHEN 'PROTECTED' THEN 8 ELSE NULL END FROM public."GameRound" WHERE "id"=round_id $$;
CREATE FUNCTION public.int9_claim_cost(kind TEXT) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE kind WHEN 'ATTEMPT' THEN public.int9_cost(0,0,1,0,0,0) WHEN 'ITEM' THEN public.int9_cost(0,1,0,1,1,4) WHEN 'ROUND' THEN public.int9_cost(1,1,0,1,0,4) WHEN 'REVIEW' THEN public.int9_cost(1,1,0,1,0,4) WHEN 'BOARD_REVIEW' THEN public.int9_cost(1,1,0,1,0,4) WHEN 'PAUSE' THEN public.int9_cost(1,1,0,0,0,0) WHEN 'GRANT' THEN public.int9_cost(1,0,0,0,0,0) WHEN 'FINISH' THEN public.int9_cost(1,1,0,0,0,0) ELSE NULL END $$;
CREATE FUNCTION public.int9_capacity_claim(game_id TEXT,round_id TEXT,kind TEXT,source_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE claim_id TEXT:=public.int6_enta_canonical(jsonb_build_array(kind,round_id,source_id)); chosen_lane TEXT:=(CASE WHEN kind='ATTEMPT' THEN 'INTERIM' WHEN kind IN ('ITEM','ROUND') THEN 'INITIAL' WHEN kind='FINISH' THEN 'PROTECTED' ELSE 'OPTIONAL' END); expected JSONB:=public.int9_claim_cost(kind); BEGIN
 IF expected IS NULL OR source_id IS NULL THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM public."CompetitiveCapacityClaim" WHERE "id"=claim_id) THEN IF NOT EXISTS(SELECT 1 FROM public."CompetitiveCapacityClaim" WHERE "id"=claim_id AND "gameId"=game_id AND "roundId" IS NOT DISTINCT FROM round_id AND "sourceKind"=kind AND "sourceId"=source_id AND "lane"=chosen_lane AND "cost"=expected) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF; RETURN; END IF;
 INSERT INTO public."CompetitiveCapacityClaim"("id","gameId","roundId","sourceKind","sourceId","lane","cost","attemptId","itemId","reviewId","boardReversalEffectId","pauseEventId","grantId") VALUES(claim_id,game_id,round_id,kind,source_id,chosen_lane,expected,CASE WHEN kind='ATTEMPT' THEN source_id END,CASE WHEN kind='ITEM' THEN source_id END,CASE WHEN kind='REVIEW' THEN source_id END,CASE WHEN kind='BOARD_REVIEW' THEN source_id END,CASE WHEN kind='PAUSE' THEN source_id END,CASE WHEN kind='GRANT' THEN source_id END);
END $$;
CREATE FUNCTION public.int9_capacity_dispose(game_id TEXT,round_id TEXT,kind TEXT,source_id TEXT,event_id TEXT,disposition TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE claim_id TEXT; BEGIN
 SELECT "id" INTO claim_id FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "roundId" IS NOT DISTINCT FROM round_id AND "sourceKind"=kind AND "sourceId"=source_id;
 IF NOT FOUND OR disposition NOT IN ('CONSUME','RELEASE') OR EXISTS(SELECT 1 FROM public."CompetitiveCapacityDisposition" WHERE "claimId"=claim_id) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 INSERT INTO public."CompetitiveCapacityDisposition"("claimId","gameId","eventId","kind") VALUES(claim_id,game_id,event_id,disposition);
END $$;
CREATE FUNCTION public.int9_capacity_initialize(game_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE r RECORD; item RECORD; chosen_lane TEXT; used JSONB; reserved JSONB; all_used JSONB; all_reserved JSONB; BEGIN
 FOR r IN SELECT "id" FROM public."GameRound" WHERE "gameId"=game_id ORDER BY "ordinal" LOOP
  FOR item IN SELECT "itemId" FROM public."RoundItemPin" WHERE "roundId"=r."id" ORDER BY "ordinal" LOOP PERFORM public.int9_capacity_claim(game_id,r."id",'ITEM',item."itemId"); END LOOP;
  PERFORM public.int9_capacity_claim(game_id,r."id",'ROUND',r."id");
  all_used:='{}'::JSONB; all_reserved:='{}'::JSONB;
  FOREACH chosen_lane IN ARRAY ARRAY['ATTEMPT','INTERIM','CANVAS','PUBLIC','INITIAL','OPEN_CLOSE','SYSTEM','OPTIONAL','PROTECTED'] LOOP used:=public.int9_capacity_vector(game_id,r."id",chosen_lane,FALSE); reserved:=public.int9_capacity_vector(game_id,r."id",chosen_lane,TRUE); all_used:=all_used||jsonb_build_object(chosen_lane,used); all_reserved:=all_reserved||jsonb_build_object(chosen_lane,reserved); END LOOP;
  INSERT INTO public."CompetitiveCapacityHead"("roundId","gameId","version","used","reserved","resourceEventId") VALUES(r."id",game_id,1,all_used,all_reserved,NULL);
 END LOOP;
 PERFORM public.int9_capacity_claim(game_id,NULL,'FINISH',game_id);
END $$;
CREATE FUNCTION public.int9_capacity_vector(game_id TEXT,round_id TEXT,selected_lane TEXT,reservation BOOLEAN) RETURNS JSONB LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE key TEXT; value BIGINT; result JSONB:='{}'::JSONB; BEGIN
 FOREACH key IN ARRAY ARRAY['events','effects','classifications','heads','consumptions','postings'] LOOP
  IF reservation THEN SELECT COALESCE(sum((c."cost"->>key)::BIGINT),0) INTO value FROM public."CompetitiveCapacityClaim" c WHERE c."gameId"=game_id AND c."roundId" IS NOT DISTINCT FROM round_id AND c."lane"=selected_lane AND NOT EXISTS(SELECT 1 FROM public."CompetitiveCapacityDisposition" d WHERE d."claimId"=c."id");
  ELSE SELECT COALESCE(sum((c."cost"->>key)::BIGINT),0) INTO value FROM public."CompetitiveCapacityCharge" c WHERE c."gameId"=game_id AND c."roundId" IS NOT DISTINCT FROM round_id AND c."lane"=selected_lane; END IF;
  result:=result||jsonb_build_object(key,value);
 END LOOP; RETURN result;
END $$;
CREATE FUNCTION public.int9_capacity_preflight(s JSONB,old JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE e JSONB; x JSONB; r JSONB; prior JSONB; claim RECORD; lane TEXT; used JSONB; reserved JSONB; usages JSONB; reservations JSONB; event_id TEXT; effects INTEGER; heads INTEGER; classifications INTEGER; consumptions INTEGER; postings INTEGER; gid TEXT:=s->>'id'; BEGIN
 -- All input facts below were independently reduced by SQL in its locked context.
 FOR x IN SELECT a FROM jsonb_array_elements(s->'attempts') a WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" p WHERE p."gameId"=gid AND p."id"=a->>'id') LOOP PERFORM public.int9_capacity_claim(gid,x->>'roundId','ATTEMPT',x->>'id'); END LOOP;
 FOR x IN SELECT a FROM jsonb_array_elements(s->'classifications') a WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" p WHERE p."gameId"=gid AND p."id"=a->>'id') LOOP PERFORM public.int9_capacity_dispose(gid,(SELECT "roundId" FROM public."CompetitiveCapacityClaim" WHERE "gameId"=gid AND "sourceKind"='ATTEMPT' AND "sourceId"=x->>'attemptId'),'ATTEMPT',x->>'attemptId',x->>'eventId','CONSUME'); END LOOP;
 FOR x IN SELECT a FROM jsonb_array_elements(s->'itemReviews') a WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveItemReview" p WHERE p."gameId"=gid AND p."id"=a->>'id') LOOP PERFORM public.int9_capacity_claim(gid,x->>'roundId','REVIEW',x->>'id'); END LOOP;
 IF s->'correctionReview'<>'null'::JSONB AND old->'correctionReview'='null'::JSONB THEN SELECT a INTO x FROM jsonb_array_elements(s->'effects') a WHERE a->>'kind'='REVERSAL' AND a->'roundId'=s->'correctionReview' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" p WHERE p."gameId"=gid AND p."id"=a->>'id'); IF x IS NULL THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF; PERFORM public.int9_capacity_claim(gid,x->>'roundId','BOARD_REVIEW',x->>'id'); END IF;
 -- Genuine consumption across the complete batch precedes every release.
 FOR claim IN SELECT c.* FROM public."CompetitiveCapacityClaim" c WHERE c."gameId"=gid AND c."sourceKind" IN ('ITEM','ROUND') AND NOT EXISTS(SELECT 1 FROM public."CompetitiveCapacityDisposition" d WHERE d."claimId"=c."id") ORDER BY c."id" COLLATE "C" LOOP
  event_id:=NULL;
  IF claim."sourceKind"='ITEM' THEN SELECT effect->>'eventId' INTO event_id FROM jsonb_array_elements(s->'rounds') round_row CROSS JOIN LATERAL jsonb_array_elements(round_row->'consumed') consumed JOIN jsonb_array_elements(s->'effects') effect ON effect->'id'=consumed->'effectId' WHERE round_row->>'id'=claim."roundId" AND consumed->>'itemId'=claim."sourceId" AND effect->>'kind' IN ('RULING','NO_SCORE') AND effect->'predecessorId'='null'::JSONB AND NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" saved WHERE saved."gameId"=gid AND saved."id"=effect->>'id');
  ELSE SELECT effect->>'eventId' INTO event_id FROM jsonb_array_elements(s->'rulings') head JOIN jsonb_array_elements(s->'effects') effect ON effect->'id'=head->'originalEffectId' WHERE head->>'roundId'=claim."roundId" AND head->'itemId'='null'::JSONB AND effect->>'kind' IN ('RULING','NO_SCORE') AND effect->'predecessorId'='null'::JSONB AND NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" saved WHERE saved."gameId"=gid AND saved."id"=effect->>'id'); END IF;
  IF event_id IS NOT NULL THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",claim."sourceKind",claim."sourceId",event_id,'CONSUME'); END IF;
 END LOOP;
 FOR e IN SELECT a FROM jsonb_array_elements(s->'events') a WHERE NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" p WHERE p."gameId"=gid AND p."id"=a->>'id') ORDER BY (a->>'sequence')::INTEGER LOOP
  event_id:=e->>'id';
  FOR r IN SELECT a FROM jsonb_array_elements(s->'rounds') a WHERE a->'contextSummary' IS DISTINCT FROM 'true'::JSONB LOOP
   prior:=public.int9_round(old,r->>'id'); IF r->'pause'->>'eventId'=event_id AND prior->'pause'->>'eventId' IS DISTINCT FROM event_id THEN PERFORM public.int9_capacity_claim(gid,r->>'id','PAUSE',event_id); END IF;
   FOR claim IN SELECT c.* FROM public."CompetitiveCapacityClaim" c WHERE c."gameId"=gid AND c."roundId"=r->>'id' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveCapacityDisposition" d WHERE d."claimId"=c."id") ORDER BY c."id" COLLATE "C" LOOP
    IF claim."sourceKind" IN ('ITEM','ROUND') AND r->>'phase'='RESOLVED' AND prior->>'phase'<>'RESOLVED' AND e->>'roundId'=r->>'id' AND public.int9_closing_batch_event(s,r->>'id',event_id) THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",claim."sourceKind",claim."sourceId",event_id,'RELEASE');
    ELSIF claim."sourceKind"='PAUSE' AND prior->'pause'->>'eventId'=claim."sourceId" AND r->'pause'='null'::JSONB AND e->>'roundId'=r->>'id' AND e->>'type' IN ('PHONE_ENDED','RESUME_ROUND','END_ASSISTANCE') THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",'PAUSE',claim."sourceId",event_id,'CONSUME');
    ELSIF claim."sourceKind"='BOARD_REVIEW' AND old->'correctionReview'=r->'id' AND s->'correctionReview'='null'::JSONB AND e->>'type'='CORRECT_RULING' AND e->'roundId'=r->'id' THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",'BOARD_REVIEW',claim."sourceId",event_id,'CONSUME');
    ELSIF claim."sourceKind"='REVIEW' AND EXISTS(SELECT 1 FROM jsonb_array_elements(s->'itemResolutions') resolution WHERE resolution->>'reviewId'=claim."sourceId" AND resolution->>'eventId'=event_id) THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",'REVIEW',claim."sourceId",event_id,'CONSUME'); END IF;
   END LOOP;
  END LOOP;
  FOR x IN SELECT g FROM jsonb_array_elements(s->'grants') g WHERE g->>'id'=event_id AND g->'revoked'='false'::JSONB LOOP PERFORM public.int9_capacity_claim(gid,x->>'roundId','GRANT',x->>'id'); END LOOP;
  FOR claim IN SELECT c.* FROM public."CompetitiveCapacityClaim" c WHERE c."gameId"=gid AND c."sourceKind"='GRANT' AND c."roundId"=e->>'roundId' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveCapacityDisposition" d WHERE d."claimId"=c."id") LOOP IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'grants') g WHERE g->>'id'=claim."sourceId" AND g->'revoked'='true'::JSONB) THEN PERFORM public.int9_capacity_dispose(gid,claim."roundId",'GRANT',claim."sourceId",event_id,CASE WHEN e->>'type'='REVOKE_GRANT' THEN 'CONSUME' ELSE 'RELEASE' END); END IF; END LOOP;
  IF e->>'type'='FINISH' THEN PERFORM public.int9_capacity_dispose(gid,NULL,'FINISH',gid,event_id,'CONSUME'); END IF;
  SELECT count(*),count(*) FILTER(WHERE effect->>'kind' IN ('RULING','NO_SCORE','REVERSAL','CORRECTION')) INTO effects,heads FROM jsonb_array_elements(s->'effects') effect WHERE effect->>'eventId'=event_id;
  SELECT count(*) INTO classifications FROM jsonb_array_elements(s->'classifications') c WHERE c->>'eventId'=event_id;
  SELECT count(*) INTO postings FROM jsonb_array_elements(s->'postings') p WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(s->'effects') effect WHERE effect->'id'=p->'effectId' AND effect->>'eventId'=event_id);
  SELECT count(*) INTO consumptions FROM jsonb_array_elements(s->'rounds') round_row CROSS JOIN LATERAL jsonb_array_elements(round_row->'consumed') consumed WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(s->'effects') effect WHERE effect->'id'=consumed->'effectId' AND effect->>'eventId'=event_id);
  INSERT INTO public."CompetitiveCapacityCharge"("eventId","gameId","roundId","lane","cost") VALUES(event_id,gid,e->>'roundId',public.int9_capacity_lane(e->>'type',e->'authority'->>'kind'),public.int9_cost(1,effects,classifications,heads,consumptions,postings));
 END LOOP;
 FOR r IN SELECT a FROM jsonb_array_elements(s->'rounds') a WHERE a->'contextSummary' IS DISTINCT FROM 'true'::JSONB LOOP
  usages:='{}'::JSONB; reservations:='{}'::JSONB;
  FOREACH lane IN ARRAY ARRAY['ATTEMPT','INTERIM','CANVAS','PUBLIC','INITIAL','OPEN_CLOSE','SYSTEM','OPTIONAL','PROTECTED'] LOOP
   used:=public.int9_capacity_vector(gid,r->>'id',lane,FALSE); reserved:=public.int9_capacity_vector(gid,r->>'id',lane,TRUE);
   IF (used->>'events')::BIGINT+(reserved->>'events')::BIGINT>public.int9_capacity_limit(r->>'id',lane) OR (used->>'effects')::BIGINT+(reserved->>'effects')::BIGINT>public.int9_capacity_limit(r->>'id',lane) THEN PERFORM public.int9_error(CASE lane WHEN 'ATTEMPT' THEN 'ATTEMPT_BUDGET_EXCEEDED' WHEN 'CANVAS' THEN 'CANVAS_BUDGET_EXCEEDED' ELSE 'OPTIONAL_CAPACITY_EXHAUSTED' END); END IF;
   usages:=usages||jsonb_build_object(lane,used); reservations:=reservations||jsonb_build_object(lane,reserved);
  END LOOP;
  IF (SELECT count(*) FROM public."CompetitiveAttempt" WHERE "gameId"=gid AND "roundId"=r->>'id')+(SELECT count(*) FROM jsonb_array_elements(s->'attempts') a WHERE a->>'roundId'=r->>'id' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" p WHERE p."gameId"=gid AND p."id"=a->>'id'))>public.int9_capacity_limit(r->>'id','ATTEMPT') THEN PERFORM public.int9_error('ATTEMPT_BUDGET_EXCEEDED'); END IF;
  INSERT INTO public."CompetitiveCapacityHead"("roundId","gameId","version","used","reserved","resourceEventId") VALUES(r->>'id',gid,COALESCE(greatest((SELECT max("sequence") FROM public."RoundAuthorityEvent" WHERE "gameId"=gid AND "roundId"=r->>'id'),(SELECT max((a->>'sequence')::INTEGER) FROM jsonb_array_elements(s->'events') a WHERE a->'roundId'=r->'id')),1),usages,reservations,r->'resourceStop'->>'eventId') ON CONFLICT("roundId") DO UPDATE SET "version"=EXCLUDED."version","used"=EXCLUDED."used","reserved"=EXCLUDED."reserved","resourceEventId"=EXCLUDED."resourceEventId" WHERE "CompetitiveCapacityHead"."gameId"=gid;
 END LOOP;
END $$;
CREATE FUNCTION public.int9_catalog_page(ns TEXT,project TEXT,uid TEXT,execution_format TEXT,category_key TEXT,snapshot TEXT,page_offset BIGINT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE identity_id TEXT; pointer public."ActiveCatalogPointer"%ROWTYPE; f public."EntaFormatRelease"%ROWTYPE; cp public."EntaCompetitiveRelease"%ROWTYPE; current_snapshot TEXT; page_rows JSONB; total BIGINT; size INTEGER:=(CASE WHEN category_key IS NULL THEN 32 ELSE 64 END); result JSONB; BEGIN
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id';
 IF execution_format NOT IN ('TIER_BOARD','MIXED_BOARD','STANDALONE_LIST','STANDALONE_ACTING') OR page_offset IS NULL OR page_offset<0 OR page_offset>9007199254740991 OR page_offset%size<>0 OR category_key IS NOT NULL AND octet_length(category_key)>1024 OR snapshot IS NOT NULL AND snapshot!~'^[a-f0-9]{64}$' THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
 SELECT "catalogReleaseId","id","releaseRootHash","validationReceiptId" INTO pointer."catalogReleaseId",pointer."id",pointer."releaseRootHash",pointer."validationReceiptId" FROM public."ActiveCatalogPointer" WHERE "id"='singleton' FOR SHARE;
 SELECT "baseReleaseId","baseRoot","formatRoot","id","mediaRoot","receiptId" INTO f."baseReleaseId",f."baseRoot",f."formatRoot",f."id",f."mediaRoot",f."receiptId" FROM public."EntaFormatRelease" WHERE "baseReleaseId"=pointer."catalogReleaseId" AND "baseRoot"=pointer."releaseRootHash" AND "receiptId"=pointer."validationReceiptId" AND "policyVersion"='enta-format-1' AND "sealedAt" IS NOT NULL;
 SELECT "id","proofRoot" INTO cp."id",cp."proofRoot" FROM public."EntaCompetitiveRelease" WHERE "formatReleaseId"=f."id" AND "formatRoot"=f."formatRoot" AND "mediaRoot"=f."mediaRoot" AND "rulesVersion"='enta-competitive-1' AND "paletteRoot"=public.int9_palette_root() AND "sealedAt" IS NOT NULL;
 IF pointer."id" IS NULL OR f."id" IS NULL OR cp."id" IS NULL OR (SELECT count(*) FROM public."EntaCompetitiveRelease" WHERE "formatReleaseId"=f."id" AND "sealedAt" IS NOT NULL)<>1 THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(jsonb_build_array(f."baseReleaseId",f."receiptId",f."id",cp."id")) value WHERE octet_length(convert_to(value,'UTF8')) NOT BETWEEN 1 AND 1024) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 PERFORM public.int9_assert_competitive(cp."id"); PERFORM public.int6_enta_assert_receipt(f."receiptId",f."baseReleaseId",f."baseRoot");
 current_snapshot:=public.int6_enta_hash(jsonb_build_object('project',project,'principal',uid,'format',execution_format,'base',f."baseRoot",'formatRoot',f."formatRoot",'proofRoot',cp."proofRoot"));
 IF snapshot IS NOT NULL AND snapshot IS DISTINCT FROM current_snapshot THEN PERFORM public.int9_error('PAGE_SNAPSHOT_RESTART'); END IF;
 IF category_key IS NULL THEN
  SELECT count(*) INTO total FROM (SELECT "categoryKey",min("format") family FROM public."EntaFormatRevision" WHERE "releaseId"=f."id" GROUP BY "categoryKey" HAVING count(DISTINCT "format")=1) categories WHERE execution_format='MIXED_BOARD' OR family=(CASE execution_format WHEN 'TIER_BOARD' THEN 'ORDINARY_TIER' WHEN 'STANDALONE_LIST' THEN 'LIST_ITEMS' ELSE 'ACTING_ITEMS' END);
  SELECT COALESCE(jsonb_agg(page_row ORDER BY category COLLATE "C"),'[]'::JSONB) INTO page_rows FROM (
   SELECT c."categoryKey" category,jsonb_build_object('key',c."categoryKey",'label',left(cr."labelAr",64),'format',c.family,'prompts','[]'::JSONB,'cover',(SELECT jsonb_build_object('id',m->'id','mime',m->'mime','bytes',m->'bytes','width',m->'width','height',m->'height','durationMs',m->'durationMs') FROM public."EntaFormatCover" cover CROSS JOIN LATERAL (SELECT public.int9_media_descriptor(cover."proofId",'COVER',NULL) m) proof WHERE cover."releaseId"=f."id" AND cover."categoryKey"=c."categoryKey")) page_row
   FROM (SELECT "categoryKey",min("format") family FROM public."EntaFormatRevision" WHERE "releaseId"=f."id" GROUP BY "categoryKey" HAVING count(DISTINCT "format")=1) c JOIN public."CatalogReleaseCategory" rc ON rc."catalogReleaseId"=f."baseReleaseId" AND rc."categoryKey"=c."categoryKey" JOIN public."CanonicalCategoryRevision" cr ON cr."id"=rc."categoryRevisionId"
   WHERE execution_format='MIXED_BOARD' OR c.family=(CASE execution_format WHEN 'TIER_BOARD' THEN 'ORDINARY_TIER' WHEN 'STANDALONE_LIST' THEN 'LIST_ITEMS' ELSE 'ACTING_ITEMS' END) ORDER BY c."categoryKey" COLLATE "C" OFFSET page_offset LIMIT size
  ) page;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM public."EntaFormatRevision" WHERE "releaseId"=f."id" AND "categoryKey"=category_key GROUP BY "categoryKey" HAVING count(DISTINCT "format")=1 AND (execution_format='MIXED_BOARD' OR min("format")=(CASE execution_format WHEN 'TIER_BOARD' THEN 'ORDINARY_TIER' WHEN 'STANDALONE_LIST' THEN 'LIST_ITEMS' ELSE 'ACTING_ITEMS' END))) THEN PERFORM public.int9_error('CATEGORY_UNAVAILABLE'); END IF;
  SELECT count(*) INTO total FROM public."EntaFormatRevision" fr JOIN public."EntaCompetitivePrompt" p ON p."releaseId"=cp."id" AND p."formatId"=fr."id" AND p."questionRevisionId"=fr."questionRevisionId" AND p."questionHash"=fr."questionHash" AND public.int9_prompt_parent(p."id",fr."id") IS TRUE WHERE fr."releaseId"=f."id" AND fr."categoryKey"=category_key;
  SELECT COALESCE(jsonb_agg(page_row ORDER BY ref COLLATE "C"),'[]'::JSONB) INTO page_rows FROM (SELECT fr."opaqueRef" ref,jsonb_build_object('ref',fr."opaqueRef",'label',left(q."prompt",64)) page_row FROM public."EntaFormatRevision" fr JOIN public."EntaCompetitivePrompt" p ON p."releaseId"=cp."id" AND p."formatId"=fr."id" AND p."questionRevisionId"=fr."questionRevisionId" AND p."questionHash"=fr."questionHash" AND public.int9_prompt_parent(p."id",fr."id") IS TRUE JOIN public."QuestionRevision" q ON q."id"=fr."questionRevisionId" AND q."contentHash"=fr."questionHash" WHERE fr."releaseId"=f."id" AND fr."categoryKey"=category_key ORDER BY fr."opaqueRef" COLLATE "C" OFFSET page_offset LIMIT size) page;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(page_rows) x WHERE public.int6_enta_valid_text(x->'ref',1,128) IS NOT TRUE) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 END IF;
 IF total>9007199254740991 OR page_offset>total OR jsonb_array_length(page_rows)<>least(size,total-page_offset) OR EXISTS(SELECT 1 FROM jsonb_array_elements(page_rows) x WHERE category_key IS NULL AND octet_length(x->>'key')>1024) THEN PERFORM public.int9_error('PAGE_PROOF_UNAVAILABLE'); END IF;
 result:=jsonb_build_object('releaseId',cp."id",'snapshot',current_snapshot,'total',total,'rows',page_rows); IF octet_length(convert_to(public.int6_enta_canonical(result),'UTF8'))>65536 THEN PERFORM public.int9_error('CATALOG_BOUND_EXCEEDED'); END IF; RETURN result;
END $$;
CREATE FUNCTION public.int9_clock_event(rid TEXT,generation INTEGER,revision INTEGER,kind TEXT,anchor DOUBLE PRECISION,moment DOUBLE PRECISION,reason TEXT) RETURNS JSONB LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$ BEGIN
 IF revision>=64946 THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('id',gen_random_uuid()::TEXT,'commandId',CASE WHEN kind='RESOURCE_LIMIT_REACHED' THEN 'resource-'||rid ELSE 'clock-'||rid||'-'||generation||'-'||revision END,'hash',public.int6_enta_hash(CASE WHEN kind='RESOURCE_LIMIT_REACHED' THEN jsonb_build_object('roundId',rid,'reason',reason,'generation',generation) ELSE jsonb_build_object('type',kind,'roundId',rid,'generation',generation,'anchor',anchor,'moment',moment) END),'type',kind,'roundId',rid,'sequence',revision+1,'at',moment,'authority',jsonb_build_object('kind','SYSTEM','operation','CLOCK_SETTLEMENT'),'pauseReason',NULL);
END $$;
CREATE FUNCTION public.int9_clock_owner(game_id TEXT,moment DOUBLE PRECISION) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE h JSONB; r JSONB; before_clock JSONB; e JSONB; effect JSONB; events JSONB:='[]'::JSONB; effects JSONB:='[]'::JSONB; heads JSONB:='[]'::JSONB; b JSONB; fields JSONB; grants JSONB; scopes JSONB; originals JSONB; bonus JSONB; team_order TEXT[]; identity_id TEXT; admission_id TEXT; execution_format TEXT; rid TEXT; format TEXT; active_id TEXT; turn_index INTEGER; turn_seconds INTEGER; revision INTEGER; effect_sequence INTEGER; team_index INTEGER; required INTEGER; system_used BIGINT; elapsed BIGINT; prospective DOUBLE PRECISION; anchor DOUBLE PRECISION; phone BOOLEAN; invalidate BOOLEAN:=FALSE; close_now BOOLEAN:=FALSE; pending BOOLEAN; review BOOLEAN; kind TEXT; stop_reason TEXT; BEGIN
 SELECT g."firebaseIdentityId",g."admissionId",g."executionFormat",rt."activeRoundId",rt."turnIndex",rt."teamOrder",(rt."setup"->'rules'->>'turnSeconds')::INTEGER,rt."version" INTO identity_id,admission_id,execution_format,active_id,turn_index,team_order,turn_seconds,revision FROM public."Game" g JOIN public."GameRuntime" rt ON rt."gameId"=g."id" WHERE g."id"=game_id AND rt."state"<>'FINISHED';
 rid:=COALESCE(active_id,(SELECT review."roundId" FROM public."CompetitiveItemReview" review JOIN public."CompetitiveRuntimeHead" head ON head."gameId"=review."gameId" AND head."openItemReviewId"=review."id" WHERE review."gameId"=game_id)); IF rid IS NULL THEN RETURN FALSE; END IF;
 SELECT jsonb_build_object('id',round."state"->'id','phase',round."state"->'phase','phaseOrdinal',round."state"->'phaseOrdinal','generation',round."state"->'generation','version',round."state"->'version','currentTeamId',round."state"->'currentTeamId','deadline',round."state"->'deadline','overallDeadline',round."state"->'overallDeadline','pause',round."state"->'pause','assignment',round."state"->'assignment','pickedPlayerId',round."state"->'pickedPlayerId','pickedEventId',round."state"->'pickedEventId','doubleAttemptTeamId',round."state"->'doubleAttemptTeamId','reason',round."state"->'reason','turnAdvanced',round."state"->'turnAdvanced','resourceStop',round."state"->'resourceStop'),round."pin"->>'format' INTO r,format FROM public."GameRound" round WHERE round."gameId"=game_id AND round."id"=rid;
 IF r IS NULL THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF r->'resourceStop' IS DISTINCT FROM 'null'::JSONB THEN RETURN FALSE; END IF;
 h:=public.int9_before_header(game_id);
 phone:=r->'pause'->>'cause'='PHONE' AND r->'pause'->>'resumeAt' IS NOT NULL AND moment>=(r->'pause'->>'resumeAt')::DOUBLE PRECISION;
 prospective:=(CASE WHEN phone THEN CASE WHEN r->'pause'->'phaseRemaining'='null'::JSONB THEN NULL ELSE (r->'pause'->>'resumeAt')::DOUBLE PRECISION+(r->'pause'->>'phaseRemaining')::DOUBLE PRECISION END ELSE (r->>'deadline')::DOUBLE PRECISION END);
 required:=(CASE WHEN phone THEN 1 ELSE 0 END)+(CASE WHEN prospective IS NOT NULL AND moment>=prospective THEN CASE WHEN r->>'phase' IN ('MAIN','TRAP') AND moment>=prospective+10000 THEN 2 ELSE 1 END ELSE 0 END);
 elapsed:=(CASE WHEN r->>'phase'='TURN' AND prospective IS NOT NULL AND moment>=prospective THEN floor((moment-prospective)/(turn_seconds*1000))+1 ELSE 0 END);
 SELECT count(*) INTO system_used FROM public."RoundAuthorityEvent" event WHERE event."gameId"=game_id AND event."roundId"=rid AND event."authorityKind"='SYSTEM' AND event."type"<>'RESOURCE_LIMIT_REACHED';
 SELECT COALESCE(max("sequence"),0) INTO effect_sequence FROM public."CompetitiveEffect" WHERE "gameId"=game_id;
 IF system_used+required>256 OR (r->>'generation')::BIGINT>=2000000000 OR (r->>'phaseOrdinal')::BIGINT>=2000000000 OR moment<0 OR moment>9007199254740991 OR moment<>floor(moment) OR elapsed>9007199254740991 OR (r->>'generation')::BIGINT+elapsed>2000000000 OR (r->>'phaseOrdinal')::BIGINT+elapsed>2000000000 THEN
  stop_reason:=(CASE WHEN system_used+required>256 THEN 'SYSTEM_CAPACITY' ELSE 'GENERATION_BOUND' END); e:=public.int9_clock_event(rid,(r->>'generation')::INTEGER,revision,'RESOURCE_LIMIT_REACHED',NULL,moment,stop_reason); revision:=revision+1; effect_sequence:=effect_sequence+1;
  r:=r||jsonb_build_object('resourceStop',jsonb_build_object('eventId',e->'id','at',moment,'reason',stop_reason),'version',(r->>'version')::INTEGER+1); invalidate:=TRUE;
  effect:=public.int9_seal_patch(public.int9_effect_patch(e,effect_sequence,rid,public.int9_snapshot(r),'TIMING','{}'::JSONB)); events:=jsonb_build_array(e); effects:=jsonb_build_array(effect); e:=NULL; effect:=NULL;
 ELSE
  IF r->'pause' IS DISTINCT FROM 'null'::JSONB THEN
   IF r->'pause'->>'cause'<>'PHONE' OR moment<(r->'pause'->>'resumeAt')::DOUBLE PRECISION THEN RETURN FALSE; END IF;
   before_clock:=public.int9_snapshot(r); anchor:=(r->'pause'->>'resumeAt')::DOUBLE PRECISION;
   r:=r||jsonb_build_object('deadline',CASE WHEN r->'pause'->'phaseRemaining'='null'::JSONB THEN NULL ELSE anchor+(r->'pause'->>'phaseRemaining')::DOUBLE PRECISION END,'overallDeadline',CASE WHEN r->'pause'->'overallRemaining'='null'::JSONB THEN NULL ELSE anchor+(r->'pause'->>'overallRemaining')::DOUBLE PRECISION END,'pause',NULL,'version',(r->>'version')::INTEGER+1);
   e:=public.int9_clock_event(rid,(r->>'generation')::INTEGER,revision,'PHONE_ENDED',anchor,moment,NULL); revision:=revision+1; effect_sequence:=effect_sequence+1;
   effect:=public.int9_seal_patch(public.int9_effect_patch(e,effect_sequence,rid,public.int9_snapshot(r),'TIMING',jsonb_build_object('beforeClock',before_clock))); events:=events||jsonb_build_array(e); effects:=effects||jsonb_build_array(effect); e:=NULL; effect:=NULL; before_clock:=NULL;
  END IF;
  IF r->'deadline'<>'null'::JSONB AND r->>'phase' NOT IN ('AWAITING_RULING','RESOLVED') THEN
   IF r->'overallDeadline'<>'null'::JSONB AND moment>=(r->>'overallDeadline')::DOUBLE PRECISION THEN close_now:=TRUE; anchor:=(r->>'overallDeadline')::DOUBLE PRECISION;
   ELSIF moment>=(r->>'deadline')::DOUBLE PRECISION THEN
    anchor:=(r->>'deadline')::DOUBLE PRECISION;
    IF r->>'phase' IN ('STEAL','SHARED') THEN close_now:=TRUE;
    ELSE
     before_clock:=public.int9_snapshot(r);
     IF r->>'phase' IN ('MAIN','TRAP') THEN
      r:=r||jsonb_build_object('phase','STEAL','phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+1,'generation',(r->>'generation')::INTEGER+1,'deadline',anchor+10000,'currentTeamId',NULL,'pickedPlayerId',NULL,'pickedEventId',NULL,'doubleAttemptTeamId',NULL,'version',(r->>'version')::INTEGER+1,'assignment',NULL); kind:='STEAL_OPENED';
     ELSIF r->>'phase'='TURN' AND execution_format IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN
      elapsed:=floor((moment-anchor)/(turn_seconds*1000))::BIGINT+1; team_index:=array_position(team_order,r->>'currentTeamId')-1;
      IF team_index IS NULL THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
      r:=r||jsonb_build_object('currentTeamId',team_order[((team_index+elapsed)%cardinality(team_order))::INTEGER+1],'deadline',anchor+elapsed::DOUBLE PRECISION*turn_seconds*1000,'phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+elapsed,'generation',(r->>'generation')::INTEGER+elapsed,'doubleAttemptTeamId',NULL,'version',(r->>'version')::INTEGER+1,'assignment',NULL); kind:='TURN_TRANSFERRED';
     ELSE PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
     invalidate:=TRUE; e:=public.int9_clock_event(rid,(r->>'generation')::INTEGER,revision,kind,anchor,moment,NULL); revision:=revision+1; effect_sequence:=effect_sequence+1;
     effect:=public.int9_seal_patch(public.int9_effect_patch(e,effect_sequence,rid,public.int9_snapshot(r),'TIMING',jsonb_build_object('beforeClock',before_clock))); events:=events||jsonb_build_array(e); effects:=effects||jsonb_build_array(effect); e:=NULL; effect:=NULL; before_clock:=NULL;
     IF kind='STEAL_OPENED' AND moment>=(r->>'deadline')::DOUBLE PRECISION THEN close_now:=TRUE; anchor:=(r->>'deadline')::DOUBLE PRECISION; END IF;
    END IF;
   END IF;
  END IF;
  IF close_now THEN
   before_clock:=public.int9_snapshot(r); r:=r||jsonb_build_object('deadline',NULL,'overallDeadline',NULL,'version',(r->>'version')::INTEGER+1,'assignment',NULL); invalidate:=TRUE;
   SELECT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND a."roundId"=rid AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" cl WHERE cl."gameId"=game_id AND cl."attemptId"=a."id")) INTO pending;
   SELECT EXISTS(SELECT 1 FROM public."CompetitiveItemReview" review JOIN public."CompetitiveRuntimeHead" head ON head."gameId"=review."gameId" AND head."openItemReviewId"=review."id" WHERE review."gameId"=game_id AND review."roundId"=rid) INTO review;
   e:=public.int9_clock_event(rid,(r->>'generation')::INTEGER,revision,'RECORDING_CLOSED',anchor,moment,NULL); revision:=revision+1; effect_sequence:=effect_sequence+1;
   IF review THEN active_id:=NULL; turn_index:=turn_index+(CASE WHEN r->'turnAdvanced'='true'::JSONB THEN 0 ELSE 1 END); r:=r||jsonb_build_object('phase',CASE WHEN pending THEN 'AWAITING_RULING' ELSE 'RESOLVED' END,'reason','TIME_EXPIRED','turnAdvanced',TRUE);
   ELSIF pending THEN r:=r||jsonb_build_object('phase','AWAITING_RULING');
   ELSE
    IF (SELECT count(*) FROM public."CompetitiveAttempt" WHERE "gameId"=game_id AND "roundId"=rid)>512 OR EXISTS(SELECT 1 FROM public."CompetitiveAttempt" a LEFT JOIN public."RoundAuthorityEvent" event ON event."gameId"=a."gameId" AND event."id"=a."eventId" WHERE a."gameId"=game_id AND a."roundId"=rid AND (event."id" IS NULL OR event."sequence">=(h->>'version')::INTEGER+1)) THEN PERFORM public.int9_error('ATTEMPT_PROOF_UNAVAILABLE'); END IF;
    SELECT COALESCE(jsonb_agg(a."id" ORDER BY event."sequence",a."id" COLLATE "C"),'[]'::JSONB),COALESCE(jsonb_agg(jsonb_build_object('attemptId',a."id",'teamId',a."teamId",'multiplier',a."payload"->'bonusMultiplier','sourceEventId',a."bonusEventId") ORDER BY event."sequence",a."id" COLLATE "C"),'[]'::JSONB) INTO originals,bonus FROM public."CompetitiveAttempt" a JOIN public."RoundAuthorityEvent" event ON event."gameId"=a."gameId" AND event."id"=a."eventId" WHERE a."gameId"=game_id AND a."roundId"=rid;
    active_id:=NULL; turn_index:=turn_index+(CASE WHEN r->'turnAdvanced'='true'::JSONB THEN 0 ELSE 1 END); r:=r||jsonb_build_object('phase','RESOLVED','reason','TIME_EXPIRED','pause',NULL,'version',(r->>'version')::INTEGER+1,'turnAdvanced',TRUE);
   END IF;
   effect:=public.int9_seal_patch(public.int9_effect_patch(e,effect_sequence,rid,public.int9_snapshot(r),CASE WHEN NOT review AND NOT pending THEN 'NO_SCORE' ELSE 'TIMING' END,CASE WHEN NOT review AND NOT pending THEN jsonb_build_object('beforeClock',before_clock,'reversible',format NOT IN ('LIST_ITEMS','ACTING_ITEMS'),'originalAttemptIds',originals,'bonusSnapshot',bonus) ELSE jsonb_build_object('beforeClock',before_clock) END)); originals:=NULL; bonus:=NULL;
   IF NOT review AND NOT pending THEN heads:=jsonb_build_array(jsonb_build_object('roundId',rid,'itemId',NULL,'scopeId',public.int6_enta_canonical(jsonb_build_array(rid,NULL)),'originalEffectId',effect->'id','effectId',effect->'id','version',1,'hash',effect->'hash','reversed',FALSE)); END IF;
   events:=events||jsonb_build_array(e); effects:=effects||jsonb_build_array(effect); e:=NULL; effect:=NULL; before_clock:=NULL;
  END IF;
 END IF;
 IF events='[]'::JSONB THEN RETURN FALSE; END IF;
 SELECT COALESCE(jsonb_object_agg(key,value),'{}'::JSONB) INTO fields FROM jsonb_each(r) WHERE key<>'id' AND value IS DISTINCT FROM (SELECT "state"->key FROM public."GameRound" WHERE "gameId"=game_id AND "id"=rid);
 b:=jsonb_build_object('id',game_id,'identityId',identity_id,'admissionId',admission_id,'beforeVersion',h->'version','finalRevision',revision,'events',events,'effects',effects,'rulings',heads,'roundChanges',jsonb_build_array(jsonb_build_object('id',rid,'fields',fields)),'runtimeChanges',jsonb_build_object('activeRoundId',active_id,'turnIndex',turn_index),'headChanges',jsonb_build_object('latestEffectId',effects->-1->'id'));
 IF invalidate THEN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',scope."id",'roundId',scope."roundId",'role',scope."role",'assignmentId',scope."assignmentId",'generation',scope."generation",'activeGrantId',NULL)),'[]'::JSONB),COALESCE(jsonb_agg(jsonb_build_object('id',gr."id",'scopeId',gr."scopeId",'roundId',gr."roundId",'role',gr."role",'assignmentId',gr."assignmentId",'generation',gr."generation",'tokenHash',gr."tokenHash",'expiresAt',floor(extract(epoch FROM gr."expiresAt")*1000),'revoked',TRUE)) FILTER(WHERE gr."id" IS NOT NULL),'[]'::JSONB) INTO scopes,grants FROM public."RoundGrantScope" scope LEFT JOIN public."RoundGrant" gr ON gr."gameId"=scope."gameId" AND gr."id"=scope."activeGrantId" WHERE scope."gameId"=game_id AND scope."roundId"=rid AND scope."activeGrantId" IS NOT NULL;
  b:=b||jsonb_build_object('grantScopes',scopes,'grants',grants);
 END IF;
 r:=NULL; fields:=NULL; scopes:=NULL; grants:=NULL; events:=NULL; effects:=NULL; heads:=NULL; team_order:=NULL;
 PERFORM public.int9_store_batch(b,h); b:=NULL; h:=NULL; PERFORM public.int9_assert_stored(game_id); RETURN TRUE;
END $$;
CREATE FUNCTION public.int9_assert_capacity_round(game_id TEXT,round_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE r RECORD; chosen_lane TEXT; used JSONB; reserved JSONB; limit_value INTEGER; current_head public."CompetitiveCapacityHead"%ROWTYPE; all_used JSONB; all_reserved JSONB; BEGIN
 SELECT "id","state" INTO r FROM public."GameRound" WHERE "gameId"=game_id AND "id"=round_id; IF r."id" IS NULL THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
  all_used:='{}'::JSONB; all_reserved:='{}'::JSONB;
  FOREACH chosen_lane IN ARRAY ARRAY['ATTEMPT','INTERIM','CANVAS','PUBLIC','INITIAL','OPEN_CLOSE','SYSTEM','OPTIONAL','PROTECTED'] LOOP
   used:=public.int9_capacity_vector(game_id,r."id",chosen_lane,FALSE); reserved:=public.int9_capacity_vector(game_id,r."id",chosen_lane,TRUE); limit_value:=public.int9_capacity_limit(r."id",chosen_lane);
   IF (used->>'events')::BIGINT+(reserved->>'events')::BIGINT>limit_value OR (used->>'effects')::BIGINT+(reserved->>'effects')::BIGINT>limit_value THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
   all_used:=all_used||jsonb_build_object(chosen_lane,used); all_reserved:=all_reserved||jsonb_build_object(chosen_lane,reserved);
  END LOOP;
  SELECT "reserved","resourceEventId","roundId","used","version" INTO current_head."reserved",current_head."resourceEventId",current_head."roundId",current_head."used",current_head."version" FROM public."CompetitiveCapacityHead" WHERE "gameId"=game_id AND "roundId"=r."id";
  IF current_head."roundId" IS NULL OR current_head."used" IS DISTINCT FROM all_used OR current_head."reserved" IS DISTINCT FROM all_reserved OR current_head."version" IS DISTINCT FROM COALESCE((SELECT max("sequence") FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "roundId"=r."id"),1) OR current_head."resourceEventId" IS DISTINCT FROM r."state"->'resourceStop'->>'eventId' OR (SELECT count(*) FROM public."CompetitiveAttempt" WHERE "gameId"=game_id AND "roundId"=r."id")>public.int9_capacity_limit(r."id",'ATTEMPT') OR (SELECT count(*) FROM public."CompetitiveClassification" c JOIN public."CompetitiveAttempt" a ON a."gameId"=c."gameId" AND a."id"=c."attemptId" WHERE c."gameId"=game_id AND a."roundId"=r."id")>public.int9_capacity_limit(r."id",'ATTEMPT') OR (SELECT count(*) FROM public."RoundGrantScope" WHERE "gameId"=game_id AND "roundId"=r."id" AND "activeGrantId" IS NOT NULL)>2 THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;

END $$;
CREATE FUNCTION public.int9_assert_attempt(game_id TEXT,attempt_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE a public."CompetitiveAttempt"%ROWTYPE; x JSONB; BEGIN
 SELECT "acceptedAt","allowanceId","bonusEventId","deadline","disclosureHeadId","eligibilityHash","eventId","generation","id","itemId","ordinal","payload","phase","phaseOrdinal","pickedEventId","playerId","roundId","teamId" INTO a."acceptedAt",a."allowanceId",a."bonusEventId",a."deadline",a."disclosureHeadId",a."eligibilityHash",a."eventId",a."generation",a."id",a."itemId",a."ordinal",a."payload",a."phase",a."phaseOrdinal",a."pickedEventId",a."playerId",a."roundId",a."teamId" FROM public."CompetitiveAttempt" WHERE "gameId"=game_id AND "id"=attempt_id; x:=a."payload";
 IF a."id" IS NULL OR octet_length(convert_to(public.int6_enta_canonical(x),'UTF8'))>2048 OR public.int6_enta_exact_keys(x,ARRAY['id','roundId','itemId','phase','phaseOrdinal','generation','teamId','playerId','ordinal','acceptedAt','deadline','eventId','pickedEventId','allowanceId','bonusEventId','bonusMultiplier','disclosureHead','eligiblePlayerIds','eligibilityHash']) IS NOT TRUE OR x->>'id' IS DISTINCT FROM a."id" OR x->>'roundId' IS DISTINCT FROM a."roundId" OR x->>'itemId' IS DISTINCT FROM a."itemId" OR x->>'teamId' IS DISTINCT FROM a."teamId" OR x->>'playerId' IS DISTINCT FROM a."playerId" OR x->>'eventId' IS DISTINCT FROM a."eventId" OR x->>'phase' IS DISTINCT FROM a."phase" OR x->'phaseOrdinal' IS DISTINCT FROM to_jsonb(a."phaseOrdinal") OR x->'generation' IS DISTINCT FROM to_jsonb(a."generation") OR x->'ordinal' IS DISTINCT FROM to_jsonb(a."ordinal") OR x->>'pickedEventId' IS DISTINCT FROM a."pickedEventId" OR x->>'allowanceId' IS DISTINCT FROM a."allowanceId" OR x->>'bonusEventId' IS DISTINCT FROM a."bonusEventId" OR x->>'disclosureHead' IS DISTINCT FROM a."disclosureHeadId" OR x->>'eligibilityHash' IS DISTINCT FROM a."eligibilityHash" OR to_timestamp((x->>'acceptedAt')::DOUBLE PRECISION/1000) IS DISTINCT FROM a."acceptedAt" OR to_timestamp((x->>'deadline')::DOUBLE PRECISION/1000) IS DISTINCT FROM a."deadline" OR a."acceptedAt">=a."deadline" OR a."phase" NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN') OR a."phaseOrdinal" NOT BETWEEN 1 AND 2000000000 OR a."generation" NOT BETWEEN 1 AND 2000000000 OR a."ordinal" NOT BETWEEN 1 AND 512 OR x->'bonusMultiplier' NOT IN ('1'::JSONB,'2'::JSONB) OR jsonb_typeof(x->'eligiblePlayerIds') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'eligiblePlayerIds') NOT BETWEEN 1 AND 8 OR NOT x->'eligiblePlayerIds' @> jsonb_build_array(a."playerId") OR x->>'eligibilityHash' IS DISTINCT FROM public.int6_enta_hash(jsonb_build_object('roundId',x->'roundId','phase',x->'phase','phaseOrdinal',x->'phaseOrdinal','generation',x->'generation','teamId',x->'teamId','playerId',x->'playerId','eligiblePlayerIds',x->'eligiblePlayerIds','pickedEventId',x->'pickedEventId','disclosureHead',x->'disclosureHead','deadline',x->'deadline')) THEN PERFORM public.int9_error('ATTEMPT_PROOF_UNAVAILABLE'); END IF;
 IF (SELECT count(DISTINCT id) FROM jsonb_array_elements(x->'eligiblePlayerIds') id)<>jsonb_array_length(x->'eligiblePlayerIds') OR EXISTS(SELECT 1 FROM jsonb_array_elements(x->'eligiblePlayerIds') id WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveRosterPlayer" player WHERE player."gameId"=game_id AND player."teamId"=a."teamId" AND player."playerId"=id#>>'{}')) OR NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" event WHERE event."gameId"=game_id AND event."id"=a."eventId" AND event."roundId"=a."roundId" AND event."type"='RECORD_ATTEMPT' AND event."authorityKind"='HOST' AND event."at"=a."acceptedAt") THEN PERFORM public.int9_error('ATTEMPT_PROOF_UNAVAILABLE'); END IF;
END $$;
CREATE FUNCTION public.int9_assert_ruling(game_id TEXT,scope_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE h public."CompetitiveRulingHead"%ROWTYPE; leaf JSONB; proof JSONB; previous_sequence INTEGER; count_chain INTEGER:=0; BEGIN
 SELECT "effectId","gameId","hash","itemId","originalEffectId","reversed","roundId","scopeId","version" INTO h."effectId",h."gameId",h."hash",h."itemId",h."originalEffectId",h."reversed",h."roundId",h."scopeId",h."version" FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id AND "scopeId"=scope_id;
 IF h."gameId" IS NULL OR h."scopeId" IS DISTINCT FROM public.int6_enta_canonical(jsonb_build_array(h."roundId",h."itemId")) OR h."version" NOT BETWEEN 1 AND 257 THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF;
 proof:=public.int9_effect_proof(game_id,h."effectId"); leaf:=proof->'effect';
 IF leaf->>'hash' IS DISTINCT FROM h."hash" OR leaf->>'roundId' IS DISTINCT FROM h."roundId" OR h."reversed" IS DISTINCT FROM (leaf->>'kind'='REVERSAL') OR EXISTS(SELECT 1 FROM public."CompetitiveEffect" later WHERE later."gameId"=game_id AND later."predecessorId"=h."effectId") THEN PERFORM public.int9_error('STALE_RULING_HEAD'); END IF;
 LOOP
  count_chain:=count_chain+1; IF count_chain>257 OR leaf->>'roundId' IS DISTINCT FROM h."roundId" OR previous_sequence IS NOT NULL AND (leaf->>'sequence')::INTEGER>=previous_sequence THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF;
  IF leaf->>'id'=h."originalEffectId" THEN IF count_chain<>h."version" OR leaf->>'kind' NOT IN ('RULING','NO_SCORE') OR leaf->>'predecessorId' IS NOT NULL THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF; EXIT; END IF;
  IF leaf->>'kind' NOT IN ('CORRECTION','REVERSAL') OR leaf->>'predecessorId' IS NULL THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF;
  previous_sequence:=(leaf->>'sequence')::INTEGER; proof:=public.int9_effect_proof(game_id,leaf->>'predecessorId'); IF proof->'effect'->'hash' IS DISTINCT FROM leaf->'predecessorHash' THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF; leaf:=proof->'effect';
 END LOOP;
END $$;
CREATE FUNCTION public.int9_assert_effect(game_id TEXT,effect_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE proof JSONB:=public.int9_effect_proof(game_id,effect_id); e JSONB:=proof->'effect'; x JSONB; a public."CompetitiveAttempt"%ROWTYPE; posting_row RECORD; BEGIN
 IF (SELECT count(*) FROM public."CompetitiveEffectAttempt" WHERE "gameId"=game_id AND "effectId"=effect_id)<>jsonb_array_length(e->'originalAttemptIds') OR (SELECT count(DISTINCT id) FROM jsonb_array_elements(e->'originalAttemptIds') id)<>jsonb_array_length(e->'originalAttemptIds') OR jsonb_array_length(e->'originalAttemptIds')>512 OR jsonb_array_length(e->'correctAttemptIds')>512 OR (CASE WHEN e->>'kind'='INTERIM' THEN jsonb_array_length(e->'bonusSnapshot')<>0 OR jsonb_array_length(e->'originalAttemptIds')<>1 OR jsonb_array_length(e->'correctAttemptIds')<>0 ELSE jsonb_array_length(e->'bonusSnapshot')<>jsonb_array_length(e->'originalAttemptIds') END) OR EXISTS(SELECT 1 FROM jsonb_array_elements(e->'correctAttemptIds') id WHERE NOT e->'originalAttemptIds' @> jsonb_build_array(id)) THEN PERFORM public.int9_error('BONUS_PROOF_UNAVAILABLE'); END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(e->'originalAttemptIds') LOOP
  SELECT "bonusEventId","id","payload","roundId","teamId" INTO a."bonusEventId",a."id",a."payload",a."roundId",a."teamId" FROM public."CompetitiveAttempt" WHERE "gameId"=game_id AND "id"=x#>>'{}' AND "roundId"=e->>'roundId'; IF a."id" IS NULL THEN PERFORM public.int9_error('ATTEMPT_PROOF_UNAVAILABLE'); END IF;
  IF e->>'kind'='INTERIM' THEN IF NOT EXISTS(SELECT 1 FROM public."CompetitiveEffectAttempt" physical WHERE physical."gameId"=game_id AND physical."effectId"=effect_id AND physical."roundId"=a."roundId" AND physical."attemptId"=a."id" AND physical."correct"=FALSE AND physical."bonusMultiplier"=1 AND physical."bonusEventId" IS NULL) THEN PERFORM public.int9_error('BONUS_PROOF_UNAVAILABLE'); END IF; CONTINUE; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(e->'bonusSnapshot') bonus WHERE bonus->'attemptId'=x AND bonus->>'teamId'=a."teamId" AND bonus->'multiplier'=a."payload"->'bonusMultiplier' AND bonus->'sourceEventId' IS NOT DISTINCT FROM a."payload"->'bonusEventId')<>1 OR NOT EXISTS(SELECT 1 FROM public."CompetitiveEffectAttempt" physical WHERE physical."gameId"=game_id AND physical."effectId"=effect_id AND physical."roundId"=a."roundId" AND physical."attemptId"=a."id" AND physical."correct"=(e->'correctAttemptIds' @> jsonb_build_array(x)) AND physical."bonusMultiplier"=(a."payload"->>'bonusMultiplier')::INTEGER AND physical."bonusEventId" IS NOT DISTINCT FROM a."bonusEventId") THEN PERFORM public.int9_error('BONUS_PROOF_UNAVAILABLE'); END IF;
 END LOOP;
 IF e->>'kind' IN ('RULING','NO_SCORE') AND e->'predecessorId'='null'::JSONB THEN
  IF (e->>'kind'='RULING') IS DISTINCT FROM (jsonb_array_length(e->'correctAttemptIds')>0) OR e->>'kind'='NO_SCORE' AND EXISTS(SELECT 1 FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "effectId"=effect_id) OR public.int9_historical_empty_closure(game_id,effect_id) IS NOT TRUE AND EXISTS(SELECT 1 FROM jsonb_array_elements(e->'originalAttemptIds') original LEFT JOIN public."CompetitiveClassification" classification ON classification."gameId"=game_id AND classification."attemptId"=original#>>'{}' WHERE classification."id" IS NULL OR classification."correct" IS DISTINCT FROM (e->'correctAttemptIds' @> jsonb_build_array(original)) OR classification."correct" AND (classification."eventId" IS DISTINCT FROM e->>'eventId' OR classification."interim") OR NOT classification."correct" AND NOT classification."interim" AND classification."eventId" IS DISTINCT FROM e->>'eventId') THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF;
 END IF;
 FOR posting_row IN SELECT "before","previousHeadId","scoreVersion","teamId" FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "effectId"=effect_id LOOP
  IF posting_row."scoreVersion"=1 THEN IF posting_row."before"<>0 OR posting_row."previousHeadId" IS NOT NULL THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
  ELSE IF NOT EXISTS(SELECT 1 FROM public."CompetitiveScorePosting" previous JOIN public."CompetitiveEffect" previous_effect ON previous_effect."gameId"=previous."gameId" AND previous_effect."id"=previous."effectId" WHERE previous."gameId"=game_id AND previous."teamId"=posting_row."teamId" AND previous."scoreVersion"=posting_row."scoreVersion"-1 AND previous."effectId"=posting_row."previousHeadId" AND previous."after"=posting_row."before" AND previous_effect."sequence"<(e->>'sequence')::INTEGER) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF; END IF;
 END LOOP;
END $$;
CREATE FUNCTION public.int9_assert_capacity(game_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE r RECORD; chosen_lane TEXT; used JSONB; reserved JSONB; limit_value INTEGER; current_head public."CompetitiveCapacityHead"%ROWTYPE; all_used JSONB; all_reserved JSONB; BEGIN
 IF EXISTS(SELECT 1 FROM public."CompetitiveCapacityClaim" c WHERE c."gameId"=game_id AND (c."cost" IS DISTINCT FROM public.int9_claim_cost(c."sourceKind") OR c."id" IS DISTINCT FROM public.int6_enta_canonical(jsonb_build_array(c."sourceKind",c."roundId",c."sourceId")) OR c."lane" IS DISTINCT FROM (CASE WHEN c."sourceKind"='ATTEMPT' THEN 'INTERIM' WHEN c."sourceKind" IN ('ITEM','ROUND') THEN 'INITIAL' WHEN c."sourceKind"='FINISH' THEN 'PROTECTED' ELSE 'OPTIONAL' END))) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 IF (SELECT count(*) FROM public."CompetitiveCapacityCharge" WHERE "gameId"=game_id)<>(SELECT count(*) FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id) OR (SELECT COALESCE(sum(("cost"->>'effects')::BIGINT),0) FROM public."CompetitiveCapacityCharge" WHERE "gameId"=game_id)<>(SELECT count(*) FROM public."CompetitiveEffect" WHERE "gameId"=game_id) OR (SELECT COALESCE(sum(("cost"->>'classifications')::BIGINT),0) FROM public."CompetitiveCapacityCharge" WHERE "gameId"=game_id)<>(SELECT count(*) FROM public."CompetitiveClassification" WHERE "gameId"=game_id) OR (SELECT COALESCE(sum(("cost"->>'postings')::BIGINT),0) FROM public."CompetitiveCapacityCharge" WHERE "gameId"=game_id)<>(SELECT count(*) FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 FOR r IN SELECT "id" FROM public."GameRound" WHERE "gameId"=game_id ORDER BY "ordinal" LOOP PERFORM public.int9_assert_capacity_round(game_id,r."id"); END LOOP;
 IF (SELECT count(*) FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "sourceKind"='ATTEMPT')<>(SELECT count(*) FROM public."CompetitiveAttempt" WHERE "gameId"=game_id) OR (SELECT count(*) FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "sourceKind"='ITEM')<>(SELECT count(*) FROM public."RoundItemPin" item JOIN public."GameRound" r ON r."id"=item."roundId" WHERE r."gameId"=game_id) OR (SELECT count(*) FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "sourceKind"='ROUND')<>(SELECT count(*) FROM public."GameRound" WHERE "gameId"=game_id) OR (SELECT count(*) FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "sourceKind"='FINISH')<>1 THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 IF (SELECT count(*) FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "sourceKind"='REVIEW')<>(SELECT count(*) FROM public."CompetitiveItemReview" WHERE "gameId"=game_id) OR (SELECT count(*) FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "sourceKind"='GRANT')<>(SELECT count(*) FROM public."RoundGrant" g JOIN public."RoundAuthorityEvent" e ON e."gameId"=g."gameId" AND e."id"=g."id" WHERE g."gameId"=game_id AND e."type" IN ('CREATE_GRANT','ROTATE_GRANT')) OR (SELECT count(*) FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "sourceKind"='PAUSE')<>(SELECT count(*) FROM public."RoundAuthorityEvent" e WHERE e."gameId"=game_id AND (e."type"='PAUSE_ROUND' OR e."type"='USE_AID' AND EXISTS(SELECT 1 FROM public."CompetitiveEffect" effect WHERE effect."gameId"=game_id AND effect."eventId"=e."id" AND effect."payload"->>'aid' IN ('PHONE','PHONE_A_FRIEND','FREEZE')))) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
END $$;
CREATE FUNCTION public.int9_assert_charge(game_id TEXT,event_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE charge public."CompetitiveCapacityCharge"%ROWTYPE; event public."RoundAuthorityEvent"%ROWTYPE; BEGIN
 SELECT "cost","eventId","lane","roundId" INTO charge."cost",charge."eventId",charge."lane",charge."roundId" FROM public."CompetitiveCapacityCharge" WHERE "gameId"=game_id AND "eventId"=event_id; SELECT "authorityKind","id","roundId","type" INTO event."authorityKind",event."id",event."roundId",event."type" FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "id"=event_id;
 IF charge."eventId" IS NULL OR event."id" IS NULL OR charge."roundId" IS DISTINCT FROM event."roundId" OR charge."lane" IS DISTINCT FROM public.int9_capacity_lane(event."type",event."authorityKind") OR charge."cost" IS DISTINCT FROM public.int9_cost(1,(SELECT count(*)::INTEGER FROM public."CompetitiveEffect" e WHERE e."gameId"=game_id AND e."eventId"=event_id),(SELECT count(*)::INTEGER FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."eventId"=event_id),(SELECT count(*)::INTEGER FROM public."CompetitiveEffect" e WHERE e."gameId"=game_id AND e."eventId"=event_id AND e."kind" IN ('RULING','NO_SCORE','REVERSAL','CORRECTION')),(SELECT count(*)::INTEGER FROM public."CompetitiveItemConsumption" c JOIN public."CompetitiveEffect" e ON e."gameId"=c."gameId" AND e."id"=c."effectId" WHERE c."gameId"=game_id AND e."eventId"=event_id),(SELECT count(*)::INTEGER FROM public."CompetitiveScorePosting" p JOIN public."CompetitiveEffect" e ON e."gameId"=p."gameId" AND e."id"=p."effectId" WHERE p."gameId"=game_id AND e."eventId"=event_id)) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
END $$;
CREATE FUNCTION public.int9_assert_claim(game_id TEXT,claim_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c public."CompetitiveCapacityClaim"%ROWTYPE; d public."CompetitiveCapacityDisposition"%ROWTYPE; event public."RoundAuthorityEvent"%ROWTYPE; valid_source BOOLEAN:=FALSE; valid_disposition BOOLEAN:=FALSE; BEGIN
 SELECT "cost","id","roundId","sourceId","sourceKind" INTO c."cost",c."id",c."roundId",c."sourceId",c."sourceKind" FROM public."CompetitiveCapacityClaim" WHERE "gameId"=game_id AND "id"=claim_id; SELECT "claimId","eventId","kind" INTO d."claimId",d."eventId",d."kind" FROM public."CompetitiveCapacityDisposition" WHERE "gameId"=game_id AND "claimId"=claim_id; SELECT "authorityKind","id","roundId","type" INTO event."authorityKind",event."id",event."roundId",event."type" FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "id"=d."eventId";
 IF c."id" IS NULL OR c."cost" IS DISTINCT FROM public.int9_claim_cost(c."sourceKind") OR c."id" IS DISTINCT FROM public.int6_enta_canonical(jsonb_build_array(c."sourceKind",c."roundId",c."sourceId")) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 CASE c."sourceKind"
 WHEN 'ATTEMPT' THEN valid_source:=EXISTS(SELECT 1 FROM public."CompetitiveAttempt" WHERE "gameId"=game_id AND "roundId"=c."roundId" AND "id"=c."sourceId"); valid_disposition:=d."kind"='CONSUME' AND EXISTS(SELECT 1 FROM public."CompetitiveClassification" WHERE "gameId"=game_id AND "attemptId"=c."sourceId" AND "eventId"=d."eventId");
 WHEN 'ITEM' THEN valid_source:=EXISTS(SELECT 1 FROM public."RoundItemPin" item JOIN public."GameRound" r ON r."id"=item."roundId" WHERE r."gameId"=game_id AND r."id"=c."roundId" AND item."itemId"=c."sourceId"); valid_disposition:=(CASE WHEN d."kind"='CONSUME' THEN EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used JOIN public."CompetitiveEffect" e ON e."gameId"=used."gameId" AND e."id"=used."effectId" WHERE used."gameId"=game_id AND used."roundId"=c."roundId" AND used."itemId"=c."sourceId" AND e."eventId"=d."eventId") ELSE public.int9_closing_event(game_id,c."roundId",d."eventId") AND event."roundId"=c."roundId" AND EXISTS(SELECT 1 FROM public."GameRound" WHERE "gameId"=game_id AND "id"=c."roundId" AND "state"->>'phase'='RESOLVED') AND NOT EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" WHERE "gameId"=game_id AND "roundId"=c."roundId" AND "itemId"=c."sourceId") END);
 WHEN 'ROUND' THEN valid_source:=c."sourceId"=c."roundId" AND EXISTS(SELECT 1 FROM public."GameRound" WHERE "gameId"=game_id AND "id"=c."roundId"); valid_disposition:=event."roundId"=c."roundId" AND (CASE WHEN d."kind"='CONSUME' THEN EXISTS(SELECT 1 FROM public."CompetitiveRulingHead" h JOIN public."CompetitiveEffect" effect ON effect."gameId"=h."gameId" AND effect."id"=h."originalEffectId" WHERE h."gameId"=game_id AND h."roundId"=c."roundId" AND h."itemId" IS NULL AND effect."eventId"=d."eventId" AND effect."kind" IN ('RULING','NO_SCORE') AND effect."predecessorId" IS NULL) ELSE public.int9_closing_event(game_id,c."roundId",d."eventId") AND NOT EXISTS(SELECT 1 FROM public."CompetitiveRulingHead" h WHERE h."gameId"=game_id AND h."roundId"=c."roundId" AND h."itemId" IS NULL) END);
 WHEN 'REVIEW' THEN valid_source:=EXISTS(SELECT 1 FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "roundId"=c."roundId" AND "id"=c."sourceId"); valid_disposition:=d."kind"='CONSUME' AND EXISTS(SELECT 1 FROM public."CompetitiveItemResolution" WHERE "gameId"=game_id AND "reviewId"=c."sourceId" AND "eventId"=d."eventId");
 WHEN 'BOARD_REVIEW' THEN valid_source:=EXISTS(SELECT 1 FROM public."CompetitiveReversal" v JOIN public."CompetitiveRulingHead" h ON h."gameId"=v."gameId" AND h."originalEffectId"=v."originalEffectId" JOIN public."GameRound" r ON r."gameId"=h."gameId" AND r."id"=h."roundId" WHERE v."gameId"=game_id AND v."reversalEffectId"=c."sourceId" AND h."roundId"=c."roundId" AND h."itemId" IS NULL AND r."pin"->>'format' IN ('ORDINARY_TIER','DRAWING_TARGET')); valid_disposition:=d."kind"='CONSUME' AND event."type"='CORRECT_RULING' AND EXISTS(SELECT 1 FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "eventId"=d."eventId" AND "predecessorId"=c."sourceId" AND "kind"='CORRECTION');
 WHEN 'PAUSE' THEN valid_source:=EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" source WHERE source."gameId"=game_id AND source."roundId"=c."roundId" AND source."id"=c."sourceId" AND source."type" IN ('PAUSE_ROUND','USE_AID')); valid_disposition:=d."kind"='CONSUME' AND event."roundId"=c."roundId" AND event."type" IN ('PHONE_ENDED','RESUME_ROUND','END_ASSISTANCE');
 WHEN 'GRANT' THEN valid_source:=EXISTS(SELECT 1 FROM public."RoundGrant" WHERE "gameId"=game_id AND "roundId"=c."roundId" AND "id"=c."sourceId"); valid_disposition:=event."roundId"=c."roundId" AND EXISTS(SELECT 1 FROM public."RoundGrant" WHERE "gameId"=game_id AND "id"=c."sourceId" AND "revoked") AND (CASE WHEN d."kind"='CONSUME' THEN event."type"='REVOKE_GRANT' ELSE event."type" IN ('ROTATE_GRANT','ASSIGN_ACTOR','PAUSE_ROUND','USE_AID','PUBLIC_REVEAL','FINAL_RULING','UNDO_EFFECT','CLOSE_ROUND','PHONE_ENDED','STEAL_OPENED','TURN_TRANSFERRED','RECORDING_CLOSED','RESOURCE_LIMIT_REACHED') END);
 WHEN 'FINISH' THEN valid_source:=c."roundId" IS NULL AND c."sourceId"=game_id; valid_disposition:=d."kind"='CONSUME' AND event."type"='FINISH' AND event."roundId" IS NULL AND event."authorityKind"='HOST';
 ELSE PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END CASE;
 IF valid_source IS NOT TRUE OR d."claimId" IS NOT NULL AND (event."id" IS NULL OR valid_disposition IS NOT TRUE) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
END $$;
CREATE FUNCTION public.int9_assert_review(game_id TEXT,review_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE review public."CompetitiveItemReview"%ROWTYPE; h public."CompetitiveRulingHead"%ROWTYPE; resolution public."CompetitiveItemResolution"%ROWTYPE; original JSONB; reversal JSONB; successor JSONB; x JSONB; BEGIN
 SELECT "consumptionEffectId","eventId","hash","id","itemId","originalEffectId","originalHash","payload","predecessorHash","predecessorVersion","reversalEffectId","roundId" INTO review."consumptionEffectId",review."eventId",review."hash",review."id",review."itemId",review."originalEffectId",review."originalHash",review."payload",review."predecessorHash",review."predecessorVersion",review."reversalEffectId",review."roundId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=review_id; SELECT "effectId","hash","itemId","reversed","roundId","version" INTO h."effectId",h."hash",h."itemId",h."reversed",h."roundId",h."version" FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id AND "originalEffectId"=review."originalEffectId"; SELECT "effectId","eventId","id","mode","reviewHash","rulingHash","rulingVersion" INTO resolution."effectId",resolution."eventId",resolution."id",resolution."mode",resolution."reviewHash",resolution."rulingHash",resolution."rulingVersion" FROM public."CompetitiveItemResolution" WHERE "gameId"=game_id AND "reviewId"=review_id;
 x:=review."payload"; original:=public.int9_effect_proof(game_id,review."originalEffectId")->'effect'; reversal:=public.int9_effect_proof(game_id,review."reversalEffectId")->'effect';
 IF public.int6_enta_exact_keys(x,ARRAY['id','roundId','itemId','originalEffectId','originalEffectHash','reversalEffectId','predecessorRulingVersion','predecessorRulingHash','originalAttemptIds','consumptionEffectId','eventId','hash']) IS NOT TRUE OR review."id" IS NULL OR x->>'id' IS DISTINCT FROM review."id" OR x->>'roundId' IS DISTINCT FROM review."roundId" OR x->>'itemId' IS DISTINCT FROM review."itemId" OR x->>'originalEffectId' IS DISTINCT FROM review."originalEffectId" OR x->>'originalEffectHash' IS DISTINCT FROM review."originalHash" OR x->>'reversalEffectId' IS DISTINCT FROM review."reversalEffectId" OR x->>'consumptionEffectId' IS DISTINCT FROM review."consumptionEffectId" OR x->>'eventId' IS DISTINCT FROM review."eventId" OR x->'predecessorRulingVersion' IS DISTINCT FROM to_jsonb(review."predecessorVersion") OR x->>'predecessorRulingHash' IS DISTINCT FROM review."predecessorHash" OR x->>'hash' IS DISTINCT FROM review."hash" OR review."hash" IS DISTINCT FROM public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.item-review.v1','payload',x-'hash')) OR x->'originalAttemptIds' IS DISTINCT FROM original->'originalAttemptIds' OR original->>'hash' IS DISTINCT FROM review."originalHash" OR reversal->>'kind' IS DISTINCT FROM 'REVERSAL' OR reversal->>'predecessorId' IS DISTINCT FROM review."originalEffectId" OR reversal->>'predecessorHash' IS DISTINCT FROM review."originalHash" OR reversal->>'eventId' IS DISTINCT FROM review."eventId" OR review."predecessorVersion"<>1 OR review."predecessorHash" IS DISTINCT FROM review."originalHash" OR NOT EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" consumed WHERE consumed."gameId"=game_id AND consumed."roundId"=review."roundId" AND consumed."itemId"=review."itemId" AND consumed."effectId"=review."consumptionEffectId" AND consumed."effectId"=review."originalEffectId") OR h."roundId" IS DISTINCT FROM review."roundId" OR h."itemId" IS DISTINCT FROM review."itemId" THEN PERFORM public.int9_error('RULING_PROOF_UNAVAILABLE'); END IF;
 IF resolution."id" IS NULL THEN IF h."effectId" IS DISTINCT FROM review."reversalEffectId" OR h."version"<>2 OR h."reversed" IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM public."CompetitiveRuntimeHead" head WHERE head."gameId"=game_id AND head."openItemReviewId"=review_id AND head."openItemReviewHash"=review."hash") THEN PERFORM public.int9_error('STALE_REVIEW_HEAD'); END IF;
 ELSE
  successor:=public.int9_effect_proof(game_id,resolution."effectId")->'effect';
  IF resolution."reviewHash" IS DISTINCT FROM review."hash" OR resolution."rulingVersion"<>3 OR resolution."rulingHash" IS DISTINCT FROM successor->>'hash' OR successor->>'kind' IS DISTINCT FROM 'CORRECTION' OR successor->>'predecessorId' IS DISTINCT FROM review."reversalEffectId" OR successor->'predecessorHash' IS DISTINCT FROM reversal->'hash' OR successor->>'eventId' IS DISTINCT FROM resolution."eventId" OR resolution."mode" NOT IN ('RESTORE_ORIGINAL','REPLACE') OR successor->'originalAttemptIds' IS DISTINCT FROM original->'originalAttemptIds' OR successor->'bonusSnapshot' IS DISTINCT FROM original->'bonusSnapshot' OR h."effectId" IS DISTINCT FROM resolution."effectId" OR h."version" IS DISTINCT FROM resolution."rulingVersion" OR h."hash" IS DISTINCT FROM resolution."rulingHash" OR h."reversed" IS NOT FALSE OR resolution."mode"='RESTORE_ORIGINAL' AND successor->'correctAttemptIds' IS DISTINCT FROM original->'correctAttemptIds' THEN PERFORM public.int9_error('STALE_REVIEW_HEAD'); END IF;
  IF resolution."mode"='RESTORE_ORIGINAL' AND (SELECT COALESCE(jsonb_object_agg("teamId","delta"),'{}'::JSONB) FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "effectId"=resolution."effectId") IS DISTINCT FROM (SELECT COALESCE(jsonb_object_agg("teamId","delta"),'{}'::JSONB) FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "effectId"=review."originalEffectId") THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 END IF;
END $$;
CREATE FUNCTION public.int9_assert_reversal(game_id TEXT,reversal_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE v public."CompetitiveReversal"%ROWTYPE; original JSONB; reversal JSONB; expected JSONB; actual JSONB; BEGIN
 SELECT "originalEffectId","originalHash" INTO v."originalEffectId",v."originalHash" FROM public."CompetitiveReversal" WHERE "gameId"=game_id AND "reversalEffectId"=reversal_id; original:=public.int9_effect_proof(game_id,v."originalEffectId")->'effect'; reversal:=public.int9_effect_proof(game_id,reversal_id)->'effect';
 IF v."originalEffectId" IS NULL OR original->>'hash' IS DISTINCT FROM v."originalHash" OR reversal->>'kind' IS DISTINCT FROM 'REVERSAL' OR reversal->>'predecessorId' IS DISTINCT FROM v."originalEffectId" OR reversal->>'predecessorHash' IS DISTINCT FROM v."originalHash" OR (reversal->>'sequence')::INTEGER<=(original->>'sequence')::INTEGER OR original->'reversible' IS DISTINCT FROM 'true'::JSONB OR original->>'predecessorId' IS NOT NULL OR NOT (original->>'kind' IN ('RULING','NO_SCORE') OR original->>'kind'='AID' AND original->>'aid'='STEAL_POINTS') OR reversal->'originalAttemptIds' IS DISTINCT FROM original->'originalAttemptIds' OR reversal->'correctAttemptIds' IS DISTINCT FROM original->'correctAttemptIds' OR reversal->'bonusSnapshot' IS DISTINCT FROM original->'bonusSnapshot' OR EXISTS(SELECT 1 FROM public."CompetitiveRulingHead" h JOIN public."GameRound" r ON r."gameId"=h."gameId" AND r."id"=h."roundId" WHERE h."gameId"=game_id AND h."originalEffectId"=v."originalEffectId" AND h."itemId" IS NULL AND r."pin"->>'format' IN ('LIST_ITEMS','ACTING_ITEMS')) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 SELECT COALESCE(jsonb_object_agg("teamId",-"delta"::BIGINT),'{}'::JSONB) INTO expected FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "effectId"=v."originalEffectId"; SELECT COALESCE(jsonb_object_agg("teamId","delta"::BIGINT),'{}'::JSONB) INTO actual FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "effectId"=reversal_id;
 IF expected IS DISTINCT FROM actual THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
END $$;
CREATE FUNCTION public.int9_runtime_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM public."GameCompetitivePin" WHERE "gameId"=NEW."gameId" AND "requestVersion"=5) AND NEW."version"=(SELECT "version" FROM public."GameRuntime" WHERE "gameId"=NEW."gameId") THEN PERFORM public.int9_assert_stored(NEW."gameId"); END IF; RETURN NULL;
END $$;
CREATE FUNCTION public.int9_media_descriptor(proof_id TEXT,media_role TEXT,item_id TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE p public."MediaObjectProof"%ROWTYPE; m public."MediaRevision"%ROWTYPE; BEGIN
 SELECT "byteLength","codec","durationMs","height","id","mediaHash","mediaRevisionId","objectVersion","width" INTO p."byteLength",p."codec",p."durationMs",p."height",p."id",p."mediaHash",p."mediaRevisionId",p."objectVersion",p."width" FROM public."MediaObjectProof" WHERE "id"=proof_id AND "sealedAt" IS NOT NULL; SELECT "id","byteLength","objectKey","mimeType" INTO m."id",m."byteLength",m."objectKey",m."mimeType" FROM public."MediaRevision" WHERE "id"=p."mediaRevisionId" AND "mediaSha256"=p."mediaHash";
 IF p."id" IS NULL OR m."id" IS NULL OR p."byteLength"<>m."byteLength" OR p."byteLength" NOT BETWEEN 1 AND 67108864 OR p."width"<1 OR p."height"<1 OR p."width"::BIGINT*p."height"::BIGINT>16000000 OR m."objectKey"!~'^enta-private/[A-Za-z0-9_/-]{1,180}$' OR position('..' IN m."objectKey")>0 OR p."objectVersion"!~'^[0-9]{1,24}$' THEN PERFORM public.int9_error('MEDIA_PROOF_UNAVAILABLE'); END IF;
 IF public.int8_json_id(to_jsonb(p."id")) IS NOT TRUE OR octet_length(p."mediaRevisionId") NOT BETWEEN 1 AND 1024 OR COALESCE(CASE WHEN m."mimeType" IN ('video/mp4','video/webm') THEN p."durationMs" BETWEEN 1 AND 120000 AND p."codec" IN ('h264','vp8','vp9') ELSE m."mimeType" IN ('image/png','image/jpeg','image/webp') AND p."byteLength"<=10485760 AND p."durationMs" IS NULL AND p."codec" IS NULL END,FALSE) IS NOT TRUE THEN PERFORM public.int9_error('MEDIA_PROOF_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('id',p."id",'objectKey',m."objectKey",'objectVersion',p."objectVersion",'sha256',p."mediaHash",'mime',m."mimeType",'bytes',p."byteLength",'width',p."width",'height',p."height",'durationMs',p."durationMs",'codec',p."codec",'role',media_role,'itemId',item_id);
END $$;
CREATE FUNCTION public.int9_descriptor(prompt_id TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE p public."EntaCompetitivePrompt"%ROWTYPE; f public."EntaFormatRevision"%ROWTYPE; q public."QuestionRevision"%ROWTYPE; items JSONB; media JSONB; hints JSONB; graphemes JSONB; descriptor JSONB; BEGIN
 SELECT "effectValue","effectValueSource","formatId","hintRoot","id","proofHash","questionHash","questionRevisionId" INTO p."effectValue",p."effectValueSource",p."formatId",p."hintRoot",p."id",p."proofHash",p."questionHash",p."questionRevisionId" FROM public."EntaCompetitivePrompt" WHERE "id"=prompt_id; SELECT "categoryKey","contentHash","format","id","opaqueRef","questionHash","questionRevisionId","rules","sourceId","sourceNamespace" INTO f."categoryKey",f."contentHash",f."format",f."id",f."opaqueRef",f."questionHash",f."questionRevisionId",f."rules",f."sourceId",f."sourceNamespace" FROM public."EntaFormatRevision" WHERE "id"=p."formatId" AND "questionRevisionId"=p."questionRevisionId" AND "questionHash"=p."questionHash"; SELECT "id","prompt","points" INTO q."id",q."prompt",q."points" FROM public."QuestionRevision" WHERE "id"=f."questionRevisionId" AND "contentHash"=f."questionHash";
 IF p."id" IS NULL OR f."id" IS NULL OR q."id" IS NULL OR public.int9_prompt_parent(p."id",f."id") IS NOT TRUE OR octet_length(f."sourceNamespace") NOT BETWEEN 1 AND 1024 OR octet_length(f."sourceId") NOT BETWEEN 1 AND 1024 OR public.int6_enta_valid_text(to_jsonb(q."prompt"),1,2000) IS NOT TRUE OR (SELECT count(*) FROM public."EntaFormatItem" WHERE "formatId"=f."id")>128 OR (SELECT count(*) FROM public."EntaFormatMedia" WHERE "formatId"=f."id")>260 OR (SELECT count(DISTINCT "proofId") FROM public."EntaFormatMedia" WHERE "formatId"=f."id")<>(SELECT count(*) FROM public."EntaFormatMedia" WHERE "formatId"=f."id") OR (SELECT count(*) FROM public."EntaCompetitiveHint" WHERE "promptId"=p."id")>4 OR (SELECT count(*) FROM public."EntaCompetitiveGrapheme" WHERE "promptId"=p."id")>128 THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM public."EntaFormatItem" i JOIN public."QuestionAnswerRevision" a ON a."id"=i."answerRevisionId" WHERE i."formatId"=f."id" AND (a."contentHash"<>i."answerHash" OR public.int6_enta_valid_text(to_jsonb(a."text"),1,512) IS NOT TRUE)) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i."id",'revisionId',i."answerRevisionId",'hash',i."answerHash",'ordinal',i."ordinal",'text',a."text",'value',i."value",'trap',i."trap",'mediaIds',(SELECT COALESCE(jsonb_agg(m."proofId" ORDER BY m."ordinal"),'[]'::JSONB) FROM public."EntaFormatMedia" m WHERE m."formatId"=i."formatId" AND m."itemId"=i."id")) ORDER BY i."ordinal"),'[]'::JSONB) INTO items FROM public."EntaFormatItem" i JOIN public."QuestionAnswerRevision" a ON a."id"=i."answerRevisionId" AND a."contentHash"=i."answerHash" WHERE i."formatId"=f."id";
 SELECT COALESCE(jsonb_agg(public.int9_media_descriptor(m."proofId",m."role",m."itemId") ORDER BY m."role" COLLATE "C",m."ordinal"),'[]'::JSONB) INTO media FROM public."EntaFormatMedia" m WHERE m."formatId"=f."id";
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',h."id",'revisionId',h."questionRevisionId",'revisionHash',h."questionHash",'ordinal',h."ordinal",'text',h."text",'contentHash',h."contentHash",'safeDrawing',h."safeDrawing") ORDER BY h."ordinal"),'[]'::JSONB) INTO hints FROM public."EntaCompetitiveHint" h WHERE h."promptId"=p."id";
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',g."id",'answerRevisionId',g."answerRevisionId",'answerHash',g."answerHash",'segmentationVersion',g."segmentationVersion",'grapheme',g."grapheme",'proofHash',g."proofHash") ORDER BY i."ordinal"),'[]'::JSONB) INTO graphemes FROM public."EntaCompetitiveGrapheme" g JOIN public."EntaFormatItem" i ON i."formatId"=f."id" AND i."answerRevisionId"=g."answerRevisionId" AND i."answerHash"=g."answerHash" WHERE g."promptId"=p."id";
 IF public.int8_json_id(to_jsonb(f."id")) IS NOT TRUE OR public.int8_json_id(to_jsonb(f."questionRevisionId")) IS NOT TRUE OR public.int8_json_id(to_jsonb(f."opaqueRef")) IS NOT TRUE OR public.int8_json_id(to_jsonb(f."categoryKey")) IS NOT TRUE OR public.int6_enta_exact_keys(f."rules",ARRAY['version','kind','target']) IS NOT TRUE OR f."rules"->'version' IS DISTINCT FROM '1'::JSONB OR f."rules"->>'kind' IS DISTINCT FROM f."format" OR (CASE WHEN f."format" IN ('ORDINARY_TIER','DRAWING_TARGET') THEN public.int6_enta_valid_text(f."rules"->'target',1,512) IS NOT TRUE OR q."points" NOT IN (200,400,600) ELSE f."rules"->'target' IS DISTINCT FROM 'null'::JSONB END) OR p."effectValue" IS DISTINCT FROM (CASE WHEN f."format" IN ('LIST_ITEMS','ACTING_ITEMS') THEN 200 ELSE q."points" END) OR p."effectValueSource" IS DISTINCT FROM (CASE WHEN f."format" IN ('LIST_ITEMS','ACTING_ITEMS') THEN 'OWNER_EMBEDDED_200' ELSE 'PINNED_TIER' END) OR p."hintRoot" IS DISTINCT FROM public.int6_enta_hash(jsonb_build_object('hints',hints,'graphemes',graphemes)) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(items) WITH ORDINALITY item(value,ordinal) WHERE public.int8_json_id(value->'id') IS NOT TRUE OR public.int8_json_id(value->'revisionId') IS NOT TRUE OR value->'ordinal' IS DISTINCT FROM to_jsonb(ordinal-1)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(media) value WHERE value->>'role' NOT IN ('PROMPT','MASKED','CLEAR','ACTOR','ITEM') OR (value->>'role'='ITEM') IS DISTINCT FROM (value->>'itemId' IS NOT NULL) OR value->>'itemId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(items) item WHERE item->'id'=value->'itemId')) THEN PERFORM public.int9_error('MEDIA_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(hints) WITH ORDINALITY hint(value,ordinal) WHERE public.int8_json_id(value->'id') IS NOT TRUE OR value->'ordinal' IS DISTINCT FROM to_jsonb(ordinal-1) OR value->>'revisionId' IS DISTINCT FROM f."questionRevisionId" OR value->>'revisionHash' IS DISTINCT FROM f."questionHash" OR public.int6_enta_valid_text(value->'text',1,512) IS NOT TRUE OR value->>'contentHash' IS DISTINCT FROM public.int6_enta_hash(jsonb_build_object('ordinal',value->'ordinal','text',value->'text'))) OR EXISTS(SELECT 1 FROM jsonb_array_elements(graphemes) value WHERE public.int8_json_id(value->'id') IS NOT TRUE OR public.int6_enta_valid_text(value->'grapheme',1,64) IS NOT TRUE OR public.int6_enta_valid_text(value->'segmentationVersion',1,64) IS NOT TRUE OR value->>'proofHash' IS DISTINCT FROM public.int6_enta_hash(value-ARRAY['id','proofHash']) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(items) item WHERE item->'revisionId'=value->'answerRevisionId' AND item->'hash'=value->'answerHash' AND item->'trap'='false'::JSONB)) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 descriptor:=jsonb_build_object('ref',f."opaqueRef",'sourceNamespace',f."sourceNamespace",'sourceId',f."sourceId",'revisionId',f."questionRevisionId",'hash',f."questionHash",'formatId',f."id",'formatHash',f."contentHash",'categoryKey',f."categoryKey",'format',f."format",'prompt',q."prompt",'target',CASE WHEN f."format" IN ('ORDINARY_TIER','DRAWING_TARGET') THEN f."rules"->'target' ELSE 'null'::JSONB END,'points',CASE WHEN f."format" IN ('ORDINARY_TIER','DRAWING_TARGET') THEN to_jsonb(q."points") ELSE 'null'::JSONB END,'items',items,'media',media,'rules',f."rules",'hints',hints,'graphemes',graphemes,'hintRoot',p."hintRoot",'effectValue',p."effectValue",'effectValueSource',p."effectValueSource",'proofHash',p."proofHash");
 IF octet_length(descriptor::TEXT)>1048576 THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF; RETURN descriptor;
END $$;
CREATE FUNCTION public.int9_context(game_id TEXT,requested_round TEXT,requested_effect TEXT,requested_scope TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE g public."Game"%ROWTYPE; rt public."GameRuntime"%ROWTYPE; execution public."EntaExecutionPin"%ROWTYPE; head public."CompetitiveRuntimeHead"%ROWTYPE; identity_row public."FirebaseIdentity"%ROWTYPE; selected_round TEXT; state JSONB; teams JSONB; categories JSONB; rounds JSONB; effects JSONB; ids TEXT[]; x JSONB; effect_sequence INTEGER; selected_descriptor JSONB; BEGIN
 SELECT "admissionId","firebaseIdentityId" INTO g."admissionId",g."firebaseIdentityId" FROM public."Game" WHERE "id"=game_id; SELECT "activeRoundId","resultReason","setup","state","teamOrder","turnIndex","version" INTO rt."activeRoundId",rt."resultReason",rt."setup",rt."state",rt."teamOrder",rt."turnIndex",rt."version" FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT "clientBinding","clientHash","intentHash","formatReleaseId",jsonb_build_object('domain',"fullIntent"->'domain','pinMaterial',"fullIntent"->'pinMaterial','seed',"fullIntent"->'seed') INTO execution."clientBinding",execution."clientHash",execution."intentHash",execution."formatReleaseId",execution."fullIntent" FROM public."EntaExecutionPin" WHERE "gameId"=game_id; SELECT "boardReviewRoundId","latestEffectId","openItemReviewId" INTO head."boardReviewRoundId",head."latestEffectId",head."openItemReviewId" FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id; SELECT "firebaseProjectId","firebaseUid" INTO identity_row."firebaseProjectId",identity_row."firebaseUid" FROM public."FirebaseIdentity" WHERE "id"=g."firebaseIdentityId";
 IF execution."clientBinding"->'version' IS DISTINCT FROM '5'::JSONB OR execution."fullIntent"->>'domain' IS DISTINCT FROM 'maydan.enta.competitive.start-intent.v1' OR execution."fullIntent"->>'pinMaterial' IS DISTINCT FROM 'maydan.enta.competitive.pin-references.v1' THEN PERFORM public.int9_error('DRAFT5_COMPATIBILITY_REVIEW_REQUIRED'); END IF;
 selected_round:=COALESCE(rt."activeRoundId",(SELECT "roundId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),head."boardReviewRoundId",(SELECT a."roundId" FROM public."CompetitiveAttempt" a JOIN public."GameRound" r ON r."gameId"=a."gameId" AND r."id"=a."roundId" WHERE a."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."attemptId"=a."id") ORDER BY r."ordinal" LIMIT 1),requested_round,(SELECT "roundId" FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=requested_effect));
 SELECT COALESCE(max("sequence"),0) INTO effect_sequence FROM public."CompetitiveEffect" WHERE "gameId"=game_id;
 SELECT jsonb_agg(jsonb_build_object('id',t."id",'name',t."name",'colorKey',rt."setup"->'teams'->(ordered.ordinal::INTEGER-1)->'colorKey','aids',rt."setup"->'teams'->(ordered.ordinal::INTEGER-1)->'aids','players',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',player."id",'name',player."name") ORDER BY roster."ordinal"),'[]'::JSONB) FROM public."CompetitiveRosterPlayer" roster JOIN public."Player" player ON player."id"=roster."playerId" AND player."teamId"=roster."teamId" WHERE roster."gameId"=game_id AND roster."teamId"=t."id"),'score',t."score",'scoreVersion',COALESCE((SELECT max("scoreVersion") FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "teamId"=t."id"),0),'scoreHead',(SELECT "effectId" FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "teamId"=t."id" ORDER BY "scoreVersion" DESC LIMIT 1)) ORDER BY ordered.ordinal) INTO teams FROM unnest(rt."teamOrder") WITH ORDINALITY ordered(team_id,ordinal) JOIN public."Team" t ON t."gameId"=game_id AND t."id"=ordered.team_id;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('key',category."categoryKey",'label',left(revision."labelAr",64),'format',(SELECT r."pin"->>'format' FROM public."GameRound" r WHERE r."gameId"=game_id AND r."categoryKey"=category."categoryKey" ORDER BY r."ordinal" LIMIT 1),'cover',(SELECT public.int9_media_descriptor(cover."proofId",'COVER',NULL) FROM public."EntaFormatCover" cover WHERE cover."releaseId"=execution."formatReleaseId" AND cover."categoryKey"=category."categoryKey")) ORDER BY category."ordinal"),'[]'::JSONB) INTO categories FROM public."GameCategoryPin" category JOIN public."CanonicalCategoryRevision" revision ON revision."id"=category."categoryRevisionId" WHERE category."gameId"=game_id;
 SELECT COALESCE(jsonb_agg(CASE WHEN r."id"=selected_round THEN r."state"||jsonb_build_object('pin',public.int9_descriptor(cp."promptId")) ELSE jsonb_build_object('contextSummary',TRUE,'id',r."id",'questionId',r."gameQuestionId",'ordinal',r."ordinal",'phase',r."state"->'phase','version',r."state"->'version','phaseOrdinal',r."state"->'phaseOrdinal','generation',r."state"->'generation','deadline',r."state"->'deadline','overallDeadline',r."state"->'overallDeadline','pause',r."state"->'pause','assignment',r."state"->'assignment','publicRevealed',r."state"->'publicRevealed','resourceStop',r."state"->'resourceStop','pin',jsonb_build_object('categoryKey',r."categoryKey",'format',r."pin"->'format','points',r."pin"->'points'),'consumed','[]'::JSONB) END ORDER BY r."ordinal"),'[]'::JSONB) INTO rounds FROM public."GameRound" r JOIN public."CompetitiveRoundPin" cp ON cp."gameId"=r."gameId" AND cp."roundId"=r."id" WHERE r."gameId"=game_id;
 ids:=ARRAY_REMOVE(ARRAY[requested_effect,head."latestEffectId",(SELECT "originalEffectId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),(SELECT "reversalEffectId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),(SELECT "effectId" FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id AND "originalEffectId"=requested_effect)],NULL);
 SELECT COALESCE(jsonb_agg("payload" ORDER BY "sequence"),'[]'::JSONB) INTO effects FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=ANY(ids);
 state:=jsonb_build_object('id',game_id,'identityId',g."firebaseIdentityId",'projectId',identity_row."firebaseProjectId",'hostUid',identity_row."firebaseUid",'admissionId',g."admissionId",'request',execution."clientBinding",'requestHash',execution."clientHash",'intent',jsonb_build_object('seed',execution."fullIntent"->'seed'),'intentHash',execution."intentHash",'version',rt."version",'finished',rt."state"='FINISHED','activeRoundId',rt."activeRoundId",'turnIndex',rt."turnIndex",'resultReason',CASE WHEN rt."state"='FINISHED' THEN CASE WHEN rt."resultReason"='HOST_ENDED' THEN 'HOST_ENDED' ELSE 'ALL_ROUNDS' END ELSE NULL END,'teams',teams,'categories',categories,'rounds',rounds,'effects',effects,'events','[]'::JSONB,'reports','[]'::JSONB,'resultSignals','[]'::JSONB,'capacityReservations','[]'::JSONB,'capacityDispositions','[]'::JSONB,'latestEffectId',head."latestEffectId",'correctionReview',head."boardReviewRoundId",'openItemReview',head."openItemReviewId",'tournamentBinding',NULL); rounds:=NULL; effects:=NULL; teams:=NULL; categories:=NULL; execution."clientBinding":=NULL; execution."fullIntent":=NULL;
 state:=state||jsonb_build_object('attempts',(SELECT COALESCE(jsonb_agg(a."payload" ORDER BY e."sequence",a."id" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveAttempt" a JOIN public."RoundAuthorityEvent" e ON e."gameId"=a."gameId" AND e."id"=a."eventId" WHERE a."gameId"=game_id AND a."roundId"=selected_round),
 'classifications',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',c."id",'attemptId',c."attemptId",'eventId',c."eventId",'correct',c."correct",'interim',c."interim") ORDER BY e."sequence",c."id" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveClassification" c JOIN public."CompetitiveAttempt" a ON a."gameId"=c."gameId" AND a."id"=c."attemptId" JOIN public."RoundAuthorityEvent" e ON e."gameId"=c."gameId" AND e."id"=c."eventId" WHERE c."gameId"=game_id AND a."roundId"=selected_round),
 'postings',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',p."id",'effectId',p."effectId",'teamId',p."teamId",'delta',p."delta",'before',p."before",'after',p."after",'scoreVersion',p."scoreVersion",'previousHead',p."previousHeadId") ORDER BY p."scoreVersion",p."id" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveScorePosting" p WHERE p."gameId"=game_id AND p."effectId"=ANY(ids)),
 'rulings',(SELECT COALESCE(jsonb_agg(jsonb_build_object('roundId',h."roundId",'itemId',h."itemId",'scopeId',h."scopeId",'originalEffectId',h."originalEffectId",'effectId',h."effectId",'version',h."version",'hash',h."hash",'reversed',h."reversed") ORDER BY h."scopeId" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveRulingHead" h WHERE h."gameId"=game_id AND h."roundId"=selected_round AND (requested_effect IS NULL OR h."originalEffectId"=requested_effect OR h."effectId"=requested_effect)),
 'itemReviews',(SELECT COALESCE(jsonb_agg("payload"),'[]'::JSONB) FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),'itemResolutions','[]'::JSONB,
 'results',(SELECT COALESCE(jsonb_agg(jsonb_build_object('payload',result."payload",'hash',result."resultHash")),'[]'::JSONB) FROM public."EngineMatchResult" result JOIN public."EngineMatchResultHead" result_head ON result_head."gameId"=result."gameId" AND result_head."resultVersion"=result."resultVersion" AND result_head."resultHash"=result."resultHash" WHERE result."gameId"=game_id));
 state:=state||jsonb_build_object('allowances',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a."id",'teamId',a."teamId",'aid',a."aid",'scope',a."scope",'scopeId',a."scopeId",'roundId',a."roundId") ORDER BY a."teamId" COLLATE "C",a."ordinal"),'[]'::JSONB) FROM public."CompetitiveAllowance" a WHERE a."gameId"=game_id),
 'consumptions',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',c."id",'allowanceId',c."allowanceId",'roundId',c."roundId",'eventId',c."eventId",'effectId',c."effectId",'aid',c."aid",'teamId',c."teamId")),'[]'::JSONB) FROM public."CompetitiveConsumption" c WHERE c."gameId"=game_id),
 'disclosures',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',d."id",'roundId',d."roundId",'targetRevisionId',d."targetRevisionId",'targetHash',d."targetHash",'playerId',d."playerId",'assignmentId',d."assignmentId",'assignmentGeneration',d."assignmentGeneration",'at',floor(extract(epoch FROM d."createdAt")*1000),'grantId',d."grantId",'grantGeneration',d."grantGeneration") ORDER BY d."createdAt",d."id" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveTargetDisclosure" d WHERE d."gameId"=game_id AND d."roundId"=selected_round),
 'grantScopes',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',sc."id",'roundId',sc."roundId",'role',sc."role",'assignmentId',sc."assignmentId",'generation',sc."generation",'activeGrantId',sc."activeGrantId") ORDER BY sc."id" COLLATE "C"),'[]'::JSONB) FROM public."RoundGrantScope" sc WHERE sc."gameId"=game_id AND (sc."roundId"=selected_round AND sc."activeGrantId" IS NOT NULL OR sc."id"=requested_scope)),
 'grants',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',gr."id",'scopeId',gr."scopeId",'roundId',gr."roundId",'role',gr."role",'assignmentId',gr."assignmentId",'generation',gr."generation",'tokenHash',gr."tokenHash",'expiresAt',floor(extract(epoch FROM gr."expiresAt")*1000),'revoked',gr."revoked") ORDER BY gr."id" COLLATE "C"),'[]'::JSONB) FROM public."RoundGrant" gr JOIN public."RoundGrantScope" sc ON sc."gameId"=gr."gameId" AND sc."id"=gr."scopeId" AND sc."activeGrantId"=gr."id" WHERE gr."gameId"=game_id AND sc."roundId"=selected_round),
 'canvases',(SELECT COALESCE(jsonb_agg("state"),'[]'::JSONB) FROM public."DrawingCanvasState" WHERE "roundId"=selected_round));
 IF jsonb_array_length(state->'attempts')>512 OR EXISTS(SELECT 1 FROM jsonb_array_elements(state->'attempts') a WHERE octet_length(a::TEXT)>2048) OR jsonb_array_length(state->'effects')>5 OR jsonb_array_length(state->'grantScopes')>3 OR jsonb_array_length(state->'grants')>2 OR octet_length(state::TEXT)>4194304 THEN PERFORM public.int9_error('CONTEXT_BOUND_EXCEEDED'); END IF;
 RETURN state||jsonb_build_object('factContext',jsonb_build_object('version',1,'selectedRoundId',selected_round,'effectSequence',effect_sequence,'pendingTotal',(SELECT count(*) FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."attemptId"=a."id")),'rulingTotal',(SELECT count(*) FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id),'terminalValidated',rt."state"='FINISHED'));
END $$;
CREATE FUNCTION public.int9_command_window(s JSONB,c JSONB) RETURNS JSONB LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE compact_rounds JSONB; compact_attempts JSONB; result JSONB; BEGIN
 -- This is a transient SQL reducer evidence projection. It is never a stored
 -- pin, revision hash input, client DTO, receipt or replacement authority.
 SELECT jsonb_agg(CASE WHEN round_row->'contextSummary'='true'::JSONB THEN round_row ELSE jsonb_set(round_row,'{pin}',(round_row->'pin')||jsonb_build_object('items',(SELECT COALESCE(jsonb_agg(item-ARRAY['text','mediaIds'] ORDER BY ordinal),'[]'::JSONB) FROM jsonb_array_elements(round_row->'pin'->'items') WITH ORDINALITY members(item,ordinal)),'media','[]'::JSONB,'hints',CASE WHEN c->>'type'='REVEAL_HINT' OR c->>'type'='USE_AID' AND c->>'aid'='MORE_HINT' THEN round_row->'pin'->'hints' ELSE '[]'::JSONB END,'graphemes',CASE WHEN c->>'type'='USE_AID' AND c->>'aid'='HINT' THEN round_row->'pin'->'graphemes' ELSE '[]'::JSONB END)) END ORDER BY ordinal) INTO compact_rounds FROM jsonb_array_elements(s->'rounds') WITH ORDINALITY rounds(round_row,ordinal);
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a->'id','roundId',a->'roundId','itemId',a->'itemId','teamId',a->'teamId','playerId',a->'playerId','phase',a->'phase','phaseOrdinal',a->'phaseOrdinal','generation',a->'generation','bonusMultiplier',a->'bonusMultiplier','bonusEventId',a->'bonusEventId') ORDER BY ordinal),'[]'::JSONB) INTO compact_attempts FROM jsonb_array_elements(s->'attempts') WITH ORDINALITY attempts(a,ordinal);
 result:=s||jsonb_build_object('rounds',compact_rounds,'attempts',compact_attempts); RETURN result;
END $$;
CREATE FUNCTION public.int9_before_facts(s JSONB) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('id',s->'id','version',s->'version','finished',s->'finished','correctionReview',s->'correctionReview','rounds',(SELECT jsonb_agg(jsonb_build_object('id',r->'id','phase',r->'phase','pause',r->'pause') ORDER BY ordinal) FROM jsonb_array_elements(s->'rounds') WITH ORDINALITY rounds(r,ordinal)))
$$;
CREATE FUNCTION public.int9_scope_facts(game_id TEXT,c JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE rid TEXT:=c->>'roundId'; original_id TEXT; BEGIN
 IF rid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."GameRound" WHERE "gameId"=game_id AND "id"=rid) OR c->>'teamId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."Team" WHERE "gameId"=game_id AND "id"=c->>'teamId') OR c->>'playerId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."CompetitiveRosterPlayer" WHERE "gameId"=game_id AND "teamId"=c->>'teamId' AND "playerId"=c->>'playerId') OR c->>'itemId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."RoundItemPin" WHERE "roundId"=rid AND "itemId"=c->>'itemId') OR c->>'attemptId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" WHERE "gameId"=game_id AND "roundId"=rid AND "id"=c->>'attemptId') OR c->>'scopeId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."RoundGrantScope" WHERE "gameId"=game_id AND "roundId"=rid AND "id"=c->>'scopeId') OR c->>'effectId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=c->>'effectId' AND (rid IS NULL OR "roundId"=rid)) OR c->>'reviewId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=c->>'reviewId') THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 IF c ? 'blockingIds' AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'blockingIds') id WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=id#>>'{}')) THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 IF c->>'type'='FINAL_RULING' AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'classifications') tuple WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" WHERE "gameId"=game_id AND "roundId"=rid AND "id"=tuple->>0 AND (c->>'itemId' IS NULL OR "itemId"=c->>'itemId'))) THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 IF c ? 'correctAttemptIds' THEN original_id:=(CASE WHEN c->>'type'='RESOLVE_ITEM_REVIEW' THEN (SELECT "originalEffectId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=c->>'reviewId') ELSE c->>'effectId' END); IF EXISTS(SELECT 1 FROM jsonb_array_elements(c->'correctAttemptIds') id WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveEffectAttempt" WHERE "gameId"=game_id AND "effectId"=original_id AND "attemptId"=id#>>'{}')) THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; END IF;
END $$;
CREATE FUNCTION public.int9_lock_context(ns TEXT,project TEXT,game_id TEXT,requested_round TEXT,requested_effect TEXT,requested_scope TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE rid TEXT; BEGIN
 PERFORM public.int8_namespace(ns,project);
 PERFORM 1 FROM public."Game" g JOIN public."FirebaseIdentity" i ON i."id"=g."firebaseIdentityId" JOIN public."GameCompetitivePin" profile ON profile."gameId"=g."id" AND profile."firebaseIdentityId"=i."id" WHERE g."id"=game_id AND g."gameFormat"='FIREBASE_PINNED' AND profile."requestVersion"=5 AND i."firebaseProjectId"=project FOR UPDATE OF g; IF NOT FOUND THEN RETURN NULL; END IF;
 PERFORM 1 FROM public."GameRuntime" WHERE "gameId"=game_id FOR UPDATE;
 PERFORM 1 FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id FOR UPDATE;
 rid:=COALESCE((SELECT "activeRoundId" FROM public."GameRuntime" WHERE "gameId"=game_id),(SELECT "roundId" FROM public."CompetitiveItemReview" review JOIN public."CompetitiveRuntimeHead" head ON head."gameId"=review."gameId" AND head."openItemReviewId"=review."id" WHERE review."gameId"=game_id),(SELECT "boardReviewRoundId" FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id),(SELECT a."roundId" FROM public."CompetitiveAttempt" a JOIN public."GameRound" r ON r."gameId"=a."gameId" AND r."id"=a."roundId" WHERE a."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."attemptId"=a."id") ORDER BY r."ordinal" LIMIT 1),requested_round,(SELECT "roundId" FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=requested_effect));
 PERFORM 1 FROM public."GameRound" WHERE "gameId"=game_id AND "id"=rid FOR UPDATE;
 PERFORM 1 FROM public."GameQuestion" q JOIN public."GameRound" r ON r."gameQuestionId"=q."id" AND r."gameId"=q."gameId" WHERE q."gameId"=game_id AND r."id"=rid FOR UPDATE OF q;
 PERFORM 1 FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id AND "roundId"=rid ORDER BY "scopeId" COLLATE "C" FOR UPDATE;
 PERFORM 1 FROM public."CompetitiveCapacityHead" WHERE "gameId"=game_id AND "roundId"=rid FOR UPDATE;
 PERFORM 1 FROM public."RoundGrantScope" WHERE "gameId"=game_id AND ("roundId"=rid AND "activeGrantId" IS NOT NULL OR "id"=requested_scope) ORDER BY "id" COLLATE "C" FOR UPDATE;
 PERFORM 1 FROM public."RoundGrant" grant_row JOIN public."RoundGrantScope" scope ON scope."gameId"=grant_row."gameId" AND scope."activeGrantId"=grant_row."id" WHERE grant_row."gameId"=game_id AND scope."roundId"=rid ORDER BY grant_row."id" COLLATE "C" FOR UPDATE OF grant_row;
 PERFORM 1 FROM public."DrawingCanvasState" WHERE "roundId"=rid FOR UPDATE;
 PERFORM 1 FROM public."GameRuntime" runtime CROSS JOIN LATERAL unnest(runtime."teamOrder") WITH ORDINALITY ordered(id,ord) JOIN public."Team" t ON t."id"=ordered.id AND t."gameId"=runtime."gameId" WHERE runtime."gameId"=game_id ORDER BY ordered.ord FOR UPDATE OF t;
 PERFORM public.int9_assert_stored(game_id); RETURN public.int9_context(game_id,requested_round,requested_effect,requested_scope);
END $$;
CREATE FUNCTION public.int9_prompt_parent(prompt_id TEXT,format_id TEXT) RETURNS BOOLEAN LANGUAGE SQL STABLE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM public."EntaCompetitivePrompt" p JOIN public."EntaFormatRevision" f ON f."id"=p."formatId" AND f."questionRevisionId"=p."questionRevisionId" AND f."questionHash"=p."questionHash" JOIN public."EntaCompetitiveRelease" cp ON cp."id"=p."releaseId" AND cp."formatReleaseId"=f."releaseId" JOIN public."EntaFormatRelease" fr ON fr."id"=f."releaseId" AND fr."formatRoot"=cp."formatRoot" AND fr."mediaRoot"=cp."mediaRoot" WHERE p."id"=prompt_id AND f."id"=format_id AND cp."sealedAt" IS NOT NULL AND fr."sealedAt" IS NOT NULL AND f."contentHash"~'^[a-f0-9]{64}$')
$$;
CREATE OR REPLACE FUNCTION public.int9_intent_hash(intent JSONB) RETURNS TEXT LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE payload TEXT; utf8 BYTEA; output TEXT; part TEXT; piece TEXT; key TEXT; field TEXT; row_value JSONB; value JSONB; i INTEGER; n INTEGER; first_key BOOLEAN; first_field BOOLEAN; BEGIN
 IF jsonb_typeof(intent) IS DISTINCT FROM 'object' OR public.int6_enta_exact_keys(intent,ARRAY['baseReleaseId','baseRoot','competitiveReleaseId','domain','formatReleaseId','formatRoot','mediaRoot','paletteRoot','pinMaterial','pinsHash','policyVersion','poolHash','proofRoot','receiptId','request','roundCount','seed','selection','tournamentBinding','version']) IS NOT TRUE OR intent->'version' IS DISTINCT FROM '5'::JSONB OR intent->>'domain' IS DISTINCT FROM 'maydan.enta.competitive.start-intent.v1' OR intent->>'pinMaterial' IS DISTINCT FROM 'maydan.enta.competitive.pin-references.v1' OR intent->'tournamentBinding' IS DISTINCT FROM 'null'::JSONB OR intent->>'policyVersion' IS DISTINCT FROM 'enta-competitive-1' OR public.int9_valid_request(intent->'request') IS NOT TRUE OR jsonb_typeof(intent->'selection') IS DISTINCT FROM 'array'  THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 FOREACH key IN ARRAY ARRAY['baseReleaseId','competitiveReleaseId','formatReleaseId','receiptId'] LOOP IF jsonb_typeof(intent->key) IS DISTINCT FROM 'string' OR octet_length(convert_to(intent->>key,'UTF8')) NOT BETWEEN 1 AND 1024 THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF; END LOOP;
 FOREACH key IN ARRAY ARRAY['baseRoot','formatRoot','mediaRoot','paletteRoot','pinsHash','poolHash','proofRoot','seed'] LOOP IF jsonb_typeof(intent->key) IS DISTINCT FROM 'string' OR intent->>key!~'^[a-f0-9]{64}$' THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF; END LOOP;
 n:=jsonb_array_length(intent->'selection'); IF n NOT BETWEEN 1 AND 36 OR intent->'roundCount' IS DISTINCT FROM to_jsonb(n) THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF; payload:='{"domain":"maydan.enta.competitive.start-intent.v1","intent":{'; first_field:=TRUE;
 FOREACH field IN ARRAY ARRAY['baseReleaseId','baseRoot','competitiveReleaseId','domain','formatReleaseId','formatRoot','mediaRoot','paletteRoot','pinMaterial','pinsHash','policyVersion','poolHash','proofRoot','receiptId','request','roundCount','seed','selection','tournamentBinding','version'] LOOP
  IF NOT first_field THEN payload:=payload||','; END IF; first_field:=FALSE;
  IF field='selection' THEN
   payload:=payload||'"selection":[';
   FOR i IN 0..n-1 LOOP
 row_value:=intent->'selection'->i; IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR public.int6_enta_exact_keys(row_value,ARRAY['categoryKey','cycle','format','formatHash','formatId','hash','hintRoot','ordinal','proofHash','revisionId','sourceId','sourceNamespace']) IS NOT TRUE OR public.int5b_json_integer(row_value->'ordinal',0,35) IS NOT TRUE OR row_value->'ordinal' IS DISTINCT FROM to_jsonb(i) OR public.int5b_json_integer(row_value->'cycle',0,2000000000) IS NOT TRUE OR jsonb_typeof(row_value->'format') IS DISTINCT FROM 'string' OR row_value->>'format' NOT IN ('ORDINARY_TIER','DRAWING_TARGET','LIST_ITEMS','ACTING_ITEMS') THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
 FOREACH key IN ARRAY ARRAY['sourceNamespace','sourceId','revisionId','categoryKey','formatId'] LOOP IF jsonb_typeof(row_value->key) IS DISTINCT FROM 'string' OR octet_length(convert_to(row_value->>key,'UTF8')) NOT BETWEEN 1 AND 1024 THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF; END LOOP;
 FOREACH key IN ARRAY ARRAY['hash','formatHash','proofHash','hintRoot'] LOOP IF jsonb_typeof(row_value->key) IS DISTINCT FROM 'string' OR row_value->>key!~'^[a-f0-9]{64}$' THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF; END LOOP;
 IF i>0 THEN payload:=payload||','; END IF; payload:=payload||'{'; first_key:=TRUE;
 FOREACH key IN ARRAY ARRAY['categoryKey','cycle','format','formatHash','formatId','hash','hintRoot','ordinal','proofHash','revisionId','sourceId','sourceNamespace'] LOOP
  IF NOT first_key THEN payload:=payload||','; END IF; first_key:=FALSE;
  value:=row_value->key; part:=public.int6_enta_canonical(value); value:=NULL;
  piece:=to_jsonb(key)::TEXT||':'||part; payload:=payload||piece; part:=NULL; piece:=NULL;
 END LOOP; payload:=payload||'}'; row_value:=NULL;
END LOOP;
   payload:=payload||']';
  ELSE
   value:=intent->field; part:=public.int6_enta_canonical(value); value:=NULL;
   piece:=to_jsonb(field)::TEXT||':'||part; payload:=payload||piece; part:=NULL; piece:=NULL;
  END IF;
 END LOOP;
 payload:=payload||'},"version":1}'; row_value:=NULL; value:=NULL; part:=NULL; piece:=NULL;
 utf8:=convert_to(payload,'UTF8'); payload:=NULL; output:=encode(int4_crypto.digest(utf8,'sha256'),'hex'); utf8:=NULL; RETURN output;
END $$;
CREATE OR REPLACE FUNCTION public.int9_references_hash(pin_references JSONB) RETURNS TEXT LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE payload TEXT; utf8 BYTEA; output TEXT; part TEXT; piece TEXT; key TEXT; field TEXT; row_value JSONB; value JSONB; i INTEGER; n INTEGER; first_key BOOLEAN; first_field BOOLEAN; BEGIN
 IF jsonb_typeof(pin_references) IS DISTINCT FROM 'array' THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF; n:=jsonb_array_length(pin_references); IF n NOT BETWEEN 1 AND 36 THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
 -- Same-frame complete original TEXT. No whole wrapper/array canonical call.
 payload:='{"domain":"maydan.enta.competitive.pin-references.v1","references":[';
 FOR i IN 0..n-1 LOOP
 row_value:=pin_references->i; IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR public.int6_enta_exact_keys(row_value,ARRAY['categoryKey','cycle','format','formatHash','formatId','hash','hintRoot','ordinal','proofHash','revisionId','sourceId','sourceNamespace']) IS NOT TRUE OR public.int5b_json_integer(row_value->'ordinal',0,35) IS NOT TRUE OR row_value->'ordinal' IS DISTINCT FROM to_jsonb(i) OR public.int5b_json_integer(row_value->'cycle',0,2000000000) IS NOT TRUE OR jsonb_typeof(row_value->'format') IS DISTINCT FROM 'string' OR row_value->>'format' NOT IN ('ORDINARY_TIER','DRAWING_TARGET','LIST_ITEMS','ACTING_ITEMS') THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
 FOREACH key IN ARRAY ARRAY['sourceNamespace','sourceId','revisionId','categoryKey','formatId'] LOOP IF jsonb_typeof(row_value->key) IS DISTINCT FROM 'string' OR octet_length(convert_to(row_value->>key,'UTF8')) NOT BETWEEN 1 AND 1024 THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF; END LOOP;
 FOREACH key IN ARRAY ARRAY['hash','formatHash','proofHash','hintRoot'] LOOP IF jsonb_typeof(row_value->key) IS DISTINCT FROM 'string' OR row_value->>key!~'^[a-f0-9]{64}$' THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF; END LOOP;
 IF i>0 THEN payload:=payload||','; END IF; payload:=payload||'{'; first_key:=TRUE;
 FOREACH key IN ARRAY ARRAY['categoryKey','cycle','format','formatHash','formatId','hash','hintRoot','ordinal','proofHash','revisionId','sourceId','sourceNamespace'] LOOP
  IF NOT first_key THEN payload:=payload||','; END IF; first_key:=FALSE;
  value:=row_value->key; part:=public.int6_enta_canonical(value); value:=NULL;
  piece:=to_jsonb(key)::TEXT||':'||part; payload:=payload||piece; part:=NULL; piece:=NULL;
 END LOOP; payload:=payload||'}'; row_value:=NULL;
END LOOP;
 payload:=payload||'],"version":1}'; row_value:=NULL; value:=NULL; part:=NULL; piece:=NULL;
 utf8:=convert_to(payload,'UTF8'); payload:=NULL; output:=encode(int4_crypto.digest(utf8,'sha256'),'hex'); utf8:=NULL; RETURN output;
END $$;
CREATE FUNCTION public.int9_reference(format_id TEXT,prompt_id TEXT,selection_ordinal INTEGER,selection_cycle INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE f public."EntaFormatRevision"%ROWTYPE; p public."EntaCompetitivePrompt"%ROWTYPE; BEGIN
 SELECT "categoryKey","contentHash","format","id","opaqueRef","questionHash","questionRevisionId","sourceId","sourceNamespace" INTO f."categoryKey",f."contentHash",f."format",f."id",f."opaqueRef",f."questionHash",f."questionRevisionId",f."sourceId",f."sourceNamespace" FROM public."EntaFormatRevision" WHERE "id"=format_id; SELECT "hintRoot","id","proofHash" INTO p."hintRoot",p."id",p."proofHash" FROM public."EntaCompetitivePrompt" WHERE "id"=prompt_id AND "formatId"=f."id" AND "questionRevisionId"=f."questionRevisionId" AND "questionHash"=f."questionHash";
 IF f."id" IS NULL OR p."id" IS NULL OR public.int8_json_id(to_jsonb(f."id")) IS NOT TRUE OR public.int8_json_id(to_jsonb(f."questionRevisionId")) IS NOT TRUE OR public.int8_json_id(to_jsonb(f."categoryKey")) IS NOT TRUE OR public.int8_json_id(to_jsonb(f."opaqueRef")) IS NOT TRUE OR octet_length(f."sourceNamespace") NOT BETWEEN 1 AND 1024 OR octet_length(f."sourceId") NOT BETWEEN 1 AND 1024 OR public.int9_prompt_parent(p."id",f."id") IS NOT TRUE THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('ordinal',selection_ordinal,'cycle',selection_cycle,'sourceNamespace',f."sourceNamespace",'sourceId',f."sourceId",'revisionId',f."questionRevisionId",'hash',f."questionHash",'categoryKey',f."categoryKey",'format',f."format",'formatId',f."id",'formatHash',f."contentHash",'proofHash',p."proofHash",'hintRoot',p."hintRoot");
END $$;
CREATE FUNCTION public.int9_pool_root(release_id TEXT,request JSONB) RETURNS TEXT LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE row_record RECORD; material JSONB; previous_root TEXT:=public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.competitive.source-pool.v1','version',1,'count',0)); pool_count BIGINT:=0; BEGIN
 FOR row_record IN SELECT f."categoryKey",f."contentHash",f."format",f."id",f."opaqueRef",f."questionHash",f."questionRevisionId",f."sourceId",f."sourceNamespace",p."id" competitive_prompt_id,p."proofHash",p."hintRoot" FROM public."EntaCompetitivePrompt" p JOIN public."EntaFormatRevision" f ON f."id"=p."formatId" AND f."questionRevisionId"=p."questionRevisionId" AND f."questionHash"=p."questionHash" JOIN public."EntaFormatRelease" format_release ON format_release."id"=f."releaseId" JOIN public."CatalogReleaseQuestion" member ON member."catalogReleaseId"=format_release."baseReleaseId" AND member."questionRevisionId"=f."questionRevisionId" AND member."questionContentHash"=f."questionHash" AND member."categoryKey"=f."categoryKey" WHERE p."releaseId"=release_id AND EXISTS(SELECT 1 FROM jsonb_array_elements(request->'setup'->'categories') c WHERE c->>'key'=f."categoryKey") ORDER BY f."sourceNamespace" COLLATE "C",f."sourceId" COLLATE "C",f."categoryKey" COLLATE "C",f."format" COLLATE "C",f."questionRevisionId" COLLATE "C",f."id" COLLATE "C",f."opaqueRef" COLLATE "C" LOOP
  IF public.int9_prompt_parent(row_record.competitive_prompt_id,row_record."id") IS NOT TRUE THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
  material:=jsonb_build_object('sourceNamespace',row_record."sourceNamespace",'sourceId',row_record."sourceId",'categoryKey',row_record."categoryKey",'format',row_record."format",'revisionId',row_record."questionRevisionId",'hash',row_record."questionHash",'formatId',row_record."id",'formatHash',row_record."contentHash",'proofHash',row_record."proofHash",'hintRoot',row_record."hintRoot",'ref',row_record."opaqueRef");
  IF pool_count>=9007199254740991 OR EXISTS(SELECT 1 FROM jsonb_each_text(material) entry WHERE entry.value IS NULL OR octet_length(convert_to(entry.value,'UTF8')) NOT BETWEEN 1 AND 1024) THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
  previous_root:=public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.competitive.source-pool.v1','version',1,'index',pool_count,'previousRoot',previous_root,'recordHash',public.int6_enta_hash(material))); pool_count:=pool_count+1;
 END LOOP;
 RETURN public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.competitive.source-pool.v1','version',1,'count',pool_count,'finalRoot',previous_root));
END $$;
CREATE FUNCTION public.int9_select_references_at(release_id TEXT,request JSONB,seed TEXT,identity_id TEXT,before_game TEXT) RETURNS JSONB LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE wanted JSONB; picked RECORD; result JSONB:='[]'::JSONB; current_cycle INTEGER; pool_count BIGINT; remaining INTEGER; need INTEGER; family TEXT; fmt TEXT:=request->>'executionFormat'; BEGIN
 FOR wanted IN SELECT c FROM jsonb_array_elements(request->'setup'->'categories') c LOOP
  SELECT count(*),min(f."format") INTO pool_count,family FROM public."EntaCompetitivePrompt" p JOIN public."EntaFormatRevision" f ON f."id"=p."formatId" WHERE p."releaseId"=release_id AND f."categoryKey"=wanted->>'key';
  IF pool_count<1 OR (SELECT count(DISTINCT f."format") FROM public."EntaCompetitivePrompt" p JOIN public."EntaFormatRevision" f ON f."id"=p."formatId" WHERE p."releaseId"=release_id AND f."categoryKey"=wanted->>'key')<>1 OR fmt='TIER_BOARD' AND family<>'ORDINARY_TIER' OR fmt='STANDALONE_LIST' AND family<>'LIST_ITEMS' OR fmt='STANDALONE_ACTING' AND family<>'ACTING_ITEMS' THEN PERFORM public.int9_error('FORMAT_UNAVAILABLE'); END IF;
  IF fmt IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN
   SELECT greatest(1,COALESCE(max("cycle"),1)) INTO current_cycle FROM public."EntaSourceExposure" WHERE "firebaseIdentityId"=identity_id AND "executionFormat"=fmt AND "categoryKey"=wanted->>'key' AND public.int9_exposure_precedes("gameId",before_game); need:=least(4,pool_count); remaining:=need;
   FOR picked IN SELECT f."id" format_id,p."id" prompt_id FROM public."EntaCompetitivePrompt" p JOIN public."EntaFormatRevision" f ON f."id"=p."formatId" WHERE p."releaseId"=release_id AND f."categoryKey"=wanted->>'key' AND NOT EXISTS(SELECT 1 FROM public."EntaSourceExposure" e WHERE e."firebaseIdentityId"=identity_id AND e."executionFormat"=fmt AND e."categoryKey"=f."categoryKey" AND e."sourceNamespace"=f."sourceNamespace" AND e."sourceId"=f."sourceId" AND e."cycle"=current_cycle AND public.int9_exposure_precedes(e."gameId",before_game)) ORDER BY public.int6_enta_hash(jsonb_build_array(seed,current_cycle,f."sourceNamespace",f."sourceId")) COLLATE "C",f."sourceNamespace" COLLATE "C",f."sourceId" COLLATE "C",f."opaqueRef" COLLATE "C" LIMIT need LOOP result:=result||jsonb_build_array(public.int9_reference(picked.format_id,picked.prompt_id,jsonb_array_length(result),current_cycle)); remaining:=remaining-1; END LOOP;
   IF remaining>0 THEN IF current_cycle>=2000000000 THEN PERFORM public.int9_error('EXPOSURE_UNAVAILABLE'); END IF; current_cycle:=current_cycle+1;
    FOR picked IN SELECT f."id" format_id,p."id" prompt_id FROM public."EntaCompetitivePrompt" p JOIN public."EntaFormatRevision" f ON f."id"=p."formatId" WHERE p."releaseId"=release_id AND f."categoryKey"=wanted->>'key' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result) selected WHERE selected->>'sourceNamespace'=f."sourceNamespace" AND selected->>'sourceId'=f."sourceId") ORDER BY public.int6_enta_hash(jsonb_build_array(seed,current_cycle,f."sourceNamespace",f."sourceId")) COLLATE "C",f."sourceNamespace" COLLATE "C",f."sourceId" COLLATE "C",f."opaqueRef" COLLATE "C" LIMIT remaining LOOP result:=result||jsonb_build_array(public.int9_reference(picked.format_id,picked.prompt_id,jsonb_array_length(result),current_cycle)); END LOOP;
   END IF;
  ELSIF family IN ('LIST_ITEMS','ACTING_ITEMS') THEN
   IF jsonb_array_length(wanted->'promptRefs') NOT BETWEEN 1 AND 6 THEN PERFORM public.int9_error('PROMPTS_REQUIRED'); END IF;
   FOR picked IN SELECT f."id" format_id,p."id" prompt_id FROM jsonb_array_elements(wanted->'promptRefs') WITH ORDINALITY selected(ref,ordinal) JOIN public."EntaFormatRevision" f ON f."opaqueRef"=selected.ref#>>'{}' AND f."categoryKey"=wanted->>'key' JOIN public."EntaCompetitivePrompt" p ON p."formatId"=f."id" AND p."releaseId"=release_id ORDER BY selected.ordinal LOOP result:=result||jsonb_build_array(public.int9_reference(picked.format_id,picked.prompt_id,jsonb_array_length(result),0)); END LOOP;
   IF (SELECT count(*) FROM jsonb_array_elements(result) selected WHERE selected->>'categoryKey'=wanted->>'key')<>jsonb_array_length(wanted->'promptRefs') THEN PERFORM public.int9_error('PROMPT_UNAVAILABLE'); END IF;
  ELSE
   IF wanted->'promptRefs'<>'[]'::JSONB OR pool_count<>6 OR EXISTS(SELECT 1 FROM (VALUES(200),(400),(600)) tier(value) WHERE (SELECT count(*) FROM public."EntaCompetitivePrompt" p JOIN public."EntaFormatRevision" f ON f."id"=p."formatId" JOIN public."QuestionRevision" q ON q."id"=f."questionRevisionId" WHERE p."releaseId"=release_id AND f."categoryKey"=wanted->>'key' AND q."points"=tier.value)<>2) THEN PERFORM public.int9_error('TIER_SUPPLY_UNAVAILABLE'); END IF;
   FOR picked IN SELECT f."id" format_id,p."id" prompt_id FROM public."EntaCompetitivePrompt" p JOIN public."EntaFormatRevision" f ON f."id"=p."formatId" JOIN public."QuestionRevision" q ON q."id"=f."questionRevisionId" WHERE p."releaseId"=release_id AND f."categoryKey"=wanted->>'key' ORDER BY q."points",f."opaqueRef" COLLATE "C" LOOP result:=result||jsonb_build_array(public.int9_reference(picked.format_id,picked.prompt_id,jsonb_array_length(result),0)); END LOOP;
  END IF;
 END LOOP;
 IF jsonb_array_length(result) NOT BETWEEN 1 AND 36 OR (SELECT count(DISTINCT (r->>'sourceNamespace',r->>'sourceId')) FROM jsonb_array_elements(result) r)<>jsonb_array_length(result) OR (SELECT count(DISTINCT r->>'revisionId') FROM jsonb_array_elements(result) r)<>jsonb_array_length(result) THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
 RETURN result;
END $$;
CREATE FUNCTION public.int9_exposure_precedes(exposure_game TEXT,before_game TEXT) RETURNS BOOLEAN LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE source_wallet TEXT; target_wallet TEXT; source_sequence BIGINT; target_sequence BIGINT; BEGIN
 IF before_game IS NULL THEN RETURN TRUE; END IF; IF exposure_game=before_game THEN RETURN FALSE; END IF;
 SELECT a."walletId",e."sequence" INTO source_wallet,source_sequence FROM public."Game" g JOIN public."Admission" a ON a."id"=g."admissionId" AND a."firebaseIdentityId"=g."firebaseIdentityId" JOIN public."WalletEntry" e ON e."walletId"=a."walletId" AND e."originType"='ADMISSION' AND e."originId"=a."id" AND e."effect"='RESERVE' WHERE g."id"=exposure_game AND a."engine"='ENTA' AND a."state"='COMMITTED' AND a."requestVersion" IN (4,5);
 SELECT a."walletId",e."sequence" INTO target_wallet,target_sequence FROM public."Game" g JOIN public."Admission" a ON a."id"=g."admissionId" AND a."firebaseIdentityId"=g."firebaseIdentityId" JOIN public."WalletEntry" e ON e."walletId"=a."walletId" AND e."originType"='ADMISSION' AND e."originId"=a."id" AND e."effect"='RESERVE' WHERE g."id"=before_game AND a."engine"='ENTA' AND a."state"='COMMITTED' AND a."requestVersion"=5;
 IF source_sequence IS NULL OR target_sequence IS NULL OR source_wallet IS DISTINCT FROM target_wallet THEN PERFORM public.int9_error('EXPOSURE_UNAVAILABLE'); END IF; RETURN source_sequence<target_sequence;
END $$;
CREATE FUNCTION public.int9_select_references(release_id TEXT,request JSONB,seed TEXT,identity_id TEXT) RETURNS JSONB LANGUAGE SQL STABLE SET search_path=pg_catalog AS $$ SELECT public.int9_select_references_at(release_id,request,seed,identity_id,NULL) $$;
CREATE FUNCTION public.int9_media_manifest(ns TEXT,project TEXT,uid TEXT,token_hash TEXT,game_id TEXT,media_id TEXT,grading_round TEXT,snapshot INTEGER) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE s JSONB; r JSONB; gr JSONB; pin JSONB; p public."MediaObjectProof"%ROWTYPE; m public."MediaRevision"%ROWTYPE; chunks JSONB; payload JSONB; moment DOUBLE PRECISION; BEGIN
 IF (uid IS NULL)=(token_hash IS NULL) OR media_id IS NULL OR snapshot IS NULL THEN PERFORM public.int9_error('MEDIA_DENIED'); END IF;
 IF uid IS NOT NULL THEN s:=public.int9_owner_load(ns,project,uid,game_id,TRUE); ELSE s:=public.int9_grant_load(ns,project,game_id,token_hash); END IF;
 IF s IS NULL THEN PERFORM public.int9_error('MEDIA_DENIED'); END IF; moment:=public.int9_now(); IF token_hash IS NOT NULL THEN gr:=public.int9_grant_physical(game_id,token_hash,moment); END IF;
 IF public.int9_mutation_owner(game_id,NULL,NULL,gr->>'scopeId',NULL,'{"grants":[]}'::JSONB,NULL,NULL,moment) THEN RETURN jsonb_build_object('restart',TRUE); END IF;
 SELECT physical."state"||jsonb_build_object('pin',public.int9_descriptor(cp."promptId")) INTO r FROM public."GameRound" physical JOIN public."CompetitiveRoundPin" cp ON cp."gameId"=physical."gameId" AND cp."roundId"=physical."id" JOIN public."GameRuntime" rt ON rt."gameId"=physical."gameId" AND rt."activeRoundId"=physical."id" WHERE physical."gameId"=game_id;
 IF (SELECT "state"='FINISHED' FROM public."GameRuntime" WHERE "gameId"=game_id) OR EXISTS(SELECT 1 FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id AND ("openItemReviewId" IS NOT NULL OR "boardReviewRoundId" IS NOT NULL)) OR r IS NOT NULL AND (r->'pause'<>'null'::JSONB OR r->'resourceStop'<>'null'::JSONB) THEN PERFORM public.int9_error('MEDIA_DENIED'); END IF;
 IF grading_round IS NOT NULL THEN
  IF uid IS NULL OR gr IS NOT NULL OR r IS NULL OR r->>'id' IS DISTINCT FROM grading_round OR r->'pin'->>'format' NOT IN ('LIST_ITEMS','ACTING_ITEMS') OR r->>'phase' IN ('READY','RESOLVED') THEN PERFORM public.int9_error('MEDIA_DENIED'); END IF;
  SELECT value INTO pin FROM jsonb_array_elements(r->'pin'->'media') WHERE value->>'id'=media_id AND value->>'role'='ITEM';
 ELSE
  IF gr IS NULL THEN SELECT public.int9_media_descriptor(cover."proofId",'COVER',NULL) INTO pin FROM public."EntaExecutionPin" execution JOIN public."GameCategoryPin" category ON category."gameId"=execution."gameId" JOIN public."EntaFormatCover" cover ON cover."releaseId"=execution."formatReleaseId" AND cover."categoryKey"=category."categoryKey" WHERE execution."gameId"=game_id AND cover."proofId"=media_id; END IF;
  IF pin IS NULL AND r IS NOT NULL AND r->>'phase'<>'READY' THEN
   SELECT media INTO pin FROM jsonb_array_elements(r->'pin'->'media') media WHERE media->>'id'=media_id AND
    (CASE WHEN gr->>'role'='ACTOR' THEN media->>'role'='ACTOR' AND r->'pin'->>'format'='DRAWING_TARGET' OR media->>'role'='ITEM' AND media->'itemId'=r->'assignment'->'itemId' AND gr->'assignmentId'=r->'assignment'->'id'
    ELSE media->>'role' IN ('PROMPT','MASKED') OR media->>'role' IN ('CLEAR','ACTOR') AND r->'publicRevealed'='true'::JSONB OR media->>'role'='ITEM' AND (gr->>'role'='JUDGE' OR r->'publicRevealed'='true'::JSONB OR r->'itemReveals' @> jsonb_build_array(media->'itemId') OR EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" c WHERE c."gameId"=game_id AND c."roundId"=r->>'id' AND c."itemId"=media->>'itemId')) END);
  END IF;
 END IF;
 IF pin IS NULL THEN PERFORM public.int9_error('MEDIA_DENIED'); END IF;

 IF (s->>'snapshot')::INTEGER IS DISTINCT FROM snapshot THEN RETURN jsonb_build_object('restart',TRUE); END IF;
 r:=NULL; s:=NULL; gr:=NULL;
 SELECT "byteLength","codec","durationMs","height","id","issuerEvidenceHash","manifestHash","mediaHash","mediaRevisionId","objectVersion","width" INTO p."byteLength",p."codec",p."durationMs",p."height",p."id",p."issuerEvidenceHash",p."manifestHash",p."mediaHash",p."mediaRevisionId",p."objectVersion",p."width" FROM public."MediaObjectProof" WHERE "id"=media_id AND "sealedAt" IS NOT NULL; SELECT "id","objectKey","mimeType" INTO m."id",m."objectKey",m."mimeType" FROM public."MediaRevision" WHERE "id"=p."mediaRevisionId" AND "mediaSha256"=p."mediaHash";
 IF p."id" IS NULL OR m."id" IS NULL OR p."mediaHash" IS DISTINCT FROM pin->>'sha256' OR (SELECT count(*) FROM public."MediaChunkProof" WHERE "proofId"=media_id) NOT BETWEEN 1 AND 256 THEN PERFORM public.int9_error('MEDIA_PROOF_UNAVAILABLE'); END IF;
 SELECT jsonb_agg(jsonb_build_object('ordinal',"ordinal",'byteLength',"byteLength",'sha256',"sha256") ORDER BY "ordinal") INTO chunks FROM public."MediaChunkProof" WHERE "proofId"=media_id;
 IF jsonb_array_length(chunks)<>ceil(p."byteLength"/262144.0) OR EXISTS(SELECT 1 FROM jsonb_array_elements(chunks) WITH ORDINALITY c(x,n) WHERE (x->>'ordinal')::INTEGER<>n-1 OR (x->>'byteLength')::INTEGER<>least(262144,p."byteLength"-(n-1)*262144) OR x->>'sha256'!~'^[a-f0-9]{64}$') THEN PERFORM public.int9_error('MEDIA_PROOF_UNAVAILABLE'); END IF;
 payload:=jsonb_build_object('version',1,'mediaRevisionId',p."mediaRevisionId",'sha256',p."mediaHash",'objectKey',m."objectKey",'mime',m."mimeType",'objectVersion',p."objectVersion",'byteLength',p."byteLength",'width',p."width",'height',p."height",'durationMs',p."durationMs",'codec',p."codec",'chunks',chunks,'issuerEvidenceHash',p."issuerEvidenceHash");
 IF p."manifestHash" IS DISTINCT FROM public.int6_enta_hash(payload) OR octet_length(convert_to(public.int6_enta_canonical(payload),'UTF8'))>524288 THEN PERFORM public.int9_error('MEDIA_PROOF_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('pin',pin||jsonb_build_object('chunks',chunks));
END $$;
CREATE FUNCTION public.int9_assert_clock_closure(game_id TEXT,event_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE e public."RoundAuthorityEvent"%ROWTYPE; fx public."CompetitiveEffect"%ROWTYPE; before_clock JSONB; after_clock JSONB; moment DOUBLE PRECISION; anchor DOUBLE PRECISION; pending BOOLEAN; review_open BOOLEAN; BEGIN
 SELECT "at","authorityKind","commandId","intentHash","roundId","sequence","type" INTO e."at",e."authorityKind",e."commandId",e."intentHash",e."roundId",e."sequence",e."type" FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "id"=event_id;
 IF e."type" IS DISTINCT FROM 'RECORDING_CLOSED' THEN RETURN; END IF;
 IF e."authorityKind" IS DISTINCT FROM 'SYSTEM' OR (SELECT count(*) FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "eventId"=event_id)<>1 THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 SELECT "kind","payload" INTO fx."kind",fx."payload" FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "eventId"=event_id; before_clock:=fx."payload"->'beforeClock'; after_clock:=fx."payload"->'afterClock'; moment:=floor(extract(epoch FROM e."at")*1000);
 IF before_clock->>'phase' NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN') OR before_clock->'deadline' IS NULL OR before_clock->'deadline'='null'::JSONB OR after_clock->'deadline' IS DISTINCT FROM 'null'::JSONB OR after_clock->'overallDeadline' IS DISTINCT FROM 'null'::JSONB OR after_clock->'pause' IS DISTINCT FROM 'null'::JSONB OR before_clock->'generation' IS DISTINCT FROM after_clock->'generation' THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 anchor:=(CASE WHEN before_clock->'overallDeadline'<>'null'::JSONB AND moment>=(before_clock->>'overallDeadline')::DOUBLE PRECISION THEN (before_clock->>'overallDeadline')::DOUBLE PRECISION ELSE (before_clock->>'deadline')::DOUBLE PRECISION END);
 IF moment<anchor OR e."intentHash" IS DISTINCT FROM public.int6_enta_hash(jsonb_build_object('type','RECORDING_CLOSED','roundId',e."roundId",'generation',after_clock->'generation','anchor',anchor,'moment',moment)) OR e."commandId" IS DISTINCT FROM 'clock-'||e."roundId"||'-'||(after_clock->>'generation')||'-'||(e."sequence"-1)::TEXT THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 pending:=EXISTS(SELECT 1 FROM public."CompetitiveAttempt" a JOIN public."RoundAuthorityEvent" recorded ON recorded."gameId"=a."gameId" AND recorded."id"=a."eventId" LEFT JOIN public."CompetitiveClassification" c ON c."gameId"=a."gameId" AND c."attemptId"=a."id" LEFT JOIN public."RoundAuthorityEvent" classified ON classified."gameId"=c."gameId" AND classified."id"=c."eventId" WHERE a."gameId"=game_id AND a."roundId"=e."roundId" AND recorded."sequence"<=e."sequence" AND (c."id" IS NULL OR classified."sequence">e."sequence"));
 review_open:=EXISTS(SELECT 1 FROM public."CompetitiveItemReview" review JOIN public."RoundAuthorityEvent" opened ON opened."gameId"=review."gameId" AND opened."id"=review."eventId" LEFT JOIN public."CompetitiveItemResolution" resolution ON resolution."gameId"=review."gameId" AND resolution."reviewId"=review."id" LEFT JOIN public."RoundAuthorityEvent" resolved ON resolved."gameId"=resolution."gameId" AND resolved."id"=resolution."eventId" WHERE review."gameId"=game_id AND review."roundId"=e."roundId" AND opened."sequence"<e."sequence" AND (resolution."id" IS NULL OR resolved."sequence">e."sequence"));
 IF after_clock->>'phase' IS DISTINCT FROM (CASE WHEN pending THEN 'AWAITING_RULING' ELSE 'RESOLVED' END) OR fx."kind" IS DISTINCT FROM (CASE WHEN pending OR review_open THEN 'TIMING' ELSE 'NO_SCORE' END) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
END $$;
CREATE FUNCTION public.int9_assert_round(game_id TEXT,round_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r public."GameRound"%ROWTYPE; x JSONB; item JSONB; runtime public."GameRuntime"%ROWTYPE; scope_row RECORD; BEGIN
 SELECT "gameQuestionId","id","ordinal","state" INTO r."gameQuestionId",r."id",r."ordinal",r."state" FROM public."GameRound" WHERE "gameId"=game_id AND "id"=round_id; SELECT "teamOrder" INTO runtime."teamOrder" FROM public."GameRuntime" WHERE "gameId"=game_id; x:=r."state";
 IF r."id" IS NULL OR public.int6_enta_exact_keys(x,ARRAY['id','questionId','ordinal','phase','phaseOrdinal','generation','version','originalTeamId','currentTeamId','originalDeadline','deadline','overallDeadline','pause','publicRevealed','itemReveals','assignment','pickedPlayerId','pickedEventId','usedAidIds','doubleAttemptTeamId','bonus','revealedHintIds','graphemeHints','consumed','reason','turnAdvanced','resourceStop']) IS NOT TRUE OR x->>'id' IS DISTINCT FROM r."id" OR x->>'questionId' IS DISTINCT FROM r."gameQuestionId" OR (x->>'ordinal')::INTEGER IS DISTINCT FROM r."ordinal" OR x->>'phase' NOT IN ('READY','MAIN','TRAP','STEAL','SHARED','TURN','AWAITING_RULING','RESOLVED') OR public.int5b_json_integer(x->'version',0,64945) IS NOT TRUE OR public.int5b_json_integer(x->'generation',0,2000000000) IS NOT TRUE OR public.int5b_json_integer(x->'phaseOrdinal',0,2000000000) IS NOT TRUE OR jsonb_typeof(x->'publicRevealed') IS DISTINCT FROM 'boolean' OR jsonb_typeof(x->'turnAdvanced') IS DISTINCT FROM 'boolean' THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 FOREACH item IN ARRAY ARRAY[x->'originalDeadline',x->'deadline',x->'overallDeadline'] LOOP IF item<>'null'::JSONB AND public.int5b_json_integer(item,0,9007199254740991) IS NOT TRUE THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF; END LOOP;
 IF x->>'originalTeamId' IS NOT NULL AND NOT x->>'originalTeamId'=ANY(runtime."teamOrder") OR x->>'currentTeamId' IS NOT NULL AND NOT x->>'currentTeamId'=ANY(runtime."teamOrder") OR x->>'doubleAttemptTeamId' IS NOT NULL AND NOT x->>'doubleAttemptTeamId'=ANY(runtime."teamOrder") THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 FOREACH item IN ARRAY ARRAY[x->'itemReveals',x->'usedAidIds',x->'revealedHintIds',x->'graphemeHints',x->'consumed'] LOOP IF jsonb_typeof(item) IS DISTINCT FROM 'array' OR jsonb_array_length(item)>128 THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF; END LOOP;
 IF jsonb_array_length(x->'revealedHintIds')>4 OR jsonb_array_length(x->'usedAidIds')>7 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(x->'itemReveals'))<>jsonb_array_length(x->'itemReveals') OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(x->'itemReveals') item WHERE NOT EXISTS(SELECT 1 FROM public."RoundItemPin" WHERE "roundId"=round_id AND "itemId"=item.value)) OR (SELECT count(*) FROM public."CompetitiveItemConsumption" WHERE "gameId"=game_id AND "roundId"=round_id)<>jsonb_array_length(x->'consumed') OR EXISTS(SELECT 1 FROM jsonb_array_elements(x->'consumed') item WHERE public.int6_enta_exact_keys(item,ARRAY['itemId','effectId','teamId']) IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" c WHERE c."gameId"=game_id AND c."roundId"=round_id AND c."itemId"=item->>'itemId' AND c."effectId"=item->>'effectId' AND c."teamId" IS NOT DISTINCT FROM item->>'teamId')) THEN PERFORM public.int9_error('ITEM_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(x->'graphemeHints') hint WHERE public.int6_enta_exact_keys(hint,ARRAY['proofId','itemId','eventId']) IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM public."CompetitiveRoundPin" pinned JOIN public."EntaCompetitiveGrapheme" proof ON proof."promptId"=pinned."promptId" JOIN public."RoundItemPin" item ON item."roundId"=pinned."roundId" AND item."answerRevisionId"=proof."answerRevisionId" AND item."answerHash"=proof."answerHash" JOIN public."CompetitiveConsumption" c ON c."gameId"=pinned."gameId" AND c."roundId"=pinned."roundId" AND c."eventId"=hint->>'eventId' AND c."aid"='HINT' JOIN public."CompetitiveEffect" effect ON effect."gameId"=c."gameId" AND effect."id"=c."effectId" AND effect."kind"='AID' AND effect."payload"->>'aid'='HINT' WHERE pinned."gameId"=game_id AND pinned."roundId"=round_id AND proof."id"=hint->>'proofId' AND item."itemId"=hint->>'itemId')) THEN PERFORM public.int9_error('GRAPHEME_PROOF_UNAVAILABLE'); END IF;
 IF x->'assignment'<>'null'::JSONB AND (public.int6_enta_exact_keys(x->'assignment',ARRAY['id','teamId','playerId','itemId','generation']) IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM public."RoundActorAssignment" a JOIN public."CompetitiveAssignmentPlayer" p ON p."gameId"=a."gameId" AND p."assignmentId"=a."id" WHERE a."gameId"=game_id AND a."roundId"=round_id AND a."id"=x->'assignment'->>'id' AND a."teamId"=x->'assignment'->>'teamId' AND a."itemId" IS NOT DISTINCT FROM x->'assignment'->>'itemId' AND a."generation"=(x->'assignment'->>'generation')::INTEGER AND p."playerId"=x->'assignment'->>'playerId')) THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 IF x->'pause'<>'null'::JSONB AND (public.int6_enta_exact_keys(x->'pause',ARRAY['cause','eventId','resumeAt','phaseRemaining','overallRemaining']) IS NOT TRUE OR x->'pause'->>'cause' NOT IN ('ADMIN','PHONE','FREEZE') OR NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" e WHERE e."gameId"=game_id AND e."roundId"=round_id AND e."id"=x->'pause'->>'eventId' AND e."type" IN ('PAUSE_ROUND','USE_AID'))) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 IF x->'resourceStop'<>'null'::JSONB AND (public.int6_enta_exact_keys(x->'resourceStop',ARRAY['eventId','at','reason']) IS NOT TRUE OR x->'resourceStop'->>'reason' NOT IN ('SYSTEM_CAPACITY','GENERATION_BOUND') OR NOT EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" e WHERE e."gameId"=game_id AND e."roundId"=round_id AND e."id"=x->'resourceStop'->>'eventId' AND e."type"='RESOURCE_LIMIT_REACHED' AND e."authorityKind"='SYSTEM' AND e."at"=to_timestamp((x->'resourceStop'->>'at')::DOUBLE PRECISION/1000))) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public."GameQuestion" q WHERE q."gameId"=game_id AND q."id"=r."gameQuestionId" AND q."isOpened"=(x->>'phase'<>'READY') AND q."isCorrect" IS NOT DISTINCT FROM CASE WHEN x->>'phase'='RESOLVED' THEN EXISTS(SELECT 1 FROM public."CompetitiveRulingHead" h JOIN public."CompetitiveEffect" e ON e."gameId"=h."gameId" AND e."id"=h."effectId" WHERE h."gameId"=game_id AND h."roundId"=round_id AND NOT h."reversed" AND e."payload"->'correctAttemptIds'<>'[]'::JSONB) ELSE NULL END) THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 FOR scope_row IN SELECT "id" FROM public."RoundGrantScope" WHERE "gameId"=game_id AND "roundId"=round_id AND "activeGrantId" IS NOT NULL LOOP PERFORM public.int9_assert_scope(game_id,scope_row."id"); END LOOP;
END $$;
CREATE FUNCTION public.int9_assert_scope(game_id TEXT,scope_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE sc public."RoundGrantScope"%ROWTYPE; gr public."RoundGrant"%ROWTYPE; r public."GameRound"%ROWTYPE; runtime public."GameRuntime"%ROWTYPE; head public."CompetitiveRuntimeHead"%ROWTYPE; BEGIN
 SELECT "activeGrantId","assignmentId","generation","id","role","roundId" INTO sc."activeGrantId",sc."assignmentId",sc."generation",sc."id",sc."role",sc."roundId" FROM public."RoundGrantScope" WHERE "gameId"=game_id AND "id"=scope_id; SELECT "id","pin","state" INTO r."id",r."pin",r."state" FROM public."GameRound" WHERE "gameId"=game_id AND "id"=sc."roundId"; SELECT "activeRoundId","state" INTO runtime."activeRoundId",runtime."state" FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT "boardReviewRoundId","openItemReviewId" INTO head."boardReviewRoundId",head."openItemReviewId" FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id;
 IF sc."id" IS NULL OR r."id" IS NULL OR public.int8_json_id(to_jsonb(sc."id")) IS NOT TRUE OR sc."generation" NOT BETWEEN 1 AND 2000000000 OR sc."role" NOT IN ('JUDGE','ACTOR') THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 IF sc."activeGrantId" IS NULL THEN RETURN; END IF; SELECT "assignmentId","generation","id","revoked","role","roundId","scopeId" INTO gr."assignmentId",gr."generation",gr."id",gr."revoked",gr."role",gr."roundId",gr."scopeId" FROM public."RoundGrant" WHERE "gameId"=game_id AND "id"=sc."activeGrantId";
 IF gr."id" IS NULL OR gr."scopeId" IS DISTINCT FROM sc."id" OR gr."roundId" IS DISTINCT FROM sc."roundId" OR gr."generation" IS DISTINCT FROM sc."generation" OR gr."role" IS DISTINCT FROM sc."role" OR gr."assignmentId" IS DISTINCT FROM sc."assignmentId" OR gr."revoked" OR runtime."state"='FINISHED' OR runtime."activeRoundId" IS DISTINCT FROM r."id" OR head."openItemReviewId" IS NOT NULL OR head."boardReviewRoundId" IS NOT NULL OR r."state"->'pause'<>'null'::JSONB OR r."state"->'resourceStop'<>'null'::JSONB OR r."state"->'publicRevealed'='true'::JSONB OR r."state"->>'phase' NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN') THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 IF sc."role"='JUDGE' THEN IF sc."assignmentId" IS NOT NULL OR r."pin"->>'format' NOT IN ('LIST_ITEMS','ACTING_ITEMS') THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 ELSE IF r."state"->'assignment'->>'id' IS DISTINCT FROM sc."assignmentId" OR r."pin"->>'format' NOT IN ('DRAWING_TARGET','ACTING_ITEMS') THEN PERFORM public.int9_error('GRANT_DENIED'); END IF; END IF;
END $$;
CREATE FUNCTION public.int9_resource_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM public."GameCompetitivePin" WHERE "gameId"=NEW."gameId" AND "requestVersion"=5) THEN
  IF NOT NEW."state"->'consumed' @> OLD."state"->'consumed' OR NOT NEW."state"->'itemReveals' @> OLD."state"->'itemReveals' OR NOT NEW."state"->'revealedHintIds' @> OLD."state"->'revealedHintIds' OR NOT NEW."state"->'graphemeHints' @> OLD."state"->'graphemeHints' OR NOT NEW."state"->'usedAidIds' @> OLD."state"->'usedAidIds' OR OLD."state"->'publicRevealed'='true'::JSONB AND NEW."state"->'publicRevealed' IS DISTINCT FROM 'true'::JSONB OR (NEW."state"->>'generation')::BIGINT<(OLD."state"->>'generation')::BIGINT OR (NEW."state"->>'phaseOrdinal')::BIGINT<(OLD."state"->>'phaseOrdinal')::BIGINT THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
  IF OLD."state"->'resourceStop'<>'null'::JSONB AND NEW."state"->'resourceStop' IS DISTINCT FROM OLD."state"->'resourceStop' OR OLD."state"->'resourceStop'='null'::JSONB AND NEW."state"->'resourceStop'<>'null'::JSONB AND (NEW."state"-ARRAY['resourceStop','version']) IS DISTINCT FROM (OLD."state"-ARRAY['resourceStop','version']) THEN PERFORM public.int9_error('CAPACITY_PROOF_UNAVAILABLE'); END IF;
 END IF; RETURN NEW;
END $$;
CREATE FUNCTION public.int9_scope_fact_complete(table_name TEXT,x JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE gid TEXT:=x->>'gameId'; e public."RoundAuthorityEvent"%ROWTYPE; gr public."RoundGrant"%ROWTYPE; scope_id TEXT; identity_id TEXT; BEGIN
 SELECT "firebaseIdentityId" INTO identity_id FROM public."GameCompetitivePin" WHERE "gameId"=gid;
 IF table_name='RoundAuthorityEvent' THEN
  SELECT "assignmentId","at","authorityGeneration","authorityGrantId","authorityKind","id","intentHash","ownerIdentityId","roundId","sequence","systemOperation","type" INTO e."assignmentId",e."at",e."authorityGeneration",e."authorityGrantId",e."authorityKind",e."id",e."intentHash",e."ownerIdentityId",e."roundId",e."sequence",e."systemOperation",e."type" FROM public."RoundAuthorityEvent" WHERE "gameId"=gid AND "id"=x->>'id';
  IF e."ownerIdentityId" IS DISTINCT FROM identity_id OR e."sequence" NOT BETWEEN 2 AND 64946 OR e."intentHash"!~'^[a-f0-9]{64}$' OR e."roundId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."GameRound" WHERE "gameId"=gid AND "id"=e."roundId") THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
  IF e."authorityKind"='HOST' THEN IF e."authorityGrantId" IS NOT NULL OR e."authorityGeneration" IS NOT NULL OR e."assignmentId" IS NOT NULL OR e."systemOperation" IS NOT NULL THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
  ELSIF e."authorityKind"='SYSTEM' THEN IF e."authorityGrantId" IS NOT NULL OR e."authorityGeneration" IS NOT NULL OR e."assignmentId" IS NOT NULL OR e."systemOperation" IS DISTINCT FROM 'CLOCK_SETTLEMENT' OR e."type" NOT IN ('PHONE_ENDED','STEAL_OPENED','TURN_TRANSFERRED','RECORDING_CLOSED','RESOURCE_LIMIT_REACHED') THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
  ELSIF e."authorityKind"='GRANT' THEN
   IF e."type" NOT IN ('TARGET_DELIVERY','CANVAS_APPEND','CANVAS_UNDO','CANVAS_REDO','CANVAS_CLEAR') OR e."systemOperation" IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public."RoundGrant" grant_row JOIN public."CompetitiveAssignmentPlayer" assignment ON assignment."assignmentId"=grant_row."assignmentId" AND assignment."gameId"=grant_row."gameId" AND assignment."roundId"=grant_row."roundId" WHERE grant_row."id"=e."authorityGrantId" AND grant_row."gameId"=gid AND grant_row."roundId"=e."roundId" AND grant_row."role"='ACTOR' AND grant_row."generation"=e."authorityGeneration" AND grant_row."assignmentId"=e."assignmentId" AND grant_row."expiresAt">e."at") THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
  ELSE PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
  PERFORM public.int9_assert_charge(gid,e."id"); PERFORM public.int9_assert_clock_closure(gid,e."id"); RETURN;
 END IF;
 IF table_name='RoundGrant' THEN
  SELECT "expiresAt","generation","id","revoked","roundId","scopeId","tokenHash" INTO gr."expiresAt",gr."generation",gr."id",gr."revoked",gr."roundId",gr."scopeId",gr."tokenHash" FROM public."RoundGrant" WHERE "gameId"=gid AND "id"=x->>'id'; SELECT "assignmentId","at","authorityGeneration","authorityGrantId","authorityKind","id","intentHash","ownerIdentityId","roundId","sequence","systemOperation","type" INTO e."assignmentId",e."at",e."authorityGeneration",e."authorityGrantId",e."authorityKind",e."id",e."intentHash",e."ownerIdentityId",e."roundId",e."sequence",e."systemOperation",e."type" FROM public."RoundAuthorityEvent" WHERE "gameId"=gid AND "id"=gr."id";
  IF gr."id" IS NULL OR e."id" IS NULL OR e."roundId" IS DISTINCT FROM gr."roundId" OR e."authorityKind" IS DISTINCT FROM 'HOST' OR e."type" NOT IN ('CREATE_GRANT','ROTATE_GRANT','REVOKE_GRANT') OR gr."generation" NOT BETWEEN 1 AND 2000000000 OR gr."tokenHash"!~'^[a-f0-9]{64}$' OR (CASE WHEN e."type"='REVOKE_GRANT' THEN NOT gr."revoked" OR gr."expiresAt" IS DISTINCT FROM e."at" ELSE gr."expiresAt"<=e."at" OR gr."expiresAt">e."at"+interval '600 seconds' END) THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
  scope_id:=gr."scopeId";
 ELSIF table_name='RoundGrantScope' THEN scope_id:=x->>'id'; ELSE PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
 PERFORM public.int9_assert_scope(gid,scope_id);
END $$;
CREATE FUNCTION public.int9_mutable_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE gid TEXT; BEGIN
 gid:=(CASE WHEN TG_TABLE_NAME='DrawingCanvasState' THEN (SELECT "gameId" FROM public."GameRound" WHERE "id"=NEW."roundId") ELSE to_jsonb(NEW)->>'gameId' END);
 IF NOT EXISTS(SELECT 1 FROM public."GameCompetitivePin" WHERE "gameId"=gid AND "requestVersion"=5) THEN RETURN NULL; END IF;
 IF TG_TABLE_NAME='GameRound' THEN IF NEW."state"=(SELECT "state" FROM public."GameRound" WHERE "id"=NEW."id") THEN PERFORM public.int9_assert_round(gid,NEW."id"); END IF;
 ELSIF TG_TABLE_NAME='GameQuestion' THEN IF to_jsonb(NEW)=(SELECT to_jsonb(current_row) FROM public."GameQuestion" current_row WHERE current_row."id"=NEW."id") THEN PERFORM public.int9_assert_round(gid,(SELECT "id" FROM public."GameRound" WHERE "gameId"=gid AND "gameQuestionId"=NEW."id")); END IF;
 ELSIF TG_TABLE_NAME='DrawingCanvasState' THEN IF NEW."revision"=(SELECT "revision" FROM public."DrawingCanvasState" WHERE "roundId"=NEW."roundId") THEN PERFORM public.int9_assert_canvas(gid,NEW."roundId"); END IF;
 ELSE PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF; RETURN NULL;
END $$;
CREATE FUNCTION public.int9_namespace_tuple_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_RELID<>'public."DeploymentNamespace"'::regclass OR TG_TABLE_SCHEMA<>'public' OR TG_TABLE_NAME<>'DeploymentNamespace' OR TG_WHEN<>'BEFORE' OR TG_LEVEL<>'ROW' OR TG_NARGS<>0 OR TG_OP NOT IN ('INSERT','UPDATE','DELETE') THEN PERFORM public.int9_error('NAMESPACE_CONTINUITY_DENIED'); END IF;
 IF TG_OP='INSERT' THEN IF NEW."id" IS DISTINCT FROM 'singleton' THEN PERFORM public.int9_error('NAMESPACE_CONTINUITY_DENIED'); END IF; RETURN NEW; END IF;
 IF TG_OP='DELETE' OR ROW(NEW."id",NEW."namespaceId",NEW."firebaseProjectId") IS DISTINCT FROM ROW(OLD."id",OLD."namespaceId",OLD."firebaseProjectId") THEN PERFORM public.int9_error('NAMESPACE_CONTINUITY_DENIED'); END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION public.int9_namespace_truncate_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_RELID<>'public."DeploymentNamespace"'::regclass OR TG_TABLE_SCHEMA<>'public' OR TG_TABLE_NAME<>'DeploymentNamespace' OR TG_WHEN<>'BEFORE' OR TG_LEVEL<>'STATEMENT' OR TG_OP<>'TRUNCATE' OR TG_NARGS<>0 THEN PERFORM public.int9_error('NAMESPACE_CONTINUITY_DENIED'); END IF;
 PERFORM public.int9_error('NAMESPACE_CONTINUITY_DENIED'); RETURN NULL;
END $$;
CREATE FUNCTION public.int9_public_media(m JSONB) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE WHEN m IS NULL OR m='null'::JSONB THEN 'null'::JSONB ELSE jsonb_build_object('id',m->'id','mime',m->'mime','bytes',m->'bytes','width',m->'width','height',m->'height','durationMs',m->'durationMs') END $$;
CREATE FUNCTION public.int9_scope_dto(game_id TEXT,uid TEXT,grant_row JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE revision INTEGER; active_id TEXT; project TEXT; rid TEXT; r RECORD; canvas_revision INTEGER; visibility JSONB; result JSONB; BEGIN
 SELECT rt."version",rt."activeRoundId",i."firebaseProjectId" INTO revision,active_id,project FROM public."GameRuntime" rt JOIN public."Game" g ON g."id"=rt."gameId" JOIN public."FirebaseIdentity" i ON i."id"=g."firebaseIdentityId" WHERE rt."gameId"=game_id;
 rid:=COALESCE(grant_row->>'roundId',active_id); SELECT "id","state"->'version' AS version,"state"->'assignment'->'generation' AS assignment_generation,"pin"->'format' AS format INTO r FROM public."GameRound" WHERE "gameId"=game_id AND "id"=rid;
 SELECT "revision" INTO canvas_revision FROM public."DrawingCanvasState" WHERE "roundId"=rid;
 SELECT jsonb_build_object('gameId',game_id,'version',revision,'activeRoundId',active_id,'review',head."openItemReviewId",'correction',head."boardReviewRoundId",'rounds',(SELECT jsonb_agg(jsonb_build_object('id',round_row."id",'version',round_row."state"->'version','pause',round_row."state"->'pause'->'eventId','assignment',round_row."state"->'assignment'->'generation','revealed',round_row."state"->'publicRevealed','stopped',round_row."state"->'resourceStop'->'eventId') ORDER BY round_row."ordinal") FROM public."GameRound" round_row WHERE round_row."gameId"=game_id),'grant',CASE WHEN grant_row IS NULL THEN 'null'::JSONB ELSE jsonb_build_object('id',grant_row->'id','generation',grant_row->'generation','expiresAt',grant_row->'expiresAt') END) INTO visibility FROM public."CompetitiveRuntimeHead" head WHERE head."gameId"=game_id;
 result:=jsonb_build_object('gameId',game_id,'projectId',project,'principal',COALESCE(grant_row->>'id',uid),'purpose',COALESCE(grant_row->>'role','OWNER'),'visibility',public.int6_enta_hash(visibility),'snapshot',revision,'roundId',rid,'roundVersion',r.version,'format',r.format,'itemTotal',(SELECT count(*) FROM public."RoundItemPin" WHERE "roundId"=rid),'canvasRevision',canvas_revision,'assignmentGeneration',r.assignment_generation,'grant',CASE WHEN grant_row IS NULL THEN 'null'::JSONB ELSE grant_row-ARRAY['assignmentId','tokenHash'] END);
 visibility:=NULL; r:=NULL; IF octet_length(convert_to(public.int6_enta_canonical(result),'UTF8'))>8192 THEN PERFORM public.int9_error('PROJECTION_BOUND_EXCEEDED'); END IF; RETURN result;
END $$;
CREATE FUNCTION public.int9_grant_physical(game_id TEXT,token_hash TEXT,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE gr public."RoundGrant"%ROWTYPE; scope public."RoundGrantScope"%ROWTYPE; r RECORD; rt RECORD; head RECORD; BEGIN
 SELECT "assignmentId","expiresAt","generation","id","revoked","role","roundId","scopeId","tokenHash" INTO gr."assignmentId",gr."expiresAt",gr."generation",gr."id",gr."revoked",gr."role",gr."roundId",gr."scopeId",gr."tokenHash" FROM public."RoundGrant" WHERE "gameId"=game_id AND "tokenHash"=token_hash; SELECT "activeGrantId","assignmentId","generation","id" INTO scope."activeGrantId",scope."assignmentId",scope."generation",scope."id" FROM public."RoundGrantScope" WHERE "gameId"=game_id AND "id"=gr."scopeId";
 SELECT "state","pin"->>'format' AS format INTO r FROM public."GameRound" WHERE "gameId"=game_id AND "id"=gr."roundId"; SELECT "state","activeRoundId" INTO rt FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT "openItemReviewId","boardReviewRoundId" INTO head FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id;
 IF token_hash IS NULL OR token_hash!~'^[a-f0-9]{64}$' OR gr."id" IS NULL OR scope."id" IS NULL OR r."state" IS NULL OR rt."state"='FINISHED' OR head."openItemReviewId" IS NOT NULL OR head."boardReviewRoundId" IS NOT NULL OR gr."revoked" OR moment>=floor(extract(epoch FROM gr."expiresAt")*1000) OR scope."activeGrantId" IS DISTINCT FROM gr."id" OR scope."generation" IS DISTINCT FROM gr."generation" OR scope."assignmentId" IS DISTINCT FROM gr."assignmentId" OR rt."activeRoundId" IS DISTINCT FROM gr."roundId" OR r."state"->'pause'<>'null'::JSONB OR r."state"->'resourceStop'<>'null'::JSONB OR r."state"->'publicRevealed'='true'::JSONB OR r."state"->>'phase' NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN') OR r."state"->'deadline'='null'::JSONB OR moment>=(r."state"->>'deadline')::DOUBLE PRECISION OR r."state"->'overallDeadline'<>'null'::JSONB AND moment>=(r."state"->>'overallDeadline')::DOUBLE PRECISION THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 IF gr."role"='JUDGE' THEN IF r.format NOT IN ('LIST_ITEMS','ACTING_ITEMS') OR gr."assignmentId" IS NOT NULL THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 ELSIF gr."role"='ACTOR' THEN IF r."state"->'assignment'='null'::JSONB OR r."state"->'assignment'->>'id' IS DISTINCT FROM gr."assignmentId" OR r.format NOT IN ('ACTING_ITEMS','DRAWING_TARGET') OR r."state"->'assignment'->'itemId'<>'null'::JSONB AND (r."state"->'itemReveals' @> jsonb_build_array(r."state"->'assignment'->'itemId') OR EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used WHERE used."gameId"=game_id AND used."roundId"=gr."roundId" AND used."itemId"=r."state"->'assignment'->>'itemId')) THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 ELSE PERFORM public.int9_error('GRANT_DENIED'); END IF;
 r:=NULL; rt:=NULL; head:=NULL; scope:=NULL;
 RETURN jsonb_build_object('id',gr."id",'scopeId',gr."scopeId",'roundId',gr."roundId",'role',gr."role",'assignmentId',gr."assignmentId",'generation',gr."generation",'tokenHash',gr."tokenHash",'expiresAt',floor(extract(epoch FROM gr."expiresAt")*1000),'revoked',gr."revoked");
END $$;
CREATE FUNCTION public.int9_main_dto(game_id TEXT,moment DOUBLE PRECISION) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE g RECORD; rt RECORD; head RECORD; current_id TEXT; current_state JSONB; current_pin JSONB; current_prompt TEXT; current_prompt_id TEXT; teams JSONB; categories JSONB; rounds JSONB; current_value JSONB; result JSONB; dto JSONB; latest JSONB; review JSONB; grants JSONB; allowances JSONB; pending_total INTEGER; feedback_total INTEGER; media_total INTEGER; format_release TEXT; BEGIN
 SELECT "id","executionFormat" INTO g FROM public."Game" WHERE "id"=game_id; SELECT "version","state","activeRoundId","turnIndex","teamOrder","setup" INTO rt FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT "latestEffectId","boardReviewRoundId","openItemReviewId" INTO head FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id; SELECT "formatReleaseId" INTO format_release FROM public."EntaExecutionPin" WHERE "gameId"=game_id;
 IF g."id" IS NULL OR rt."version" IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 current_id:=COALESCE(rt."activeRoundId",(SELECT "roundId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),(SELECT a."roundId" FROM public."CompetitiveAttempt" a JOIN public."GameRound" r ON r."gameId"=a."gameId" AND r."id"=a."roundId" WHERE a."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" cl WHERE cl."gameId"=game_id AND cl."attemptId"=a."id") ORDER BY r."ordinal" LIMIT 1));
 SELECT jsonb_agg(jsonb_build_object('id',t."id",'name',t."name",'colorKey',rt."setup"->'teams'->(ordered.ordinal::INTEGER-1)->'colorKey','color',CASE rt."setup"->'teams'->(ordered.ordinal::INTEGER-1)->>'colorKey' WHEN 'CORAL' THEN '#ff7a4d' WHEN 'SKY' THEN '#3fc6ff' WHEN 'VIOLET' THEN '#7c5cff' WHEN 'MINT' THEN '#34d399' WHEN 'GOLD' THEN '#ffc94d' ELSE '#ff5c72' END,'players',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',p."id",'name',p."name") ORDER BY roster."ordinal"),'[]'::JSONB) FROM public."CompetitiveRosterPlayer" roster JOIN public."Player" p ON p."id"=roster."playerId" AND p."teamId"=roster."teamId" WHERE roster."gameId"=game_id AND roster."teamId"=t."id"),'score',t."score",'aids',rt."setup"->'teams'->(ordered.ordinal::INTEGER-1)->'aids') ORDER BY ordered.ordinal) INTO teams FROM unnest(rt."teamOrder") WITH ORDINALITY ordered(id,ordinal) JOIN public."Team" t ON t."gameId"=game_id AND t."id"=ordered.id;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('key',category."categoryKey",'label',left(revision."labelAr",64),'format',(SELECT r."pin"->'format' FROM public."GameRound" r WHERE r."gameId"=game_id AND r."categoryKey"=category."categoryKey" ORDER BY r."ordinal" LIMIT 1),'cover',(SELECT public.int9_public_media(public.int9_media_descriptor(cover."proofId",'COVER',NULL)) FROM public."EntaFormatCover" cover WHERE cover."releaseId"=format_release AND cover."categoryKey"=category."categoryKey")) ORDER BY category."ordinal"),'[]'::JSONB) INTO categories FROM public."GameCategoryPin" category JOIN public."CanonicalCategoryRevision" revision ON revision."id"=category."categoryRevisionId" WHERE category."gameId"=game_id;
 SELECT jsonb_agg(jsonb_build_object('id',r."id",'ordinal',r."ordinal",'categoryKey',r."categoryKey",'format',r."pin"->'format','points',r."pin"->'points','phase',r."state"->'phase') ORDER BY r."ordinal") INTO rounds FROM public."GameRound" r WHERE r."gameId"=game_id;
 current_value:='null'::JSONB; pending_total:=0; feedback_total:=0; media_total:=0;
 IF current_id IS NOT NULL THEN
  SELECT r."state",jsonb_build_object('format',r."pin"->'format','points',r."pin"->'points','target',CASE WHEN r."state"->'publicRevealed'='true'::JSONB THEN r."pin"->'target' ELSE 'null'::JSONB END),q."prompt",cp."promptId" INTO current_state,current_pin,current_prompt,current_prompt_id FROM public."GameRound" r JOIN public."CompetitiveRoundPin" cp ON cp."gameId"=r."gameId" AND cp."roundId"=r."id" JOIN public."QuestionRevision" q ON q."id"=r."questionRevisionId" AND q."contentHash"=r."questionHash" WHERE r."gameId"=game_id AND r."id"=current_id;
  SELECT count(*) INTO pending_total FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND a."roundId"=current_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" cl WHERE cl."gameId"=game_id AND cl."attemptId"=a."id");
  SELECT count(*) INTO feedback_total FROM public."RoundItemPin" i WHERE i."roundId"=current_id AND (current_state->'publicRevealed'='true'::JSONB OR current_state->'itemReveals' @> jsonb_build_array(i."itemId") OR EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used WHERE used."gameId"=game_id AND used."roundId"=current_id AND used."itemId"=i."itemId") OR EXISTS(SELECT 1 FROM jsonb_array_elements(current_state->'graphemeHints') hint JOIN public."CompetitiveConsumption" consumed ON consumed."gameId"=game_id AND consumed."roundId"=current_id AND consumed."aid"='HINT' AND consumed."eventId"=hint->>'eventId' WHERE hint->>'itemId'=i."itemId"));
  IF rt."state"<>'FINISHED' AND head."openItemReviewId" IS NULL AND head."boardReviewRoundId" IS NULL AND current_state->'pause'='null'::JSONB AND current_state->'resourceStop'='null'::JSONB AND current_state->>'phase'<>'READY' THEN SELECT count(*) INTO media_total FROM public."EntaFormatMedia" m JOIN public."GameRound" r ON r."formatId"=m."formatId" WHERE r."gameId"=game_id AND r."id"=current_id AND (m."role" IN ('PROMPT','MASKED') OR m."role" IN ('CLEAR','ACTOR') AND current_state->'publicRevealed'='true'::JSONB OR m."role"='ITEM' AND (current_state->'publicRevealed'='true'::JSONB OR current_state->'itemReveals' @> jsonb_build_array(m."itemId") OR EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used WHERE used."gameId"=game_id AND used."roundId"=current_id AND used."itemId"=m."itemId"))); END IF;
  current_value:=jsonb_build_object('id',current_id,'version',current_state->'version','phase',current_state->'phase','phaseOrdinal',current_state->'phaseOrdinal','generation',current_state->'generation','format',current_pin->'format','prompt',current_prompt,'points',current_pin->'points','originalTeamId',current_state->'originalTeamId','currentTeamId',current_state->'currentTeamId','deadline',current_state->'deadline','overallDeadline',current_state->'overallDeadline','pause',CASE WHEN current_state->'pause'='null'::JSONB THEN 'null'::JSONB ELSE jsonb_build_object('cause',current_state->'pause'->'cause','resumeAt',current_state->'pause'->'resumeAt','phaseRemaining',current_state->'pause'->'phaseRemaining','overallRemaining',current_state->'pause'->'overallRemaining') END,'resourceStop',current_state->'resourceStop','publicRevealed',current_state->'publicRevealed','items',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i."itemId",'ordinal',i."ordinal",'consumed',EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used WHERE used."gameId"=game_id AND used."roundId"=current_id AND used."itemId"=i."itemId"),'revealed',current_state->'publicRevealed'='true'::JSONB OR current_state->'itemReveals' @> jsonb_build_array(i."itemId") OR EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used WHERE used."gameId"=game_id AND used."roundId"=current_id AND used."itemId"=i."itemId")) ORDER BY i."ordinal"),'[]'::JSONB) FROM public."RoundItemPin" i WHERE i."roundId"=current_id),'hints',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',hint."id",'text',hint."text") ORDER BY hint."ordinal"),'[]'::JSONB) FROM public."EntaCompetitiveHint" hint WHERE hint."promptId"=current_prompt_id AND current_state->'revealedHintIds' @> jsonb_build_array(hint."id")),'graphemeHints','[]'::JSONB,'assignment',CASE WHEN current_state->'assignment'='null'::JSONB THEN 'null'::JSONB ELSE jsonb_build_object('teamId',current_state->'assignment'->'teamId','playerId',current_state->'assignment'->'playerId','itemId',current_state->'assignment'->'itemId','generation',current_state->'assignment'->'generation') END,'pickedPlayerId',current_state->'pickedPlayerId','eligibleAids',to_jsonb(public.int9_aids(g."executionFormat",current_pin->>'format')),'media','[]'::JSONB,'canvas',CASE WHEN current_pin->>'format'='DRAWING_TARGET' THEN jsonb_build_object('revision',COALESCE((SELECT "revision" FROM public."DrawingCanvasState" WHERE "roundId"=current_id),0)) ELSE 'null'::JSONB END);
  IF current_state->'publicRevealed'='true'::JSONB AND current_pin->'target'<>'null'::JSONB THEN current_value:=current_value||jsonb_build_object('target',current_pin->'target'); END IF;
 END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a."id",'teamId',a."teamId",'aid',a."aid",'roundId',a."roundId",'consumed',EXISTS(SELECT 1 FROM public."CompetitiveConsumption" used WHERE used."gameId"=game_id AND used."allowanceId"=a."id")) ORDER BY a."teamId" COLLATE "C",a."ordinal"),'[]'::JSONB) INTO allowances FROM public."CompetitiveAllowance" a WHERE a."gameId"=game_id AND (a."roundId" IS NULL OR a."roundId"=current_id);
 SELECT jsonb_build_object('id',e."id",'hash',e."hash",'kind',e."kind",'reversible',e."reversible",'postings',(SELECT COALESCE(jsonb_agg(jsonb_build_object('teamId',p."teamId",'delta',p."delta") ORDER BY p."scoreVersion"),'[]'::JSONB) FROM public."CompetitiveScorePosting" p WHERE p."gameId"=game_id AND p."effectId"=e."id")) INTO latest FROM public."CompetitiveEffect" e WHERE e."gameId"=game_id AND e."id"=head."latestEffectId";
 SELECT jsonb_build_object('id',review_row."id",'hash',review_row."hash",'roundId',review_row."roundId",'itemId',review_row."itemId",'originalEffectId',review_row."originalEffectId",'rulingVersion',ruling."version") INTO review FROM public."CompetitiveItemReview" review_row JOIN public."CompetitiveRulingHead" ruling ON ruling."gameId"=review_row."gameId" AND ruling."originalEffectId"=review_row."originalEffectId" WHERE review_row."gameId"=game_id AND review_row."id"=head."openItemReviewId";
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',gr."id",'scopeId',gr."scopeId",'roundId',gr."roundId",'role',gr."role",'generation',gr."generation",'expiresAt',floor(extract(epoch FROM gr."expiresAt")*1000),'revoked',gr."revoked") ORDER BY gr."id" COLLATE "C"),'[]'::JSONB) INTO grants FROM public."RoundGrant" gr JOIN public."RoundGrantScope" scope ON scope."gameId"=gr."gameId" AND scope."activeGrantId"=gr."id" WHERE gr."gameId"=game_id AND scope."roundId"=current_id;
 SELECT jsonb_build_object('payload',r."payload",'hash',r."resultHash") INTO result FROM public."EngineMatchResultHead" h JOIN public."EngineMatchResult" r ON r."gameId"=h."gameId" AND r."resultVersion"=h."resultVersion" AND r."resultHash"=h."resultHash" WHERE h."gameId"=game_id;
 dto:=jsonb_build_object('id',game_id,'requestVersion',5,'rulesVersion','enta-competitive-1','version',rt."version",'executionFormat',g."executionFormat",'serverNow',moment,'finished',rt."state"='FINISHED','turnTeamId',to_jsonb(rt."teamOrder"[(rt."turnIndex"%cardinality(rt."teamOrder"))+1]),'collections',jsonb_build_object('pending',pending_total,'rulings',(SELECT count(*) FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id),'feedback',feedback_total,'media',media_total),'teams',teams,'categories',categories,'rounds',rounds,'currentRound',current_value,'allowances',allowances,'attempts','[]'::JSONB,'rulings','[]'::JSONB,'latestEffect',latest,'review',review,'boardCorrectionRoundId',head."boardReviewRoundId",'grants',grants,'result',result);
 current_state:=NULL; current_pin:=NULL; current_value:=NULL; rt."setup":=NULL; teams:=NULL; categories:=NULL; rounds:=NULL; latest:=NULL; review:=NULL; grants:=NULL; allowances:=NULL; result:=NULL;
 IF octet_length(convert_to(public.int6_enta_canonical(dto),'UTF8'))>65536 THEN PERFORM public.int9_error('PROJECTION_BOUND_EXCEEDED'); END IF; RETURN dto;
END $$;
CREATE FUNCTION public.int9_operation_pin(game_id TEXT,round_id TEXT,c JSONB) RETURNS JSONB LANGUAGE SQL STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('categoryKey',r."categoryKey",'format',r."pin"->'format','points',r."pin"->'points','revisionId',r."pin"->'revisionId','hash',r."pin"->'hash','target',r."pin"->'target','effectValue',cp."pin"->'effectValue',
 'items',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i."id",'revisionId',i."answerRevisionId",'hash',i."answerHash",'ordinal',i."ordinal",'value',i."value",'trap',i."trap") ORDER BY i."ordinal"),'[]'::JSONB) FROM public."EntaFormatItem" i WHERE i."formatId"=r."formatId"),
 'hints',CASE WHEN c->>'type'='REVEAL_HINT' OR c->>'type'='USE_AID' AND c->>'aid'='MORE_HINT' THEN (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',h."id",'ordinal',h."ordinal",'text',h."text",'safeDrawing',h."safeDrawing") ORDER BY h."ordinal"),'[]'::JSONB) FROM public."EntaCompetitiveHint" h WHERE h."promptId"=cp."promptId") ELSE '[]'::JSONB END,
 'graphemes',CASE WHEN c->>'type'='USE_AID' AND c->>'aid'='HINT' THEN (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',g."id",'answerRevisionId',g."answerRevisionId",'answerHash',g."answerHash",'segmentationVersion',g."segmentationVersion",'grapheme',g."grapheme",'proofHash',g."proofHash") ORDER BY i."ordinal"),'[]'::JSONB) FROM public."EntaCompetitiveGrapheme" g JOIN public."EntaFormatItem" i ON i."formatId"=r."formatId" AND i."answerRevisionId"=g."answerRevisionId" AND i."answerHash"=g."answerHash" WHERE g."promptId"=cp."promptId") ELSE '[]'::JSONB END)
 FROM public."GameRound" r JOIN public."CompetitiveRoundPin" cp ON cp."gameId"=r."gameId" AND cp."roundId"=r."id" WHERE r."gameId"=game_id AND r."id"=round_id
$$;
CREATE FUNCTION public.int9_operation_context(game_id TEXT,requested_round TEXT,requested_effect TEXT,requested_scope TEXT,command JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE g public."Game"%ROWTYPE; rt public."GameRuntime"%ROWTYPE; execution public."EntaExecutionPin"%ROWTYPE; head public."CompetitiveRuntimeHead"%ROWTYPE; identity_row public."FirebaseIdentity"%ROWTYPE; selected_round TEXT; state JSONB; teams JSONB; categories JSONB; rounds JSONB; effects JSONB; ids TEXT[]; x JSONB; effect_sequence INTEGER; selected_descriptor JSONB; BEGIN
 SELECT "id","firebaseIdentityId","admissionId" INTO g."id",g."firebaseIdentityId",g."admissionId" FROM public."Game" WHERE "id"=game_id; SELECT "version","state","activeRoundId","turnIndex","teamOrder","setup","resultReason" INTO rt."version",rt."state",rt."activeRoundId",rt."turnIndex",rt."teamOrder",rt."setup",rt."resultReason" FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT "clientBinding","clientHash","intentHash","formatReleaseId",jsonb_build_object('domain',"fullIntent"->'domain','pinMaterial',"fullIntent"->'pinMaterial','seed',"fullIntent"->'seed') INTO execution."clientBinding",execution."clientHash",execution."intentHash",execution."formatReleaseId",execution."fullIntent" FROM public."EntaExecutionPin" WHERE "gameId"=game_id; SELECT "boardReviewRoundId","latestEffectId","openItemReviewId" INTO head."boardReviewRoundId",head."latestEffectId",head."openItemReviewId" FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id; SELECT "firebaseProjectId","firebaseUid" INTO identity_row."firebaseProjectId",identity_row."firebaseUid" FROM public."FirebaseIdentity" WHERE "id"=g."firebaseIdentityId";
 IF execution."clientBinding"->'version' IS DISTINCT FROM '5'::JSONB OR execution."fullIntent"->>'domain' IS DISTINCT FROM 'maydan.enta.competitive.start-intent.v1' OR execution."fullIntent"->>'pinMaterial' IS DISTINCT FROM 'maydan.enta.competitive.pin-references.v1' THEN PERFORM public.int9_error('DRAFT5_COMPATIBILITY_REVIEW_REQUIRED'); END IF;
 selected_round:=COALESCE(rt."activeRoundId",(SELECT "roundId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),head."boardReviewRoundId",(SELECT a."roundId" FROM public."CompetitiveAttempt" a JOIN public."GameRound" r ON r."gameId"=a."gameId" AND r."id"=a."roundId" WHERE a."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."attemptId"=a."id") ORDER BY r."ordinal" LIMIT 1),requested_round,(SELECT "roundId" FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=requested_effect));
 SELECT COALESCE(max("sequence"),0) INTO effect_sequence FROM public."CompetitiveEffect" WHERE "gameId"=game_id;
 SELECT jsonb_agg(jsonb_build_object('id',t."id",'name',t."name",'colorKey',rt."setup"->'teams'->(ordered.ordinal::INTEGER-1)->'colorKey','aids',rt."setup"->'teams'->(ordered.ordinal::INTEGER-1)->'aids','players',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',player."id",'name',player."name") ORDER BY roster."ordinal"),'[]'::JSONB) FROM public."CompetitiveRosterPlayer" roster JOIN public."Player" player ON player."id"=roster."playerId" AND player."teamId"=roster."teamId" WHERE roster."gameId"=game_id AND roster."teamId"=t."id"),'score',t."score",'scoreVersion',COALESCE((SELECT max("scoreVersion") FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "teamId"=t."id"),0),'scoreHead',(SELECT "effectId" FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "teamId"=t."id" ORDER BY "scoreVersion" DESC LIMIT 1)) ORDER BY ordered.ordinal) INTO teams FROM unnest(rt."teamOrder") WITH ORDINALITY ordered(team_id,ordinal) JOIN public."Team" t ON t."gameId"=game_id AND t."id"=ordered.team_id;
 categories:='[]'::JSONB;
 SELECT COALESCE(jsonb_agg(CASE WHEN r."id"=selected_round THEN r."state"||jsonb_build_object('pin',public.int9_operation_pin(r."gameId",r."id",command)) ELSE jsonb_build_object('contextSummary',TRUE,'id',r."id",'questionId',r."gameQuestionId",'ordinal',r."ordinal",'phase',r."state"->'phase','version',r."state"->'version','phaseOrdinal',r."state"->'phaseOrdinal','generation',r."state"->'generation','deadline',r."state"->'deadline','overallDeadline',r."state"->'overallDeadline','pause',r."state"->'pause','assignment',r."state"->'assignment','publicRevealed',r."state"->'publicRevealed','resourceStop',r."state"->'resourceStop','pin',jsonb_build_object('categoryKey',r."categoryKey",'format',r."pin"->'format','points',r."pin"->'points'),'consumed','[]'::JSONB) END ORDER BY r."ordinal"),'[]'::JSONB) INTO rounds FROM public."GameRound" r JOIN public."CompetitiveRoundPin" cp ON cp."gameId"=r."gameId" AND cp."roundId"=r."id" WHERE r."gameId"=game_id;
 ids:=ARRAY_REMOVE(ARRAY[requested_effect,head."latestEffectId",(SELECT "originalEffectId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),(SELECT "reversalEffectId" FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),(SELECT "effectId" FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id AND "originalEffectId"=requested_effect)],NULL);
 SELECT COALESCE(jsonb_agg("payload" ORDER BY "sequence"),'[]'::JSONB) INTO effects FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=ANY(ids) AND command->>'type' IN ('UNDO_EFFECT','CORRECT_RULING','RESOLVE_ITEM_REVIEW');
 state:=jsonb_build_object('id',game_id,'identityId',g."firebaseIdentityId",'projectId',identity_row."firebaseProjectId",'hostUid',identity_row."firebaseUid",'admissionId',g."admissionId",'request',execution."clientBinding",'requestHash',execution."clientHash",'intent',jsonb_build_object('seed',execution."fullIntent"->'seed'),'intentHash',execution."intentHash",'version',rt."version",'finished',rt."state"='FINISHED','activeRoundId',rt."activeRoundId",'turnIndex',rt."turnIndex",'resultReason',CASE WHEN rt."state"='FINISHED' THEN CASE WHEN rt."resultReason"='HOST_ENDED' THEN 'HOST_ENDED' ELSE 'ALL_ROUNDS' END ELSE NULL END,'teams',teams,'categories',categories,'rounds',rounds,'effects',effects,'events','[]'::JSONB,'reports','[]'::JSONB,'resultSignals','[]'::JSONB,'capacityReservations','[]'::JSONB,'capacityDispositions','[]'::JSONB,'latestEffectId',head."latestEffectId",'correctionReview',head."boardReviewRoundId",'openItemReview',head."openItemReviewId",'tournamentBinding',NULL); rounds:=NULL; effects:=NULL; teams:=NULL; categories:=NULL; execution."clientBinding":=NULL; execution."fullIntent":=NULL;
 state:=state||jsonb_build_object('attempts',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a."id",'roundId',a."roundId",'itemId',a."itemId",'teamId',a."teamId",'playerId',a."playerId",'phase',a."phase",'phaseOrdinal',a."phaseOrdinal",'generation',a."generation",'bonusMultiplier',a."payload"->'bonusMultiplier','bonusEventId',a."bonusEventId") ORDER BY e."sequence",a."id" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveAttempt" a JOIN public."RoundAuthorityEvent" e ON e."gameId"=a."gameId" AND e."id"=a."eventId" WHERE a."gameId"=game_id AND a."roundId"=selected_round AND COALESCE(command->>'type','CLOCK') NOT IN ('UNDO_EFFECT','APPEND','UNDO','REDO','CLEAR')),
 'classifications',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',c."id",'attemptId',c."attemptId",'eventId',c."eventId",'correct',c."correct",'interim',c."interim") ORDER BY e."sequence",c."id" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveClassification" c JOIN public."CompetitiveAttempt" a ON a."gameId"=c."gameId" AND a."id"=c."attemptId" JOIN public."RoundAuthorityEvent" e ON e."gameId"=c."gameId" AND e."id"=c."eventId" WHERE c."gameId"=game_id AND a."roundId"=selected_round AND COALESCE(command->>'type','CLOCK') NOT IN ('UNDO_EFFECT','CORRECT_RULING','RESOLVE_ITEM_REVIEW','APPEND','UNDO','REDO','CLEAR')),
 'postings',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',p."id",'effectId',p."effectId",'teamId',p."teamId",'delta',p."delta",'before',p."before",'after',p."after",'scoreVersion',p."scoreVersion",'previousHead',p."previousHeadId") ORDER BY p."scoreVersion",p."id" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveScorePosting" p WHERE p."gameId"=game_id AND p."effectId"=ANY(ids) AND command->>'type' IN ('UNDO_EFFECT','CORRECT_RULING','RESOLVE_ITEM_REVIEW')),
 'rulings',(SELECT COALESCE(jsonb_agg(jsonb_build_object('roundId',h."roundId",'itemId',h."itemId",'scopeId',h."scopeId",'originalEffectId',h."originalEffectId",'effectId',h."effectId",'version',h."version",'hash',h."hash",'reversed',h."reversed") ORDER BY h."scopeId" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveRulingHead" h WHERE h."gameId"=game_id AND h."roundId"=selected_round AND (h."originalEffectId"=ANY(ids) OR h."effectId"=ANY(ids)) AND command->>'type' IN ('UNDO_EFFECT','CORRECT_RULING','RESOLVE_ITEM_REVIEW')),
 'itemReviews',(SELECT COALESCE(jsonb_agg("payload"),'[]'::JSONB) FROM public."CompetitiveItemReview" WHERE "gameId"=game_id AND "id"=head."openItemReviewId"),'itemResolutions','[]'::JSONB,
 'results',(SELECT COALESCE(jsonb_agg(jsonb_build_object('payload',result."payload",'hash',result."resultHash")),'[]'::JSONB) FROM public."EngineMatchResult" result JOIN public."EngineMatchResultHead" result_head ON result_head."gameId"=result."gameId" AND result_head."resultVersion"=result."resultVersion" AND result_head."resultHash"=result."resultHash" WHERE result."gameId"=game_id));
 state:=state||jsonb_build_object('allowances',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a."id",'teamId',a."teamId",'aid',a."aid",'scope',a."scope",'scopeId',a."scopeId",'roundId',a."roundId") ORDER BY a."teamId" COLLATE "C",a."ordinal"),'[]'::JSONB) FROM public."CompetitiveAllowance" a WHERE a."gameId"=game_id),
 'consumptions',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',c."id",'allowanceId',c."allowanceId",'roundId',c."roundId",'eventId',c."eventId",'effectId',c."effectId",'aid',c."aid",'teamId',c."teamId")),'[]'::JSONB) FROM public."CompetitiveConsumption" c WHERE c."gameId"=game_id),
 'disclosures',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',d."id",'roundId',d."roundId",'targetRevisionId',d."targetRevisionId",'targetHash',d."targetHash",'playerId',d."playerId",'assignmentId',d."assignmentId",'assignmentGeneration',d."assignmentGeneration",'at',floor(extract(epoch FROM d."createdAt")*1000),'grantId',d."grantId",'grantGeneration',d."grantGeneration") ORDER BY d."createdAt",d."id" COLLATE "C"),'[]'::JSONB) FROM public."CompetitiveTargetDisclosure" d WHERE d."gameId"=game_id AND d."roundId"=selected_round AND command->>'type'='RECORD_ATTEMPT'),
 'grantScopes',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',sc."id",'roundId',sc."roundId",'role',sc."role",'assignmentId',sc."assignmentId",'generation',sc."generation",'activeGrantId',sc."activeGrantId") ORDER BY sc."id" COLLATE "C"),'[]'::JSONB) FROM public."RoundGrantScope" sc WHERE sc."gameId"=game_id AND (sc."roundId"=selected_round AND sc."activeGrantId" IS NOT NULL OR sc."id"=requested_scope)),
 'grants',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',gr."id",'scopeId',gr."scopeId",'roundId',gr."roundId",'role',gr."role",'assignmentId',gr."assignmentId",'generation',gr."generation",'tokenHash',gr."tokenHash",'expiresAt',floor(extract(epoch FROM gr."expiresAt")*1000),'revoked',gr."revoked") ORDER BY gr."id" COLLATE "C"),'[]'::JSONB) FROM public."RoundGrant" gr JOIN public."RoundGrantScope" sc ON sc."gameId"=gr."gameId" AND sc."id"=gr."scopeId" AND sc."activeGrantId"=gr."id" WHERE gr."gameId"=game_id AND sc."roundId"=selected_round),
 'canvases',CASE WHEN command->>'type' IN ('APPEND','UNDO','REDO','CLEAR') THEN (SELECT COALESCE(jsonb_agg("state"),'[]'::JSONB) FROM public."DrawingCanvasState" WHERE "roundId"=selected_round) ELSE '[]'::JSONB END);
 IF jsonb_array_length(state->'attempts')>512 OR EXISTS(SELECT 1 FROM jsonb_array_elements(state->'attempts') a WHERE octet_length(a::TEXT)>2048) OR jsonb_array_length(state->'effects')>5 OR jsonb_array_length(state->'grantScopes')>3 OR jsonb_array_length(state->'grants')>2 OR octet_length(state::TEXT)>4194304 THEN PERFORM public.int9_error('CONTEXT_BOUND_EXCEEDED'); END IF;
 RETURN state||jsonb_build_object('factContext',jsonb_build_object('version',1,'selectedRoundId',selected_round,'effectSequence',effect_sequence,'pendingTotal',(SELECT count(*) FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."attemptId"=a."id")),'rulingTotal',(SELECT count(*) FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id),'terminalValidated',rt."state"='FINISHED'));
END $$;
CREATE FUNCTION public.int9_historical_empty_closure(game_id TEXT,effect_id TEXT) RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM public."CompetitiveEffect" e JOIN public."RoundAuthorityEvent" event ON event."gameId"=e."gameId" AND event."id"=e."eventId" JOIN public."CompetitiveRulingHead" h ON h."gameId"=e."gameId" AND h."originalEffectId"=e."id" JOIN public."GameRound" r ON r."gameId"=e."gameId" AND r."id"=e."roundId"
  WHERE e."gameId"=game_id AND e."id"=effect_id AND e."kind"='NO_SCORE' AND e."amountKind"='NONE' AND NOT e."reversible" AND e."barrier" AND e."predecessorId" IS NULL AND h."itemId" IS NULL AND h."effectId"=e."id" AND h."version"=1 AND NOT h."reversed" AND r."pin"->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') AND r."state"->>'phase'='RESOLVED' AND e."payload"->'afterClock'->>'phase'='RESOLVED' AND e."payload"->'correctAttemptIds'='[]'::JSONB AND e."payload"->'postingIds'='[]'::JSONB AND e."payload"->'reads'='[]'::JSONB AND e."payload"->'dependencies'='[]'::JSONB
  AND (event."authorityKind"='HOST' AND event."type"='FINAL_RULING' OR event."authorityKind"='SYSTEM' AND event."type"='RECORDING_CLOSED')
  AND (SELECT count(*) FROM public."CompetitiveEffect" sibling WHERE sibling."gameId"=game_id AND sibling."eventId"=event."id")=1
  AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" cl WHERE cl."gameId"=game_id AND cl."eventId"=event."id")
  AND NOT EXISTS(SELECT 1 FROM public."CompetitiveScorePosting" p JOIN public."CompetitiveEffect" posting_effect ON posting_effect."gameId"=p."gameId" AND posting_effect."id"=p."effectId" WHERE p."gameId"=game_id AND posting_effect."eventId"=event."id")
  AND NOT EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used JOIN public."CompetitiveEffect" consumption_effect ON consumption_effect."gameId"=used."gameId" AND consumption_effect."id"=used."effectId" WHERE used."gameId"=game_id AND consumption_effect."eventId"=event."id")
  AND (SELECT count(*) FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND a."roundId"=e."roundId")=jsonb_array_length(e."payload"->'originalAttemptIds')
  AND NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" a LEFT JOIN public."RoundAuthorityEvent" attempt_event ON attempt_event."gameId"=a."gameId" AND attempt_event."id"=a."eventId" LEFT JOIN public."CompetitiveClassification" cl ON cl."gameId"=a."gameId" AND cl."attemptId"=a."id" LEFT JOIN public."RoundAuthorityEvent" classification_event ON classification_event."gameId"=cl."gameId" AND classification_event."id"=cl."eventId" WHERE a."gameId"=game_id AND a."roundId"=e."roundId" AND (NOT e."payload"->'originalAttemptIds' @> jsonb_build_array(a."id") OR attempt_event."sequence" IS NULL OR attempt_event."sequence">=event."sequence" OR cl."id" IS NULL OR classification_event."sequence" IS NULL OR classification_event."sequence">=event."sequence")))
$$;
CREATE FUNCTION public.int9_effect_patch(event_row JSONB,effect_sequence INTEGER,round_id TEXT,clock_after JSONB,kind TEXT,options JSONB) RETURNS JSONB LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$ DECLARE effect JSONB; BEGIN
 IF effect_sequence NOT BETWEEN 1 AND 64945 OR jsonb_typeof(options) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(options) key WHERE key NOT IN ('aid','amountKind','reversible','barrier','reads','dependencies','postingIds','beforeClock','originalAttemptIds','correctAttemptIds','bonusSnapshot','predecessorId','predecessorHash','reason')) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 effect:=jsonb_build_object('id',gen_random_uuid()::TEXT,'eventId',event_row->'id','sequence',effect_sequence,'roundId',round_id,'kind',kind,'aid',NULL,'amountKind','NONE','reversible',FALSE,'barrier',TRUE,'reads','[]'::JSONB,'dependencies','[]'::JSONB,'postingIds','[]'::JSONB,'beforeClock',NULL,'afterClock',clock_after,'originalAttemptIds','[]'::JSONB,'correctAttemptIds','[]'::JSONB,'bonusSnapshot','[]'::JSONB,'predecessorId',NULL,'predecessorHash',NULL,'reason',NULL,'hash','')||options;
 RETURN effect;
END $$;
CREATE FUNCTION public.int9_mutation_owner(game_id TEXT,requested_round TEXT,requested_effect TEXT,requested_scope TEXT,c JSONB,proposal JSONB,command_hash TEXT,grant_row JSONB,moment DOUBLE PRECISION) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE s JSONB; h JSONB; b JSONB; revision INTEGER; BEGIN
 IF c->>'type'='FINAL_RULING' AND grant_row IS NULL THEN PERFORM public.int9_ruling_owner(game_id,c,command_hash,moment); RETURN TRUE; END IF;
 IF c IS NULL OR c='null'::JSONB THEN RETURN public.int9_clock_owner(game_id,moment); END IF;
 h:=public.int9_before_header(game_id); revision:=(h->>'version')::INTEGER;
 s:=public.int9_operation_context(game_id,requested_round,requested_effect,requested_scope,c);
 IF grant_row IS NOT NULL THEN
 <<canvas_control_owned>>  DECLARE r JSONB:=public.int9_round((SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['rounds'])),grant_row->>'roundId'); canvas JSONB; stroke JSONB; leaf_input JSONB; leaf_output JSONB; original_has_fact_context BOOLEAN; original_events_is_array BOOLEAN; BEGIN
 IF grant_row->>'role'<>'ACTOR' OR r->'pin'->>'format'<>'DRAWING_TARGET' OR public.int9_review((SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['openItemReview','correctionReview']))) OR r->'pause'<>'null'::JSONB THEN PERFORM public.int9_error('CANVAS_DENIED'); END IF;
 SELECT value INTO canvas FROM jsonb_array_elements(s->'canvases') WHERE value->'roundId'=r->'id'; IF canvas IS NULL THEN PERFORM public.int9_error('CANVAS_UNAVAILABLE'); END IF;
 IF c->'expectedRevision' IS DISTINCT FROM canvas->'revision' THEN PERFORM public.int9_error('STALE_CANVAS_REVISION'); END IF; IF (canvas->>'mutations')::INTEGER>=512 THEN PERFORM public.int9_error('CANVAS_BUDGET_EXCEEDED'); END IF;
 IF c->>'type'='APPEND' THEN stroke:=c->'stroke'; IF jsonb_array_length(canvas->'strokes')>=128 OR (canvas->>'cumulativePoints')::INTEGER+jsonb_array_length(stroke->'points')>8192 OR EXISTS(SELECT 1 FROM jsonb_array_elements(canvas->'strokes') prior WHERE prior->'id'=stroke->'id') THEN PERFORM public.int9_error('CANVAS_BUDGET_EXCEEDED'); END IF; canvas:=canvas||jsonb_build_object('strokes',canvas->'strokes'||jsonb_build_array(stroke),'visibleIds',canvas->'visibleIds'||jsonb_build_array(stroke->'id'),'redoIds','[]'::JSONB,'cumulativePoints',(canvas->>'cumulativePoints')::INTEGER+jsonb_array_length(stroke->'points'));
 ELSIF c->>'type'='UNDO' THEN IF canvas->'visibleIds'='[]'::JSONB THEN PERFORM public.int9_error('CANVAS_EMPTY'); END IF; canvas:=canvas||jsonb_build_object('redoIds',canvas->'redoIds'||jsonb_build_array(canvas->'visibleIds'->-1),'visibleIds',(canvas->'visibleIds')-(jsonb_array_length(canvas->'visibleIds')-1));
 ELSIF c->>'type'='REDO' THEN IF canvas->'redoIds'='[]'::JSONB THEN PERFORM public.int9_error('NO_REDO'); END IF; canvas:=canvas||jsonb_build_object('visibleIds',canvas->'visibleIds'||jsonb_build_array(canvas->'redoIds'->-1),'redoIds',(canvas->'redoIds')-(jsonb_array_length(canvas->'redoIds')-1));
 ELSE canvas:=canvas||jsonb_build_object('visibleIds','[]'::JSONB,'redoIds','[]'::JSONB); END IF;
 canvas:=canvas||jsonb_build_object('revision',(canvas->>'revision')::INTEGER+1,'mutations',(canvas->>'mutations')::INTEGER+1,'receipts',canvas->'receipts'||jsonb_build_array(jsonb_build_object('commandId',c->>'commandId','hash',public.int6_enta_hash(c),'revision',(canvas->>'revision')::INTEGER+1)));
 s:=jsonb_set(s,'{canvases}',(SELECT jsonb_agg(CASE WHEN x->'roundId'=r->'id' THEN canvas ELSE x END ORDER BY ord) FROM jsonb_array_elements(s->'canvases') WITH ORDINALITY canvases(x,ord))); SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['version','identityId','events']);
 original_events_is_array:=jsonb_typeof(s->'events')='array';
 IF original_events_is_array THEN leaf_input:=jsonb_set(leaf_input,'{events}','[]'::JSONB); END IF;
 leaf_output:=public.int9_event(leaf_input,c->>'commandId',public.int6_enta_hash(c),'CANVAS_'||(c->>'type'),r->>'id',jsonb_build_object('kind','GRANT','grantId',grant_row->'id','generation',grant_row->'generation','assignmentId',grant_row->'assignmentId'),moment,NULL);
 IF leaf_output IS NULL THEN s:=NULL; ELSE s:=s||jsonb_build_object('version',leaf_output->'version','events',CASE WHEN original_events_is_array THEN s->'events'||leaf_output->'events' ELSE leaf_output->'events' END); END IF;
 leaf_input:=NULL; leaf_output:=NULL; original_has_fact_context:=s ? 'factContext';
 SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['events','effects','factContext']);
 IF s ? 'events' THEN leaf_input:=jsonb_set(leaf_input,'{events}',jsonb_build_array(s->'events'->-1)); END IF;
 IF original_has_fact_context THEN leaf_input:=jsonb_set(leaf_input,'{effects}','[]'::JSONB,TRUE); END IF;
 leaf_output:=public.int9_effect(leaf_input,r,'TIMING','{}'::JSONB);
 IF leaf_output IS NULL THEN s:=NULL; ELSE
  IF original_has_fact_context THEN s:=jsonb_set(s,'{factContext,effectSequence}',leaf_output->'factContext'->'effectSequence'); END IF;
  s:=s||jsonb_build_object('effects',CASE WHEN original_has_fact_context THEN s->'effects'||leaf_output->'effects' ELSE leaf_output->'effects' END,'latestEffectId',leaf_output->'latestEffectId');
 END IF;
 leaf_input:=NULL; leaf_output:=NULL;
 leaf_input:=jsonb_build_object('effects',jsonb_build_array(s->'effects'->-1)); leaf_output:=public.int9_seal(leaf_input);
 IF leaf_output IS NULL THEN s:=NULL; ELSE s:=jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT],leaf_output->'effects'->-1); END IF;
 leaf_input:=NULL; leaf_output:=NULL;
END canvas_control_owned;
 ELSIF c->>'type' IN ('USE_AID','RECORD_ATTEMPT','INTERIM_WRONG','PUBLIC_REVEAL','CREATE_GRANT','ROTATE_GRANT','REVOKE_GRANT','UNDO_EFFECT','CORRECT_RULING','RESOLVE_ITEM_REVIEW') THEN

<<aid_reduce_preamble>>
DECLARE kind TEXT:=c->>'type'; dispatch_round JSONB; projection JSONB;
BEGIN
 IF (s->>'finished')::BOOLEAN THEN PERFORM public.int9_error('MATCH_FINISHED'); END IF;
 IF s->'openItemReview'<>'null'::JSONB AND kind NOT IN ('RESOLVE_ITEM_REVIEW','REVOKE_GRANT') OR s->'correctionReview'<>'null'::JSONB AND kind NOT IN ('CORRECT_RULING','REVOKE_GRANT') THEN PERFORM public.int9_error('RULING_REVIEW_OPEN'); END IF;
 SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO projection FROM jsonb_each(s) field(field_key,field_value) WHERE field_key='rounds';
 dispatch_round:=public.int9_round(projection,c->>'roundId'); projection:=NULL;
 IF dispatch_round->'resourceStop' IS DISTINCT FROM 'null'::JSONB AND dispatch_round IS NOT NULL AND kind NOT IN ('PUBLIC_REVEAL','FINAL_RULING','CLOSE_ROUND','END_ASSISTANCE','RESUME_ROUND','REVOKE_GRANT','RESOLVE_ITEM_REVIEW','CORRECT_RULING','FINISH','REPORT_VAR') THEN PERFORM public.int9_error('RESOURCE_LIMIT_REACHED'); END IF;
 dispatch_round:=NULL;
 IF kind='USE_AID' THEN
 <<aid_control_owned>>
 DECLARE r JSONB; standalone BOOLEAN; aid TEXT; tid TEXT; allowance JSONB; before_clock JSONB; hint JSONB; item JSONB; proof JSONB; player JSONB; opponent JSONB; effect JSONB; consumption JSONB; amount BIGINT; idx INTEGER; leaf_input JSONB; leaf_output JSONB; original_has_fact_context BOOLEAN; original_events_is_array BOOLEAN;
 BEGIN
  SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key='rounds'; r:=public.int9_round(leaf_input,c->>'roundId'); leaf_input:=NULL;
  SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key='request';
  standalone:=public.int9_standalone(leaf_input); leaf_input:=NULL;
  aid:=c->>'aid'; tid:=c->>'teamId';
  SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['openItemReview','correctionReview']);
  IF public.int9_review(leaf_input) OR r->'pause'<>'null'::JSONB OR (r->>'publicRevealed')::BOOLEAN OR r->>'phase' NOT IN ('MAIN','SHARED','TURN') OR r->'deadline'='null'::JSONB OR moment>=(r->>'deadline')::DOUBLE PRECISION OR tid IS DISTINCT FROM (CASE WHEN standalone THEN r->>'currentTeamId' ELSE r->>'originalTeamId' END) OR NOT aid=ANY(public.int9_aids(s->'request'->>'executionFormat',r->'pin'->>'format')) THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
