  END IF;
  leaf_input:=NULL; leaf_output:=NULL;
 IF aid IN ('PHONE_A_FRIEND','PHONE','FREEZE') THEN r:=r||jsonb_build_object('pause',jsonb_build_object('cause',CASE WHEN aid='FREEZE' THEN 'FREEZE' ELSE 'PHONE' END,'eventId',s->'events'->-1->'id','resumeAt',CASE WHEN aid='FREEZE' THEN NULL ELSE moment+60000 END,'phaseRemaining',(r->>'deadline')::DOUBLE PRECISION-moment,'overallRemaining',CASE WHEN r->'overallDeadline'='null'::JSONB THEN NULL ELSE greatest(0,(r->>'overallDeadline')::DOUBLE PRECISION-moment) END),'deadline',NULL,'overallDeadline',NULL);
 ELSIF aid IN ('DOUBLE_ANSWER','DOUBLE') THEN IF r->'doubleAttemptTeamId'<>'null'::JSONB THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF; r:=r||jsonb_build_object('doubleAttemptTeamId',tid);
