  IF jsonb_array_length(r->'pin'->'hints')=0 OR NOT public.int9_items(r) AND NOT r->'revealedHintIds' @> jsonb_build_array(r->'pin'->'hints'->0->'id') THEN PERFORM public.int9_error('HINT_UNAVAILABLE'); END IF;
  SELECT x INTO hint FROM jsonb_array_elements(r->'pin'->'hints') WITH ORDINALITY hints(x,ord) WHERE NOT r->'revealedHintIds' @> jsonb_build_array(x->'id') ORDER BY ord LIMIT 1; IF hint IS NULL OR r->'pin'->>'format'='DRAWING_TARGET' AND hint->'safeDrawing' IS DISTINCT FROM 'true'::JSONB THEN PERFORM public.int9_error('HINT_UNAVAILABLE'); END IF; r:=r||jsonb_build_object('revealedHintIds',r->'revealedHintIds'||jsonb_build_array(hint->'id'));
 ELSIF aid='HINT' THEN
  SELECT x INTO item FROM jsonb_array_elements(r->'pin'->'items') x WHERE x->'trap'='false'::JSONB AND NOT r->'itemReveals' @> jsonb_build_array(x->'id') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=x->'id') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'graphemeHints') used WHERE used->'itemId'=x->'id') ORDER BY (x->>'value')::INTEGER DESC,(x->>'ordinal')::INTEGER LIMIT 1;
  SELECT x INTO proof FROM jsonb_array_elements(r->'pin'->'graphemes') x WHERE x->'answerRevisionId'=item->'revisionId' AND x->'answerHash'=item->'hash'; IF item IS NULL OR proof IS NULL THEN PERFORM public.int9_error('HINT_UNAVAILABLE'); END IF; r:=r||jsonb_build_object('graphemeHints',r->'graphemeHints'||jsonb_build_array(jsonb_build_object('proofId',proof->'id','itemId',item->'id','eventId',s->'events'->-1->'id')));
 ELSIF aid='PICK_ANSWERER' THEN SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['teams','disclosures']); leaf_output:=public.int9_players(leaf_input,r,tid); leaf_input:=NULL; SELECT x INTO player FROM jsonb_array_elements(leaf_output) x ORDER BY public.int6_enta_hash(jsonb_build_array(s->'intent'->>'seed',r->>'id',r->'generation',x->>'id')) COLLATE "C",(x->>'id') COLLATE "C" LIMIT 1; leaf_output:=NULL; IF player IS NULL THEN PERFORM public.int9_error('NO_ELIGIBLE_PLAYER'); END IF; r:=r||jsonb_build_object('pickedPlayerId',player->'id','pickedEventId',s->'events'->-1->'id');
 ELSIF aid='TRAP' THEN
  IF r->'usedAidIds'<>'[]'::JSONB OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'attempts') a WHERE a->'roundId'=r->'id') THEN PERFORM public.int9_error('AID_PAIRING_DENIED'); END IF; SELECT ord::INTEGER-1 INTO idx FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'=r->>'originalTeamId'; r:=r||jsonb_build_object('phase','TRAP','phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+1,'generation',(r->>'generation')::INTEGER+1,'currentTeamId',s->'teams'->((idx+1)%jsonb_array_length(s->'teams'))->'id','deadline',least((r->>'deadline')::DOUBLE PRECISION,moment+10000),'doubleAttemptTeamId',NULL); SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['grants','grantScopes','rounds']); leaf_output:=public.int9_invalidate(leaf_input,r,FALSE);
  IF leaf_output IS NULL THEN s:=NULL; ELSE s:=s||jsonb_build_object('grants',leaf_output->'grants','grantScopes',leaf_output->'grantScopes','rounds',leaf_output->'rounds'); END IF;
  leaf_input:=NULL; leaf_output:=NULL; SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['rounds']); r:=public.int9_round(leaf_input,r->>'id'); leaf_input:=NULL;
 ELSIF aid='PASS' THEN IF r->>'doubleAttemptTeamId'=tid AND (SELECT count(*) FROM jsonb_array_elements(s->'attempts') a WHERE a->'roundId'=r->'id' AND a->>'teamId'=tid AND a->'generation'=r->'generation')<2 THEN PERFORM public.int9_error('AID_PAIRING_DENIED'); END IF; <<aid_transfer_owned>>
  DECLARE transfer_round JSONB:=r; transfer_idx INTEGER;
  BEGIN
 SELECT ord::INTEGER-1 INTO transfer_idx FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'=transfer_round->>'currentTeamId';
 transfer_round:=transfer_round||jsonb_build_object('currentTeamId',s->'teams'->((transfer_idx+1)%jsonb_array_length(s->'teams'))->'id','phaseOrdinal',(transfer_round->>'phaseOrdinal')::INTEGER+1,'generation',(transfer_round->>'generation')::INTEGER+1,'doubleAttemptTeamId',NULL,'deadline',moment+(s->'request'->'setup'->'rules'->>'turnSeconds')::INTEGER*1000,'version',(transfer_round->>'version')::INTEGER+1);
   SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['grants','grantScopes','rounds']); leaf_output:=public.int9_invalidate(leaf_input,transfer_round,FALSE);
  IF leaf_output IS NULL THEN s:=NULL; ELSE s:=s||jsonb_build_object('grants',leaf_output->'grants','grantScopes',leaf_output->'grantScopes','rounds',leaf_output->'rounds'); END IF;
