  SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['rounds']); r:=public.int9_round(leaf_input,r->>'id'); leaf_input:=NULL;
