  SELECT x INTO opponent FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'<>tid ORDER BY (x->>'score')::INTEGER DESC,ord LIMIT 1; amount:=least((r->'pin'->>'effectValue')::BIGINT,greatest(0,(opponent->>'score')::BIGINT)); IF opponent IS NULL OR amount=0 THEN PERFORM public.int9_error('AID_UNAVAILABLE'); END IF;
  effect:=s->'effects'->-1; effect:=effect||jsonb_build_object('amountKind','DERIVED','reversible',TRUE,'reads',(SELECT jsonb_agg(public.int9_read(x,'RANK') ORDER BY ord) FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'<>tid),'dependencies',(SELECT COALESCE(jsonb_agg(value ORDER BY first_ord),'[]'::JSONB) FROM (SELECT x->'scoreHead' value,min(ord) first_ord FROM jsonb_array_elements(s->'teams') WITH ORDINALITY teams(x,ord) WHERE x->>'id'<>tid AND x->'scoreHead'<>'null'::JSONB GROUP BY x->'scoreHead') distinct_heads)); s:=jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT],effect); SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['teams','effects','postings','request']);
  leaf_input:=jsonb_set(leaf_input,'{effects}',jsonb_build_array(s->'effects'->-1));
  leaf_output:=public.int9_post(leaf_input,opponent->>'id',-amount,FALSE);
