   s:=jsonb_set(s,'{teams}',leaf_output->'teams');
   s:=jsonb_set(s,ARRAY['effects',(jsonb_array_length(s->'effects')-1)::TEXT],leaf_output->'effects'->-1);
   s:=jsonb_set(s,'{postings}',leaf_output->'postings');
