  leaf_input:=NULL; leaf_output:=NULL;
  SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['teams','effects','postings','request']);
