 END aid_control_owned;
 ELSIF kind='RECORD_ATTEMPT' THEN
 <<attempt_control_owned>>  DECLARE r JSONB:=public.int9_round((SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['rounds'])),c->>'roundId'); tid TEXT:=c->>'teamId'; player_id TEXT:=c->>'playerId'; previous JSONB; players JSONB; snapshot JSONB; attempt JSONB; allowance JSONB; picked BOOLEAN; budget INTEGER; leaf_input JSONB; leaf_output JSONB; original_has_fact_context BOOLEAN; original_events_is_array BOOLEAN; BEGIN
 IF s->'activeRoundId' IS DISTINCT FROM r->'id' OR public.int9_review((SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['openItemReview','correctionReview']))) OR r->'pause'<>'null'::JSONB OR (r->>'publicRevealed')::BOOLEAN OR r->'deadline'='null'::JSONB OR moment>=(r->>'deadline')::DOUBLE PRECISION OR r->>'phase' NOT IN ('MAIN','TRAP','STEAL','SHARED','TURN') THEN PERFORM public.int9_error('ATTEMPT_UNAVAILABLE'); END IF;
 IF (CASE r->>'phase' WHEN 'STEAL' THEN tid=r->>'originalTeamId' WHEN 'SHARED' THEN FALSE ELSE tid IS DISTINCT FROM r->>'currentTeamId' END) OR (CASE WHEN public.int9_items(r) THEN c->'itemId'='null'::JSONB OR r->'itemReveals' @> jsonb_build_array(c->'itemId') OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=c->'itemId') ELSE c->'itemId'<>'null'::JSONB END) THEN PERFORM public.int9_error('ATTEMPT_UNAVAILABLE'); END IF;
 SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) INTO leaf_input FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['teams','disclosures']); players:=public.int9_players(leaf_input,r,tid); leaf_input:=NULL; picked:=EXISTS(SELECT 1 FROM jsonb_array_elements(s->'teams') t CROSS JOIN LATERAL jsonb_array_elements(t->'players') p WHERE t->>'id'=tid AND p->'id'=r->'pickedPlayerId'); IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(players) p WHERE p->>'id'=player_id) OR picked AND player_id IS DISTINCT FROM r->>'pickedPlayerId' THEN PERFORM public.int9_error('NO_ELIGIBLE_PLAYER'); END IF;
