 IF leaf_output IS NULL THEN s:=NULL; ELSE s:=s||jsonb_build_object('version',leaf_output->'version','events',CASE WHEN original_events_is_array THEN s->'events'||leaf_output->'events' ELSE leaf_output->'events' END); END IF;
 leaf_input:=NULL; leaf_output:=NULL; SELECT x INTO allowance FROM jsonb_array_elements(s->'allowances') x WHERE r->>'doubleAttemptTeamId'=tid AND x->>'teamId'=tid AND x->>'aid' IN ('DOUBLE','DOUBLE_ANSWER') AND x->>'scopeId'=(CASE WHEN public.int9_standalone((SELECT COALESCE(jsonb_object_agg(field_key,field_value),'{}'::JSONB) FROM jsonb_each(s) field(field_key,field_value) WHERE field_key=ANY(ARRAY['request']))) THEN r->>'id' ELSE s->>'id' END);
 snapshot:=jsonb_build_object('roundId',r->'id','phase',r->'phase','phaseOrdinal',r->'phaseOrdinal','generation',r->'generation','teamId',tid,'playerId',player_id,'eligiblePlayerIds',(SELECT jsonb_agg(p->'id' ORDER BY ord) FROM jsonb_array_elements(players) WITH ORDINALITY p(p,ord)),'pickedEventId',CASE WHEN picked THEN r->'pickedEventId' ELSE 'null'::JSONB END,'disclosureHead',(SELECT x->'id' FROM jsonb_array_elements(s->'disclosures') WITH ORDINALITY disclosures(x,ord) WHERE x->'roundId'=r->'id' ORDER BY ord DESC LIMIT 1),'deadline',r->'deadline');
