 IF changes<>'{}'::JSONB THEN owned_batch:=owned_batch||jsonb_build_object('headChanges',changes); END IF; changes:=NULL; physical:=NULL;
 IF s->'finished'='true'::JSONB AND h->'finished'='false'::JSONB THEN
  SELECT e INTO final_event FROM jsonb_array_elements(events) e WHERE e->>'type'='FINISH';
  SELECT COALESCE(jsonb_agg(x),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->'results') x WHERE x->'payload'->'authority'->'eventId'=final_event->'id';
  IF jsonb_array_length(selected)<>1 THEN PERFORM public.int9_error('RESULT_INTEGRITY_FAILURE'); END IF;
  owned_batch:=owned_batch||jsonb_build_object('results',selected,'resultHead',jsonb_build_object('resultVersion',selected->0->'payload'->'resultVersion','resultHash',selected->0->'hash'),'gameChanges',jsonb_build_object('status','FINISHED','finishedAt',final_event->'at','winnerTeamId',CASE WHEN jsonb_array_length(selected->0->'payload'->'winnerParticipantIds')=1 THEN selected->0->'payload'->'winnerParticipantIds'->0 ELSE 'null'::JSONB END,'isTie',selected->0->'payload'->>'outcome'='UNRESOLVED_TIE'));
  owned_batch:=jsonb_set(owned_batch,'{runtimeChanges}',COALESCE(owned_batch->'runtimeChanges','{}'::JSONB)||jsonb_build_object('unplayedCount',selected->0->'payload'->'unplayedCount')); selected:=NULL; final_event:=NULL;
 END IF;
 events:=NULL; event_ids:=NULL; new_effect_ids:=NULL; b:=owned_batch;
END;
 s:=NULL;
 PERFORM public.int9_store_batch(b,h); b:=NULL; h:=NULL; PERFORM public.int9_assert_stored(game_id); RETURN TRUE;
END $$;
CREATE FUNCTION public.int9_ruling_owner(game_id TEXT,c JSONB,command_hash TEXT,moment DOUBLE PRECISION) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE header JSONB; r JSONB; pin JSONB; all_attempts JSONB; pending JSONB; keys JSONB; item_key JSONB; item JSONB; originals JSONB; correct JSONB; a JSONB; tuple JSONB; winner JSONB; teams JSONB; team JSONB; post_result JSONB; effect JSONB; event_row JSONB; batch JSONB; posts JSONB:='[]'::JSONB; effects JSONB:='[]'::JSONB; heads JSONB:='[]'::JSONB; classifications JSONB:='[]'::JSONB; consumed JSONB:='[]'::JSONB; grant_changes JSONB; scope_changes JSONB; runtime_active TEXT; identity_id TEXT; admission_id TEXT; execution_format TEXT; turn_index INTEGER; effect_sequence INTEGER; team_index INTEGER; turn_seconds INTEGER; multiplier INTEGER; after_pending INTEGER; before_clock JSONB; final_clock JSONB; whole BOOLEAN; closed BOOLEAN:=FALSE; invalidate BOOLEAN:=FALSE; BEGIN
 SELECT g."firebaseIdentityId",g."admissionId",g."executionFormat",rt."activeRoundId",rt."turnIndex",(rt."setup"->'rules'->>'turnSeconds')::INTEGER INTO identity_id,admission_id,execution_format,runtime_active,turn_index,turn_seconds FROM public."Game" g JOIN public."GameRuntime" rt ON rt."gameId"=g."id" WHERE g."id"=game_id;
 header:=public.int9_before_header(game_id); IF header IS NULL OR header->'finished'='true'::JSONB THEN PERFORM public.int9_error('MATCH_FINISHED'); END IF;
 IF EXISTS(SELECT 1 FROM public."CompetitiveRuntimeHead" h WHERE h."gameId"=game_id AND (h."openItemReviewId" IS NOT NULL OR h."boardReviewRoundId" IS NOT NULL)) THEN PERFORM public.int9_error('RULING_REVIEW_OPEN'); END IF;
 SELECT "state",jsonb_build_object('format',"pin"->'format','points',"pin"->'points','items',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',x->'id','value',x->'value','trap',x->'trap') ORDER BY ordinal),'[]'::JSONB) FROM jsonb_array_elements("pin"->'items') WITH ORDINALITY members(x,ordinal))) INTO r,pin FROM public."GameRound" WHERE "gameId"=game_id AND "id"=c->>'roundId';
 IF r IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; IF r->>'phase' IN ('READY','RESOLVED') THEN PERFORM public.int9_error('INVALID_PHASE'); END IF;
 whole:=pin->>'format' IN ('LIST_ITEMS','ACTING_ITEMS') AND c->'itemId'='null'::JSONB;
 IF r->'pause'<>'null'::JSONB OR (CASE WHEN c->'itemId'='null'::JSONB THEN r->'publicRevealed' IS DISTINCT FROM 'true'::JSONB ELSE NOT r->'itemReveals' @> jsonb_build_array(c->'itemId') END) THEN PERFORM public.int9_error('PUBLIC_REVEAL_REQUIRED'); END IF;
 IF pin->>'format' NOT IN ('LIST_ITEMS','ACTING_ITEMS') AND c->'itemId'<>'null'::JSONB OR c->'itemId'<>'null'::JSONB AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=c->'itemId') THEN PERFORM public.int9_error('ITEM_RESOLVED'); END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a."id",'itemId',a."itemId",'teamId',a."teamId",'generation',a."generation",'bonusMultiplier',a."payload"->'bonusMultiplier','bonusEventId',a."bonusEventId") ORDER BY event."sequence",a."id" COLLATE "C"),'[]'::JSONB) INTO all_attempts FROM public."CompetitiveAttempt" a JOIN public."RoundAuthorityEvent" event ON event."gameId"=a."gameId" AND event."id"=a."eventId" WHERE a."gameId"=game_id AND a."roundId"=r->>'id';
 SELECT COALESCE(jsonb_agg(a ORDER BY ordinal),'[]'::JSONB) INTO pending FROM jsonb_array_elements(all_attempts) WITH ORDINALITY attempts(a,ordinal) WHERE (whole OR a->'itemId' IS NOT DISTINCT FROM c->'itemId') AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" cl WHERE cl."gameId"=game_id AND cl."attemptId"=a->>'id');
 IF jsonb_array_length(pending)<>jsonb_array_length(c->'classifications') OR EXISTS(SELECT 1 FROM jsonb_array_elements(c->'classifications') requested WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pending) a WHERE a->'id'=requested->0)) THEN PERFORM public.int9_error('COMPLETE_RULING_REQUIRED'); END IF;
 IF whole AND EXISTS(SELECT 1 FROM jsonb_array_elements(pending) a WHERE a->'itemId'='null'::JSONB) THEN PERFORM public.int9_error('ATTEMPT_PROOF_UNAVAILABLE'); END IF;
 SELECT COALESCE(max("sequence"),0) INTO effect_sequence FROM public."CompetitiveEffect" WHERE "gameId"=game_id;
 SELECT jsonb_agg(jsonb_build_object('id',t."id",'score',t."score",'scoreVersion',COALESCE(p."scoreVersion",0),'scoreHead',p."effectId") ORDER BY ordered.ordinal) INTO teams FROM public."GameRuntime" rt CROSS JOIN LATERAL unnest(rt."teamOrder") WITH ORDINALITY ordered(id,ordinal) JOIN public."Team" t ON t."gameId"=rt."gameId" AND t."id"=ordered.id LEFT JOIN LATERAL (SELECT "scoreVersion","effectId" FROM public."CompetitiveScorePosting" WHERE "gameId"=game_id AND "teamId"=t."id" ORDER BY "scoreVersion" DESC LIMIT 1) p ON TRUE WHERE rt."gameId"=game_id;
 event_row:=jsonb_build_object('id',gen_random_uuid()::TEXT,'commandId',c->'commandId','hash',command_hash,'type','FINAL_RULING','roundId',r->'id','sequence',(header->>'version')::INTEGER+1,'at',moment,'authority',jsonb_build_object('kind','HOST','identityId',identity_id),'pauseReason',NULL); before_clock:=public.int9_snapshot(r);
 FOR a IN SELECT x FROM jsonb_array_elements(pending) x LOOP SELECT x INTO tuple FROM jsonb_array_elements(c->'classifications') x WHERE x->0=a->'id'; classifications:=classifications||jsonb_build_array(jsonb_build_object('id',gen_random_uuid()::TEXT,'attemptId',a->'id','eventId',event_row->'id','correct',tuple->1,'interim',FALSE)); tuple:=NULL; a:=NULL; END LOOP;
 IF whole THEN SELECT COALESCE(jsonb_agg(item_id ORDER BY first_ordinal),'[]'::JSONB) INTO keys FROM (SELECT a->'itemId' item_id,min(ordinal) first_ordinal FROM jsonb_array_elements(pending) WITH ORDINALITY attempts(a,ordinal) GROUP BY a->'itemId') ordered_items; IF keys='[]'::JSONB THEN keys:='[null]'::JSONB; END IF; ELSE keys:=jsonb_build_array(c->'itemId'); END IF;
 SELECT count(*) INTO after_pending FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND a."roundId"=r->>'id' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" cl WHERE cl."gameId"=game_id AND cl."attemptId"=a."id") AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'classifications') cl WHERE cl->>0=a."id");
 FOR item_key IN SELECT x FROM jsonb_array_elements(keys) x LOOP
  item:=NULL; winner:=NULL; IF item_key<>'null'::JSONB THEN SELECT x INTO item FROM jsonb_array_elements(pin->'items') x WHERE x->'id'=item_key; IF item IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'consumed') used WHERE used->'itemId'=item_key) THEN PERFORM public.int9_error('ITEM_RESOLVED'); END IF; END IF;
  SELECT COALESCE(jsonb_agg(a ORDER BY ordinal),'[]'::JSONB) INTO originals FROM jsonb_array_elements(all_attempts) WITH ORDINALITY attempts(a,ordinal) WHERE item_key='null'::JSONB OR a->'itemId'=item_key;
  SELECT COALESCE(jsonb_agg(a ORDER BY ordinal),'[]'::JSONB) INTO correct FROM jsonb_array_elements(pending) WITH ORDINALITY attempts(a,ordinal) WHERE (item_key='null'::JSONB OR a->'itemId'=item_key) AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'classifications') cl WHERE cl->0=a->'id' AND cl->1='true'::JSONB);
  IF item IS NOT NULL AND (SELECT count(DISTINCT a->'teamId') FROM jsonb_array_elements(correct) a)>1 THEN PERFORM public.int9_error('ITEM_RULING_REQUIRED'); END IF;
  effect_sequence:=effect_sequence+1; effect:=public.int9_effect_patch(event_row,effect_sequence,r->>'id',NULL,CASE WHEN correct<>'[]'::JSONB THEN 'RULING' ELSE 'NO_SCORE' END,jsonb_build_object('reversible',NOT(whole AND item_key='null'::JSONB),'amountKind',CASE WHEN item->'trap'='true'::JSONB AND execution_format NOT IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN 'DERIVED' WHEN whole AND item_key='null'::JSONB THEN 'NONE' ELSE 'FIXED' END,'beforeClock',CASE WHEN whole THEN 'null'::JSONB ELSE before_clock END,'originalAttemptIds',public.int9_team_ids(originals),'correctAttemptIds',public.int9_team_ids(correct),'bonusSnapshot',public.int9_bonus(originals)));
  IF item IS NOT NULL THEN
   winner:=correct->0; IF winner IS NOT NULL THEN SELECT x INTO team FROM jsonb_array_elements(teams) x WHERE x->'id'=winner->'teamId'; post_result:=public.int9_post_patch(team,effect,'[]'::JSONB,CASE WHEN item->'trap'='true'::JSONB THEN -(item->>'value')::BIGINT ELSE (item->>'value')::BIGINT END,execution_format NOT IN ('STANDALONE_LIST','STANDALONE_ACTING'),execution_format IN ('STANDALONE_LIST','STANDALONE_ACTING')); effect:=post_result->'effect'; posts:=posts||jsonb_build_array(post_result->'posting'); SELECT jsonb_agg(CASE WHEN x->'id'=team->'id' THEN post_result->'team' ELSE x END ORDER BY ordinal) INTO teams FROM jsonb_array_elements(teams) WITH ORDINALITY members(x,ordinal); post_result:=NULL; team:=NULL; END IF;
   consumed:=consumed||jsonb_build_array(jsonb_build_object('roundId',r->'id','itemId',item_key,'effectId',effect->'id','teamId',winner->'teamId')); r:=jsonb_set(r,'{consumed}',r->'consumed'||jsonb_build_array(jsonb_build_object('itemId',item_key,'effectId',effect->'id','teamId',winner->'teamId')));
   IF NOT whole THEN
    IF r->'assignment'->'itemId'=item_key THEN invalidate:=TRUE; r:=jsonb_set(r,'{assignment}','null'::JSONB); END IF;
    IF r->'resourceStop'='null'::JSONB AND execution_format IN ('STANDALONE_LIST','STANDALONE_ACTING') AND winner IS NOT NULL AND winner->'generation'=r->'generation' AND winner->'teamId'=r->'currentTeamId' AND r->>'phase'='TURN' AND r->'deadline'<>'null'::JSONB AND moment<(r->>'deadline')::DOUBLE PRECISION THEN
     IF item->'trap'='true'::JSONB THEN SELECT ordinal::INTEGER-1 INTO team_index FROM jsonb_array_elements(teams) WITH ORDINALITY ordered(x,ordinal) WHERE x->'id'=r->'currentTeamId'; r:=jsonb_set(r,'{currentTeamId}',teams->((team_index+1)%jsonb_array_length(teams))->'id'); END IF;
     r:=r||jsonb_build_object('deadline',moment+turn_seconds*1000,'phaseOrdinal',(r->>'phaseOrdinal')::INTEGER+1,'generation',(r->>'generation')::INTEGER+1,'doubleAttemptTeamId',NULL,'version',(r->>'version')::INTEGER+1,'assignment',NULL); invalidate:=TRUE;
    END IF;
    IF after_pending=0 AND (jsonb_array_length(r->'consumed')=jsonb_array_length(pin->'items') OR r->'deadline'='null'::JSONB) THEN closed:=TRUE; r:=jsonb_set(r,'{reason}',to_jsonb(CASE WHEN jsonb_array_length(r->'consumed')=jsonb_array_length(pin->'items') THEN 'ALL_ITEMS' ELSE 'TIME_EXPIRED' END)); END IF;
   END IF;
  ELSIF pin->>'format' NOT IN ('LIST_ITEMS','ACTING_ITEMS') THEN
   FOR team IN SELECT x FROM jsonb_array_elements(teams) x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(correct) a WHERE a->'teamId'=x->'id') LOOP SELECT max((a->>'bonusMultiplier')::INTEGER) INTO multiplier FROM jsonb_array_elements(correct) a WHERE a->'teamId'=team->'id'; post_result:=public.int9_post_patch(team,effect,posts,(pin->>'points')::BIGINT*multiplier,FALSE,FALSE); effect:=post_result->'effect'; posts:=posts||jsonb_build_array(post_result->'posting'); SELECT jsonb_agg(CASE WHEN x->'id'=team->'id' THEN post_result->'team' ELSE x END ORDER BY ordinal) INTO teams FROM jsonb_array_elements(teams) WITH ORDINALITY members(x,ordinal); post_result:=NULL; END LOOP; team:=NULL;
  END IF;
  heads:=heads||jsonb_build_array(jsonb_build_object('roundId',r->'id','itemId',item_key,'scopeId',public.int6_enta_canonical(jsonb_build_array(r->'id',item_key)),'originalEffectId',effect->'id','effectId',effect->'id','version',1,'hash','','reversed',FALSE)); effects:=effects||jsonb_build_array(effect); effect:=NULL; originals:=NULL; correct:=NULL; winner:=NULL; item:=NULL;
 END LOOP; pending:=NULL; all_attempts:=NULL; keys:=NULL; pin:=NULL;
 IF c->'itemId'='null'::JSONB THEN IF after_pending<>0 THEN PERFORM public.int9_error('PENDING_RULING_REQUIRED'); END IF; closed:=TRUE; r:=jsonb_set(r,'{reason}','"ADJUDICATED"'::JSONB); END IF;
 IF closed THEN turn_index:=turn_index+(CASE WHEN r->'turnAdvanced'='true'::JSONB THEN 0 ELSE 1 END); runtime_active:=NULL; r:=r||jsonb_build_object('phase','RESOLVED','pause',NULL,'deadline',NULL,'overallDeadline',NULL,'version',(r->>'version')::INTEGER+1,'turnAdvanced',TRUE,'assignment',NULL); invalidate:=TRUE; END IF;
 final_clock:=public.int9_snapshot(r); FOR effect IN SELECT x FROM jsonb_array_elements(effects) x LOOP effect:=public.int9_seal_patch(jsonb_set(effect,'{afterClock}',final_clock)); SELECT jsonb_agg(CASE WHEN x->'id'=effect->'id' THEN effect ELSE x END ORDER BY ordinal) INTO effects FROM jsonb_array_elements(effects) WITH ORDINALITY members(x,ordinal); SELECT jsonb_agg(CASE WHEN x->'effectId'=effect->'id' THEN jsonb_set(x,'{hash}',effect->'hash') ELSE x END ORDER BY ordinal) INTO heads FROM jsonb_array_elements(heads) WITH ORDINALITY members(x,ordinal); effect:=NULL; END LOOP;
 IF NOT whole THEN r:=jsonb_set(r,'{version}',to_jsonb((r->>'version')::INTEGER+1)); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(heads) proposed JOIN public."CompetitiveRulingHead" saved ON saved."gameId"=game_id AND saved."scopeId"=proposed->>'scopeId') THEN PERFORM public.int9_error('RULING_ALREADY_FINAL'); END IF;
 batch:=jsonb_build_object('id',game_id,'identityId',identity_id,'admissionId',admission_id,'beforeVersion',header->'version','finalRevision',event_row->'sequence','events',jsonb_build_array(event_row),'effects',effects,'classifications',classifications,'postings',posts,'rulings',heads,'itemConsumptions',consumed,'roundChanges',jsonb_build_array(jsonb_build_object('id',r->'id','fields',r-ARRAY['id','questionId','ordinal'])),'teamChanges',(SELECT jsonb_agg(jsonb_build_object('id',t->'id','score',t->'score')) FROM jsonb_array_elements(teams) t),'runtimeChanges',jsonb_build_object('activeRoundId',runtime_active,'turnIndex',turn_index),'headChanges',jsonb_build_object('latestEffectId',effects->-1->'id'));
 IF invalidate THEN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',scope."id",'roundId',scope."roundId",'role',scope."role",'assignmentId',scope."assignmentId",'generation',scope."generation",'activeGrantId',NULL)),'[]'::JSONB),COALESCE(jsonb_agg(jsonb_build_object('id',gr."id",'scopeId',gr."scopeId",'roundId',gr."roundId",'role',gr."role",'assignmentId',gr."assignmentId",'generation',gr."generation",'tokenHash',gr."tokenHash",'expiresAt',floor(extract(epoch FROM gr."expiresAt")*1000),'revoked',TRUE)) FILTER(WHERE gr."id" IS NOT NULL),'[]'::JSONB) INTO scope_changes,grant_changes FROM public."RoundGrantScope" scope LEFT JOIN public."RoundGrant" gr ON gr."gameId"=scope."gameId" AND gr."id"=scope."activeGrantId" WHERE scope."gameId"=game_id AND scope."roundId"=c->>'roundId' AND scope."activeGrantId" IS NOT NULL; batch:=batch||jsonb_build_object('grantScopes',scope_changes,'grants',grant_changes);
 END IF;
 r:=NULL; teams:=NULL; effects:=NULL; heads:=NULL; classifications:=NULL; posts:=NULL; consumed:=NULL; event_row:=NULL; before_clock:=NULL; final_clock:=NULL; grant_changes:=NULL; scope_changes:=NULL;
 PERFORM public.int9_store_batch(batch,header); batch:=NULL; header:=NULL; PERFORM public.int9_assert_stored(game_id);
END $$;
CREATE FUNCTION public.int9_seal_patch(effect JSONB) RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$ SELECT jsonb_set(effect,'{hash}',to_jsonb(public.int9_effect_hash(effect))) $$;
CREATE FUNCTION public.int9_post_patch(team JSONB,effect JSONB,prior_postings JSONB,delta BIGINT,clamped BOOLEAN,standalone BOOLEAN) RETURNS JSONB LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$ DECLARE after_score BIGINT; read JSONB; posting JSONB; BEGIN
 IF team IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(prior_postings) p WHERE p->'effectId'=effect->'id' AND p->'teamId'=team->'id') THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 after_score:=(team->>'score')::BIGINT+delta; IF clamped THEN after_score:=greatest(0,after_score); END IF;
 IF after_score NOT BETWEEN -2147483648 AND 2147483647 OR NOT standalone AND after_score<0 THEN PERFORM public.int9_error('SCORE_BOUND_EXCEEDED'); END IF;
 read:=public.int9_read(team,CASE WHEN clamped THEN 'CLAMP' ELSE 'BASE' END);
 effect:=effect||jsonb_build_object('reads',effect->'reads'||jsonb_build_array(read),'dependencies',CASE WHEN read->>'sourceEffectId' IS NOT NULL AND NOT effect->'dependencies' ? (read->>'sourceEffectId') THEN effect->'dependencies'||jsonb_build_array(read->'sourceEffectId') ELSE effect->'dependencies' END);
 posting:=jsonb_build_object('id',gen_random_uuid()::TEXT,'effectId',effect->'id','teamId',team->'id','delta',after_score-(team->>'score')::BIGINT,'before',team->'score','after',after_score,'scoreVersion',(team->>'scoreVersion')::INTEGER+1,'previousHead',team->'scoreHead');
 effect:=effect||jsonb_build_object('postingIds',effect->'postingIds'||jsonb_build_array(posting->'id'));
 team:=team||jsonb_build_object('score',after_score,'scoreVersion',(team->>'scoreVersion')::INTEGER+1,'scoreHead',effect->'id');
 RETURN jsonb_build_object('team',team,'effect',effect,'posting',posting);
END $$;
CREATE FUNCTION public.int9_before_header(game_id TEXT) RETURNS JSONB LANGUAGE SQL STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('id',game_id,'version',rt."version",'finished',rt."state"='FINISHED','correctionReview',head."boardReviewRoundId",'rounds',(SELECT jsonb_agg(jsonb_build_object('id',r."id",'phase',r."state"->'phase','pause',CASE WHEN r."state"->'pause'='null'::JSONB THEN 'null'::JSONB ELSE jsonb_build_object('eventId',r."state"->'pause'->'eventId') END) ORDER BY r."ordinal") FROM public."GameRound" r WHERE r."gameId"=game_id)) FROM public."GameRuntime" rt JOIN public."CompetitiveRuntimeHead" head ON head."gameId"=rt."gameId" WHERE rt."gameId"=game_id
$$;
CREATE FUNCTION public.int9_lock_only(ns TEXT,project TEXT,game_id TEXT,requested_round TEXT,requested_effect TEXT,requested_scope TEXT) RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE rid TEXT; BEGIN
 PERFORM public.int8_namespace(ns,project);
 PERFORM 1 FROM public."Game" g JOIN public."FirebaseIdentity" i ON i."id"=g."firebaseIdentityId" JOIN public."GameCompetitivePin" profile ON profile."gameId"=g."id" AND profile."firebaseIdentityId"=i."id" WHERE g."id"=game_id AND g."gameFormat"='FIREBASE_PINNED' AND profile."requestVersion"=5 AND i."firebaseProjectId"=project FOR UPDATE OF g; IF NOT FOUND THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 PERFORM 1 FROM public."GameRuntime" WHERE "gameId"=game_id FOR UPDATE;
 PERFORM 1 FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id FOR UPDATE;
 rid:=COALESCE((SELECT "activeRoundId" FROM public."GameRuntime" WHERE "gameId"=game_id),(SELECT "roundId" FROM public."CompetitiveItemReview" review JOIN public."CompetitiveRuntimeHead" head ON head."gameId"=review."gameId" AND head."openItemReviewId"=review."id" WHERE review."gameId"=game_id),(SELECT "boardReviewRoundId" FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id),(SELECT a."roundId" FROM public."CompetitiveAttempt" a JOIN public."GameRound" r ON r."gameId"=a."gameId" AND r."id"=a."roundId" WHERE a."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" cl WHERE cl."gameId"=game_id AND cl."attemptId"=a."id") ORDER BY r."ordinal" LIMIT 1),requested_round,(SELECT "roundId" FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=requested_effect));
 PERFORM 1 FROM public."GameRound" WHERE "gameId"=game_id AND "id"=rid FOR UPDATE;
 PERFORM 1 FROM public."GameQuestion" q JOIN public."GameRound" r ON r."gameQuestionId"=q."id" AND r."gameId"=q."gameId" WHERE q."gameId"=game_id AND r."id"=rid FOR UPDATE OF q;
 PERFORM 1 FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id AND "roundId"=rid ORDER BY "scopeId" COLLATE "C" FOR UPDATE;
 PERFORM 1 FROM public."CompetitiveCapacityHead" WHERE "gameId"=game_id AND "roundId"=rid FOR UPDATE;
 PERFORM 1 FROM public."RoundGrantScope" WHERE "gameId"=game_id AND ("roundId"=rid AND "activeGrantId" IS NOT NULL OR "id"=requested_scope) ORDER BY "id" COLLATE "C" FOR UPDATE;
 PERFORM 1 FROM public."RoundGrant" gr JOIN public."RoundGrantScope" scope ON scope."gameId"=gr."gameId" AND scope."activeGrantId"=gr."id" WHERE gr."gameId"=game_id AND scope."roundId"=rid ORDER BY gr."id" COLLATE "C" FOR UPDATE OF gr;
 PERFORM 1 FROM public."DrawingCanvasState" WHERE "roundId"=rid FOR UPDATE;
 PERFORM 1 FROM public."GameRuntime" rt CROSS JOIN LATERAL unnest(rt."teamOrder") WITH ORDINALITY ordered(id,ord) JOIN public."Team" t ON t."id"=ordered.id AND t."gameId"=rt."gameId" WHERE rt."gameId"=game_id ORDER BY ordered.ord FOR UPDATE OF t;
 PERFORM public.int9_assert_stored(game_id); RETURN rid;
END $$;
CREATE FUNCTION public.int9_page_attempt(a public."CompetitiveAttempt") RETURNS JSONB LANGUAGE SQL STABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('id',(a)."id",'roundId',(a)."roundId",'itemId',(a)."itemId",'phase',(a)."phase",'phaseOrdinal',(a)."phaseOrdinal",'teamId',(a)."teamId",'playerId',(a)."playerId",'acceptedAt',floor(extract(epoch FROM (a)."acceptedAt")*1000),'classification',(SELECT "correct" FROM public."CompetitiveClassification" WHERE "gameId"=(a)."gameId" AND "attemptId"=(a)."id")) $$;
CREATE FUNCTION public.int9_page_rows(ns TEXT,project TEXT,uid TEXT,token_hash TEXT,game_id TEXT,q JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE s JSONB; r JSONB; grant_row JSONB; effect JSONB; page_rows JSONB; total INTEGER; size INTEGER; page_offset INTEGER; collection TEXT:=q->>'collection'; moment DOUBLE PRECISION; BEGIN
 IF collection='canvas' THEN RETURN public.int9_canvas_page(ns,project,uid,token_hash,game_id,q); END IF;
 IF (uid IS NULL)=(token_hash IS NULL) OR NOT public.int6_enta_exact_keys(q,ARRAY['collection','roundId','effectId','snapshot','offset']) OR collection NOT IN ('pending','feedback','rulings','correction','media','grading') OR public.int9_id_or_null(q->'roundId') IS NOT TRUE OR public.int9_id_or_null(q->'effectId') IS NOT TRUE OR public.int5b_json_integer(q->'snapshot',1,64946) IS NOT TRUE OR public.int5b_json_integer(q->'offset',0,64945) IS NOT TRUE THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
 IF uid IS NOT NULL THEN s:=public.int9_owner_load(ns,project,uid,game_id,TRUE); ELSE s:=public.int9_grant_load(ns,project,game_id,token_hash); END IF; IF s IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 moment:=public.int9_now(); IF token_hash IS NOT NULL THEN grant_row:=public.int9_grant_physical(game_id,token_hash,moment); END IF;
 IF public.int9_mutation_owner(game_id,NULL,NULL,grant_row->>'scopeId',NULL,'{"grants":[]}'::JSONB,NULL,NULL,moment) THEN RETURN jsonb_build_object('restart',TRUE,'total',0,'rows','[]'::JSONB); END IF;

 SELECT "state" INTO r FROM public."GameRound" WHERE "gameId"=game_id AND "id"=q->>'roundId'; IF q->>'roundId' IS NOT NULL AND r IS NULL THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF;
 IF q->>'effectId' IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=q->>'effectId') THEN PERFORM public.int9_error('MATCH_NOT_FOUND'); END IF; effect:=public.int9_effect_proof(game_id,q->>'effectId')->'effect'; END IF;
 IF grant_row IS NOT NULL AND (q->'roundId' IS DISTINCT FROM grant_row->'roundId' OR collection NOT IN ('grading','media') OR collection='grading' AND grant_row->>'role'<>'JUDGE') THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
 size:=(CASE collection WHEN 'pending' THEN 64 WHEN 'feedback' THEN 16 WHEN 'rulings' THEN 32 WHEN 'correction' THEN 64 WHEN 'media' THEN 64 ELSE 16 END); page_offset:=(q->>'offset')::INTEGER;
 IF page_offset%size<>0 THEN PERFORM public.int9_error('PAGE_SNAPSHOT_RESTART'); END IF;
 IF collection IN ('pending','feedback','grading','media') AND (r IS NULL OR effect IS NOT NULL) OR collection='correction' AND (r IS NOT NULL OR effect IS NULL) OR collection='rulings' AND (r IS NOT NULL OR effect IS NOT NULL) THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;

 IF (s->>'snapshot')::INTEGER IS DISTINCT FROM (q->>'snapshot')::INTEGER THEN RETURN jsonb_build_object('restart',TRUE,'total',0,'rows','[]'::JSONB); END IF;
 CASE collection
 WHEN 'pending' THEN
  IF r IS NULL OR effect IS NOT NULL OR grant_row IS NOT NULL THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
  SELECT count(*) INTO total FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND a."roundId"=r->>'id' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."attemptId"=a."id");
  SELECT COALESCE(jsonb_agg(page_row ORDER BY sequence,id COLLATE "C"),'[]'::JSONB) INTO page_rows FROM (SELECT public.int9_page_attempt(a) page_row,e."sequence" sequence,a."id" id FROM public."CompetitiveAttempt" a JOIN public."RoundAuthorityEvent" e ON e."gameId"=a."gameId" AND e."id"=a."eventId" WHERE a."gameId"=game_id AND a."roundId"=r->>'id' AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."attemptId"=a."id") ORDER BY e."sequence",a."id" COLLATE "C" OFFSET page_offset LIMIT size) page;
 WHEN 'correction' THEN
  IF effect IS NULL OR r IS NOT NULL OR grant_row IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public."CompetitiveRulingHead" h WHERE h."gameId"=game_id AND (h."effectId"=effect->>'id' OR h."originalEffectId"=effect->>'id')) THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
  total:=jsonb_array_length(effect->'originalAttemptIds'); IF total>512 OR EXISTS(SELECT 1 FROM jsonb_array_elements(effect->'originalAttemptIds') id WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND a."roundId"=effect->>'roundId' AND a."id"=id#>>'{}')) THEN PERFORM public.int9_error('ATTEMPT_PROOF_UNAVAILABLE'); END IF;
  SELECT COALESCE(jsonb_agg(page_row ORDER BY ordinal),'[]'::JSONB) INTO page_rows FROM (SELECT public.int9_page_attempt(a)||jsonb_build_object('classification',effect->'correctAttemptIds' @> jsonb_build_array(to_jsonb(a."id")),'effectId',effect->'id','effectHash',effect->'hash','rulingVersion',(SELECT h."version" FROM public."CompetitiveRulingHead" h WHERE h."gameId"=game_id AND (h."effectId"=effect->>'id' OR h."originalEffectId"=effect->>'id')),'reversed',(SELECT h."reversed" FROM public."CompetitiveRulingHead" h WHERE h."gameId"=game_id AND (h."effectId"=effect->>'id' OR h."originalEffectId"=effect->>'id')),'effectKind',effect->'kind') page_row,original.ordinal FROM jsonb_array_elements(effect->'originalAttemptIds') WITH ORDINALITY original(id,ordinal) JOIN public."CompetitiveAttempt" a ON a."gameId"=game_id AND a."id"=original.id#>>'{}' ORDER BY original.ordinal OFFSET page_offset LIMIT size) page;
 WHEN 'rulings' THEN
  IF r IS NOT NULL OR effect IS NOT NULL OR grant_row IS NOT NULL THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
  SELECT count(*) INTO total FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id;
  SELECT COALESCE(jsonb_agg(page_row ORDER BY ordinal,item_id COLLATE "C" NULLS FIRST),'[]'::JSONB) INTO page_rows FROM (SELECT jsonb_build_object('roundId',h."roundId",'itemId',h."itemId",'originalEffectId',h."originalEffectId",'effectId',h."effectId",'version',h."version",'hash',h."hash",'reversed',h."reversed",'correctAttemptCount',jsonb_array_length(e."payload"->'correctAttemptIds')) page_row,rnd."ordinal" ordinal,h."itemId" item_id FROM public."CompetitiveRulingHead" h JOIN public."GameRound" rnd ON rnd."gameId"=h."gameId" AND rnd."id"=h."roundId" JOIN public."CompetitiveEffect" e ON e."gameId"=h."gameId" AND e."id"=h."effectId" AND e."hash"=h."hash" WHERE h."gameId"=game_id ORDER BY rnd."ordinal",h."itemId" COLLATE "C" NULLS FIRST OFFSET page_offset LIMIT size) page;
 WHEN 'feedback','grading' THEN
  IF r IS NULL OR effect IS NOT NULL THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
  IF collection='feedback' AND grant_row IS NOT NULL THEN PERFORM public.int9_error('GRANT_DENIED'); END IF;
  IF collection='grading' AND ((SELECT "state"='FINISHED' FROM public."GameRuntime" WHERE "gameId"=game_id) OR EXISTS(SELECT 1 FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id AND ("openItemReviewId" IS NOT NULL OR "boardReviewRoundId" IS NOT NULL)) OR (SELECT to_jsonb("activeRoundId") FROM public."GameRuntime" WHERE "gameId"=game_id) IS DISTINCT FROM r->'id' OR r->'pause'<>'null'::JSONB OR r->'resourceStop'<>'null'::JSONB OR NOT public.int9_items(r) OR r->>'phase' IN ('READY','RESOLVED')) THEN PERFORM public.int9_error('GRADING_DENIED'); END IF;
  r:=r||jsonb_build_object('pin',public.int9_descriptor((SELECT "promptId" FROM public."CompetitiveRoundPin" WHERE "gameId"=game_id AND "roundId"=r->>'id')));
  SELECT count(*) INTO total FROM jsonb_array_elements(r->'pin'->'items') item WHERE collection='grading' OR r->'publicRevealed'='true'::JSONB OR r->'itemReveals' @> jsonb_build_array(item->'id') OR EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" consumed WHERE consumed."gameId"=game_id AND consumed."roundId"=r->>'id' AND consumed."itemId"=item->>'id') OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'graphemeHints') hint WHERE hint->'itemId'=item->'id' AND EXISTS(SELECT 1 FROM public."CompetitiveConsumption" c WHERE c."gameId"=game_id AND c."roundId"=r->>'id' AND c."aid"='HINT' AND c."eventId"=hint->>'eventId'));
  SELECT COALESCE(jsonb_agg(page_row ORDER BY ordinal),'[]'::JSONB) INTO page_rows FROM (
   SELECT jsonb_build_object('id',item->'id','ordinal',item->'ordinal','consumed',consumed,'revealed',disclosed)||CASE WHEN disclosed THEN jsonb_build_object('text',item->'text','value',item->'value','trap',item->'trap','mediaIds',item->'mediaIds') ELSE '{}'::JSONB END||CASE WHEN NOT disclosed AND grapheme IS NOT NULL THEN jsonb_build_object('grapheme',grapheme) ELSE '{}'::JSONB END page_row,(item->>'ordinal')::INTEGER ordinal
   FROM jsonb_array_elements(r->'pin'->'items') item
   CROSS JOIN LATERAL (SELECT EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used WHERE used."gameId"=game_id AND used."roundId"=r->>'id' AND used."itemId"=item->>'id') consumed) consumption
   CROSS JOIN LATERAL (SELECT collection='grading' OR r->'publicRevealed'='true'::JSONB OR r->'itemReveals' @> jsonb_build_array(item->'id') OR consumed disclosed) visibility
   LEFT JOIN LATERAL (SELECT proof->'grapheme' grapheme FROM jsonb_array_elements(r->'graphemeHints') hint JOIN jsonb_array_elements(r->'pin'->'graphemes') proof ON proof->'id'=hint->'proofId' WHERE hint->'itemId'=item->'id' AND EXISTS(SELECT 1 FROM public."CompetitiveConsumption" c WHERE c."gameId"=game_id AND c."roundId"=r->>'id' AND c."aid"='HINT' AND c."eventId"=hint->>'eventId')) hint_proof ON TRUE
   WHERE disclosed OR grapheme IS NOT NULL ORDER BY (item->>'ordinal')::INTEGER OFFSET page_offset LIMIT size
  ) page;
 WHEN 'media' THEN
  IF r IS NULL OR effect IS NOT NULL THEN PERFORM public.int9_error('INVALID_PAGE_REQUEST'); END IF;
  IF (SELECT "state"='FINISHED' FROM public."GameRuntime" WHERE "gameId"=game_id) OR EXISTS(SELECT 1 FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id AND ("openItemReviewId" IS NOT NULL OR "boardReviewRoundId" IS NOT NULL)) OR r->'pause'<>'null'::JSONB OR r->'resourceStop'<>'null'::JSONB OR r->>'phase'='READY' THEN total:=0; page_rows:='[]'::JSONB;
  ELSE
   r:=r||jsonb_build_object('pin',public.int9_descriptor((SELECT "promptId" FROM public."CompetitiveRoundPin" WHERE "gameId"=game_id AND "roundId"=r->>'id')));
   SELECT COALESCE(jsonb_agg(jsonb_build_object('id',media->'id','mime',media->'mime','bytes',media->'bytes','width',media->'width','height',media->'height','durationMs',media->'durationMs') ORDER BY ordinal),'[]'::JSONB) INTO page_rows FROM jsonb_array_elements(r->'pin'->'media') WITH ORDINALITY members(media,ordinal) WHERE CASE WHEN grant_row->>'role'='ACTOR' THEN media->>'role'='ACTOR' AND r->'pin'->>'format'='DRAWING_TARGET' OR media->>'role'='ITEM' AND media->'itemId'=r->'assignment'->'itemId' AND grant_row->'assignmentId'=r->'assignment'->'id' ELSE media->>'role' IN ('PROMPT','MASKED') OR media->>'role' IN ('CLEAR','ACTOR') AND r->'publicRevealed'='true'::JSONB OR media->>'role'='ITEM' AND (grant_row->>'role'='JUDGE' OR r->'publicRevealed'='true'::JSONB OR r->'itemReveals' @> jsonb_build_array(media->'itemId') OR EXISTS(SELECT 1 FROM public."CompetitiveItemConsumption" used WHERE used."gameId"=game_id AND used."roundId"=r->>'id' AND used."itemId"=media->>'itemId')) END;
   total:=jsonb_array_length(page_rows); SELECT COALESCE(jsonb_agg(value ORDER BY ordinal),'[]'::JSONB) INTO page_rows FROM jsonb_array_elements(page_rows) WITH ORDINALITY page(value,ordinal) WHERE ordinal>page_offset AND ordinal<=page_offset+size;
  END IF;
 END CASE;
 IF page_offset>total OR jsonb_array_length(page_rows)<>least(size,total-page_offset) OR octet_length(convert_to(public.int6_enta_canonical(page_rows),'UTF8'))>65536 THEN PERFORM public.int9_error('PAGE_PROOF_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('total',total,'rows',page_rows);
END $$;
CREATE FUNCTION public.int9_state_batch(s JSONB,h JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE b JSONB; events JSONB; event_ids JSONB; selected JSONB; changes JSONB; r JSONB; x JSONB; key TEXT; physical JSONB; new_effect_ids JSONB; final_event JSONB; BEGIN
 SELECT COALESCE(jsonb_agg(e ORDER BY (e->>'sequence')::INTEGER),'[]'::JSONB) INTO events FROM jsonb_array_elements(s->'events') e WHERE (e->>'sequence')::INTEGER>(h->>'version')::INTEGER;
 SELECT COALESCE(jsonb_agg(e->'id'),'[]'::JSONB) INTO event_ids FROM jsonb_array_elements(events) e;
 b:=jsonb_build_object('id',s->'id','identityId',s->'identityId','admissionId',s->'admissionId','beforeVersion',h->'version','finalRevision',s->'version','events',events);
 FOREACH key IN ARRAY ARRAY['attempts','classifications','effects','consumptions','disclosures','itemReviews','itemResolutions'] LOOP
  SELECT COALESCE(jsonb_agg(x ORDER BY ordinal),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->key) WITH ORDINALITY rows(x,ordinal) WHERE event_ids @> jsonb_build_array(x->'eventId');
  IF selected<>'[]'::JSONB THEN b:=b||jsonb_build_object(key,selected); END IF; selected:=NULL;
 END LOOP;
 SELECT COALESCE(jsonb_agg(e->'id'),'[]'::JSONB) INTO new_effect_ids FROM jsonb_array_elements(b->'effects') e;
 SELECT COALESCE(jsonb_agg(x ORDER BY ordinal),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->'postings') WITH ORDINALITY rows(x,ordinal) WHERE new_effect_ids @> jsonb_build_array(x->'effectId'); IF selected<>'[]'::JSONB THEN b:=b||jsonb_build_object('postings',selected); END IF; selected:=NULL;
 SELECT COALESCE(jsonb_agg(x ORDER BY ordinal),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->'rulings') WITH ORDINALITY rows(x,ordinal) WHERE new_effect_ids @> jsonb_build_array(x->'effectId'); IF selected<>'[]'::JSONB THEN b:=b||jsonb_build_object('rulings',selected); END IF; selected:=NULL;
 FOR r IN SELECT x FROM jsonb_array_elements(s->'rounds') x WHERE x->'contextSummary' IS DISTINCT FROM 'true'::JSONB LOOP
  SELECT "state" INTO physical FROM public."GameRound" WHERE "gameId"=s->>'id' AND "id"=r->>'id'; changes:='{}'::JSONB;
  FOREACH key IN ARRAY ARRAY['phase','phaseOrdinal','generation','version','originalTeamId','currentTeamId','originalDeadline','deadline','overallDeadline','pause','publicRevealed','itemReveals','assignment','pickedPlayerId','pickedEventId','usedAidIds','doubleAttemptTeamId','bonus','revealedHintIds','graphemeHints','consumed','reason','turnAdvanced','resourceStop'] LOOP
   IF NOT r ? key THEN PERFORM public.int9_error('MATCH_DATA_UNAVAILABLE'); END IF;
   IF r->key IS DISTINCT FROM physical->key THEN changes:=changes||jsonb_build_object(key,r->key); END IF;
  END LOOP;
  IF changes<>'{}'::JSONB THEN b:=jsonb_set(b,'{roundChanges}',COALESCE(b->'roundChanges','[]'::JSONB)||jsonb_build_array(jsonb_build_object('id',r->'id','fields',changes))); END IF; changes:=NULL;
  IF r->'assignment'<>'null'::JSONB AND event_ids @> jsonb_build_array(r->'assignment'->'id') THEN
   x:=r->'assignment'; b:=jsonb_set(b,'{assignmentFacts}',COALESCE(b->'assignmentFacts','[]'::JSONB)||jsonb_build_array(jsonb_build_object('id',x->'id','roundId',r->'id','teamId',x->'teamId','playerId',x->'playerId','playerIndex',(SELECT roster."ordinal" FROM public."CompetitiveRosterPlayer" roster WHERE roster."gameId"=s->>'id' AND roster."teamId"=x->>'teamId' AND roster."playerId"=x->>'playerId'),'itemId',x->'itemId','generation',x->'generation','targetHash',public.int6_enta_hash(jsonb_build_object('revisionId',r->'pin'->'revisionId','revisionHash',r->'pin'->'hash','target',r->'pin'->'target'))))); x:=NULL;
  END IF;
  FOR x IN SELECT used FROM jsonb_array_elements(r->'consumed') used WHERE new_effect_ids @> jsonb_build_array(used->'effectId') LOOP b:=jsonb_set(b,'{itemConsumptions}',COALESCE(b->'itemConsumptions','[]'::JSONB)||jsonb_build_array(x||jsonb_build_object('roundId',r->'id'))); x:=NULL; END LOOP;
  physical:=NULL; r:=NULL;
 END LOOP;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',t->'id','score',t->'score')),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->'teams') t JOIN public."Team" saved ON saved."gameId"=s->>'id' AND saved."id"=t->>'id' WHERE saved."score" IS DISTINCT FROM (t->>'score')::INTEGER; IF selected<>'[]'::JSONB THEN b:=b||jsonb_build_object('teamChanges',selected); END IF; selected:=NULL;
 SELECT COALESCE(jsonb_agg(x),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->'grantScopes') x LEFT JOIN public."RoundGrantScope" saved ON saved."gameId"=s->>'id' AND saved."id"=x->>'id' WHERE saved."id" IS NULL OR saved."generation" IS DISTINCT FROM (x->>'generation')::INTEGER OR saved."activeGrantId" IS DISTINCT FROM x->>'activeGrantId'; IF selected<>'[]'::JSONB THEN b:=b||jsonb_build_object('grantScopes',selected); END IF; selected:=NULL;
 SELECT COALESCE(jsonb_agg(x),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->'grants') x LEFT JOIN public."RoundGrant" saved ON saved."gameId"=s->>'id' AND saved."id"=x->>'id' WHERE saved."id" IS NULL OR saved."revoked" IS DISTINCT FROM (x->>'revoked')::BOOLEAN; IF selected<>'[]'::JSONB THEN b:=b||jsonb_build_object('grants',selected); END IF; selected:=NULL;
 SELECT COALESCE(jsonb_agg(x),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->'canvases') x JOIN public."DrawingCanvasState" saved ON saved."roundId"=x->>'roundId' WHERE saved."state" IS DISTINCT FROM x; IF selected<>'[]'::JSONB THEN b:=b||jsonb_build_object('canvasChanges',selected); END IF; selected:=NULL;
 changes:='{}'::JSONB; FOR key,physical IN SELECT key,value FROM jsonb_each(jsonb_build_object('activeRoundId',s->'activeRoundId','turnIndex',s->'turnIndex','state',CASE WHEN s->'finished'='true'::JSONB THEN 'FINISHED' ELSE 'BOARD' END,'resultReason',CASE WHEN s->'finished'='true'::JSONB THEN CASE WHEN s->>'resultReason'='HOST_ENDED' THEN 'HOST_ENDED' ELSE 'ALL_QUESTIONS_PLAYED' END ELSE NULL END)) LOOP
  IF physical IS DISTINCT FROM (SELECT CASE key WHEN 'activeRoundId' THEN to_jsonb(rt."activeRoundId") WHEN 'turnIndex' THEN to_jsonb(rt."turnIndex") WHEN 'state' THEN to_jsonb(rt."state") ELSE to_jsonb(rt."resultReason") END FROM public."GameRuntime" rt WHERE rt."gameId"=s->>'id') THEN changes:=changes||jsonb_build_object(key,physical); END IF;
 END LOOP; IF changes<>'{}'::JSONB THEN b:=b||jsonb_build_object('runtimeChanges',changes); END IF; changes:=NULL; physical:=NULL;
 changes:='{}'::JSONB; FOR key,physical IN SELECT key,value FROM jsonb_each(jsonb_build_object('latestEffectId',s->'latestEffectId','boardReviewRoundId',s->'correctionReview','openItemReviewId',s->'openItemReview')) LOOP
  IF physical IS DISTINCT FROM (SELECT to_jsonb(head)->key FROM public."CompetitiveRuntimeHead" head WHERE head."gameId"=s->>'id') THEN changes:=changes||jsonb_build_object(key,physical); END IF;
 END LOOP;
 IF changes ? 'openItemReviewId' THEN changes:=changes||jsonb_build_object('openItemReviewHash',CASE WHEN changes->'openItemReviewId'='null'::JSONB THEN NULL ELSE COALESCE((SELECT x->>'hash' FROM jsonb_array_elements(b->'itemReviews') x WHERE x->'id'=changes->'openItemReviewId'),(SELECT "hash" FROM public."CompetitiveItemReview" WHERE "gameId"=s->>'id' AND "id"=changes->>'openItemReviewId')) END); END IF;
 IF changes<>'{}'::JSONB THEN b:=b||jsonb_build_object('headChanges',changes); END IF; changes:=NULL; physical:=NULL;
 IF s->'finished'='true'::JSONB AND h->'finished'='false'::JSONB THEN
  SELECT e INTO final_event FROM jsonb_array_elements(events) e WHERE e->>'type'='FINISH';
  SELECT COALESCE(jsonb_agg(x),'[]'::JSONB) INTO selected FROM jsonb_array_elements(s->'results') x WHERE x->'payload'->'authority'->'eventId'=final_event->'id';
  IF jsonb_array_length(selected)<>1 THEN PERFORM public.int9_error('RESULT_INTEGRITY_FAILURE'); END IF;
  b:=b||jsonb_build_object('results',selected,'resultHead',jsonb_build_object('resultVersion',selected->0->'payload'->'resultVersion','resultHash',selected->0->'hash'),'gameChanges',jsonb_build_object('status','FINISHED','finishedAt',final_event->'at','winnerTeamId',CASE WHEN jsonb_array_length(selected->0->'payload'->'winnerParticipantIds')=1 THEN selected->0->'payload'->'winnerParticipantIds'->0 ELSE 'null'::JSONB END,'isTie',selected->0->'payload'->>'outcome'='UNRESOLVED_TIE'));
  b:=jsonb_set(b,'{runtimeChanges}',COALESCE(b->'runtimeChanges','{}'::JSONB)||jsonb_build_object('unplayedCount',selected->0->'payload'->'unplayedCount')); selected:=NULL; final_event:=NULL;
 END IF;
 events:=NULL; event_ids:=NULL; new_effect_ids:=NULL; RETURN b;
END $$;
CREATE FUNCTION public.int9_effect_proof(game_id TEXT,effect_id TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE e public."CompetitiveEffect"%ROWTYPE; p JSONB; BEGIN
 SELECT "amountKind","barrier","eventId","hash","id","kind","payload","predecessorHash","predecessorId","reversible","roundId","sequence" INTO e."amountKind",e."barrier",e."eventId",e."hash",e."id",e."kind",e."payload",e."predecessorHash",e."predecessorId",e."reversible",e."roundId",e."sequence" FROM public."CompetitiveEffect" WHERE "gameId"=game_id AND "id"=effect_id;
 IF e."id" IS NULL OR public.int6_enta_exact_keys(e."payload",ARRAY['id','eventId','sequence','roundId','kind','aid','amountKind','reversible','barrier','reads','dependencies','postingIds','beforeClock','afterClock','originalAttemptIds','correctAttemptIds','bonusSnapshot','predecessorId','predecessorHash','reason','hash']) IS NOT TRUE THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['reads','dependencies','postingIds','originalAttemptIds','correctAttemptIds','bonusSnapshot']) key WHERE jsonb_typeof(e."payload"->key) IS DISTINCT FROM 'array') THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF jsonb_array_length(e."payload"->'reads')>8 OR jsonb_array_length(e."payload"->'dependencies')>8 OR jsonb_array_length(e."payload"->'postingIds')>4 OR jsonb_array_length(e."payload"->'originalAttemptIds')>512 OR jsonb_array_length(e."payload"->'correctAttemptIds')>512 OR jsonb_array_length(e."payload"->'bonusSnapshot')>512 THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF e."id" IS NULL OR e."hash" IS DISTINCT FROM public.int9_effect_hash(e."payload") OR e."payload"->>'id' IS DISTINCT FROM e."id" OR e."payload"->>'hash' IS DISTINCT FROM e."hash" OR e."payload"->'sequence' IS DISTINCT FROM to_jsonb(e."sequence") OR e."payload"->>'eventId' IS DISTINCT FROM e."eventId" OR e."payload"->>'roundId' IS DISTINCT FROM e."roundId" OR e."payload"->>'predecessorId' IS DISTINCT FROM e."predecessorId" OR e."payload"->>'predecessorHash' IS DISTINCT FROM e."predecessorHash" THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF e."payload"->>'kind' IS DISTINCT FROM e."kind" OR e."payload"->>'amountKind' IS DISTINCT FROM e."amountKind" OR e."payload"->'reversible' IS DISTINCT FROM to_jsonb(e."reversible") OR e."payload"->'barrier' IS DISTINCT FROM to_jsonb(e."barrier") OR e."sequence" NOT BETWEEN 1 AND 64945 OR e."kind" NOT IN ('AID','RULING','NO_SCORE','INTERIM','TIMING','DISCLOSURE','REVERSAL','CORRECTION','FINISH') OR e."amountKind" NOT IN ('FIXED','DERIVED','NONE') THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;

 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',x."id",'effectId',x."effectId",'teamId',x."teamId",'delta',x."delta",'before',x."before",'after',x."after",'scoreVersion',x."scoreVersion",'previousHead',x."previousHeadId") ORDER BY x."scoreVersion",x."id" COLLATE "C"),'[]'::JSONB) INTO p FROM public."CompetitiveScorePosting" x WHERE x."gameId"=game_id AND x."effectId"=effect_id;
 IF jsonb_array_length(p)>4 OR jsonb_array_length(p)<>jsonb_array_length(e."payload"->'postingIds') OR (SELECT count(DISTINCT x->>'teamId') FROM jsonb_array_elements(p) x)<>jsonb_array_length(p) OR EXISTS(SELECT 1 FROM jsonb_array_elements(p) x WHERE NOT e."payload"->'postingIds' @> jsonb_build_array(x->'id') OR (x->>'after')::BIGINT-(x->>'before')::BIGINT<>(x->>'delta')::BIGINT OR NOT EXISTS(SELECT 1 FROM public."Team" t WHERE t."gameId"=game_id AND t."id"=x->>'teamId')) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF e."payload"->'reads' IS DISTINCT FROM (SELECT COALESCE(jsonb_agg(jsonb_build_object('teamId',r."teamId",'scoreVersion',r."scoreVersion",'value',r."value",'sourceEffectId',r."sourceEffectId",'kind',r."kind") ORDER BY r."ordinal"),'[]'::JSONB) FROM public."CompetitiveScoreRead" r WHERE r."gameId"=game_id AND r."effectId"=effect_id) OR (SELECT count(*) FROM public."CompetitiveDependency" d WHERE d."gameId"=game_id AND d."effectId"=effect_id)<>jsonb_array_length(e."payload"->'dependencies') OR EXISTS(SELECT 1 FROM jsonb_array_elements(e."payload"->'dependencies') source WHERE NOT EXISTS(SELECT 1 FROM public."CompetitiveDependency" d WHERE d."gameId"=game_id AND d."effectId"=effect_id AND d."sourceEffectId"=source#>>'{}')) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM public."CompetitiveScoreRead" r WHERE r."gameId"=game_id AND r."effectId"=effect_id AND (NOT EXISTS(SELECT 1 FROM public."Team" t WHERE t."gameId"=game_id AND t."id"=r."teamId") OR (CASE WHEN r."scoreVersion"=0 THEN r."value"<>0 OR r."sourceEffectId" IS NOT NULL ELSE NOT EXISTS(SELECT 1 FROM public."CompetitiveScorePosting" source JOIN public."CompetitiveEffect" previous ON previous."gameId"=source."gameId" AND previous."id"=source."effectId" WHERE source."gameId"=game_id AND source."teamId"=r."teamId" AND source."scoreVersion"=r."scoreVersion" AND source."after"=r."value" AND source."effectId"=r."sourceEffectId" AND previous."sequence"<e."sequence") END))) OR EXISTS(SELECT 1 FROM public."CompetitiveDependency" d WHERE d."gameId"=game_id AND d."effectId"=effect_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveScoreRead" r WHERE r."gameId"=game_id AND r."effectId"=effect_id AND r."sourceEffectId"=d."sourceEffectId")) THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 IF octet_length(convert_to(public.int6_enta_canonical(jsonb_build_object('effect',e."payload",'postings',p)),'UTF8'))+2>524288 THEN PERFORM public.int9_error('EFFECT_PROOF_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('effect',e."payload",'postings',p);
END $$;
CREATE FUNCTION public.int9_result_material(game_id TEXT,terminal JSONB,reason TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE g public."Game"%ROWTYPE; rt public."GameRuntime"%ROWTYPE; identity_row public."FirebaseIdentity"%ROWTYPE; scores JSONB; leaders JSONB; highest BIGINT; unplayed INTEGER; round_count INTEGER; outcome TEXT; payload JSONB; ruling RECORD; BEGIN
 SELECT "admissionId","executionFormat","firebaseIdentityId" INTO g."admissionId",g."executionFormat",g."firebaseIdentityId" FROM public."Game" WHERE "id"=game_id; SELECT "activeRoundId","state","teamOrder","version" INTO rt."activeRoundId",rt."state",rt."teamOrder",rt."version" FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT "firebaseProjectId" INTO identity_row."firebaseProjectId" FROM public."FirebaseIdentity" WHERE "id"=g."firebaseIdentityId";
 IF terminal->>'type' IS DISTINCT FROM 'FINISH' OR terminal->'authority' IS DISTINCT FROM jsonb_build_object('kind','HOST','identityId',g."firebaseIdentityId") OR (terminal->>'sequence')::INTEGER IS DISTINCT FROM rt."version"+(CASE WHEN rt."state"='FINISHED' THEN 0 ELSE 1 END) OR reason NOT IN ('HOST_ENDED','ALL_ROUNDS') OR rt."activeRoundId" IS NOT NULL OR EXISTS(SELECT 1 FROM public."CompetitiveRuntimeHead" WHERE "gameId"=game_id AND ("boardReviewRoundId" IS NOT NULL OR "openItemReviewId" IS NOT NULL)) OR EXISTS(SELECT 1 FROM public."CompetitiveAttempt" a WHERE a."gameId"=game_id AND NOT EXISTS(SELECT 1 FROM public."CompetitiveClassification" c WHERE c."gameId"=game_id AND c."attemptId"=a."id")) THEN PERFORM public.int9_error('RESULT_NOT_TERMINAL'); END IF;
 FOR ruling IN SELECT "scopeId" FROM public."CompetitiveRulingHead" WHERE "gameId"=game_id ORDER BY "scopeId" COLLATE "C" LOOP PERFORM public.int9_assert_ruling(game_id,ruling."scopeId"); END LOOP;
 IF EXISTS(SELECT 1 FROM public."Team" t WHERE t."gameId"=game_id AND t."score"::BIGINT IS DISTINCT FROM (SELECT COALESCE(sum(p."delta"::BIGINT),0) FROM public."CompetitiveScorePosting" p WHERE p."gameId"=game_id AND p."teamId"=t."id")) THEN PERFORM public.int9_error('RESULT_INTEGRITY_FAILURE'); END IF;
 SELECT jsonb_agg(jsonb_build_object('participantId',t."id",'score',t."score") ORDER BY ordered.ordinal),max(t."score"::BIGINT) INTO scores,highest FROM unnest(rt."teamOrder") WITH ORDINALITY ordered(team_id,ordinal) JOIN public."Team" t ON t."gameId"=game_id AND t."id"=ordered.team_id;
 SELECT jsonb_agg(t."id" ORDER BY ordered.ordinal) INTO leaders FROM unnest(rt."teamOrder") WITH ORDINALITY ordered(team_id,ordinal) JOIN public."Team" t ON t."gameId"=game_id AND t."id"=ordered.team_id WHERE t."score"::BIGINT=highest;
 SELECT count(*),count(*) FILTER(WHERE "state"->>'phase'<>'RESOLVED') INTO round_count,unplayed FROM public."GameRound" WHERE "gameId"=game_id; outcome:=(CASE WHEN reason='HOST_ENDED' THEN 'HOST_ENDED' WHEN jsonb_array_length(leaders)>1 THEN 'UNRESOLVED_TIE' ELSE 'DECISIVE' END);
 IF reason='ALL_ROUNDS' AND unplayed<>0 THEN PERFORM public.int9_error('RESULT_NOT_TERMINAL'); END IF;
 payload:=jsonb_build_object('schemaVersion',1,'rulesVersion','enta-competitive-1','requestVersion',5,'executionFormat',g."executionFormat",'projectId',identity_row."firebaseProjectId",'engine','ENTA','gameId',game_id,'admissionId',g."admissionId",'logicalMatchId',game_id,'resultVersion',1,'predecessor',NULL,'terminal',jsonb_build_object('eventId',terminal->'id','revision',terminal->'sequence'),'authority',jsonb_build_object('eventId',terminal->'id','kind','HOST','correctionReason',NULL),'participants',to_jsonb(rt."teamOrder"),'reason',reason,'prescribedCount',round_count,'completedCount',round_count-unplayed,'unplayedCount',unplayed,'outcome',outcome,'scores',scores,'winnerParticipantIds',CASE WHEN outcome='DECISIVE' THEN leaders ELSE '[]'::JSONB END,'tournamentBinding',NULL);
 RETURN jsonb_build_object('payload',payload,'hash',public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.result.v1','payload',payload)));
END $$;
CREATE FUNCTION public.int9_assert_terminal(game_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result public."EngineMatchResult"%ROWTYPE; head public."EngineMatchResultHead"%ROWTYPE; terminal public."RoundAuthorityEvent"%ROWTYPE; expected JSONB; g public."Game"%ROWTYPE; rt public."GameRuntime"%ROWTYPE; BEGIN
 SELECT "resultReason","state","version" INTO rt."resultReason",rt."state",rt."version" FROM public."GameRuntime" WHERE "gameId"=game_id; SELECT "admissionId","firebaseIdentityId","isTie","status","winnerTeamId" INTO g."admissionId",g."firebaseIdentityId",g."isTie",g."status",g."winnerTeamId" FROM public."Game" WHERE "id"=game_id; SELECT "admissionId","authorityEventId","bindingHash","bindingId","gameId","ownerIdentityId","payload","predecessorHash","predecessorVersion","resultHash","terminalEventId","terminalRevision" INTO result."admissionId",result."authorityEventId",result."bindingHash",result."bindingId",result."gameId",result."ownerIdentityId",result."payload",result."predecessorHash",result."predecessorVersion",result."resultHash",result."terminalEventId",result."terminalRevision" FROM public."EngineMatchResult" WHERE "gameId"=game_id AND "resultVersion"=1; SELECT "resultHash","resultVersion" INTO head."resultHash",head."resultVersion" FROM public."EngineMatchResultHead" WHERE "gameId"=game_id; SELECT "authorityKind","commandId","id","intentHash","ownerIdentityId","sequence","type" INTO terminal."authorityKind",terminal."commandId",terminal."id",terminal."intentHash",terminal."ownerIdentityId",terminal."sequence",terminal."type" FROM public."RoundAuthorityEvent" WHERE "gameId"=game_id AND "sequence"=rt."version";
 IF rt."state" IS DISTINCT FROM 'FINISHED' OR result."gameId" IS NULL OR (SELECT count(*) FROM public."EngineMatchResult" WHERE "gameId"=game_id)<>1 OR head."resultVersion" IS DISTINCT FROM 1 OR head."resultHash" IS DISTINCT FROM result."resultHash" OR result."ownerIdentityId" IS DISTINCT FROM g."firebaseIdentityId" OR result."admissionId" IS DISTINCT FROM g."admissionId" OR result."terminalRevision" IS DISTINCT FROM rt."version" OR result."terminalEventId" IS DISTINCT FROM terminal."id" OR result."authorityEventId" IS DISTINCT FROM terminal."id" OR result."predecessorVersion" IS NOT NULL OR result."predecessorHash" IS NOT NULL OR result."bindingId" IS NOT NULL OR result."bindingHash" IS NOT NULL OR terminal."type" IS DISTINCT FROM 'FINISH' OR terminal."authorityKind" IS DISTINCT FROM 'HOST' OR terminal."ownerIdentityId" IS DISTINCT FROM g."firebaseIdentityId" OR NOT EXISTS(SELECT 1 FROM public."GameEvent" event WHERE event."gameId"=game_id AND event."sequence"=terminal."sequence" AND event."commandId"=terminal."commandId" AND event."actorFirebaseIdentityId"=g."firebaseIdentityId" AND event."type"='FINISH' AND event."intentHash"=terminal."intentHash") THEN PERFORM public.int9_error('RESULT_INTEGRITY_FAILURE'); END IF;
 expected:=public.int9_result_material(game_id,jsonb_build_object('id',terminal."id",'sequence',terminal."sequence",'type',terminal."type",'authority',jsonb_build_object('kind','HOST','identityId',terminal."ownerIdentityId")),CASE WHEN rt."resultReason"='HOST_ENDED' THEN 'HOST_ENDED' ELSE 'ALL_ROUNDS' END);
 IF result."payload" IS DISTINCT FROM expected->'payload' OR result."resultHash" IS DISTINCT FROM expected->>'hash' OR g."status" IS DISTINCT FROM 'FINISHED' OR g."winnerTeamId" IS DISTINCT FROM (CASE WHEN expected->'payload'->>'outcome'='DECISIVE' THEN expected->'payload'->'winnerParticipantIds'->>0 ELSE NULL END) OR g."isTie" IS DISTINCT FROM (expected->'payload'->>'outcome'='UNRESOLVED_TIE') THEN PERFORM public.int9_error('RESULT_INTEGRITY_FAILURE'); END IF;
END $$;
CREATE FUNCTION public.int9_catalog_material(ns TEXT,project TEXT,uid TEXT,execution_format TEXT,selected_keys JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE identity_id TEXT; pointer public."ActiveCatalogPointer"%ROWTYPE; f public."EntaFormatRelease"%ROWTYPE; competitive public."EntaCompetitiveRelease"%ROWTYPE; categories JSONB; material JSONB; BEGIN
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; IF execution_format NOT IN ('TIER_BOARD','MIXED_BOARD','STANDALONE_LIST','STANDALONE_ACTING') OR selected_keys IS NOT NULL AND (jsonb_typeof(selected_keys) IS DISTINCT FROM 'array' OR jsonb_array_length(selected_keys) NOT BETWEEN 1 AND 6) THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 SELECT "catalogReleaseId","id","releaseRootHash","validationReceiptId" INTO pointer."catalogReleaseId",pointer."id",pointer."releaseRootHash",pointer."validationReceiptId" FROM public."ActiveCatalogPointer" WHERE "id"='singleton' FOR SHARE;
 SELECT "baseReleaseId","baseRoot","formatRoot","id","mediaRoot","policyVersion","receiptId" INTO f."baseReleaseId",f."baseRoot",f."formatRoot",f."id",f."mediaRoot",f."policyVersion",f."receiptId" FROM public."EntaFormatRelease" WHERE "baseReleaseId"=pointer."catalogReleaseId" AND "baseRoot"=pointer."releaseRootHash" AND "receiptId"=pointer."validationReceiptId" AND "sealedAt" IS NOT NULL AND "policyVersion"='enta-format-1';
 SELECT "id","paletteRoot","proofRoot" INTO competitive."id",competitive."paletteRoot",competitive."proofRoot" FROM public."EntaCompetitiveRelease" WHERE "formatReleaseId"=f."id" AND "formatRoot"=f."formatRoot" AND "mediaRoot"=f."mediaRoot" AND "rulesVersion"='enta-competitive-1' AND "paletteRoot"=public.int9_palette_root() AND "sealedAt" IS NOT NULL;
 IF pointer."id" IS NULL OR f."id" IS NULL OR competitive."id" IS NULL OR (SELECT count(*) FROM public."EntaCompetitiveRelease" WHERE "formatReleaseId"=f."id" AND "sealedAt" IS NOT NULL)<>1 THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(jsonb_build_array(f."baseReleaseId",f."receiptId",f."id",competitive."id")) value WHERE octet_length(convert_to(value,'UTF8')) NOT BETWEEN 1 AND 1024) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 -- These named authority denials are retained. Sealed metadata never supplies
 -- a missing approved receipt, issuer, authoring or tournament authority.
 PERFORM public.int9_assert_competitive(competitive."id"); PERFORM public.int6_enta_assert_receipt(f."receiptId",f."baseReleaseId",f."baseRoot");
 SELECT COALESCE(jsonb_agg(jsonb_build_object('key',category."categoryKey",'label',left(revision."labelAr",64),'format',family."format",'cover',(SELECT public.int9_media_descriptor(cover."proofId",'COVER',NULL) FROM public."EntaFormatCover" cover WHERE cover."releaseId"=f."id" AND cover."categoryKey"=category."categoryKey")) ORDER BY category."categoryKey" COLLATE "C"),'[]'::JSONB) INTO categories FROM public."CatalogReleaseCategory" category JOIN public."CanonicalCategoryRevision" revision ON revision."id"=category."categoryRevisionId" JOIN LATERAL (SELECT min("format") AS "format" FROM public."EntaFormatRevision" WHERE "releaseId"=f."id" AND "categoryKey"=category."categoryKey") family ON family."format" IS NOT NULL WHERE category."catalogReleaseId"=f."baseReleaseId" AND (selected_keys IS NULL OR selected_keys @> jsonb_build_array(category."categoryKey")) AND (execution_format='MIXED_BOARD' OR family."format"=(CASE execution_format WHEN 'TIER_BOARD' THEN 'ORDINARY_TIER' WHEN 'STANDALONE_LIST' THEN 'LIST_ITEMS' ELSE 'ACTING_ITEMS' END));
 IF selected_keys IS NULL OR jsonb_array_length(categories)<>jsonb_array_length(selected_keys) THEN PERFORM public.int9_error('CATEGORY_UNAVAILABLE'); END IF;
 material:=jsonb_build_object('base',jsonb_build_object('baseReleaseId',f."baseReleaseId",'baseRoot',f."baseRoot",'receiptId',f."receiptId",'formatReleaseId',f."id",'formatRoot',f."formatRoot",'mediaRoot',f."mediaRoot",'policyVersion',f."policyVersion",'categories',categories),'policyVersion','enta-competitive-1','competitiveReleaseId',competitive."id",'proofRoot',competitive."proofRoot",'paletteRoot',competitive."paletteRoot");
 IF octet_length(convert_to(public.int6_enta_canonical(material),'UTF8'))>65536 THEN PERFORM public.int9_error('CATALOG_BOUND_EXCEEDED'); END IF; RETURN material;
END $$;
CREATE FUNCTION public.int9_start_request(ns TEXT,project TEXT,uid TEXT,request JSONB,seed TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c4_captured JSONB; identity_id TEXT; wallet public."Wallet"%ROWTYPE; prior JSONB; catalog JSONB; base JSONB; selection JSONB; intent JSONB; selected_keys JSONB; state JSONB; saved_receipt_id TEXT; BEGIN
 IF public.int9_valid_request(request) IS NOT TRUE OR seed!~'^[a-f0-9]{64}$' THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; SELECT "available","debt" INTO wallet."available",wallet."debt" FROM public."Wallet" WHERE "firebaseIdentityId"=identity_id FOR UPDATE; IF NOT FOUND THEN PERFORM public.int9_error('ACCOUNT_NOT_READY'); END IF;
 prior:=public.int9_find_start(ns,project,uid,request->>'requestKey',request->>'logicalMatchId'); IF prior IS NOT NULL THEN IF prior->'request' IS DISTINCT FROM request THEN PERFORM public.int9_error('IDEMPOTENCY_KEY_CONFLICT'); END IF; prior:=NULL; RETURN jsonb_build_object('match',public.int9_main_dto(request->>'logicalMatchId',public.int9_now()),'idempotent',TRUE); END IF;
 IF wallet."debt">0 THEN PERFORM public.int9_error('WALLET_DEBT_BLOCKS_START'); END IF; IF wallet."available"<1 THEN PERFORM public.int9_error('INSUFFICIENT_CREDIT'); END IF;
 SELECT jsonb_agg(category->'key' ORDER BY ordinal) INTO selected_keys FROM jsonb_array_elements(request->'setup'->'categories') WITH ORDINALITY wanted(category,ordinal);
 c4_captured:=public.int9_c4_f11_capture(ns,project,uid,request,NULL); catalog:=public.int9_c4_catalog_at(ns,project,uid,request,c4_captured); c4_captured:=NULL; base:=catalog->'base'; selection:=public.int9_select_references(catalog->>'competitiveReleaseId',request,seed,identity_id);
 intent:=jsonb_build_object('domain','maydan.enta.competitive.start-intent.v1','pinMaterial','maydan.enta.competitive.pin-references.v1','version',5,'request',request,'baseReleaseId',base->'baseReleaseId','baseRoot',base->'baseRoot','receiptId',base->'receiptId','formatReleaseId',base->'formatReleaseId','formatRoot',base->'formatRoot','mediaRoot',base->'mediaRoot','policyVersion','enta-competitive-1','poolHash',public.int9_pool_root(catalog->>'competitiveReleaseId',request),'seed',seed,'selection',selection,'roundCount',jsonb_array_length(selection),'pinsHash',public.int9_references_hash(selection),'competitiveReleaseId',catalog->'competitiveReleaseId','proofRoot',catalog->'proofRoot','paletteRoot',catalog->'paletteRoot','tournamentBinding',NULL);
 IF octet_length(convert_to(public.int6_enta_canonical(intent),'UTF8'))>1048576 THEN PERFORM public.int9_error('START_BOUND_EXCEEDED'); END IF;
 saved_receipt_id:=base->>'receiptId'; catalog:=NULL; base:=NULL; selection:=NULL; selected_keys:=NULL;
 state:=public.int9_start(ns,project,uid,request,intent,intent->'selection',saved_receipt_id); intent:=NULL;
 PERFORM public.int9_complete_game(state->>'id'); state:=NULL; RETURN jsonb_build_object('match',public.int9_main_dto(request->>'logicalMatchId',public.int9_now()),'idempotent',FALSE);
END $$;
