 IF (SELECT count(*) FROM public."DeploymentNamespace")>1 OR EXISTS(SELECT 1 FROM public."DeploymentNamespace" WHERE "id" IS DISTINCT FROM 'singleton' OR "namespaceId" IS NULL OR "firebaseProjectId" IS NULL OR "namespaceId"='' OR "firebaseProjectId"='') THEN RAISE EXCEPTION 'NAMESPACE_INSTALL_REVIEW_REQUIRED'; END IF;
END $namespace_preflight$;
