covered_MediaObjectProof AS (SELECT r."id",r."mediaRevisionId",r."mediaHash" FROM public."MediaObjectProof" r WHERE (r."id" IN(SELECT proof_id FROM candidate_proofs)) OR (EXISTS(SELECT 1 FROM covered_MediaChunkProof child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatCover child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id"))),
