 UNION ALL SELECT 1 FROM wanted w WHERE (SELECT count(*) FROM public."CatalogReleaseCategory" c,tuple_source t WHERE c."catalogReleaseId"=t.base_id AND c."categoryKey"=w.key)<>1 UNION ALL SELECT 1 FROM public."EntaCompetitivePrompt" p JOIN covered_EntaCompetitivePrompt c ON c."id"=p."id",tuple_source t WHERE (SELECT count(*) FROM public."EntaFormatRevision" f WHERE f."id"=p."formatId" AND f."releaseId"=t.format_id AND f."questionRevisionId"=p."questionRevisionId" AND f."questionHash"=p."questionHash")<>1)) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 -- Original bounded-content/child predicates move before wide exports here;
 -- their full invalid inputs remain within the declared preprofile boundary.
 IF (WITH tuple_source AS (SELECT p."catalogReleaseId" base_id,p."releaseRootHash" base_root,p."validationReceiptId" receipt_id,f."id" format_id,f."formatRoot" format_root,f."mediaRoot" media_root,c."id" competitive_id,c."proofRoot" proof_root,c."paletteRoot" palette_root FROM public."ActiveCatalogPointer" p JOIN public."EntaFormatRelease" f ON f."baseReleaseId"=p."catalogReleaseId" AND f."baseRoot"=p."releaseRootHash" AND f."receiptId"=p."validationReceiptId" AND f."sealedAt" IS NOT NULL AND f."policyVersion"='enta-format-1' JOIN public."EntaCompetitiveRelease" c ON c."formatReleaseId"=f."id" AND c."formatRoot"=f."formatRoot" AND c."mediaRoot"=f."mediaRoot" AND c."rulesVersion"='enta-competitive-1' AND c."paletteRoot"=public.int9_palette_root() AND c."sealedAt" IS NOT NULL WHERE p."id"='singleton'),
wanted AS (SELECT value->>'key' key FROM jsonb_array_elements(request->'setup'->'categories')),
candidate_formats AS (SELECT f."id" id FROM public."EntaFormatRevision" f,tuple_source t WHERE f."categoryKey" IN(SELECT key FROM wanted) AND (f."releaseId"=t.format_id OR EXISTS(SELECT 1 FROM public."EntaCompetitivePrompt" p WHERE p."releaseId"=t.competitive_id AND p."formatId"=f."id"))),
candidate_prompts AS (SELECT p."id" id FROM public."EntaCompetitivePrompt" p,tuple_source t WHERE p."releaseId"=t.competitive_id AND (p."formatId" IN(SELECT id FROM candidate_formats) OR NOT EXISTS(SELECT 1 FROM public."EntaFormatRevision" f WHERE f."id"=p."formatId"))),
candidate_proofs AS (SELECT m."proofId" proof_id FROM public."EntaFormatMedia" m WHERE m."formatId" IN(SELECT id FROM candidate_formats) UNION SELECT c."proofId" FROM public."EntaFormatCover" c,tuple_source t WHERE c."releaseId"=t.format_id AND c."categoryKey" IN(SELECT key FROM wanted)),
covered_DeploymentNamespace AS (SELECT r."id",r."namespaceId",r."firebaseProjectId" FROM public."DeploymentNamespace" r WHERE (r."id"='singleton')),
covered_Wallet AS (SELECT r."id",r."firebaseIdentityId" FROM public."Wallet" r WHERE (EXISTS(SELECT 1 FROM public."FirebaseIdentity" i WHERE i."id"=r."firebaseIdentityId" AND i."firebaseProjectId"=project AND i."firebaseUid"=uid))),
covered_FirebaseIdentity AS (SELECT r."id",r."firebaseProjectId",r."firebaseUid",r."userId" FROM public."FirebaseIdentity" r WHERE (r."firebaseProjectId"=project AND r."firebaseUid"=uid) OR (EXISTS(SELECT 1 FROM covered_Wallet child WHERE child."firebaseIdentityId" IS NOT NULL AND child."firebaseIdentityId"=r."id"))),
covered_ActiveCatalogPointer AS (SELECT r."catalogReleaseId",r."validationReceiptId",r."releaseRootHash",r."id" FROM public."ActiveCatalogPointer" r WHERE (r."id"='singleton')),
covered_EntaFormatMedia AS (SELECT r."formatId",r."questionRevisionId",r."itemId",r."proofId",r."questionHash",r."id" FROM public."EntaFormatMedia" r WHERE (r."formatId" IN(SELECT id FROM candidate_formats))),
covered_EntaFormatItem AS (SELECT r."id",r."formatId",r."questionRevisionId",r."answerRevisionId",r."questionHash",r."answerHash" FROM public."EntaFormatItem" r WHERE (r."formatId" IN(SELECT id FROM candidate_formats)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."formatId" AND child."itemId" IS NOT NULL AND child."itemId"=r."id"))),
covered_EntaCompetitiveHint AS (SELECT r."id",r."promptId",r."questionRevisionId",r."questionHash" FROM public."EntaCompetitiveHint" r WHERE (r."promptId" IN(SELECT id FROM candidate_prompts))),
covered_EntaCompetitiveGrapheme AS (SELECT r."id",r."promptId",r."questionRevisionId",r."answerRevisionId",r."questionHash",r."answerHash" FROM public."EntaCompetitiveGrapheme" r WHERE (r."promptId" IN(SELECT id FROM candidate_prompts))),
covered_EntaCompetitivePrompt AS (SELECT r."id",r."releaseId",r."formatId",r."questionRevisionId",r."questionHash" FROM public."EntaCompetitivePrompt" r WHERE (r."id" IN(SELECT id FROM candidate_prompts)) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveHint child WHERE child."promptId" IS NOT NULL AND child."promptId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveGrapheme child WHERE child."promptId" IS NOT NULL AND child."promptId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash"))),
covered_EntaFormatRevision AS (SELECT r."id",r."opaqueRef",r."categoryKey",r."sourceNamespace",r."sourceId",r."releaseId",r."questionRevisionId",r."questionHash" FROM public."EntaFormatRevision" r WHERE (r."id" IN(SELECT id FROM candidate_formats)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatItem child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitivePrompt child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash"))),
covered_EntaFormatCover AS (SELECT r."releaseId",r."categoryKey",r."proofId" FROM public."EntaFormatCover" r WHERE (r."releaseId" IN(SELECT format_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted))),
covered_EntaCompetitiveRelease AS (SELECT r."id",r."formatReleaseId",r."formatRoot",r."mediaRoot" FROM public."EntaCompetitiveRelease" r WHERE (r."id" IN(SELECT competitive_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitivePrompt child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id"))),
covered_EntaFormatRelease AS (SELECT r."id",r."baseReleaseId",r."receiptId",r."baseRoot",r."formatRoot",r."mediaRoot" FROM public."EntaFormatRelease" r WHERE (r."id" IN(SELECT format_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRevision child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatCover child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveRelease child WHERE child."formatReleaseId" IS NOT NULL AND child."formatReleaseId"=r."id" AND child."formatRoot" IS NOT NULL AND child."formatRoot"=r."formatRoot" AND child."mediaRoot" IS NOT NULL AND child."mediaRoot"=r."mediaRoot"))),
covered_CatalogReleaseQuestion AS (SELECT r."catalogReleaseId",r."questionRevisionId",r."categoryKey",r."sourceNamespace",r."sourceSnapshotHash",r."questionContentHash",r."id" FROM public."CatalogReleaseQuestion" r WHERE (r."catalogReleaseId" IN(SELECT base_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted))),
covered_CatalogReleaseSourceSnapshot AS (SELECT r."catalogReleaseId",r."sourceNamespace",r."snapshotHash",r."id" FROM public."CatalogReleaseSourceSnapshot" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceSnapshotHash" IS NOT NULL AND child."sourceSnapshotHash"=r."snapshotHash"))),
covered_CatalogReleaseCategory AS (SELECT r."catalogReleaseId",r."categoryKey",r."categoryRevisionId",r."categoryContentHash",r."id" FROM public."CatalogReleaseCategory" r WHERE (r."catalogReleaseId" IN(SELECT base_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted)) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."categoryKey"))),
covered_CatalogValidationReceipt AS (SELECT r."id",r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."proofId",r."policyVersion" FROM public."CatalogValidationReceipt" r WHERE (r."id" IN(SELECT receipt_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_ActiveCatalogPointer child WHERE child."validationReceiptId" IS NOT NULL AND child."validationReceiptId"=r."id" AND child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRelease child WHERE child."receiptId" IS NOT NULL AND child."receiptId"=r."id" AND child."baseReleaseId" IS NOT NULL AND child."baseReleaseId"=r."catalogReleaseId" AND child."baseRoot" IS NOT NULL AND child."baseRoot"=r."releaseRootHash"))),
covered_CatalogValidationProof AS (SELECT r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."id",r."policyVersion" FROM public."CatalogValidationProof" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogValidationReceipt child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id" AND child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash" AND child."policyVersion" IS NOT NULL AND child."policyVersion"=r."policyVersion"))),
covered_CatalogReleaseSeal AS (SELECT r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."id" FROM public."CatalogReleaseSeal" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogValidationReceipt child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogValidationProof child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash"))),
covered_CatalogRelease AS (SELECT r."id",r."releaseRootHash" FROM public."CatalogRelease" r WHERE (r."id" IN(SELECT base_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseSourceSnapshot child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseCategory child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_ActiveCatalogPointer child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseSeal child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRelease child WHERE child."baseReleaseId" IS NOT NULL AND child."baseReleaseId"=r."id" AND child."baseRoot" IS NOT NULL AND child."baseRoot"=r."releaseRootHash"))),
covered_CanonicalCategoryRevision AS (SELECT r."id",r."categoryKey",r."sourceNamespace",r."coverMediaRevisionId",r."editorialReceiptId",r."revision",r."contentHash",r."editorialDecision" FROM public."CanonicalCategoryRevision" r WHERE (r."id" IN(SELECT c."categoryRevisionId" FROM public."CatalogReleaseCategory" c,tuple_source t WHERE c."catalogReleaseId"=t.base_id AND c."categoryKey" IN(SELECT key FROM wanted))) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseCategory child WHERE child."categoryRevisionId" IS NOT NULL AND child."categoryRevisionId"=r."id" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."categoryKey" AND child."categoryContentHash" IS NOT NULL AND child."categoryContentHash"=r."contentHash"))),
covered_MediaChunkProof AS (SELECT r."proofId" FROM public."MediaChunkProof" r WHERE (r."proofId" IN(SELECT proof_id FROM candidate_proofs))),
covered_MediaObjectProof AS (SELECT r."id",r."mediaRevisionId",r."mediaHash" FROM public."MediaObjectProof" r WHERE (r."id" IN(SELECT proof_id FROM candidate_proofs)) OR (EXISTS(SELECT 1 FROM covered_MediaChunkProof child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatCover child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id"))),
covered_QuestionRevisionMedia AS (SELECT r."questionRevisionId",r."mediaRevisionId",r."questionContentHash",r."mediaSha256",r."id" FROM public."QuestionRevisionMedia" r WHERE (r."questionRevisionId" IN(SELECT f."questionRevisionId" FROM public."EntaFormatRevision" f WHERE f."id" IN(SELECT id FROM candidate_formats)))),
covered_User AS (SELECT r."id" FROM public."User" r WHERE (EXISTS(SELECT 1 FROM covered_FirebaseIdentity child WHERE child."userId" IS NOT NULL AND child."userId"=r."id"))),
covered_MediaRevision AS (SELECT r."id",r."rightsReceiptId",r."sourceNamespace",r."rightsSubjectType",r."sourceMediaId",r."mediaSha256",r."rightsDecision" FROM public."MediaRevision" r WHERE (EXISTS(SELECT 1 FROM covered_CanonicalCategoryRevision child WHERE child."coverMediaRevisionId" IS NOT NULL AND child."coverMediaRevisionId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionMedia child WHERE child."mediaRevisionId" IS NOT NULL AND child."mediaRevisionId"=r."id" AND child."mediaSha256" IS NOT NULL AND child."mediaSha256"=r."mediaSha256")) OR (EXISTS(SELECT 1 FROM covered_MediaObjectProof child WHERE child."mediaRevisionId" IS NOT NULL AND child."mediaRevisionId"=r."id" AND child."mediaHash" IS NOT NULL AND child."mediaHash"=r."mediaSha256"))),
covered_QuestionAnswerRevision AS (SELECT r."id",r."questionRevisionId",r."questionContentHash",r."contentHash" FROM public."QuestionAnswerRevision" r WHERE (EXISTS(SELECT 1 FROM covered_EntaFormatItem child WHERE child."answerRevisionId" IS NOT NULL AND child."answerRevisionId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionContentHash" AND child."answerHash" IS NOT NULL AND child."answerHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveGrapheme child WHERE child."answerRevisionId" IS NOT NULL AND child."answerRevisionId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionContentHash" AND child."answerHash" IS NOT NULL AND child."answerHash"=r."contentHash"))),
covered_QuestionRevisionSeal AS (SELECT r."questionRevisionId",r."contentHash",r."id" FROM public."QuestionRevisionSeal" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash"))),
covered_QuestionRevision AS (SELECT r."id",r."canonicalCategoryKey",r."crosswalkRevisionId",r."sourceNamespace",r."sourceCategoryId",r."crosswalkRevision",r."editorialReceiptId",r."sourceQuestionId",r."revision",r."contentHash",r."editorialDecision",r."rightsReceiptId",r."rightsSubjectType",r."rightsDecision" FROM public."QuestionRevision" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionAnswerRevision child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionMedia child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."canonicalCategoryKey" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionSeal child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRevision child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceId" IS NOT NULL AND child."sourceId"=r."sourceQuestionId" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."canonicalCategoryKey" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."contentHash"))),
covered_ContentRightsReceipt AS (SELECT r."id",r."sourceNamespace",r."subjectType",r."sourceKey",r."subjectHash",r."decision" FROM public."ContentRightsReceipt" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."rightsReceiptId" IS NOT NULL AND child."rightsReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."rightsSubjectType" IS NOT NULL AND child."rightsSubjectType"=r."subjectType" AND child."sourceQuestionId" IS NOT NULL AND child."sourceQuestionId"=r."sourceKey" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."rightsDecision" IS NOT NULL AND child."rightsDecision"=r."decision")) OR (EXISTS(SELECT 1 FROM covered_MediaRevision child WHERE child."rightsReceiptId" IS NOT NULL AND child."rightsReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."rightsSubjectType" IS NOT NULL AND child."rightsSubjectType"=r."subjectType" AND child."sourceMediaId" IS NOT NULL AND child."sourceMediaId"=r."sourceKey" AND child."mediaSha256" IS NOT NULL AND child."mediaSha256"=r."subjectHash" AND child."rightsDecision" IS NOT NULL AND child."rightsDecision"=r."decision"))),
covered_EditorialReviewReceipt AS (SELECT r."id",r."sourceNamespace",r."sourceKey",r."sourceRevision",r."subjectHash",r."decision" FROM public."EditorialReviewReceipt" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."editorialReceiptId" IS NOT NULL AND child."editorialReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceQuestionId" IS NOT NULL AND child."sourceQuestionId"=r."sourceKey" AND child."revision" IS NOT NULL AND child."revision"=r."sourceRevision" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."editorialDecision" IS NOT NULL AND child."editorialDecision"=r."decision")) OR (EXISTS(SELECT 1 FROM covered_CanonicalCategoryRevision child WHERE child."editorialReceiptId" IS NOT NULL AND child."editorialReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."sourceKey" AND child."revision" IS NOT NULL AND child."revision"=r."sourceRevision" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."editorialDecision" IS NOT NULL AND child."editorialDecision"=r."decision"))),
covered_SourceCategoryCrosswalkRevision AS (SELECT r."id",r."sourceNamespace",r."sourceCategoryId",r."revision",r."canonicalCategoryKey" FROM public."SourceCategoryCrosswalkRevision" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."crosswalkRevisionId" IS NOT NULL AND child."crosswalkRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceCategoryId" IS NOT NULL AND child."sourceCategoryId"=r."sourceCategoryId" AND child."crosswalkRevision" IS NOT NULL AND child."crosswalkRevision"=r."revision" AND child."canonicalCategoryKey" IS NOT NULL AND child."canonicalCategoryKey"=r."canonicalCategoryKey"))) SELECT EXISTS(SELECT 1 FROM public."QuestionRevision" q JOIN covered_QuestionRevision c ON c."id"=q."id" WHERE public.int6_enta_valid_text(to_jsonb(q."prompt"),1,2000) IS NOT TRUE UNION ALL SELECT 1 FROM public."QuestionAnswerRevision" a JOIN covered_QuestionAnswerRevision c ON c."id"=a."id" WHERE public.int6_enta_valid_text(to_jsonb(a."text"),1,512) IS NOT TRUE
 UNION ALL SELECT 1 FROM covered_EntaFormatRevision f WHERE (SELECT count(*) FROM public."EntaFormatItem" i WHERE i."formatId"=f."id")>128 OR (SELECT count(*) FROM public."EntaFormatMedia" m WHERE m."formatId"=f."id")>260 OR (SELECT count(*)-count(DISTINCT m."proofId") FROM public."EntaFormatMedia" m WHERE m."formatId"=f."id")<>0 UNION ALL SELECT 1 FROM covered_EntaCompetitivePrompt p WHERE (SELECT count(*) FROM public."EntaCompetitiveHint" h WHERE h."promptId"=p."id")>4 OR (SELECT count(*) FROM public."EntaCompetitiveGrapheme" g WHERE g."promptId"=p."id")>128
 UNION ALL SELECT 1 FROM public."EntaFormatRevision" f JOIN covered_EntaFormatRevision c ON c."id"=f."id" JOIN public."QuestionRevision" q ON q."id"=f."questionRevisionId" WHERE f."id"!~'^[A-Za-z0-9_-]{1,128}$' OR f."questionRevisionId"!~'^[A-Za-z0-9_-]{1,128}$' OR f."opaqueRef"!~'^[A-Za-z0-9_-]{1,128}$' OR f."categoryKey"!~'^[A-Za-z0-9_-]{1,128}$' OR public.int6_enta_exact_keys(f."rules",ARRAY['version','kind','target']) IS NOT TRUE OR f."rules"->'version' IS DISTINCT FROM '1'::JSONB OR f."rules"->>'kind' IS DISTINCT FROM f."format" OR (CASE WHEN f."format" IN('ORDINARY_TIER','DRAWING_TARGET') THEN public.int6_enta_valid_text(f."rules"->'target',1,512) IS NOT TRUE OR q."points" NOT IN(200,400,600) ELSE f."rules"->'target' IS DISTINCT FROM 'null'::JSONB END)
 UNION ALL SELECT 1 FROM public."EntaFormatItem" i JOIN covered_EntaFormatItem c ON c."id"=i."id" WHERE i."id"!~'^[A-Za-z0-9_-]{1,128}$' OR i."answerRevisionId"!~'^[A-Za-z0-9_-]{1,128}$' OR (SELECT count(*) FROM public."EntaFormatItem" sibling WHERE sibling."formatId"=i."formatId" AND sibling."ordinal"<=i."ordinal")<>i."ordinal"+1 UNION ALL SELECT 1 FROM public."EntaCompetitiveHint" h JOIN covered_EntaCompetitiveHint c ON c."id"=h."id" WHERE h."id"!~'^[A-Za-z0-9_-]{1,128}$' OR public.int6_enta_valid_text(to_jsonb(h."text"),1,512) IS NOT TRUE OR (SELECT count(*) FROM public."EntaCompetitiveHint" sibling WHERE sibling."promptId"=h."promptId" AND sibling."ordinal"<=h."ordinal")<>h."ordinal"+1 UNION ALL SELECT 1 FROM public."EntaCompetitiveGrapheme" g JOIN covered_EntaCompetitiveGrapheme c ON c."id"=g."id" JOIN public."EntaCompetitivePrompt" p ON p."id"=g."promptId" WHERE g."id"!~'^[A-Za-z0-9_-]{1,128}$' OR public.int6_enta_valid_text(to_jsonb(g."grapheme"),1,64) IS NOT TRUE OR public.int6_enta_valid_text(to_jsonb(g."segmentationVersion"),1,64) IS NOT TRUE OR (SELECT count(*) FROM public."EntaFormatItem" i WHERE i."formatId"=p."formatId" AND i."answerRevisionId"=g."answerRevisionId" AND i."answerHash"=g."answerHash" AND NOT i."trap")<>1
 UNION ALL SELECT 1 FROM public."MediaObjectProof" p JOIN covered_MediaObjectProof c ON c."id"=p."id" JOIN public."MediaRevision" m ON m."id"=p."mediaRevisionId" WHERE p."sealedAt" IS NULL OR p."mediaHash" IS DISTINCT FROM m."mediaSha256" OR p."byteLength" IS DISTINCT FROM m."byteLength" OR p."byteLength" NOT BETWEEN 1 AND 67108864 OR p."width"<1 OR p."height"<1 OR p."width"::BIGINT*p."height"::BIGINT>16000000 OR m."objectKey"!~'^enta-private/[A-Za-z0-9_/-]{1,180}$' OR position('..' IN m."objectKey")>0 OR p."objectVersion"!~'^[0-9]{1,24}$' OR COALESCE(CASE WHEN m."mimeType" IN('video/mp4','video/webm') THEN p."durationMs" BETWEEN 1 AND 120000 AND p."codec" IN('h264','vp8','vp9') ELSE m."mimeType" IN('image/png','image/jpeg','image/webp') AND p."byteLength"<=10485760 AND p."durationMs" IS NULL AND p."codec" IS NULL END,FALSE) IS NOT TRUE OR (SELECT count(*) FROM public."MediaChunkProof" chunk WHERE chunk."proofId"=p."id")<>ceil(p."byteLength"/262144.0) OR EXISTS(SELECT 1 FROM generate_series(0,ceil(p."byteLength"/262144.0)::INTEGER-1) n WHERE NOT EXISTS(SELECT 1 FROM public."MediaChunkProof" chunk WHERE chunk."proofId"=p."id" AND chunk."ordinal"=n AND chunk."byteLength"=least(262144,p."byteLength"-n*262144)))
 UNION ALL SELECT 1 FROM public."EntaFormatMedia" m JOIN covered_EntaFormatMedia c ON c."formatId"=m."formatId" AND c."proofId"=m."proofId" WHERE m."role" NOT IN('PROMPT','MASKED','CLEAR','ACTOR','ITEM') OR (m."role"='ITEM') IS DISTINCT FROM (m."itemId" IS NOT NULL) OR m."itemId" IS NOT NULL AND (SELECT count(*) FROM public."EntaFormatItem" i WHERE i."formatId"=m."formatId" AND i."id"=m."itemId")<>1)) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 -- No caller flag/length is authority. Private start compares its actual full
 -- expected intent tuple to the independently locked physical relation here.
 IF expected IS NOT NULL AND (WITH tuple_source AS (SELECT p."catalogReleaseId" base_id,p."releaseRootHash" base_root,p."validationReceiptId" receipt_id,f."id" format_id,f."formatRoot" format_root,f."mediaRoot" media_root,c."id" competitive_id,c."proofRoot" proof_root,c."paletteRoot" palette_root FROM public."ActiveCatalogPointer" p JOIN public."EntaFormatRelease" f ON f."baseReleaseId"=p."catalogReleaseId" AND f."baseRoot"=p."releaseRootHash" AND f."receiptId"=p."validationReceiptId" AND f."sealedAt" IS NOT NULL AND f."policyVersion"='enta-format-1' JOIN public."EntaCompetitiveRelease" c ON c."formatReleaseId"=f."id" AND c."formatRoot"=f."formatRoot" AND c."mediaRoot"=f."mediaRoot" AND c."rulesVersion"='enta-competitive-1' AND c."paletteRoot"=public.int9_palette_root() AND c."sealedAt" IS NOT NULL WHERE p."id"='singleton'),
wanted AS (SELECT value->>'key' key FROM jsonb_array_elements(request->'setup'->'categories')),
candidate_formats AS (SELECT f."id" id FROM public."EntaFormatRevision" f,tuple_source t WHERE f."categoryKey" IN(SELECT key FROM wanted) AND (f."releaseId"=t.format_id OR EXISTS(SELECT 1 FROM public."EntaCompetitivePrompt" p WHERE p."releaseId"=t.competitive_id AND p."formatId"=f."id"))),
candidate_prompts AS (SELECT p."id" id FROM public."EntaCompetitivePrompt" p,tuple_source t WHERE p."releaseId"=t.competitive_id AND (p."formatId" IN(SELECT id FROM candidate_formats) OR NOT EXISTS(SELECT 1 FROM public."EntaFormatRevision" f WHERE f."id"=p."formatId"))),
candidate_proofs AS (SELECT m."proofId" proof_id FROM public."EntaFormatMedia" m WHERE m."formatId" IN(SELECT id FROM candidate_formats) UNION SELECT c."proofId" FROM public."EntaFormatCover" c,tuple_source t WHERE c."releaseId"=t.format_id AND c."categoryKey" IN(SELECT key FROM wanted)),
covered_DeploymentNamespace AS (SELECT r."id",r."namespaceId",r."firebaseProjectId" FROM public."DeploymentNamespace" r WHERE (r."id"='singleton')),
covered_Wallet AS (SELECT r."id",r."firebaseIdentityId" FROM public."Wallet" r WHERE (EXISTS(SELECT 1 FROM public."FirebaseIdentity" i WHERE i."id"=r."firebaseIdentityId" AND i."firebaseProjectId"=project AND i."firebaseUid"=uid))),
covered_FirebaseIdentity AS (SELECT r."id",r."firebaseProjectId",r."firebaseUid",r."userId" FROM public."FirebaseIdentity" r WHERE (r."firebaseProjectId"=project AND r."firebaseUid"=uid) OR (EXISTS(SELECT 1 FROM covered_Wallet child WHERE child."firebaseIdentityId" IS NOT NULL AND child."firebaseIdentityId"=r."id"))),
covered_ActiveCatalogPointer AS (SELECT r."catalogReleaseId",r."validationReceiptId",r."releaseRootHash",r."id" FROM public."ActiveCatalogPointer" r WHERE (r."id"='singleton')),
covered_EntaFormatMedia AS (SELECT r."formatId",r."questionRevisionId",r."itemId",r."proofId",r."questionHash",r."id" FROM public."EntaFormatMedia" r WHERE (r."formatId" IN(SELECT id FROM candidate_formats))),
covered_EntaFormatItem AS (SELECT r."id",r."formatId",r."questionRevisionId",r."answerRevisionId",r."questionHash",r."answerHash" FROM public."EntaFormatItem" r WHERE (r."formatId" IN(SELECT id FROM candidate_formats)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."formatId" AND child."itemId" IS NOT NULL AND child."itemId"=r."id"))),
covered_EntaCompetitiveHint AS (SELECT r."id",r."promptId",r."questionRevisionId",r."questionHash" FROM public."EntaCompetitiveHint" r WHERE (r."promptId" IN(SELECT id FROM candidate_prompts))),
covered_EntaCompetitiveGrapheme AS (SELECT r."id",r."promptId",r."questionRevisionId",r."answerRevisionId",r."questionHash",r."answerHash" FROM public."EntaCompetitiveGrapheme" r WHERE (r."promptId" IN(SELECT id FROM candidate_prompts))),
covered_EntaCompetitivePrompt AS (SELECT r."id",r."releaseId",r."formatId",r."questionRevisionId",r."questionHash" FROM public."EntaCompetitivePrompt" r WHERE (r."id" IN(SELECT id FROM candidate_prompts)) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveHint child WHERE child."promptId" IS NOT NULL AND child."promptId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveGrapheme child WHERE child."promptId" IS NOT NULL AND child."promptId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash"))),
covered_EntaFormatRevision AS (SELECT r."id",r."opaqueRef",r."categoryKey",r."sourceNamespace",r."sourceId",r."releaseId",r."questionRevisionId",r."questionHash" FROM public."EntaFormatRevision" r WHERE (r."id" IN(SELECT id FROM candidate_formats)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatItem child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitivePrompt child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash"))),
covered_EntaFormatCover AS (SELECT r."releaseId",r."categoryKey",r."proofId" FROM public."EntaFormatCover" r WHERE (r."releaseId" IN(SELECT format_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted))),
covered_EntaCompetitiveRelease AS (SELECT r."id",r."formatReleaseId",r."formatRoot",r."mediaRoot" FROM public."EntaCompetitiveRelease" r WHERE (r."id" IN(SELECT competitive_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitivePrompt child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id"))),
covered_EntaFormatRelease AS (SELECT r."id",r."baseReleaseId",r."receiptId",r."baseRoot",r."formatRoot",r."mediaRoot" FROM public."EntaFormatRelease" r WHERE (r."id" IN(SELECT format_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRevision child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatCover child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveRelease child WHERE child."formatReleaseId" IS NOT NULL AND child."formatReleaseId"=r."id" AND child."formatRoot" IS NOT NULL AND child."formatRoot"=r."formatRoot" AND child."mediaRoot" IS NOT NULL AND child."mediaRoot"=r."mediaRoot"))),
covered_CatalogReleaseQuestion AS (SELECT r."catalogReleaseId",r."questionRevisionId",r."categoryKey",r."sourceNamespace",r."sourceSnapshotHash",r."questionContentHash",r."id" FROM public."CatalogReleaseQuestion" r WHERE (r."catalogReleaseId" IN(SELECT base_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted))),
covered_CatalogReleaseSourceSnapshot AS (SELECT r."catalogReleaseId",r."sourceNamespace",r."snapshotHash",r."id" FROM public."CatalogReleaseSourceSnapshot" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceSnapshotHash" IS NOT NULL AND child."sourceSnapshotHash"=r."snapshotHash"))),
covered_CatalogReleaseCategory AS (SELECT r."catalogReleaseId",r."categoryKey",r."categoryRevisionId",r."categoryContentHash",r."id" FROM public."CatalogReleaseCategory" r WHERE (r."catalogReleaseId" IN(SELECT base_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted)) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."categoryKey"))),
covered_CatalogValidationReceipt AS (SELECT r."id",r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."proofId",r."policyVersion" FROM public."CatalogValidationReceipt" r WHERE (r."id" IN(SELECT receipt_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_ActiveCatalogPointer child WHERE child."validationReceiptId" IS NOT NULL AND child."validationReceiptId"=r."id" AND child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRelease child WHERE child."receiptId" IS NOT NULL AND child."receiptId"=r."id" AND child."baseReleaseId" IS NOT NULL AND child."baseReleaseId"=r."catalogReleaseId" AND child."baseRoot" IS NOT NULL AND child."baseRoot"=r."releaseRootHash"))),
covered_CatalogValidationProof AS (SELECT r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."id",r."policyVersion" FROM public."CatalogValidationProof" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogValidationReceipt child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id" AND child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash" AND child."policyVersion" IS NOT NULL AND child."policyVersion"=r."policyVersion"))),
covered_CatalogReleaseSeal AS (SELECT r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."id" FROM public."CatalogReleaseSeal" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogValidationReceipt child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogValidationProof child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash"))),
covered_CatalogRelease AS (SELECT r."id",r."releaseRootHash" FROM public."CatalogRelease" r WHERE (r."id" IN(SELECT base_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseSourceSnapshot child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseCategory child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_ActiveCatalogPointer child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseSeal child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRelease child WHERE child."baseReleaseId" IS NOT NULL AND child."baseReleaseId"=r."id" AND child."baseRoot" IS NOT NULL AND child."baseRoot"=r."releaseRootHash"))),
covered_CanonicalCategoryRevision AS (SELECT r."id",r."categoryKey",r."sourceNamespace",r."coverMediaRevisionId",r."editorialReceiptId",r."revision",r."contentHash",r."editorialDecision" FROM public."CanonicalCategoryRevision" r WHERE (r."id" IN(SELECT c."categoryRevisionId" FROM public."CatalogReleaseCategory" c,tuple_source t WHERE c."catalogReleaseId"=t.base_id AND c."categoryKey" IN(SELECT key FROM wanted))) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseCategory child WHERE child."categoryRevisionId" IS NOT NULL AND child."categoryRevisionId"=r."id" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."categoryKey" AND child."categoryContentHash" IS NOT NULL AND child."categoryContentHash"=r."contentHash"))),
covered_MediaChunkProof AS (SELECT r."proofId" FROM public."MediaChunkProof" r WHERE (r."proofId" IN(SELECT proof_id FROM candidate_proofs))),
covered_MediaObjectProof AS (SELECT r."id",r."mediaRevisionId",r."mediaHash" FROM public."MediaObjectProof" r WHERE (r."id" IN(SELECT proof_id FROM candidate_proofs)) OR (EXISTS(SELECT 1 FROM covered_MediaChunkProof child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatCover child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id"))),
covered_QuestionRevisionMedia AS (SELECT r."questionRevisionId",r."mediaRevisionId",r."questionContentHash",r."mediaSha256",r."id" FROM public."QuestionRevisionMedia" r WHERE (r."questionRevisionId" IN(SELECT f."questionRevisionId" FROM public."EntaFormatRevision" f WHERE f."id" IN(SELECT id FROM candidate_formats)))),
covered_User AS (SELECT r."id" FROM public."User" r WHERE (EXISTS(SELECT 1 FROM covered_FirebaseIdentity child WHERE child."userId" IS NOT NULL AND child."userId"=r."id"))),
covered_MediaRevision AS (SELECT r."id",r."rightsReceiptId",r."sourceNamespace",r."rightsSubjectType",r."sourceMediaId",r."mediaSha256",r."rightsDecision" FROM public."MediaRevision" r WHERE (EXISTS(SELECT 1 FROM covered_CanonicalCategoryRevision child WHERE child."coverMediaRevisionId" IS NOT NULL AND child."coverMediaRevisionId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionMedia child WHERE child."mediaRevisionId" IS NOT NULL AND child."mediaRevisionId"=r."id" AND child."mediaSha256" IS NOT NULL AND child."mediaSha256"=r."mediaSha256")) OR (EXISTS(SELECT 1 FROM covered_MediaObjectProof child WHERE child."mediaRevisionId" IS NOT NULL AND child."mediaRevisionId"=r."id" AND child."mediaHash" IS NOT NULL AND child."mediaHash"=r."mediaSha256"))),
covered_QuestionAnswerRevision AS (SELECT r."id",r."questionRevisionId",r."questionContentHash",r."contentHash" FROM public."QuestionAnswerRevision" r WHERE (EXISTS(SELECT 1 FROM covered_EntaFormatItem child WHERE child."answerRevisionId" IS NOT NULL AND child."answerRevisionId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionContentHash" AND child."answerHash" IS NOT NULL AND child."answerHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveGrapheme child WHERE child."answerRevisionId" IS NOT NULL AND child."answerRevisionId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionContentHash" AND child."answerHash" IS NOT NULL AND child."answerHash"=r."contentHash"))),
covered_QuestionRevisionSeal AS (SELECT r."questionRevisionId",r."contentHash",r."id" FROM public."QuestionRevisionSeal" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash"))),
covered_QuestionRevision AS (SELECT r."id",r."canonicalCategoryKey",r."crosswalkRevisionId",r."sourceNamespace",r."sourceCategoryId",r."crosswalkRevision",r."editorialReceiptId",r."sourceQuestionId",r."revision",r."contentHash",r."editorialDecision",r."rightsReceiptId",r."rightsSubjectType",r."rightsDecision" FROM public."QuestionRevision" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionAnswerRevision child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionMedia child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."canonicalCategoryKey" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionSeal child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRevision child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceId" IS NOT NULL AND child."sourceId"=r."sourceQuestionId" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."canonicalCategoryKey" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."contentHash"))),
covered_ContentRightsReceipt AS (SELECT r."id",r."sourceNamespace",r."subjectType",r."sourceKey",r."subjectHash",r."decision" FROM public."ContentRightsReceipt" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."rightsReceiptId" IS NOT NULL AND child."rightsReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."rightsSubjectType" IS NOT NULL AND child."rightsSubjectType"=r."subjectType" AND child."sourceQuestionId" IS NOT NULL AND child."sourceQuestionId"=r."sourceKey" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."rightsDecision" IS NOT NULL AND child."rightsDecision"=r."decision")) OR (EXISTS(SELECT 1 FROM covered_MediaRevision child WHERE child."rightsReceiptId" IS NOT NULL AND child."rightsReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."rightsSubjectType" IS NOT NULL AND child."rightsSubjectType"=r."subjectType" AND child."sourceMediaId" IS NOT NULL AND child."sourceMediaId"=r."sourceKey" AND child."mediaSha256" IS NOT NULL AND child."mediaSha256"=r."subjectHash" AND child."rightsDecision" IS NOT NULL AND child."rightsDecision"=r."decision"))),
covered_EditorialReviewReceipt AS (SELECT r."id",r."sourceNamespace",r."sourceKey",r."sourceRevision",r."subjectHash",r."decision" FROM public."EditorialReviewReceipt" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."editorialReceiptId" IS NOT NULL AND child."editorialReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceQuestionId" IS NOT NULL AND child."sourceQuestionId"=r."sourceKey" AND child."revision" IS NOT NULL AND child."revision"=r."sourceRevision" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."editorialDecision" IS NOT NULL AND child."editorialDecision"=r."decision")) OR (EXISTS(SELECT 1 FROM covered_CanonicalCategoryRevision child WHERE child."editorialReceiptId" IS NOT NULL AND child."editorialReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."sourceKey" AND child."revision" IS NOT NULL AND child."revision"=r."sourceRevision" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."editorialDecision" IS NOT NULL AND child."editorialDecision"=r."decision"))),
covered_SourceCategoryCrosswalkRevision AS (SELECT r."id",r."sourceNamespace",r."sourceCategoryId",r."revision",r."canonicalCategoryKey" FROM public."SourceCategoryCrosswalkRevision" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."crosswalkRevisionId" IS NOT NULL AND child."crosswalkRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceCategoryId" IS NOT NULL AND child."sourceCategoryId"=r."sourceCategoryId" AND child."crosswalkRevision" IS NOT NULL AND child."crosswalkRevision"=r."revision" AND child."canonicalCategoryKey" IS NOT NULL AND child."canonicalCategoryKey"=r."canonicalCategoryKey"))) SELECT NOT EXISTS(SELECT 1 FROM tuple_source t WHERE t.base_id IS NOT DISTINCT FROM expected->>'baseReleaseId' AND t.base_root IS NOT DISTINCT FROM expected->>'baseRoot' AND t.receipt_id IS NOT DISTINCT FROM expected->>'receiptId' AND t.format_id IS NOT DISTINCT FROM expected->>'formatReleaseId' AND t.format_root IS NOT DISTINCT FROM expected->>'formatRoot' AND t.media_root IS NOT DISTINCT FROM expected->>'mediaRoot' AND t.competitive_id IS NOT DISTINCT FROM expected->>'competitiveReleaseId' AND t.proof_root IS NOT DISTINCT FROM expected->>'proofRoot' AND t.palette_root IS NOT DISTINCT FROM expected->>'paletteRoot')) THEN PERFORM public.int9_error('FORMAT_CATALOG_UNAVAILABLE'); END IF;
 -- Complete the original direct-private selection/intent prerequisites before
 -- the first bounded tuple export. This moves existing equality obligations;
 -- it adds no fullIntent/text/content cap and trusts no approval flag.
 IF expected IS NOT NULL AND expected ? 'selection' THEN
  IF expected->>'policyVersion' IS DISTINCT FROM 'enta-competitive-1' OR expected->'request' IS DISTINCT FROM request OR expected->'selection' IS DISTINCT FROM public.int9_select_references((SELECT c."id" FROM public."EntaCompetitiveRelease" c JOIN public."EntaFormatRelease" f ON f."id"=c."formatReleaseId" JOIN public."ActiveCatalogPointer" p ON p."catalogReleaseId"=f."baseReleaseId" AND p."releaseRootHash"=f."baseRoot" AND p."validationReceiptId"=f."receiptId" WHERE p."id"='singleton' AND c."id"=expected->>'competitiveReleaseId'),request,expected->>'seed',(SELECT "id" FROM public."FirebaseIdentity" WHERE "firebaseProjectId"=project AND "firebaseUid"=uid)) OR expected->>'poolHash' IS DISTINCT FROM public.int9_pool_root(expected->>'competitiveReleaseId',request) THEN PERFORM public.int9_error('SELECTION_UNAVAILABLE'); END IF;
 END IF;
 RETURN (WITH tuple_source AS (SELECT p."catalogReleaseId" base_id,p."releaseRootHash" base_root,p."validationReceiptId" receipt_id,f."id" format_id,f."formatRoot" format_root,f."mediaRoot" media_root,c."id" competitive_id,c."proofRoot" proof_root,c."paletteRoot" palette_root FROM public."ActiveCatalogPointer" p JOIN public."EntaFormatRelease" f ON f."baseReleaseId"=p."catalogReleaseId" AND f."baseRoot"=p."releaseRootHash" AND f."receiptId"=p."validationReceiptId" AND f."sealedAt" IS NOT NULL AND f."policyVersion"='enta-format-1' JOIN public."EntaCompetitiveRelease" c ON c."formatReleaseId"=f."id" AND c."formatRoot"=f."formatRoot" AND c."mediaRoot"=f."mediaRoot" AND c."rulesVersion"='enta-competitive-1' AND c."paletteRoot"=public.int9_palette_root() AND c."sealedAt" IS NOT NULL WHERE p."id"='singleton'),
wanted AS (SELECT value->>'key' key FROM jsonb_array_elements(request->'setup'->'categories')),
candidate_formats AS (SELECT f."id" id FROM public."EntaFormatRevision" f,tuple_source t WHERE f."categoryKey" IN(SELECT key FROM wanted) AND (f."releaseId"=t.format_id OR EXISTS(SELECT 1 FROM public."EntaCompetitivePrompt" p WHERE p."releaseId"=t.competitive_id AND p."formatId"=f."id"))),
candidate_prompts AS (SELECT p."id" id FROM public."EntaCompetitivePrompt" p,tuple_source t WHERE p."releaseId"=t.competitive_id AND (p."formatId" IN(SELECT id FROM candidate_formats) OR NOT EXISTS(SELECT 1 FROM public."EntaFormatRevision" f WHERE f."id"=p."formatId"))),
candidate_proofs AS (SELECT m."proofId" proof_id FROM public."EntaFormatMedia" m WHERE m."formatId" IN(SELECT id FROM candidate_formats) UNION SELECT c."proofId" FROM public."EntaFormatCover" c,tuple_source t WHERE c."releaseId"=t.format_id AND c."categoryKey" IN(SELECT key FROM wanted)),
covered_DeploymentNamespace AS (SELECT r."id",r."namespaceId",r."firebaseProjectId" FROM public."DeploymentNamespace" r WHERE (r."id"='singleton')),
covered_Wallet AS (SELECT r."id",r."firebaseIdentityId" FROM public."Wallet" r WHERE (EXISTS(SELECT 1 FROM public."FirebaseIdentity" i WHERE i."id"=r."firebaseIdentityId" AND i."firebaseProjectId"=project AND i."firebaseUid"=uid))),
covered_FirebaseIdentity AS (SELECT r."id",r."firebaseProjectId",r."firebaseUid",r."userId" FROM public."FirebaseIdentity" r WHERE (r."firebaseProjectId"=project AND r."firebaseUid"=uid) OR (EXISTS(SELECT 1 FROM covered_Wallet child WHERE child."firebaseIdentityId" IS NOT NULL AND child."firebaseIdentityId"=r."id"))),
covered_ActiveCatalogPointer AS (SELECT r."catalogReleaseId",r."validationReceiptId",r."releaseRootHash",r."id" FROM public."ActiveCatalogPointer" r WHERE (r."id"='singleton')),
covered_EntaFormatMedia AS (SELECT r."formatId",r."questionRevisionId",r."itemId",r."proofId",r."questionHash",r."id" FROM public."EntaFormatMedia" r WHERE (r."formatId" IN(SELECT id FROM candidate_formats))),
covered_EntaFormatItem AS (SELECT r."id",r."formatId",r."questionRevisionId",r."answerRevisionId",r."questionHash",r."answerHash" FROM public."EntaFormatItem" r WHERE (r."formatId" IN(SELECT id FROM candidate_formats)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."formatId" AND child."itemId" IS NOT NULL AND child."itemId"=r."id"))),
covered_EntaCompetitiveHint AS (SELECT r."id",r."promptId",r."questionRevisionId",r."questionHash" FROM public."EntaCompetitiveHint" r WHERE (r."promptId" IN(SELECT id FROM candidate_prompts))),
covered_EntaCompetitiveGrapheme AS (SELECT r."id",r."promptId",r."questionRevisionId",r."answerRevisionId",r."questionHash",r."answerHash" FROM public."EntaCompetitiveGrapheme" r WHERE (r."promptId" IN(SELECT id FROM candidate_prompts))),
covered_EntaCompetitivePrompt AS (SELECT r."id",r."releaseId",r."formatId",r."questionRevisionId",r."questionHash" FROM public."EntaCompetitivePrompt" r WHERE (r."id" IN(SELECT id FROM candidate_prompts)) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveHint child WHERE child."promptId" IS NOT NULL AND child."promptId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveGrapheme child WHERE child."promptId" IS NOT NULL AND child."promptId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash"))),
covered_EntaFormatRevision AS (SELECT r."id",r."opaqueRef",r."categoryKey",r."sourceNamespace",r."sourceId",r."releaseId",r."questionRevisionId",r."questionHash" FROM public."EntaFormatRevision" r WHERE (r."id" IN(SELECT id FROM candidate_formats)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatItem child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitivePrompt child WHERE child."formatId" IS NOT NULL AND child."formatId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionHash"))),
covered_EntaFormatCover AS (SELECT r."releaseId",r."categoryKey",r."proofId" FROM public."EntaFormatCover" r WHERE (r."releaseId" IN(SELECT format_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted))),
covered_EntaCompetitiveRelease AS (SELECT r."id",r."formatReleaseId",r."formatRoot",r."mediaRoot" FROM public."EntaCompetitiveRelease" r WHERE (r."id" IN(SELECT competitive_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitivePrompt child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id"))),
covered_EntaFormatRelease AS (SELECT r."id",r."baseReleaseId",r."receiptId",r."baseRoot",r."formatRoot",r."mediaRoot" FROM public."EntaFormatRelease" r WHERE (r."id" IN(SELECT format_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRevision child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatCover child WHERE child."releaseId" IS NOT NULL AND child."releaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveRelease child WHERE child."formatReleaseId" IS NOT NULL AND child."formatReleaseId"=r."id" AND child."formatRoot" IS NOT NULL AND child."formatRoot"=r."formatRoot" AND child."mediaRoot" IS NOT NULL AND child."mediaRoot"=r."mediaRoot"))),
covered_CatalogReleaseQuestion AS (SELECT r."catalogReleaseId",r."questionRevisionId",r."categoryKey",r."sourceNamespace",r."sourceSnapshotHash",r."questionContentHash",r."id" FROM public."CatalogReleaseQuestion" r WHERE (r."catalogReleaseId" IN(SELECT base_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted))),
covered_CatalogReleaseSourceSnapshot AS (SELECT r."catalogReleaseId",r."sourceNamespace",r."snapshotHash",r."id" FROM public."CatalogReleaseSourceSnapshot" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceSnapshotHash" IS NOT NULL AND child."sourceSnapshotHash"=r."snapshotHash"))),
covered_CatalogReleaseCategory AS (SELECT r."catalogReleaseId",r."categoryKey",r."categoryRevisionId",r."categoryContentHash",r."id" FROM public."CatalogReleaseCategory" r WHERE (r."catalogReleaseId" IN(SELECT base_id FROM tuple_source) AND r."categoryKey" IN(SELECT key FROM wanted)) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."categoryKey"))),
covered_CatalogValidationReceipt AS (SELECT r."id",r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."proofId",r."policyVersion" FROM public."CatalogValidationReceipt" r WHERE (r."id" IN(SELECT receipt_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_ActiveCatalogPointer child WHERE child."validationReceiptId" IS NOT NULL AND child."validationReceiptId"=r."id" AND child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRelease child WHERE child."receiptId" IS NOT NULL AND child."receiptId"=r."id" AND child."baseReleaseId" IS NOT NULL AND child."baseReleaseId"=r."catalogReleaseId" AND child."baseRoot" IS NOT NULL AND child."baseRoot"=r."releaseRootHash"))),
covered_CatalogValidationProof AS (SELECT r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."id",r."policyVersion" FROM public."CatalogValidationProof" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogValidationReceipt child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id" AND child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash" AND child."policyVersion" IS NOT NULL AND child."policyVersion"=r."policyVersion"))),
covered_CatalogReleaseSeal AS (SELECT r."catalogReleaseId",r."releaseRootHash",r."sealHash",r."id" FROM public."CatalogReleaseSeal" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogValidationReceipt child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogValidationProof child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."catalogReleaseId" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash" AND child."sealHash" IS NOT NULL AND child."sealHash"=r."sealHash"))),
covered_CatalogRelease AS (SELECT r."id",r."releaseRootHash" FROM public."CatalogRelease" r WHERE (r."id" IN(SELECT base_id FROM tuple_source)) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseSourceSnapshot child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseCategory child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_ActiveCatalogPointer child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseSeal child WHERE child."catalogReleaseId" IS NOT NULL AND child."catalogReleaseId"=r."id" AND child."releaseRootHash" IS NOT NULL AND child."releaseRootHash"=r."releaseRootHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRelease child WHERE child."baseReleaseId" IS NOT NULL AND child."baseReleaseId"=r."id" AND child."baseRoot" IS NOT NULL AND child."baseRoot"=r."releaseRootHash"))),
covered_CanonicalCategoryRevision AS (SELECT r."id",r."categoryKey",r."sourceNamespace",r."coverMediaRevisionId",r."editorialReceiptId",r."revision",r."contentHash",r."editorialDecision" FROM public."CanonicalCategoryRevision" r WHERE (r."id" IN(SELECT c."categoryRevisionId" FROM public."CatalogReleaseCategory" c,tuple_source t WHERE c."catalogReleaseId"=t.base_id AND c."categoryKey" IN(SELECT key FROM wanted))) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseCategory child WHERE child."categoryRevisionId" IS NOT NULL AND child."categoryRevisionId"=r."id" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."categoryKey" AND child."categoryContentHash" IS NOT NULL AND child."categoryContentHash"=r."contentHash"))),
covered_MediaChunkProof AS (SELECT r."proofId" FROM public."MediaChunkProof" r WHERE (r."proofId" IN(SELECT proof_id FROM candidate_proofs))),
covered_MediaObjectProof AS (SELECT r."id",r."mediaRevisionId",r."mediaHash" FROM public."MediaObjectProof" r WHERE (r."id" IN(SELECT proof_id FROM candidate_proofs)) OR (EXISTS(SELECT 1 FROM covered_MediaChunkProof child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatMedia child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatCover child WHERE child."proofId" IS NOT NULL AND child."proofId"=r."id"))),
covered_QuestionRevisionMedia AS (SELECT r."questionRevisionId",r."mediaRevisionId",r."questionContentHash",r."mediaSha256",r."id" FROM public."QuestionRevisionMedia" r WHERE (r."questionRevisionId" IN(SELECT f."questionRevisionId" FROM public."EntaFormatRevision" f WHERE f."id" IN(SELECT id FROM candidate_formats)))),
covered_User AS (SELECT r."id" FROM public."User" r WHERE (EXISTS(SELECT 1 FROM covered_FirebaseIdentity child WHERE child."userId" IS NOT NULL AND child."userId"=r."id"))),
covered_MediaRevision AS (SELECT r."id",r."rightsReceiptId",r."sourceNamespace",r."rightsSubjectType",r."sourceMediaId",r."mediaSha256",r."rightsDecision" FROM public."MediaRevision" r WHERE (EXISTS(SELECT 1 FROM covered_CanonicalCategoryRevision child WHERE child."coverMediaRevisionId" IS NOT NULL AND child."coverMediaRevisionId"=r."id")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionMedia child WHERE child."mediaRevisionId" IS NOT NULL AND child."mediaRevisionId"=r."id" AND child."mediaSha256" IS NOT NULL AND child."mediaSha256"=r."mediaSha256")) OR (EXISTS(SELECT 1 FROM covered_MediaObjectProof child WHERE child."mediaRevisionId" IS NOT NULL AND child."mediaRevisionId"=r."id" AND child."mediaHash" IS NOT NULL AND child."mediaHash"=r."mediaSha256"))),
covered_QuestionAnswerRevision AS (SELECT r."id",r."questionRevisionId",r."questionContentHash",r."contentHash" FROM public."QuestionAnswerRevision" r WHERE (EXISTS(SELECT 1 FROM covered_EntaFormatItem child WHERE child."answerRevisionId" IS NOT NULL AND child."answerRevisionId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionContentHash" AND child."answerHash" IS NOT NULL AND child."answerHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_EntaCompetitiveGrapheme child WHERE child."answerRevisionId" IS NOT NULL AND child."answerRevisionId"=r."id" AND child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."questionContentHash" AND child."answerHash" IS NOT NULL AND child."answerHash"=r."contentHash"))),
covered_QuestionRevisionSeal AS (SELECT r."questionRevisionId",r."contentHash",r."id" FROM public."QuestionRevisionSeal" r WHERE (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."questionRevisionId" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash"))),
covered_QuestionRevision AS (SELECT r."id",r."canonicalCategoryKey",r."crosswalkRevisionId",r."sourceNamespace",r."sourceCategoryId",r."crosswalkRevision",r."editorialReceiptId",r."sourceQuestionId",r."revision",r."contentHash",r."editorialDecision",r."rightsReceiptId",r."rightsSubjectType",r."rightsDecision" FROM public."QuestionRevision" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionAnswerRevision child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionMedia child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_CatalogReleaseQuestion child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."canonicalCategoryKey" AND child."questionContentHash" IS NOT NULL AND child."questionContentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_QuestionRevisionSeal child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."contentHash")) OR (EXISTS(SELECT 1 FROM covered_EntaFormatRevision child WHERE child."questionRevisionId" IS NOT NULL AND child."questionRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceId" IS NOT NULL AND child."sourceId"=r."sourceQuestionId" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."canonicalCategoryKey" AND child."questionHash" IS NOT NULL AND child."questionHash"=r."contentHash"))),
covered_ContentRightsReceipt AS (SELECT r."id",r."sourceNamespace",r."subjectType",r."sourceKey",r."subjectHash",r."decision" FROM public."ContentRightsReceipt" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."rightsReceiptId" IS NOT NULL AND child."rightsReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."rightsSubjectType" IS NOT NULL AND child."rightsSubjectType"=r."subjectType" AND child."sourceQuestionId" IS NOT NULL AND child."sourceQuestionId"=r."sourceKey" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."rightsDecision" IS NOT NULL AND child."rightsDecision"=r."decision")) OR (EXISTS(SELECT 1 FROM covered_MediaRevision child WHERE child."rightsReceiptId" IS NOT NULL AND child."rightsReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."rightsSubjectType" IS NOT NULL AND child."rightsSubjectType"=r."subjectType" AND child."sourceMediaId" IS NOT NULL AND child."sourceMediaId"=r."sourceKey" AND child."mediaSha256" IS NOT NULL AND child."mediaSha256"=r."subjectHash" AND child."rightsDecision" IS NOT NULL AND child."rightsDecision"=r."decision"))),
covered_EditorialReviewReceipt AS (SELECT r."id",r."sourceNamespace",r."sourceKey",r."sourceRevision",r."subjectHash",r."decision" FROM public."EditorialReviewReceipt" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."editorialReceiptId" IS NOT NULL AND child."editorialReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceQuestionId" IS NOT NULL AND child."sourceQuestionId"=r."sourceKey" AND child."revision" IS NOT NULL AND child."revision"=r."sourceRevision" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."editorialDecision" IS NOT NULL AND child."editorialDecision"=r."decision")) OR (EXISTS(SELECT 1 FROM covered_CanonicalCategoryRevision child WHERE child."editorialReceiptId" IS NOT NULL AND child."editorialReceiptId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."categoryKey" IS NOT NULL AND child."categoryKey"=r."sourceKey" AND child."revision" IS NOT NULL AND child."revision"=r."sourceRevision" AND child."contentHash" IS NOT NULL AND child."contentHash"=r."subjectHash" AND child."editorialDecision" IS NOT NULL AND child."editorialDecision"=r."decision"))),
covered_SourceCategoryCrosswalkRevision AS (SELECT r."id",r."sourceNamespace",r."sourceCategoryId",r."revision",r."canonicalCategoryKey" FROM public."SourceCategoryCrosswalkRevision" r WHERE (EXISTS(SELECT 1 FROM covered_QuestionRevision child WHERE child."crosswalkRevisionId" IS NOT NULL AND child."crosswalkRevisionId"=r."id" AND child."sourceNamespace" IS NOT NULL AND child."sourceNamespace"=r."sourceNamespace" AND child."sourceCategoryId" IS NOT NULL AND child."sourceCategoryId"=r."sourceCategoryId" AND child."crosswalkRevision" IS NOT NULL AND child."crosswalkRevision"=r."revision" AND child."canonicalCategoryKey" IS NOT NULL AND child."canonicalCategoryKey"=r."canonicalCategoryKey"))) SELECT jsonb_build_object('profile','CAP-C4-OCT16-R8','baseReleaseId',t.base_id,'baseRoot',t.base_root,'receiptId',t.receipt_id,'formatReleaseId',t.format_id,'formatRoot',t.format_root,'mediaRoot',t.media_root,'competitiveReleaseId',t.competitive_id,'proofRoot',t.proof_root,'paletteRoot',t.palette_root) FROM tuple_source t);
END $$;
REVOKE ALL ON FUNCTION public.int9_c4_f11_capture(TEXT,TEXT,TEXT,JSONB,JSONB) FROM PUBLIC,enta_runtime,enta_gameplay_runtime;
ALTER FUNCTION public.int9_c4_f11_capture(TEXT,TEXT,TEXT,JSONB,JSONB) OWNER TO enta_finance_executor;

-- INERT CAP-C4 SOURCE PROPOSAL. NOT INSTALLED OR SQL-PARSED/COMPILED.
-- Measurement is the explicit preprofile boundary; arbitrary invalid source
-- inputs/native residency are not covered by the encoded 4194304 worksheet.
-- Schema/reader-permitted publication model only; existing policy denials stay.
CREATE FUNCTION public.int9_c4_catalog_at(ns TEXT,project TEXT,uid TEXT,request JSONB,captured JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE execution_format TEXT:=request->>'executionFormat'; selected_keys JSONB:=(SELECT jsonb_agg(value->'key' ORDER BY ordinal) FROM jsonb_array_elements(request->'setup'->'categories') WITH ORDINALITY wanted(value,ordinal)); identity_id TEXT; pointer public."ActiveCatalogPointer"%ROWTYPE; f public."EntaFormatRelease"%ROWTYPE; competitive public."EntaCompetitiveRelease"%ROWTYPE; categories JSONB; material JSONB; BEGIN
 -- Caller completed the full relational precheck; revalidate only the exact physical tuple below.
 identity_id:=public.int6_enta_identity(ns,project,uid)->>'id'; IF execution_format NOT IN ('TIER_BOARD','MIXED_BOARD','STANDALONE_LIST','STANDALONE_ACTING') OR selected_keys IS NOT NULL AND (jsonb_typeof(selected_keys) IS DISTINCT FROM 'array' OR jsonb_array_length(selected_keys) NOT BETWEEN 1 AND 6) THEN PERFORM public.int9_error('INVALID_REQUEST'); END IF;
 SELECT "catalogReleaseId","id","releaseRootHash","validationReceiptId" INTO pointer."catalogReleaseId",pointer."id",pointer."releaseRootHash",pointer."validationReceiptId" FROM public."ActiveCatalogPointer" WHERE "id"='singleton' AND "catalogReleaseId"=captured->>'baseReleaseId' AND "releaseRootHash"=captured->>'baseRoot' AND "validationReceiptId"=captured->>'receiptId' FOR SHARE;
 SELECT "baseReleaseId","baseRoot","formatRoot","id","mediaRoot","policyVersion","receiptId" INTO f."baseReleaseId",f."baseRoot",f."formatRoot",f."id",f."mediaRoot",f."policyVersion",f."receiptId" FROM public."EntaFormatRelease" WHERE "id"=captured->>'formatReleaseId' AND "baseReleaseId"=pointer."catalogReleaseId" AND "baseRoot"=pointer."releaseRootHash" AND "receiptId"=pointer."validationReceiptId" AND "sealedAt" IS NOT NULL AND "policyVersion"='enta-format-1';
 SELECT "id","paletteRoot","proofRoot" INTO competitive."id",competitive."paletteRoot",competitive."proofRoot" FROM public."EntaCompetitiveRelease" WHERE "id"=captured->>'competitiveReleaseId' AND "formatReleaseId"=f."id" AND "formatRoot"=f."formatRoot" AND "mediaRoot"=f."mediaRoot" AND "rulesVersion"='enta-competitive-1' AND "paletteRoot"=public.int9_palette_root() AND "sealedAt" IS NOT NULL;
 IF pointer."id" IS NULL OR f."id" IS NULL OR competitive."id" IS NULL OR (SELECT count(*) FROM public."EntaCompetitiveRelease" WHERE "formatReleaseId"=f."id" AND "sealedAt" IS NOT NULL)<>1 THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(jsonb_build_array(f."baseReleaseId",f."receiptId",f."id",competitive."id")) value WHERE octet_length(convert_to(value,'UTF8')) NOT BETWEEN 1 AND 1024) THEN PERFORM public.int9_error('COMPETITIVE_PROOF_UNAVAILABLE'); END IF;
 IF (pointer."catalogReleaseId",pointer."releaseRootHash",pointer."validationReceiptId",f."id",f."formatRoot",f."mediaRoot",competitive."id",competitive."proofRoot",competitive."paletteRoot") IS DISTINCT FROM (captured->>'baseReleaseId',captured->>'baseRoot',captured->>'receiptId',captured->>'formatReleaseId',captured->>'formatRoot',captured->>'mediaRoot',captured->>'competitiveReleaseId',captured->>'proofRoot',captured->>'paletteRoot') THEN PERFORM public.int9_error('FORMAT_CATALOG_UNAVAILABLE'); END IF;
 -- These named authority denials are retained. Sealed metadata never supplies
 -- a missing approved receipt, issuer, authoring or tournament authority.
 PERFORM public.int9_assert_competitive(competitive."id"); PERFORM public.int6_enta_assert_receipt(f."receiptId",f."baseReleaseId",f."baseRoot");
 SELECT COALESCE(jsonb_agg(jsonb_build_object('key',category."categoryKey",'label',left(revision."labelAr",64),'format',family."format",'cover',(SELECT public.int9_media_descriptor(cover."proofId",'COVER',NULL) FROM public."EntaFormatCover" cover WHERE cover."releaseId"=f."id" AND cover."categoryKey"=category."categoryKey")) ORDER BY category."categoryKey" COLLATE "C"),'[]'::JSONB) INTO categories FROM public."CatalogReleaseCategory" category JOIN public."CanonicalCategoryRevision" revision ON revision."id"=category."categoryRevisionId" JOIN LATERAL (SELECT min("format") AS "format" FROM public."EntaFormatRevision" WHERE "releaseId"=f."id" AND "categoryKey"=category."categoryKey") family ON family."format" IS NOT NULL WHERE category."catalogReleaseId"=f."baseReleaseId" AND (selected_keys IS NULL OR selected_keys @> jsonb_build_array(category."categoryKey")) AND (execution_format='MIXED_BOARD' OR family."format"=(CASE execution_format WHEN 'TIER_BOARD' THEN 'ORDINARY_TIER' WHEN 'STANDALONE_LIST' THEN 'LIST_ITEMS' ELSE 'ACTING_ITEMS' END));
 IF selected_keys IS NULL OR jsonb_array_length(categories)<>jsonb_array_length(selected_keys) THEN PERFORM public.int9_error('CATEGORY_UNAVAILABLE'); END IF;
 material:=jsonb_build_object('base',jsonb_build_object('baseReleaseId',f."baseReleaseId",'baseRoot',f."baseRoot",'receiptId',f."receiptId",'formatReleaseId',f."id",'formatRoot',f."formatRoot",'mediaRoot',f."mediaRoot",'policyVersion',f."policyVersion",'categories',categories),'policyVersion','enta-competitive-1','competitiveReleaseId',competitive."id",'proofRoot',competitive."proofRoot",'paletteRoot',competitive."paletteRoot");
 IF octet_length(convert_to(public.int6_enta_canonical(material),'UTF8'))>65536 THEN PERFORM public.int9_error('CATALOG_BOUND_EXCEEDED'); END IF; RETURN material;
END $$;
REVOKE ALL ON FUNCTION public.int9_c4_catalog_at(TEXT,TEXT,TEXT,JSONB,JSONB) FROM PUBLIC,enta_runtime,enta_gameplay_runtime;
ALTER FUNCTION public.int9_c4_catalog_at(TEXT,TEXT,TEXT,JSONB,JSONB) OWNER TO enta_finance_executor;

-- INERT C4 effective-ACL successor; install only after C5 exact composite review.
-- INERT least-column read proposal for exact F11 integrity/width/old-predicate queries.
-- Existing PUBLIC/runtime roles receive no new EXECUTE, SELECT or write privilege.
-- Column read grants require exact Database/Security preedit review under C5;
-- installed effective grants/memberships/defaults remain unverified under R6.
