GRANT SELECT ("answerHash","answerRevisionId","formatId","id","ordinal","questionHash","questionRevisionId","trap") ON public."EntaFormatItem" TO enta_finance_executor;
GRANT SELECT ("id","ordinal","promptId","questionHash","questionRevisionId","text") ON public."EntaCompetitiveHint" TO enta_finance_executor;
GRANT SELECT ("answerHash","answerRevisionId","grapheme","id","promptId","questionHash","questionRevisionId","segmentationVersion") ON public."EntaCompetitiveGrapheme" TO enta_finance_executor;
GRANT SELECT ("formatId","id","questionHash","questionRevisionId","releaseId") ON public."EntaCompetitivePrompt" TO enta_finance_executor;
