GRANT SELECT ("formatReleaseId","formatRoot","id","mediaRoot","paletteRoot","proofRoot","rulesVersion","sealedAt") ON public."EntaCompetitiveRelease" TO enta_finance_executor;
GRANT SELECT ("baseReleaseId","baseRoot","formatRoot","id","mediaRoot","policyVersion","receiptId","sealedAt") ON public."EntaFormatRelease" TO enta_finance_executor;
GRANT SELECT ("catalogReleaseId","categoryKey","id","questionContentHash","questionRevisionId","sourceNamespace","sourceSnapshotHash") ON public."CatalogReleaseQuestion" TO enta_finance_executor;
GRANT SELECT ("catalogReleaseId","id","snapshotHash","sourceNamespace") ON public."CatalogReleaseSourceSnapshot" TO enta_finance_executor;
GRANT SELECT ("catalogReleaseId","categoryContentHash","categoryKey","categoryRevisionId","id") ON public."CatalogReleaseCategory" TO enta_finance_executor;
GRANT SELECT ("catalogReleaseId","id","policyVersion","proofId","releaseRootHash","sealHash") ON public."CatalogValidationReceipt" TO enta_finance_executor;
GRANT SELECT ("catalogReleaseId","id","policyVersion","releaseRootHash","sealHash") ON public."CatalogValidationProof" TO enta_finance_executor;
GRANT SELECT ("catalogReleaseId","id","releaseRootHash","sealHash") ON public."CatalogReleaseSeal" TO enta_finance_executor;
GRANT SELECT ("id","releaseRootHash") ON public."CatalogRelease" TO enta_finance_executor;
GRANT SELECT ("categoryKey","contentHash","coverMediaRevisionId","editorialDecision","editorialReceiptId","id","labelAr","revision","sourceNamespace") ON public."CanonicalCategoryRevision" TO enta_finance_executor;
GRANT SELECT ("byteLength","ordinal","proofId") ON public."MediaChunkProof" TO enta_finance_executor;
GRANT SELECT ("byteLength","codec","durationMs","height","id","mediaHash","mediaRevisionId","objectVersion","sealedAt","width") ON public."MediaObjectProof" TO enta_finance_executor;
GRANT SELECT ("id","mediaRevisionId","mediaSha256","questionContentHash","questionRevisionId") ON public."QuestionRevisionMedia" TO enta_finance_executor;
GRANT SELECT ("id") ON public."User" TO enta_finance_executor;
GRANT SELECT ("byteLength","id","mediaSha256","mimeType","objectKey","rightsDecision","rightsReceiptId","rightsSubjectType","sourceMediaId","sourceNamespace") ON public."MediaRevision" TO enta_finance_executor;
GRANT SELECT ("contentHash","id","questionContentHash","questionRevisionId","text") ON public."QuestionAnswerRevision" TO enta_finance_executor;
GRANT SELECT ("contentHash","id","questionRevisionId") ON public."QuestionRevisionSeal" TO enta_finance_executor;
GRANT SELECT ("canonicalCategoryKey","contentHash","crosswalkRevision","crosswalkRevisionId","editorialDecision","editorialReceiptId","id","points","prompt","revision","rightsDecision","rightsReceiptId","rightsSubjectType","sourceCategoryId","sourceNamespace","sourceQuestionId") ON public."QuestionRevision" TO enta_finance_executor;
GRANT SELECT ("decision","id","sourceKey","sourceNamespace","subjectHash","subjectType") ON public."ContentRightsReceipt" TO enta_finance_executor;
GRANT SELECT ("decision","id","sourceKey","sourceNamespace","sourceRevision","subjectHash") ON public."EditorialReviewReceipt" TO enta_finance_executor;
GRANT SELECT ("canonicalCategoryKey","id","revision","sourceCategoryId","sourceNamespace") ON public."SourceCategoryCrosswalkRevision" TO enta_finance_executor;
REVOKE ALL ON FUNCTION public.int9_c4_f11_capture(TEXT,TEXT,TEXT,JSONB,JSONB),public.int9_c4_catalog_at(TEXT,TEXT,TEXT,JSONB,JSONB) FROM PUBLIC,enta_runtime,enta_gameplay_runtime;

