log_at(TEXT,TEXT,TEXT,JSONB,JSONB)']::TEXT[]) signature;
 -- Conservative MEMBER ancestors cover inherited and transitive SET paths, including NOINHERIT.
 FOR runtime_role IN WITH RECURSIVE descendants(id) AS (SELECT oid FROM pg_roles WHERE rolname IN ('enta_runtime','enta_gameplay_runtime') UNION SELECT m.member FROM pg_auth_members m JOIN descendants d ON d.id=m.roleid), reachable(id) AS (SELECT id FROM descendants UNION SELECT m.roleid FROM pg_auth_members m JOIN reachable r ON m.member=r.id) SELECT id FROM reachable LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE oid=runtime_role AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolreplication OR rolbypassrls)) OR pg_has_role(runtime_role,'enta_finance_executor','MEMBER') OR has_schema_privilege(runtime_role,'public','CREATE') THEN RAISE EXCEPTION 'INT9_RUNTIME_ACL_DENIED'; END IF;
  SELECT COALESCE(array_agg(signature::regprocedure::OID),ARRAY[]::OID[]) INTO legacy_allowed FROM (VALUES ('public.int6_enta_identity(TEXT,TEXT,TEXT)',ARRAY['enta_gameplay_runtime']::TEXT[]), ('public.int7_enta_history(TEXT,TEXT,TEXT,JSONB)',ARRAY['enta_gameplay_runtime']::TEXT[])) entries(signature,roles) WHERE EXISTS(SELECT 1 FROM unnest(roles) role_name WHERE pg_has_role(runtime_role,role_name,'MEMBER'));
  FOREACH fn IN ARRAY audited LOOP
   IF (SELECT proowner=runtime_role FROM pg_proc WHERE oid=fn) OR has_function_privilege(runtime_role,fn,'EXECUTE') AND NOT (fn=ANY(allowed) AND pg_has_role(runtime_role,'enta_gameplay_runtime','MEMBER') OR fn=ANY(legacy_allowed) AND NOT fn=ANY(created)) THEN RAISE EXCEPTION 'INT9_FUNCTION_ACL_DENIED'; END IF;
  END LOOP;
  FOREACH table_name IN ARRAY ARRAY['public."ActiveCatalogPointer"','public."Admission"','public."AdmissionEvent"','public."CanonicalCategoryRevision"','public."CatalogRelease"','public."CatalogReleaseAvailability"','public."CatalogReleaseCategory"','public."CatalogReleaseQuestion"','public."CatalogReleaseSeal"','public."CatalogReleaseSourceSnapshot"','public."CatalogValidationProof"','public."CatalogValidationReceipt"','public."CompetitiveAllowance"','public."CompetitiveAssignmentPlayer"','public."CompetitiveAttempt"','public."CompetitiveAuditReport"','public."CompetitiveCapacityCharge"','public."CompetitiveCapacityClaim"','public."CompetitiveCapacityDisposition"','public."CompetitiveCapacityHead"','public."CompetitiveClassification"','public."CompetitiveConsumption"','public."CompetitiveDependency"','public."CompetitiveEffect"','public."CompetitiveEffectAttempt"','public."CompetitiveItemConsumption"','public."CompetitiveItemResolution"','public."CompetitiveItemReview"','public."CompetitiveReversal"','public."CompetitiveRosterPlayer"','public."CompetitiveRoundPin"','public."CompetitiveRulingHead"','public."CompetitiveRuntimeHead"','public."CompetitiveScorePosting"','public."CompetitiveScoreRead"','public."CompetitiveTargetDisclosure"','public."ContentRightsReceipt"','public."DeploymentNamespace"','public."DrawingCanvasState"','public."EditorialReviewReceipt"','public."EngineMatchResult"','public."EngineMatchResultHead"','public."EngineMatchResultSignal"','public."EngineTournamentBindingSnapshot"','public."EntaCompetitiveGrapheme"','public."EntaCompetitiveHint"','public."EntaCompetitivePrompt"','public."EntaCompetitiveRelease"','public."EntaExecutionPin"','public."EntaFormatCover"','public."EntaFormatItem"','public."EntaFormatMedia"','public."EntaFormatRelease"','public."EntaFormatRevision"','public."EntaRematchLink"','public."EntaSourceExposure"','public."FirebaseIdentity"','public."Game"','public."GameCategory"','public."GameCategoryPin"','public."GameCompetitivePin"','public."GameEvent"','public."GameQuestion"','public."GameRound"','public."GameRuntime"','public."MediaChunkProof"','public."MediaObjectProof"','public."MediaRevision"','public."Player"','public."QuestionAnswerRevision"','public."QuestionRevision"','public."QuestionRevisionMedia"','public."QuestionRevisionSeal"','public."Reservation"','public."RoundActorAssignment"','public."RoundAuthorityEvent"','public."RoundGrant"','public."RoundGrantScope"','public."RoundItemPin"','public."RoundScorePosting"','public."SourceCategoryCrosswalkRevision"','public."Team"','public."User"','public."Wallet"','public."WalletEntry"']::TEXT[] LOOP
   relation:=table_name::regclass::OID;
   IF (SELECT relowner=runtime_role FROM pg_class WHERE oid=relation) OR has_table_privilege(runtime_role,relation,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege(runtime_role,relation,'INSERT,UPDATE,REFERENCES') OR NOT table_name=ANY(ARRAY['public."SourceCategoryCrosswalkRevision"','public."CanonicalCategoryRevision"','public."EditorialReviewReceipt"','public."ContentRightsReceipt"','public."QuestionRevision"','public."QuestionAnswerRevision"','public."MediaRevision"','public."QuestionRevisionMedia"','public."CatalogRelease"','public."CatalogReleaseSourceSnapshot"','public."CatalogReleaseCategory"','public."CatalogReleaseQuestion"','public."CatalogReleaseAvailability"','public."QuestionRevisionSeal"','public."CatalogReleaseSeal"','public."CatalogValidationReceipt"','public."CatalogActivationEvent"','public."ActiveCatalogPointer"']::TEXT[]) AND (has_table_privilege(runtime_role,relation,'SELECT') OR has_any_column_privilege(runtime_role,relation,'SELECT')) THEN RAISE EXCEPTION 'INT9_TABLE_ACL_DENIED'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) a WHERE d.defaclobjtype='f' AND d.defaclnamespace IN (0,'public'::regnamespace::OID) AND a.privilege_type='EXECUTE' AND (CASE WHEN a.grantee=0 THEN TRUE ELSE a.grantee=runtime_role OR pg_has_role(runtime_role,a.grantee,'MEMBER') END)) THEN RAISE EXCEPTION 'INT9_DEFAULT_FUNCTION_ACL_DENIED'; END IF;
  IF EXISTS(SELECT 1 FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) a WHERE d.defaclobjtype='r' AND d.defaclnamespace IN (0,'public'::regnamespace::OID) AND a.privilege_type IN ('SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER') AND (CASE WHEN a.grantee=0 THEN TRUE ELSE a.grantee=runtime_role OR pg_has_role(runtime_role,a.grantee,'MEMBER') END)) THEN RAISE EXCEPTION 'INT9_DEFAULT_TABLE_ACL_DENIED'; END IF;
 END LOOP;
 FOREACH fn IN ARRAY audited LOOP IF EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=fn AND a.grantee=0 AND a.privilege_type='EXECUTE') THEN RAISE EXCEPTION 'INT9_PUBLIC_FUNCTION_ACL_DENIED'; END IF; END LOOP;
