_catalog_at(TEXT,TEXT,TEXT,JSONB,JSONB)']::TEXT[]) signature;
 SELECT relowner INTO protected_owner FROM pg_class WHERE oid=protected_relation;
 IF EXISTS(SELECT 1 FROM pg_class relation CROSS JOIN LATERAL aclexplode(COALESCE(relation.relacl,acldefault('r',relation.relowner))) acl WHERE relation.oid=protected_relation AND acl.grantee=0 AND acl.privilege_type IN ('INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER')) OR EXISTS(SELECT 1 FROM pg_attribute attribute CROSS JOIN LATERAL aclexplode(attribute.attacl) acl WHERE attribute.attrelid=protected_relation AND acl.grantee=0 AND acl.privilege_type IN ('INSERT','UPDATE','REFERENCES')) THEN RAISE EXCEPTION 'INT9_NAMESPACE_PUBLIC_ACL_DENIED'; END IF;
 FOR role_id IN WITH RECURSIVE descendants(id) AS (SELECT oid FROM pg_roles WHERE rolname IN ('enta_runtime','enta_gameplay_runtime','enta_finance_executor','catalog_issuer','enta_catalog_issuer_login') UNION SELECT membership.member FROM pg_auth_members membership JOIN descendants parent ON parent.id=membership.roleid), reachable(id) AS (SELECT id FROM descendants UNION SELECT membership.roleid FROM pg_auth_members membership JOIN reachable parent ON membership.member=parent.id) SELECT id FROM reachable LOOP
  IF role_id=protected_owner OR pg_has_role(role_id,protected_owner,'MEMBER') OR EXISTS(SELECT 1 FROM pg_roles WHERE oid=role_id AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolreplication OR rolbypassrls)) OR has_schema_privilege(role_id,'public','CREATE') OR has_table_privilege(role_id,protected_relation,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege(role_id,protected_relation,'INSERT,UPDATE,REFERENCES') THEN RAISE EXCEPTION 'INT9_NAMESPACE_WRITER_ACL_DENIED'; END IF;
  IF EXISTS(SELECT 1 FROM pg_default_acl defaults CROSS JOIN LATERAL aclexplode(defaults.defaclacl) acl WHERE defaults.defaclobjtype='r' AND defaults.defaclnamespace IN (0,'public'::regnamespace::OID) AND acl.privilege_type IN ('INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER') AND (CASE WHEN acl.grantee=0 THEN TRUE ELSE acl.grantee=role_id OR pg_has_role(role_id,acl.grantee,'MEMBER') END)) THEN RAISE EXCEPTION 'INT9_NAMESPACE_DEFAULT_ACL_DENIED'; END IF;
  -- Source-known namespace readers remain approved through the exact recursive
  -- audit above. Any other reachable definer mentioning the protected relation
  -- must be separately reviewed; no unknown provisioning writer is repaired.
  FOR definition IN SELECT p.oid,p.prosrc FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prosecdef AND n.nspname='public' AND has_function_privilege(role_id,p.oid,'EXECUTE') AND p.prosrc LIKE '%DeploymentNamespace%' LOOP
   IF NOT definition.oid=ANY(approved_oid) THEN RAISE NOTICE 'INT9_NAMESPACE UNAPPROVED: % (oid: %), approved has % items, contains? %', definition.oid::regprocedure, definition.oid, cardinality(approved_oid), (definition.oid=ANY(approved_oid)); RAISE EXCEPTION 'INT9_NAMESPACE_DEFINER_REVIEW_REQUIRED'; END IF;
   IF definition.prosrc ~* '(INSERT[[:space:]]+INTO|UPDATE|DELETE[[:space:]]+FROM|TRUNCATE([[:space:]]+TABLE)?)[[:space:]]+(public[.])?"?DeploymentNamespace"?' THEN RAISE EXCEPTION 'INT9_NAMESPACE_DEFINER_WRITER_DENIED'; END IF;
  END LOOP;
 END LOOP;
 IF (SELECT count(*) FROM pg_trigger WHERE tgrelid=protected_relation AND NOT tgisinternal AND tgname IN ('int9_namespace_tuple','int9_namespace_truncate') AND tgenabled='A' AND tgfoid IN ('public.int9_namespace_tuple_guard()'::regprocedure::OID,'public.int9_namespace_truncate_guard()'::regprocedure::OID))<>2 THEN RAISE EXCEPTION 'INT9_NAMESPACE_TRIGGER_UNAVAILABLE'; END IF;
END $namespace_acl$;
